-- ============================================================
-- Ereb3e (5/7) — DB kontentinin AR tərcüməsi
-- COALESCE + guarded UPDATE — mövcud/əl tərcümələri qorunur (idempotent).
-- Cəmi: 6170 UPDATE (day-notifications İSTİSNA — ayrıca faylda)
-- ƏVVƏL sxem faylı (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبحت "قبضة الكماشة" (pincer grasp) متطورة إلى درجة تمكّن طفلكِ من التقاط حتى أنحف خيط أو أصغر فتات على الأرض بسهولة. ولاختبار هذه المهارة، يمكنكِ تقديم بقوليات مطهوة جيدًا له، مثل الحمص والعدس. لكن تذكّري أن عادة وضع كل غرض صغير يعثر عليه في فمه تكون أيضًا في ذروتها خلال هذه المرحلة. لذلك، يظل الحفاظ على نظافة أرضية المنزل وخلوّها من الأغراض الصغيرة أهم قاعدة للسلامة.') WHERE id = '1053192f-a2a7-43d0-8335-34db00482590';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تطوّر الألعاب الاجتماعية: لقد ارتقى طفلكِ بلعبة "أعطني وخذ" إلى مستوى آخر. فقد يعطيكِ اللعبة ثم يطلب استعادتها فورًا، أو قد يخفيها عمدًا عندما تقولين له "أعطني". هذه هي "مزحاته" الأولى. قابلي حسه الفكاهي بالضحك، فالضحك والاستمتاع معًا يقوّيان الرابطة العاطفية بينكما بدرجة مذهلة.') WHERE id = '3451f734-1652-4c0f-97a4-7d508b0bb860';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'نظام النوم وفترات الاستيقاظ: في الشهر 11، قد تظهر على الأطفال علامات الانتقال من قيلولتين نهارًا إلى قيلولة واحدة، لكن لا تتعجلي بعد. يحتاج معظم الأطفال إلى قيلولتين نهارًا حتى عمر 14-15 شهرًا. إذا كان طفلكِ يجد صعوبة في النوم خلال قيلولة الصباح، فجرّبي إطالة فترة استيقاظه قليلًا (نحو 3 - 3.5 ساعات). فالطفل الذي يحصل على قسط جيد من الراحة يتعلم المهارات الجديدة بحماس أكبر.') WHERE id = '852db72f-d9a2-475c-b994-d1ab8a6b4f97';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الإدراك المكاني": أصبح طفلكِ يحب النظر داخل الصناديق، وفتح الأغطية وإغلاقها، ووضع الأشياء بعضها داخل بعض. أعطيه أوعية بلاستيكية بأحجام مختلفة. عندما يكتشف أن الوعاء الصغير يدخل داخل الوعاء الكبير، تتشكل في دماغه روابط رياضية ومنطقية معقدة. قد يبدو ذلك بسيطًا، لكنه في الحقيقة اكتشاف كبير.') WHERE id = '114fd473-c44c-4c3b-b5d0-19ac5cbf17e6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد أكملنا 310 أيام! أصبح طفلكِ يُظهر إرادته بوضوح: فقد يشدّ ساقيه عندما لا يرغب في ارتداء ملابسه، ويصفق بيديه عندما يرى طعامه المفضل. وعلى الرغم من أن علامات "الشخصية" هذه قد ترهقكِ أحيانًا، فإنها في الحقيقة مؤشر على نموه النفسي السليم. اجلسي معه اليوم على الأرض والعبي ببساطة اللعبة التي يختارها هو. فاهتمامكِ هو أعظم مكافأة في العالم بالنسبة إليه.') WHERE id = '2a98f756-8ee8-4fcc-b117-1adb344f61bd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل أصبح طفلكِ قادرًا على ترك يديه والوقوف من دون مساعدة لبضع ثوانٍ؟ هذه ذروة ثقته بنفسه. حتى إن لم يبدأ المشي بعد، فإن لحظات التوازن هذه تطوّر مركز التوازن في دماغه (الجهاز الدهليزي). امدحيه وافتحي ذراعيكِ لتشجيعه على اتخاذ خطوة نحوكِ. فكل محاولة صغيرة تبشّر بخطوة كبيرة!') WHERE id = '94901ac5-33b9-4db0-bb43-734602fe969c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'فهم كلمة "لا" واختبارها! أصبح طفلكِ يتوقف وينظر إليكِ عندما تقولين "لا"، لكنه قد يكرر التصرف نفسه عمدًا أحيانًا. إنه يختبر الحدود ورد فعلكِ. تحلّي بالصبر وحافظي على حزمكِ. في المواقف الخطرة، اشرحي له السبب بنبرة جادة لكن هادئة. فهو يواصل تعلّم القواعد الاجتماعية من تعابير وجهكِ ونبرة صوتكِ.') WHERE id = '996a8930-2fe4-4558-a5f9-55c594d11cb6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبحت "الثرثرة" في كلام طفلكِ (أي حديثه بلغته الخاصة) أكثر تعقيدًا الآن. فهو يرفع صوته كما لو كان يطرح سؤالًا، أو يحرّك يديه وذراعيه كأنه يشرح شيئًا. وهذا يدل على أنه يتعلم تنغيم الكلام (prosody). أنصتي إليه باهتمام وواصلي الحوار قائلةً: "حقًا؟ هذا مثير جدًا للاهتمام!" سيزيد اهتمامكِ هذا رغبته في التواصل بدرجة مذهلة.') WHERE id = '79994c5e-b38e-4456-bddc-86c51746ecdb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الاندماج مع مائدة الأسرة في التغذية: أصبح بإمكان طفلكِ الآن تناول كل ما تأكلونه تقريبًا معكم، بشرط أن يكون الطعام بلا ملح أو توابل حارة. أعطيه ملعقته الخاصة وكوبًا يستطيع الشرب منه بمفرده. إن إتاحة الفرصة له ليأكل بنفسه تعزز مهاراته الحركية، وتحول تناول الطعام إلى نشاط اجتماعي إيجابي. والجلوس معًا إلى المائدة هو أفضل قدوة لعاداته الغذائية مستقبلًا.') WHERE id = '4a48790e-7f13-40fe-9b6e-dd306e1f2a08';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الذاكرة المكانية" والبحث: أصبح طفلكِ قادرًا على تذكّر المكان الذي أُخفيت فيه لعبته المفضلة حتى بعد مرور عدة دقائق. العبي معه ألعاب "الغميضة" الأكثر تعقيدًا. على سبيل المثال، أخفي اللعبة تحت غطاء وراقبيه وهو يعثر عليها. فهذا يعزز ذاكرته وقدرته على تركيز انتباهه. وعندما يحل المشكلة، امتدحيه بحماس.') WHERE id = 'f29f91f0-dc1e-44f0-842d-ac8ae1283e19';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'محاولات "المشاركة" ضمن المهارات الاجتماعية: قد يمد طفلكِ اللعبة التي في يده نحوكِ وكأنه سيعطيكِ إياها، ثم يسحبها مجددًا. هذه أولى محاولاته للمزاح والتأثير الاجتماعي! تفاعلي مع هذه "اللعبة" بالضحك والفرح. فالضحك والاستمتاع معًا يقويان الرابطة العاطفية بينكما بدرجة مذهلة، ويضعان لديه أساس حس الفكاهة.') WHERE id = 'ffe2c8a7-1840-4df7-a9fa-47dc0268105b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبحت "قبضة الكماشة" (pincer grasp) متقنة تمامًا الآن. إذ يستطيع طفلكِ بسهولة التقاط حتى أنحف خيط أو أصغر فتات من الأرض. ولتنمية هذه المهارة، قدّمي له البقوليات المطهوة جيدًا أو قطعًا صغيرة من الجبن القريش. لكن كوني حذرة: فهذه البراعة تعني أيضًا أنه يستطيع وضع أي غرض صغير وخطير في فمه بالسرعة نفسها. لذا يجب مراقبة سلامته باستمرار!') WHERE id = 'c1101eea-3caa-455b-a661-c216864cdeb4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الموسيقى والإيقاع: هل أصبح طفلكِ يتمايل بجسمه أو يصفق بيديه عندما يسمع الموسيقى؟ إن الإحساس بإيقاع الموسيقى علامة على تطور قدرته السمعية وتناسق حركات جسمه. ارقصي وصفقي معه. فهذا يزيد نشاطه البدني، ويساعده أيضًا على تنمية الحس الجمالي والإحساس بالإيقاع. وحاولا ترديد كلمات الأغاني معًا.') WHERE id = '3a1cdf9f-7bc8-427f-b1e3-a23a8f78241b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الاستيقاظ الحركي" أثناء النوم ليلًا: قد ينهض طفلكِ فجأة وهو نائم، أو يحاول الحبو وهو في حالة نعاس. فدماغه يكرر ليلًا الحركات التي تعلمها نهارًا. إذا لم يكن يبكي، فلا تلمسيه ودعيه يجد وضعيته بنفسه ويعود إلى النوم. أما إذا كان يبكي، فتوجهي إليه بهدوء، وأعيديه إلى وضعية الاستلقاء من دون تشغيل الضوء، وقولي له كلمات مطمئنة. وجودكِ وحده يكفي ليعود إلى النوم.') WHERE id = '8706f5e6-ca0d-4a1d-8941-e5de02cc1dad';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد أكملنا 320 يومًا! لم يتبقَّ سوى 45 يومًا على عيد ميلاده الأول. أصبح طفلكِ يُظهر شخصيته وخياراته ورغباته بحزم. استلقي معه اليوم على الأرض والعبا ببساطة لعبة "التقليد"؛ دعيه يصدر صوتًا وكرريه أنتِ، وصفّقي بيديكِ ليقلدكِ. أنتِ ملاذه الأكثر أمانًا وصديقته الأقرب في أثناء اكتشافه للعالم، يا أمي!') WHERE id = '6671dafc-f72e-46f2-8504-39bf2769162e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'ندخل الآن الأيام العشرة الأخيرة من الشهر 11. هل يمشي طفلكِ بثقة كبيرة عندما تمسكين بإحدى يديه، أم لا يزال يتنقل مستندًا إلى حافة الأريكة فحسب؟ قد يخطو في هذه الأيام خطوة أو خطوتين مستقلتين، مع مد ذراعيه إلى الجانبين للحفاظ على توازنه. تعمل حركات "التوازن" هذه على تدريب مركز التوازن في دماغه (الجهاز الدهليزي). لا تستعجليه، ودعيه يكتسب ثقته بنفسه تمامًا.') WHERE id = '223de2de-87c5-4289-96a9-08ae91456aa1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بدأ طفلكِ يفهم الغرض من استخدام الأشياء (اللعب الوظيفي). فمثلًا، يضع المشط على رأسه، أو يمسك الهاتف بجوار أذنه، أو يرفع الكوب إلى فمه ويتظاهر بأنه "يشرب". إنها قفزة كبيرة في تطوره المعرفي! ادعمي مهارة التقليد هذه بتقديم أدوات منزلية آمنة له. فهو يتعلم عن العالم من خلال مراقبتكِ، لذا حاولي أن تكوني قدوة له في تصرفاتكِ.') WHERE id = '1023ea09-5e35-4d01-b1e5-ee2d0049110b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لعبة "ديمومة الأشياء": يعرف طفلكِ الآن أن اللعبة لا تختفي إذا وضعتِها داخل وعاء وغطيتِها. العبي معه ألعاب غميضة أكثر تعقيدًا. فمثلًا، أخفي اللعبة تحت أحد غطاءين مختلفين وراقبيه وهو يعثر عليها. فهذا يعزز ذاكرته وقدرته على التركيز. وامدحيه بحماس عندما يحل المشكلة.') WHERE id = '8ef86f1c-b50a-4f76-b6a2-1deccffcaf49';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الاستقلالية في تناول الطعام: أصبح طفلكِ الآن يرغب في إمساك الملعقة بنفسه تمامًا ووضعها في فمه. نعم، سينتهي معظم الطعام على الأرض وعلى المريلة، لكن هذا من أهم التدريبات على المهارات الحركية الدقيقة والتنسيق بين اليد والعين. أعطيه ملعقة مريحة له، مصنوعة من السيليكون أو ذات مقبض سميك. ويمكنكِ مساعدته في الوقت نفسه بملعقة أخرى. إنه أشبه بـ"العمل الجماعي"!') WHERE id = '7871caf2-41cf-4c3f-b2a8-4d60c9c5acd7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بالشهر الثاني عشر! لم يتبقَّ سوى 30 يومًا على عيد ميلاد طفلكِ الأول. لقد أصبح طفلكِ الآن شخصًا مختلفًا تمامًا. فهو لم يعد يكتفي بتقليد حركاتكِ، بل بات يفهم معناها أيضًا. قدّمي له هذا الشهر خيارات بسيطة لتعزيز ثقته بنفسه. على سبيل المثال: "هل تريد ارتداء هذا القميص أم ذاك؟". بذلك تزرعين البذور الأولى لمهارته في اتخاذ القرار.') WHERE id = 'fd9ad5fc-02c4-489e-8c2f-e2ab1ee56a7e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إذا بدأ طفلكِ بالفعل بالمشي من دون مساعدة، فارفعي مستوى تدابير السلامة في المنزل إلى أقصى حد. وإذا لم يبدأ المشي بعد، فلا تقلقي؛ فكثير من الأطفال الأصحاء لا يمشون حتى عمر 15 شهرًا. سرعة البدء بالمشي ليست مؤشرًا على الذكاء. المهم أن يكون قادرًا على الوقوف ولديه الدافع لاستكشاف ما حوله.') WHERE id = 'e0fb9df8-7033-4ff7-a1b1-5c3d3e6afa83';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الكلمات ذات المعنى" في الكلام: هل بدأ طفلكِ يستخدم كلمات بسيطة مثل "ماء" و"أعطني" و"تعال" في مواضعها الصحيحة؟ بات بإمكانه إخباركِ بما يريده بكلمة واحدة أو إشارة. وسّعي أنتِ هذه المحاولات، فقولي مثلًا: "نعم، هل تريد أن تشرب الماء؟ تفضل، هذا كوبك الأزرق". يساعد ذلك دماغه على بناء الروابط النحوية بين الكلمات.') WHERE id = 'c5cc511f-2fea-4b22-b8e8-1b77f482261c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'حان وقت الاندماج الكامل في مائدة الأسرة. يستطيع طفلكِ الآن الجلوس إلى المائدة معكم في الوقت نفسه وتناول الأطعمة نفسها تقريبًا. وهذا مهم جدًا لنمو مهاراته الاجتماعية. أعطيه أدوات المائدة الخاصة به وهيّئي له فرصة تناول الطعام بنفسه. ينبغي ألا يكون تناول الطعام واجبًا مفروضًا عليه، بل نشاطًا ممتعًا وشهيًا.') WHERE id = '8b39909f-51d2-4504-9985-513b605dc042';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبحت "قبضة الملقط" (pincer grasp) متقنة الآن، وتتيح له مهاراته الحركية الدقيقة ممارسة ألعاب أكثر تعقيدًا. علّميه تكديس المكعبات بعضها فوق بعض، ونظم الخرز الكبير في خيط (تحت إشرافكِ!)، أو حل الأحاجي البسيطة (puzzle). تُنمّي هذه الألعاب قدرته على التركيز والتنسيق بين اليد والعين بدرجة مذهلة.') WHERE id = 'e3225412-1384-48a0-aa55-7ca8a5ef8659';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تظهر الآن البوادر الأولى لـ"التعاطف" في التواصل الاجتماعي. قد يأتي طفلكِ ليلمسكِ أو يعطيكِ لعبته عندما تكونين حزينة أو تبكين. وهذا يدل على أنه بدأ يفهم مشاعر الآخرين. قابلي تصرفاته الحنونة هذه بالحب. سيساعده ذلك مستقبلًا على أن يصبح شخصًا يتمتع بصحة عاطفية جيدة.') WHERE id = '31745949-5ef4-444a-8a69-ec5929c0332b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'حان وقت "أصوات الحيوانات" في تطور النطق! قد يبدأ طفلكِ الآن بالإجابة بطريقته الخاصة عن أسئلة مثل: "كيف ينبح الكلب؟" و"ما الصوت الذي تصدره القطة؟". تمثل هذه المرحلة ذروة قدرته على تقليد الأصوات. واصلي هذه الألعاب أثناء تصفح الكتب التي تحتوي على صور الحيوانات. يساعد تقليد الأصوات على تهيئة أعضاء النطق، مثل اللسان وعضلات الشفتين، لنطق كلمات أكثر تعقيدًا في المستقبل.') WHERE id = 'cdc84d0d-886f-4a27-bf41-fd9c5be5503c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبحت "قبضة الملقط" (pincer grasp) متقنة الآن إلى درجة أن طفلكِ يستطيع بسهولة التقاط أنحف خيط أو حتى فتات صغير من الأرض. ولاختبار هذه المهارة، يمكنكِ تقديم البقوليات المطهية جيدًا، مثل الحمص والعدس، له. لكن تذكّري أن عادته في وضع كل ما يجده من أشياء صغيرة في فمه تبلغ ذروتها أيضًا. لذلك تظل نظافة أرضية المنزل وخلوّها من الأغراض الصغيرة أهم قواعد السلامة لديكِ.') WHERE id = '03beae21-c620-431a-a745-a2cb5663e55d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تزداد الألعاب الاجتماعية تعقيدًا: يرتقي طفلكِ الآن بلعبة "أعطِ وخذ" إلى مستوى آخر. فقد يعطيكِ اللعبة ثم يطلب استعادتها فورًا، أو قد يخفيها عمدًا عندما تقولين له "أعطني". هذه أولى "مزحاته". قابلي حسه الفكاهي هذا بالضحك. فالضحك والاستمتاع معًا يقويان الرابطة العاطفية بينكما بدرجة مذهلة.') WHERE id = '3339985d-3305-4eb1-9ee4-eac876362604';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'نظام النوم وفترات اليقظة: في الشهر 11، قد تظهر لدى الرضّع علامات الانتقال من قيلولتين نهارًا إلى قيلولة واحدة (nap transition)، لكن لا تتعجلي بعد. يحتاج معظم الرضّع إلى قيلولتين نهارًا حتى عمر 14-15 شهرًا. إذا كان طفلكِ يجد صعوبة في النوم خلال قيلولة الصباح، فجرّبي إطالة فترة يقظته قليلًا (نحو 3 - 3.5 ساعات). فالطفل الذي يحصل على قسط جيد من الراحة يتعلم المهارات الجديدة بحماس أكبر.') WHERE id = 'db42c776-feed-4c94-906a-857e9999bca9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الإدراك المكاني": يحب طفلكِ الآن النظر داخل الصناديق، وفتح الأغطية وإغلاقها، ووضع الأشياء داخل بعضها بعضًا. أعطيه أوعية بلاستيكية بأحجام مختلفة. عندما يكتشف أن الوعاء الصغير يدخل داخل الوعاء الكبير، تتكوّن في دماغه روابط رياضية ومنطقية معقدة. قد يبدو هذا بسيطًا، لكنه في الحقيقة اكتشاف كبير.') WHERE id = 'c317d6dc-6305-468b-bef4-37407eacbfe2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد أتممنا 330 يومًا! لم يتبقَّ سوى شهر واحد على عيد ميلاده الأول. بدأ طفلكِ الآن يُظهر إرادته: فقد يشدّ ساقيه عندما لا يرغب في ارتداء ملابسه، ويصفق بيديه عندما يرى طعامه المفضل. ورغم أن علامات "الشخصية" هذه قد ترهقكِ أحيانًا، فإنها في الواقع دليل على نموه النفسي السليم. لقد قطعتِ شوطًا رائعًا يا أمي!') WHERE id = 'c209d7a9-28c5-4bcf-a9ab-ed5e68cd5e38';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'ينبغي أن تكون عادة الشرب من الكوب قد ترسخت تمامًا الآن. لقد حان الوقت للابتعاد تدريجيًا عن زجاجة الرضاعة. فقد يؤثر استخدامها لفترة طويلة سلبًا في انتظام الأسنان وتطور النطق. قدّمي لطفلكِ كوب تدريب ملوّنًا وجذابًا أو كوبًا عاديًا مفتوحًا. وسيمنحه الشرب بنفسه شعورًا كبيرًا بالاستقلالية.') WHERE id = '38eafb23-62e2-4538-a93f-213f32e35986';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الذاكرة المكانية» والنظام: أصبح طفلكِ يعرف الآن مكان ألعابه. بعد انتهاء اللعب، رتّباها معًا. شجّعيه بقولكِ: «هيا، لنُعِد الدب إلى بيته (الصندوق)». فهذا ينمّي لديه الشعور بالمسؤولية، ويساعده أيضًا على فهم أن لكل غرض مكانًا محددًا. وتبدأ عادات النظام والانضباط بالتشكل في هذه الأشهر تحديدًا.') WHERE id = 'c880f2e4-5f85-403c-b1f7-b1634ed3e06b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'النوم ليلًا وفترات الاستيقاظ: قد يبدأ طفلكِ الآن في أخذ قيلولاته النهارية في وقت أبكر أو الاستغناء عن إحدى القيلولات. إذا كان يشعر بالراحة مع قيلولة واحدة خلال النهار، فعدّلي روتينه وفقًا لذلك. لكن معظم الأطفال في عمر 1 سنة ما زالوا يحتاجون إلى قيلولتين. واصلي مراقبة علامات التعب لديه؛ فالطفل الذي يحصل على قسط جيد من الراحة يكون أكثر سعادة واستعدادًا للتعلّم.') WHERE id = '9898d949-3ccb-4708-a982-1de8127dfcfd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد أكملنا 340 يومًا! لم يتبقَّ سوى 25 يومًا على عيد ميلاده الأول. لقد أصبح طفلكِ الآن شخصية مستقلة، له أذواقه وطباعه وألعابه المفضلة. استلقي اليوم معه على الأرض والعبِي ببساطة لعبة يختارها هو. دخولكِ إلى عالمه هو أعظم هدية بالنسبة إليه. لقد خضتِ عامًا رائعًا يا ماما!') WHERE id = 'c4c0444c-fad1-4344-8a31-c99f7a9878d9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يتبقَّ سوى 25 يومًا على عيد ميلاده! إذا كان طفلكِ يخطو بضع خطوات بمفرده، فهذا يدل على أن قدرته على التوازن قد تطورت جيدًا. وإذا لم يبدأ المشي بعد، فلا تمسكي بيديه لإجباره على المشي، لأن ذلك قد يضع عبئًا غير ضروري على عموده الفقري. الأفضل أن تقفي أمامه وتفتحي ذراعيكِ لتشجيعه على التقدم نحوكِ. فنظراتكِ الواثقة تمنحه أكبر قدر من الشجاعة.') WHERE id = '8681364a-206a-4e87-acfa-4a44f4404ec8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تطور «اللغة الاستقبالية» (القدرة على الفهم): أصبح طفلكِ الآن يفهم التعليمات البسيطة. هل يستطيع تنفيذ ما تطلبينه عندما تقولين له: «أعطني الكرة»، «تعال إلى هنا»، «أحضر قبعتك»؟ رغم أنه قد لا يتمكن بعد من نطق جميع الكلمات، فقد كوّن في دماغه حصيلة كبيرة من المفردات. واصلي التحدث إليه مع وصف كل حركة تقومين بها. فهذا يشكّل أساسًا متينًا لنطقه وكلامه مستقبلًا.') WHERE id = 'b0d73932-0d82-458c-b55b-ddc718662495';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«المزاح» ضمن المهارات الاجتماعية: هل يناولكِ طفلكِ اللعبة عمدًا ثم يسحبها فورًا ويضحك؟ يدل ذلك على بدء تطور حس الفكاهة لديه وقدرته على التفاعل الاجتماعي بمرح. شاركيه هذه «اللعبة» بحماس. فالضحك معًا يقوّي الرابط العاطفي بينكما ويساعده على بناء ثقة إيجابية بنفسه.') WHERE id = 'f977f0c6-061a-4189-bf33-4e6656c97984';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد تبدأ مرحلة «الانتقائية» في الطعام. فقد يرفض طفلكِ اليوم بإصرار طعامًا تناوله بالأمس. وهذه طريقته في التعبير عن إرادته. لا تجبريه، لكن أعيدي تقديم الطعام الذي لم يحبه بعد فترة وبشكل مختلف. الأهم هو ألّا يسود التوتر وقت تناول الطعام، بل أن يظل موعد الوجبة طقسًا ممتعًا بالنسبة إليه.') WHERE id = 'eb15bd6a-93d6-4986-92eb-7294c9a935c2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مهارة «البناء» ضمن المهارات الحركية الدقيقة: يحاول طفلكِ الآن وضع المكعبات بعضها فوق بعض لبناء «أبراج» صغيرة. قد ينهار البرج سريعًا في الوقت الحالي، لكن هذا تمرين رائع لتطوير التناسق بين عينيه ويديه وتعزيز تركيزه. قدّمي له مكعبات مختلفة الأحجام والألوان. اضحكا معًا عندما ينهار البرج، وشجّعيه بقولكِ: «هيا، لنبنه مرة أخرى!»') WHERE id = '7a4a5884-cfbe-4717-937f-7483274cf1dd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الإدراك المكاني» والذاكرة: أصبح طفلكِ يعرف أين أُخفيت لعبته المفضلة، ويزيح العوائق، مثل الوسادة، ليعثر عليها. وهذا دليل على تطور قدرته على حل المشكلات. العبي معه ألعاب «الغميضة» بدرجة أكبر من التعقيد. فتجاوز العوائق يقوّي الروابط المنطقية في دماغه.') WHERE id = '87a69c40-9317-47d9-89ca-fad250ba27cf';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الوعي بالذات والاستقلالية: هل يحاول طفلكِ الآن «مساعدتكِ» عند ارتداء ملابسه؟ كأن يمد قدمه نحو الجورب أو يُدخل ذراعه في كم القميص. ادعمي هذه المحاولات وامدحيه. فقولكِ: «ما أجمل ملابسك!» يسهم كثيرًا في إدراكه لذاته بوصفه فردًا مستقلًا، ويعزز رغبته في الاعتماد على نفسه.') WHERE id = '82ceaad9-caa0-45d0-ae94-6fb25e59d3dc';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المراحل الأخيرة من التسنين خلال العام الأول: عند الاقتراب من عمر 1 سنة، يكون لدى معظم الأطفال 4-8 أسنان. وقد تتورم لثة طفلكِ أو تؤلمه مجددًا. قدّمي له شرائح باردة من الخضراوات ليمضغها، مثل الجزر أو الخيار، مع مراقبته باستمرار! فالمضغ يدلّك اللثة ويقوّي عضلات الفك أيضًا.') WHERE id = '3fe62d47-f929-4c62-b0de-6bc80e34943b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قوة كلمة «لا»: قد يعترض طفلكِ الآن عندما تقولين له «لا»، بل قد يستلقي على الأرض ويبكي (نوبات الغضب الأولى). يحدث ذلك لأنه لا يزال غير قادر على التحكم في مشاعره. حافظي على هدوئكِ، وانزلي إلى مستواه وعبّري عن مشاعره بالكلمات: «أنت غاضب الآن لأنني لم أعطك اللعبة، وأنا أتفهم ذلك». هدوؤكِ هذا هو أفضل درس يعلّمه الاستقرار العاطفي.') WHERE id = '627b69c9-1a97-4379-b790-7b2e4d39bfb2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد أتممنا 350 يومًا! لم يتبقَّ سوى 15 يومًا على عيد ميلاده الأول! انظري اليوم إلى صوره في الأشهر الأولى، وفكّري في المسافة الطويلة التي قطعتماها معًا. لقد أصبح ذلك الرضيع العاجز الآن فردًا له شخصيته الخاصة. استمتعي بهذه الأيام الـ15 من دون توتر، واقضي وقتكِ معه فحسب. لقد عشتِ عامًا رائعًا، يا ماما!') WHERE id = '8417d81b-7389-4675-845a-7c49bcb07801';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يتبقَّ سوى 10 أيام على عيد ميلاده الأول! هل يستطيع طفلكِ الآن تقليب صفحات الكتاب (حتى لو كان يقلب عدة صفحات معًا في الوقت الحالي)؟ هذا مؤشر على تطور مهاراته الحركية الدقيقة واهتمامه بالكتب. واصلي قراءة الكتب ذات الصور الكبيرة والملونة له. وعندما تسألينه، وأنتِ تنظرين إلى الكلب في الصورة: «أين الكلب الذي يقول عَو عَو؟»، فإن إشارته إليه بإصبعه تعكس تطورًا رائعًا في قدرته على الفهم.') WHERE id = '3e342e5d-4541-4b82-ae58-b2cc792f784b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل بدأ طفلكِ يهز جسمه عند سماع الموسيقى، ويثني ركبتيه ويمدهما وكأنه «يرقص»؟ إن الإحساس بإيقاع الموسيقى يدل على تطور سمعه وتناسق حركات جسمه. صفّقا معًا وحافظا على الإيقاع. تزيد هذه اللحظات المرحة هرمونات السعادة في دماغه، وتعزز الرابطة بينكما أكثر.') WHERE id = '824b4580-ab45-4cbc-9104-e999a9e050cb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ الآن يفهم «وظائف الأشياء» تمامًا. فعندما يرى المشط يقرّبه من رأسه، وعندما يرى حذاءه يمدّه نحو قدمه. لقد أدرك أن الأشياء ليست مجرد ألعاب، بل إن لكل منها وظيفة محددة. اسمحي له باللعب بأدوات منزلية آمنة (مثل الأوعية البلاستيكية والفُرَش النظيفة). فهذا يساعده على التكيف مع الحياة اليومية بسرعة أكبر.') WHERE id = '40fb0a95-63d4-4ada-888b-1faf14ddd19d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة «التكرار» في تطور الكلام. قد يحاول طفلكِ تكرار المقاطع الأخيرة من الكلمات التي تقولينها. فمثلًا، عندما تقولين «تفاحة»، قد يقول هو «حة». هذا تمرين فعّال لجهاز النطق لديه. تحدثي معه دائمًا بوضوح ونطق صحيح. فذكر الأسماء الحقيقية للأشياء، بدلًا من استخدام «لغة الأطفال» (مثل بيبو ومياو مياو وغيرها)، يساعده على بناء حصيلته اللغوية بصورة سليمة.') WHERE id = '40321163-794d-42e6-bcde-127caef60c13';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'من المفترض أن تكون مهارات تناول الطعام باستقلالية قد بدأت تستقر الآن. نعم، لا يزال طفلكِ يمسك الملعقة بالمقلوب أو يُسقط نصف الطعام على الأرض، لكن محاولته تناول الطعام بنفسه أهم من أي شيء آخر لتعزيز ثقته بنفسه. قدّمي له وعاءً عميقًا مريحًا للاستخدام وملعقة ذات مقبض مطاطي. تحلّي بالصبر، فسرعان ما سيصبح أكثر أفراد مائدة الأسرة نشاطًا و"استقلالية".') WHERE id = 'd42878d7-1b6d-456a-b198-9e59777aacf0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد يبلغ "قلق الانفصال" (Separation anxiety) ذروته مجددًا عند اقتراب طفلكِ من عمر سنة. إن صراخه الشديد عندما تغادرين الغرفة دليل على تعلّقه العميق بكِ وعلى خوفه المستمر من أن "تذهب أمي ولا تعود". أخبريه دائمًا إلى أين تذهبين ومتى ستعودين، حتى لو كنتِ تنتقلين إلى غرفة أخرى. صدقكِ معه سيعيد إليه شعوره بالأمان.') WHERE id = 'bf1abd20-6eb2-41e7-85ec-e1c3f46808a3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إنجاز جديد في المهارات الحركية الدقيقة: "فتح الأغطية وإغلاقها". أصبح طفلكِ يستمتع بحركات مثل فتح أغطية العلب ومحاولة لف أغطية الزجاجات. ويتطلب ذلك مستوى عاليًا من التناسق بين عضلات الرسغ والأصابع. قدّمي له أوعية بلاستيكية بأحجام مختلفة ودعيه يضع بعضها داخل بعض. فهذا أيضًا أول تدريب له على التفكير الرياضي والمنطقي.') WHERE id = '4e49e60c-de35-4a74-ac4f-e95ac56a3410';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تعلُّم القواعد الاجتماعية: أصبح طفلكِ يؤدي بوعي إيماءات مثل قول "مع السلامة" (بالتلويح باليد) أو "إرسال قبلة" أو "المصافحة". وهذه بمنزلة أولى "تأشيرات دخوله" إلى المجتمع. استقبلي دائمًا هذه السلوكيات الإيجابية بفرح. فردّ فعلكِ يساعده على فهم السلوك الذي يُعدّ "جيدًا".') WHERE id = '21db9180-06af-489e-83b0-28bdcc1730d0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'غدًا يُكمل طفلكِ عامه الأول! استعيدي اليوم ذكريات مغامرة الأشهر الـ12 الماضية: الابتسامة الأولى، والسن الأولى، والحبو الأول... مهما كان الأمر صعبًا، فقد نجحتِ! لم يعد طفلكِ رضيعًا عاجزًا، بل أصبح إنسانًا صغيرًا له شخصيته ورغباته. وعندما تخلدين إلى النوم الليلة، قولي لنفسكِ أيضًا: "أحسنتِ". أنتِ أم رائعة!') WHERE id = '74f434ee-a5bf-498f-af06-34cc0939c106';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا! عيد ميلاد أول سعيد! 🎂 أصبح عمر طفلكِ رسميًا سنة كاملة. لقد كان هذا العام حافلًا بأكبر التغيّرات في حياته وحياتكِ أيضًا. وقد أصبح الآن طفلًا دارجًا (طفلًا بدأ المشي)، مستعدًا للمشي والكلام واستكشاف العالم. احتفلوا بهذا اليوم من دون توتر، مستمتعين بضحكاته وحبكم. نتمنى لكم دربًا ميسّرًا وعمرًا مديدًا حافلًا بالبركة!') WHERE id = '56917d9b-b358-4310-b651-30aecbaf8560';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بكِ في العام الثاني! انتهت حماسة عيد الميلاد الأول، لكن المغامرة الحقيقية تبدأ الآن. أصبح طفلكِ رسميًا في مرحلة "الطفل الدارج" (toddler). ابتداءً من هذا الشهر، سيرغب في استكشاف العالم أكثر وهو في وضعية الوقوف. ومع ازدياد نشاطه وحركته، تتغير احتياجاته من الطاقة أيضًا. لكن تذكّري أن حليب الأم أو الحليب الصناعي قد يظل جزءًا مهمًا من نظامه الغذائي.') WHERE id = '165b6f1d-3374-4097-b9a4-8e514ea4fdd0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تزداد مهارة المشي ثباتًا! إذا كان طفلكِ يمشي وحده بالفعل، فستلاحظين أن خطواته لا تزال مترنحة قليلًا ومتباعدة. وهذه آلية طبيعية تساعده على الحفاظ على توازنه. اتركيه يمشي حافي القدمين في المنزل قدر الإمكان، فهذه أفضل وسيلة لتتشكّل أقواس قدميه بشكل سليم ولينقل إلى دماغه معلومات أكثر عن ملمس الأرض.') WHERE id = 'c278e801-c9bd-49de-b0fb-e7e23f4f7d75';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بعد عمر سنة، قد يُلاحظ انخفاض مفاجئ في شهية الأطفال. ويُسمى ذلك "فقدان الشهية الفسيولوجي". والسبب بسيط: تتباطأ سرعة نمو طفلكِ مقارنة بالسنة الأولى، فلا يعود بحاجة إلى كمية السعرات الحرارية نفسها. لا تحاولي إجباره على الأكل. الأهم أن تكون الأطعمة التي تقدمينها له مغذية ومتنوعة. يجب أن يتعلم بنفسه تنظيم كمية الطعام التي يحتاج إليها.') WHERE id = 'dd5c13fb-e41c-4d49-a21d-c17c38691c1f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة "الجمل المكوّنة من كلمة واحدة" في تطور الكلام. أصبح طفلكِ يعبّر عن فكرة كاملة بكلمة واحدة فقط. فمثلًا، قد تعني كلمة "برّا" لديه كلاً من "لنخرج" و"ألبسيني حذائي". أجيبيه بتوسيع كلمته الواحدة إلى جملة: "نعم، سنلبس حذاءك الآن ونخرج إلى الحديقة (برّا)". فهذا يسرّع تطور قدرته على تكوين الجمل.') WHERE id = '4f614506-d560-4d40-bad9-c0ba7ee808d8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تزداد لديه رغبة "سأفعل ذلك بنفسي!". قد يرفض طفلكِ مساعدتكِ عندما يحاول غسل يديه أو صعود الدرج أو ارتداء ملابسه. هذا ليس عنادًا، بل محاولة للاستقلال. امنحيه "حرية ضمن حدود مسموح بها" كلما كان الأمر آمنًا. فرؤيته أنه قادر على إنجاز الأمور بنفسه من أهم العوامل التي تبني ثقته بنفسه (self-esteem).') WHERE id = '884b93ff-cafb-4926-88b8-45e9267f348c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة "اللعب المتوازي" في تطور المهارات الاجتماعية. إذا اصطحبتِ طفلكِ إلى أطفال في مثل سنه، فستلاحظين أنه يلعب بمفرده إلى جوارهم، لا معهم. وهذا طبيعي تمامًا لدى الأطفال بين عمر سنة وسنتين. فهم لا يعرفون بعد كيف يشاركون الآخرين أو يلعبون معهم، لكنهم يتعلمون الكثير من خلال مراقبة بعضهم بعضًا. واصلي اصطحابه إلى الحدائق ومجموعات اللعب لدعم تطور مهاراته الاجتماعية.') WHERE id = 'e23b48b6-63ac-4bcc-9b95-51974a62ac74';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إتقان المهارات الحركية الدقيقة: أصبح طفلكِ الآن قادرًا على إمساك قلم أو فرشاة رسم (براحة يده حتى الآن) و"الخربشة" على الورق. وهذا يمثل مستوى جديدًا من التناسق بين يديه وعينيه. قدّمي له أوراقًا كبيرة وأقلام تلوين آمنة للأطفال. كما يزرع هذا النشاط البذور الأولى لمخيلته الإبداعية. أبقيه دائمًا تحت إشرافكِ حتى لا تتحول الجدران إلى "أعمال فنية"!') WHERE id = '0b6473c4-31af-4b7f-87fd-2d01229d5be8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تغيّر نمط النوم: في الشهر 13، يرغب كثير من الأطفال في الانتقال من قيلولتين نهاريتين إلى قيلولة واحدة. إذا كان طفلكِ يجد صعوبة في أخذ قيلولة الصباح أو أصبحت قيلولة الظهر متأخرة جدًا، فقد حان الوقت لتعديل نظام نومه. قد يستغرق الانتقال إلى قيلولة واحدة بضعة أسابيع، وقد يصبح خلال هذه الفترة الانتقالية أكثر "تململًا" قليلًا في المساء. تحلّي بالصبر، فالنظام الجديد سيكون أكثر راحة لكليكما.') WHERE id = '04380a78-48ac-47f1-b32c-6d6f9bfeb4d4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'عامل "الارتفاع" في السلامة: أصبح طفلكِ يتسلق الكراسي ويحاول الصعود فوق الطاولة. فهو لا يدرك بعد مخاطر الارتفاعات ولا يشعر بالخوف منها تمامًا. تحققي من أقفال النوافذ وثبّتي قطع الأثاث الطويلة في الحائط. ومهمتكِ الأساسية هي جعل البيئة آمنة قدر الإمكان من السقوط، من دون تقييد حرية حركته.') WHERE id = '6948a89f-6493-4c6e-9adb-708a1f0063cb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لقد أكملتِ الأيام العشرة الأولى من الشهر 13! أصبح طفلكِ الآن ينفّذ التعليمات البسيطة ("ضع لعبتك في الصندوق"، "تعال إلى هنا") بوعي تام. وهذا مؤشر مهم على تطوره اللغوي والاجتماعي معًا. اقرئي معه كتابًا اليوم واطلبي منه العثور على الأشياء الموجودة في الصور. فكل دقيقة ممتعة وهادفة يقضيها معكِ هي أعظم دعم لنموه وتطوره.') WHERE id = '702b1e33-f64a-46f4-9e5d-44efebebe748';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لقد اكتشف طفلكِ الآن قوة كلمة "لا"! في هذه المرحلة، يختبر حدوده من خلال الاعتراض على كل شيء. وليس هذا عنادًا، بل جزء من تكوّن شخصيته المستقلة. فعندما تقولين له "لا"، قد يتعمد فعل الأمر نفسه ليراقب رد فعلكِ. حاولي الحفاظ على هدوئكِ؛ فثباتكِ الانفعالي هو أفضل دليل يساعده على تعلّم القواعد.') WHERE id = 'e0c32222-756f-4ca9-8533-fb5e6a6bf334';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مع تحسّن مهارة المشي لديه، يبدأ طفلكِ بمحاولة المشي إلى الخلف أو حمل لعبة بيده أثناء سيره. وهذا يدل على ازدياد قوته البدنية وقدرة دماغه على التنسيق. قدّمي له ألعابًا ذات عجلات يمكنه سحبها خلفه. فهذا النوع من اللعب يقوّي عضلات ساقيه أكثر.') WHERE id = '49b402b9-bb72-400d-ac9d-7af091029dd1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد يقوم طفلكِ بـ"حركات نشطة" أثناء نومه ليلًا. فقد يتقلب في نومه، أو يغيّر وضعيته، أو يجلس فجأة. إذ يتدرّب دماغه خلال النوم على جميع الحركات الجديدة التي تعلّمها نهارًا. إذا لم يكن يبكي، فلا تتدخلي. دعيه يجد بنفسه وضعية مريحة ويواصل نومه.') WHERE id = '5ccc44b7-6be9-42e8-9051-5aba385dfbb3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، أنتِ الآن في منتصف الشهر الثالث عشر! أصبح طفلكِ يفهم الطلبات البسيطة تمامًا، بل ويرغب في "مساعدتكِ" أيضًا (مثل وضع اللعبة في الصندوق). لا تثبّطي حماسه، وامدحي بحماس كل مساعدة صغيرة يقدمها. دعمكِ سيجعله في المستقبل شخصًا أكثر تحمّلًا للمسؤولية وثقةً بنفسه. أنتِ أم رائعة!') WHERE id = '2f2ae51c-beef-4df3-9d10-cb7325ea4331';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ الآن أكثر مهارة في استخدام الملعقة. نعم، لا يزال بعض الطعام يسقط على الأرض، لكنه بات يتحكم في حركات معصمه بشكل أفضل. امنحيه مزيدًا من الفرص ليتناول الطعام بنفسه. وعندما يدرك أنه شبع ويدفع الطعام بعيدًا، فهذا يدل على أنه يصغي إلى إشارات الجوع والشبع الداخلية لديه. وهذا مهم جدًا لاكتساب عادات غذائية صحية في المستقبل.') WHERE id = '45554d06-2e09-4223-93a8-104614df2f0c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ الآن يحاول بوعي أن "يساعدكِ". فمثلًا، يجمع ألعابه في الصندوق أو يناولكِ شيئًا ما. وهذه أولى بوادر إحساسه بالمسؤولية الاجتماعية. في كل مرة يحضر لكِ شيئًا، قولي له: "شكرًا جزيلًا، لقد ساعدتني كثيرًا". فهذا النوع من المديح يجعله يشعر بأنه نافع وقادر.') WHERE id = '5614d8e1-6798-45a7-8bfd-239e88293a49';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'ظهور مخاوف جديدة: قد يبدأ الأطفال في عمر 13-14 شهرًا فجأة بالخوف من صوت المكنسة الكهربائية أو الظلام أو الغرباء. ويرتبط ذلك بتطور خيال طفلكِ وفهمه للبيئة المحيطة. لا تسخري من خوفه، ولا تقولي له: "ما المخيف في ذلك؟". ابقي إلى جانبه فحسب، واحتضنيه، وأشعريه بالأمان. ستزول هذه المخاوف مع مرور الوقت.') WHERE id = '320f797a-413e-4747-8432-a77c70f8f1ae';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تطورت "مسكة الملقط" لدى طفلكِ إلى حد أنه أصبح قادرًا على تقليب صفحات الكتاب واحدة تلو الأخرى (الصفحات السميكة في الوقت الحالي). وهذا يعزز مهاراته الحركية الدقيقة واهتمامه بالكتب. واصلي قراءة الكتب ذات الصور الكبيرة والملونة له. وشجعيه على الكلام بأن تطلبي منه تسمية الأشياء التي يراها في الصور.') WHERE id = '3f0fc8bf-420a-4d0f-acf7-ab2d58fa2a4b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ الآن يحرّك جسمه بإيقاع أو يصفّق بيديه عندما يسمع الموسيقى. يرتبط الإحساس بالإيقاع ارتباطًا وثيقًا بمراكز الرياضيات واللغة في الدماغ. ارقصي معه وصفّقا معًا وجرّبا إيقاعات مختلفة. فهذا نشاط بدني ممتع، كما أنه يقوّي الرابط العاطفي بينكما.') WHERE id = '22fc8a33-8e0b-4e79-86f9-460a94db933b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'البوادر الأولى لـ"التعاطف" في التواصل الاجتماعي: عندما تبدين حزينة أو تصطدم قدمكِ بشيء، قد يأتي طفلكِ ليلمسكِ أو يعانقكِ أو يعطيكِ لعبته. وهذا يدل على أنه بدأ يشعر بمشاعر الآخرين. استجيبي لتصرّفه الحنون بقولكِ: "شكرًا لك، أنت لطيف جدًا". ففي هذا العمر تحديدًا تبدأ بذور التعاطف بالنمو.') WHERE id = '993a5a5e-046b-489d-bd9d-9580428e1cdc';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الذاكرة المكانية" والبحث: أصبح طفلكِ الآن يعرف أين أُخفيت لعبته المفضلة. العبي معه ألعاب اختباء وبحث أكثر تعقيدًا. ضعي اللعبة، مثلًا، داخل صندوق ثم غطّيه بمنشفة. إن تمكّنه من تجاوز العوائق والعثور على اللعبة ينمّي مهاراته في حل المشكلات. وهذه "الانتصارات" الصغيرة تعزّز ثقته بنفسه.') WHERE id = '63dfa4ff-f8c9-4a30-bd0e-f8d086dd0898';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تذكير بالسلامة: يرغب طفلكِ الآن في تسلّق كل شيء، مثل الأرائك والكراسي والرفوف... لكنه لا يدرك بعد تمامًا مخاطر الارتفاع والسقوط. تأكدي من تثبيت قطع الأثاث الثقيلة في الحائط وتركيب حواجز أمان عند السلالم. من المهم توفير بيئة آمنة له من دون كبح شغفه بالاستكشاف.') WHERE id = 'cc4b37ce-4e2e-4d58-a313-414b2395c5eb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة "التكرار" في تطوّر الكلام. قد يحاول طفلكِ تكرار المقاطع الأخيرة من الكلمات التي تقولينها. فعلى سبيل المثال، عندما تقولين "ماء"، قد يقول "اء" أو "ماء". تحدّثي معه دائمًا بلغة صحيحة وواضحة. إن استخدام الأسماء الحقيقية للأشياء بدلًا من الكلمات الطفولية يساعده على بناء حصيلة لغوية سليمة.') WHERE id = 'd1034aae-153e-40ef-b35f-875a226037db';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد أكملنا الشهر الثالث عشر! أصبح طفلكِ الآن يُظهر إرادته وشخصيته ومحبته بوضوح بوصفه طفلًا بدأ المشي. استلقي معه اليوم على الأرض واقضيا بعض الوقت في ممارسة لعبة يختارها هو. فكل لحظة ممتعة وقيّمة تقضينها معه هي أساس سعادته المستقبلية. أنتِ أم رائعة!') WHERE id = '4d58b019-ad51-4763-b775-1cff7a5c244e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تستمر مرحلة "الانتقائية" في تناول الطعام. فقد يرمي طفلكِ اليوم الطعام الذي أحبه بالأمس على الأرض. في هذه المرحلة، اتركي له تحديد "الكمية التي يريد تناولها"، بينما تحددين أنتِ "متى وماذا" سيأكل. اجعلي وقت الطعام ممتعًا وخاليًا من الإجبار. وتذكري أن معدته لا تزال صغيرة، وقد تكفيه بضع لقيمات فقط.') WHERE id = '853086ca-90b3-4556-bd83-70b66fd42f49';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'ظهور أول "المفاهيم المتضادة" في الكلام. فقد بدأ طفلكِ يفهم بصريًا وعن طريق اللمس الفروق بين مفاهيم مثل "كبير وصغير" و"ساخن وبارد". قارني بين الأشياء أثناء اللعب، قائلةً: "انظر، هذه كرة كبيرة، أما هذه فصغيرة". تساعد هذه الحوارات البسيطة على تنمية قدرته على التفكير المجرد وتوسيع حصيلته اللغوية بسرعة.') WHERE id = '8381dd6a-9188-4a53-b0c0-fe9e5722bee4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد يعود "قلق الانفصال" (Separation anxiety) على شكل موجات خلال هذه الأشهر. وبكاؤه عند مغادرتكِ الغرفة دليل على حاجته إليكِ. قولي له دائمًا قبل أن تذهبي: "إلى اللقاء، سأعود بعد قليل"، ولا تتسللي خفيةً. فصدقكِ يعزز لديه الثقة بأن "أمي حتى إن اختفت، فإنها ستعود حتمًا".') WHERE id = 'd51eadcf-ced3-43a7-a954-d65ad8f07d93';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'خطوة جديدة في المهارات الحركية الدقيقة: فتح الأغطية وإغلاقها. قد تكون العبوات البلاستيكية الفارغة وأغطيتها أكثر "الألغاز" تشويقًا لطفلكِ. إن تنسيق حركة أصابعه مع تركيزه لوضع الغطاء في مكانه الصحيح يُنشئ روابط عصبية جديدة في دماغه. اسمحي له باللعب بهذه الأدوات المنزلية البسيطة.') WHERE id = '6e7fc713-da58-436a-956b-2725c7ebe15b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ قادرًا على التعبير عن مشاعره جسديًا، كالصراخ أو الارتماء على الأرض أو احتضانكِ. وهذا يدل على أن قدرته على تنظيم انفعالاته لا تزال محدودة. عندما يغضب، انزلي إلى مستواه وانظري إليه وقولي: "أنت غاضب الآن، وأنا أتفهم ذلك"، وبذلك تساعدينه على تسمية مشاعره. فهذا يضع الأساس لقدرته على التحكم في مشاعره مستقبلًا.') WHERE id = '49f6d0be-6454-4212-a7b3-56294a93638b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'خلال مرحلة التسنين (إذ قد تبدأ الأضراس عادةً بالظهور في هذه الفترة)، قد تلاحظين زيادة إفراز اللعاب وألم اللثة. وقد يؤثر ذلك في نمط نومه وتناوله للطعام. قدّمي له عضّاضات التسنين أو شرائح فاكهة باردة يمكنه مضغها. وسيساعده حنانكِ وصبركِ على اجتياز هذه المرحلة المؤلمة براحة أكبر.') WHERE id = '48e458f5-c261-485d-bb67-d4e81e9a6931';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بالشهر الرابع عشر! سيطالب طفلكِ هذا الشهر بمزيد من "الاستقلالية" جسديًا وعاطفيًا. فقد أصبح يُظهر بوضوح إلى أين يريد الذهاب وما لا يريد تناوله. وهذه مرحلة مهمة في تطور شخصيته. امنحيه خيارات بسيطة خلال اليوم (مثلًا: "هل تأكل التفاح أم الكمثرى؟"). ستساعده فرصة الاختيار على تقليل نوبات اعتراضه وتعزيز ثقته بنفسه.') WHERE id = '05712130-29d6-4028-9cd7-1eeae1f8b5f6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ أكثر مهارة في تكديس الأشياء بعضها فوق بعض (مثل بناء برج بالمكعبات). وهذا ليس مجرد لعب؛ فهو يتعلم عن الجاذبية والتوازن والعلاقات المكانية. وعندما ينهار البرج، يبدأ في فهم علاقة "السبب والنتيجة". ادعمي هذه العملية الإدراكية المهمة بتقديم مكعبات مختلفة الأحجام والألوان له.') WHERE id = '0c30df46-8b8a-4974-a5d4-fa643bc0045f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'استعدي لـ"طفرة الكلمات" في تطور النطق! يتعلم طفلكِ الآن أصواتًا أو كلمات جديدة كل يوم. ويشير بإصبعه إلى الأشياء من حوله منتظرًا منكِ أن تسمّيها. وكلما سمّيتِ له الأشياء، نمت حصيلته اللغوية الاستقبالية (الكلمات التي يفهمها) بوتيرة أسرع من حصيلته التعبيرية (الكلمات التي ينطقها). تحدثي معه باستمرار، فهذه أفضل وسيلة لتسريع تطور نطقه.') WHERE id = '462a5499-02c0-46d8-9b87-781f37471081';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تبدأ مرحلة "إنه لي!". قد يرفض طفلكِ إعطاء ألعابه أو أغراضه للآخرين. وهذه هي البوادر الأولى لفهمه مفهوم "الملكية". لا تضغطي عليه بقولكِ "يجب أن تشارك"، لأنه لا يفهم بعد معنى المشاركة تمامًا. وبدلًا من ذلك، علّميه القواعد الاجتماعية من خلال توضيح كيفية تبادل الأدوار في اللعب ("الآن دورك، ثم دور أبيك").') WHERE id = 'bf0454b9-f968-4795-a96d-a48966050e5d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'النشاط البدني: يحاول طفلكِ الآن صعود الدرج (غالبًا زحفًا أو ممسكًا بيدكِ). وهذا يقوّي عضلات ساقيه ويحسّن تناسق حركاته. ابقي دائمًا إلى جانبه على الدرج، ولا تنسي استخدام بوابات الأمان. فصعود كل درجة يُعد بالنسبة إليه "إنجازًا" عظيمًا!') WHERE id = '6d0b9b84-0a2e-4b5d-941c-44ac3c78711f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الخطوة التالية نحو تناول الطعام والشراب باستقلالية: أصبح طفلكِ الآن قادرًا على شرب الماء من الكوب دون أن يسكبه تقريبًا. والشرب من كوب مفتوح يهيئ عضلات شفتيه ولسانه للنطق. إذا كنتِ لا تزالين تستخدمين زجاجة الرضاعة، فقد حان الوقت للتوقف عنها تمامًا. فهذا مهم جدًا لنمو الأسنان نموًا سليمًا وصحة الحنك.') WHERE id = '59bb00a9-cd0f-4293-859e-3a1c2a23e167';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'فن «الخربشة» لتنمية المهارات الحركية الدقيقة! أصبح طفلكِ قادرًا الآن على إمساك قلم الرصاص ورسم خطوط واضحة على الورق. وهذه هي أولى مراحل تنمية التآزر بين اليد والعين واكتساب المهارات التمهيدية للكتابة. أعطيه أقلام رصاص سميكة وآمنة للأطفال وأوراقًا كبيرة. وامدحي أولى «أعماله الإبداعية»، فهذا سيعزز اهتمامه بالفن.') WHERE id = '32044af7-f666-4ab4-a029-c8309f8e7a1b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح «التقليد» في السلوك الاجتماعي أكثر تعقيدًا الآن. فقد لا يكتفي طفلكِ بتقليدكِ، بل قد يقلد الأطفال الآخرين الذين يراهم، وحتى الشخصيات التلفزيونية. فعندما تنظفين المنزل، يرغب هو أيضًا في مسح شيء ما، وعندما تطبخين، يريد المشاركة في التحريك. أشركيه في «الأعمال المنزلية» بإعطائه مكنسةً للعب أو أوعيةً بلاستيكية. فهذا ينمّي لديه الشعور بالمسؤولية.') WHERE id = '0d48495d-8dfc-4d4f-a65f-4e2b54b5955c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد يحدث «تراجع في النوم» (اضطراب) خلال الليل. وغالبًا ما يرجع ذلك إلى اكتساب مهارات جسدية جديدة، مثل المشي بسرعة أكبر أو التسلق، أو إلى زيادة قلق الانفصال. إذا استيقظ طفلكِ ليلًا وناداكِ، فتوجهي إليه بهدوء، وطمئنيه من دون حمله، وساعديه على العودة إلى النوم. وسيساعد الحفاظ على روتين ثابت في تسهيل هذه المرحلة المؤقتة.') WHERE id = '15f626ab-5c76-4c8c-ba7f-675666d5bc7d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد أكملنا 400 يوم! إنه رقم مذهل. لم يعد طفلكِ مجرد «رضيع»، بل أصبح فردًا كاملًا من أفراد أسرتكم وأكثرهم نشاطًا، وله أفكاره وشخصيته وضحكته الخاصة. اصطحبيه اليوم في نزهة إلى حديقته المفضلة، وراقبي كيف يكتشف العالم بشغف كبير. أنتِ أقوى سند له وأحنّ معلمة في رحلته هذه. أحسنتِ يا أمي!') WHERE id = 'cc5a3ed7-bfca-476b-b299-2377ba4200f3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لقد تجاوزنا الآن المحطة المهمة المتمثلة في إكمال 400 يوم! قد يحاول طفلكِ في هذه الأيام خلع بعض ملابسه بنفسه، مثل قبعته أو جوربه. وهذه هي خطوته الأولى نحو اكتساب مهارات العناية بالذات. إذا أراد ارتداء شيء أو خلعه، فأمهليه الوقت ولا تستعجليه. إن رؤيته لنفسه قادرًا على إنجاز شيء بمفرده تعزز تقديره لذاته (الثقة بالنفس) أكثر من أي شيء آخر.') WHERE id = 'c405a38b-5463-4f2f-a8fe-555b36296982';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'ينتقل طفلكِ الآن من مرحلة «اللعب الوظيفي» إلى أولى بوادر «اللعب الرمزي». فقد «يطعم» دبه المحشو أو يضع دميته في الفراش. وهذا يدل على نمو خياله وشعوره بالتعاطف. شاركيه هذه الألعاب وقولي: «هل الدب جائع؟ هيا نطعمه قليلًا من الطعام المهروس». تسرّع هذه الألعاب نموه الاجتماعي والمعرفي.') WHERE id = 'a392702d-a437-4a73-9212-0aa4a4ef5685';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«دمج المقاطع» في الكلام: أصبح طفلكِ يدمج مقاطع مختلفة ليكوّن «جملًا» طويلة بلغته الخاصة. ورغم أنكِ لا تفهمين كلماته تمامًا، فإنه يقلّد نبرة حديث الكبار ببراعة. استمعي إليه باهتمام وأجيبيه قائلة: «حقًا؟ وماذا حدث بعد ذلك؟». يعزّز هذا «الحوار» رغبته في التعبير عن نفسه ويُثري حصيلته اللغوية في الدماغ.') WHERE id = '71d396d7-4d37-40f4-a3f7-9c1e6ac427ba';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الاستقلالية في تناول الطعام: أصبح طفلكِ متحمسًا لاستخدام الشوكة الآمنة للأطفال. ومحاولته التقاط قطع الفاكهة أو الخضراوات الطرية بالشوكة تطوّر التناسق بين يديه وعينيه بدرجة كبيرة. امنحيه هذه الفرصة حتى لو تسبب ذلك ببعض الفوضى على المائدة. فهذا يساهم في تنمية مهاراته الحركية وفي بناء علاقة إيجابية مع الطعام.') WHERE id = '333db3d2-14f1-4e63-a2dd-abc9df47ccf2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التصنيف» في التطور المعرفي: بدأ طفلكِ يميّز الأشياء ذات اللون نفسه أو التي تنتمي إلى النوع نفسه. أريه كرات أو سيارات مختلفة واسأليه: «أين الكرة الأخرى؟». سيبدأ في اكتشاف أوجه التشابه. وهذا أساس التفكير المنطقي لديه. العبي معه في المنزل لعبة تصنيف الأشياء وفقًا لألوانها أو أحجامها.') WHERE id = 'e2b8df1f-c1e3-4ba1-a168-83dfc3901148';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«حب المساعدة» في المهارات الاجتماعية: إذا أراد طفلكِ تقليدكِ بمسح شيء أو إحضاره، فأعطيه «مهام» صغيرة. قولي له مثلًا: «من فضلك، أعطني هذه الحفاضة». عندما يشعر بأنه يساعدكِ، فإنه يرى نفسه شخصًا كبيرًا ومفيدًا. وهذا مهم جدًا لتنمية حس المسؤولية وروح التعاون لديه في المستقبل.') WHERE id = 'dec6a9fe-e431-4948-b5e9-cde4811493c1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التطور الجسدي: بدأ طفلكِ يحاول القفز في مكانه أو الرقص على أنغام الموسيقى مع ثني ركبتيه. وهذا يقوّي إحساسه بالتوازن وعضلاته المسؤولة عن المهارات الحركية الكبرى. ارقصي معه وقلّدي حركاته. فهذا تمرين بدني، كما أنه من أكثر الأنشطة مرحًا وتعزيزًا للرابطة العاطفية بينكما.') WHERE id = 'f2ba7880-c8a0-44c4-9683-adcae62249c7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الإدراك المكاني» ومكعبات البناء: لم يعد طفلكِ يكتفي بتكديس المكعبات بعضها فوق بعض، بل بدأ يحاول صنع «جدران» أو أشكال بسيطة منها. قدّمي له مكعبات بناء بأحجام مختلفة. تنمّي هذه الألعاب إبداعه وقدرته على حل المشكلات. وعندما ينهار البرج، اضحكي وقولي: «هيا، لنحاول مرة أخرى!». فهذا يعلّمه ألّا يخاف من الإخفاق.') WHERE id = '3bcda1a7-5185-49d5-9cff-a4657ec214ad';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«انتكاسة» النوم الليلي أو المخاوف: في الشهر الرابع عشر، قد يبدأ بعض الأطفال بالخوف من الظلام أو البقاء بمفردهم. وهذا ناتج عن تطورهم المعرفي وفهمهم الأعمق لما يحيط بهم. حافظي على ثبات طقوس ما قبل النوم، مثل قراءة قصة أو غناء تهويدة. سيمنحه صوتكِ الهادئ والواثق رسالة مفادها: «كل شيء على ما يرام، أنت بأمان».') WHERE id = 'eff64bbb-3777-4339-9e6a-476beebba20d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد اجتزنا 410 أيام! أصبح طفلكِ يفاجئكِ بشيء جديد كل يوم؛ فإما أن يقول كلمة جديدة، أو يتعلم حركة جديدة. استلقي اليوم معه على الأرض، واقضيا بعض الوقت في ممارسة لعبة يختارها هو. دخولكِ إلى عالمه هو أكبر مصدر للسعادة بالنسبة إليه. أنتِ أم رائعة تسير في هذا الطريق بصبر وحب!') WHERE id = '21628582-4016-4734-a5cc-d731fc576c16';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لقد انغمس طفلكِ الآن تمامًا في عالم «أصوات الحيوانات». اطرحي عليه أسئلة مثل: «ما الصوت الذي يصدره الكلب؟» أو «ماذا تقول القطة؟». يساعد تقليد هذه الأصوات على تهيئة جهاز النطق، أي عضلات اللسان والشفتين، لنطق كلمات أكثر تعقيدًا مستقبلًا. أكثري من هذه الحوارات أثناء تصفح الكتب المصورة عن الحيوانات، واطلبي منه العثور على الحيوان في الصورة وتقليد صوته.') WHERE id = '1ba32438-5f06-49eb-a326-d4e6c5037f1b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ الآن أكثر ثقة في المشي بمفرده. وهو يتعلم الدوران في مكانه، والمشي إلى الخلف، أو الانحناء لالتقاط لعبة من الأرض أثناء المشي. وهذا تمرين معقد على التوازن. كلّفيه بتجاوز بعض العوائق، مثل الوسائد أو الصناديق الصغيرة. تساعد هذه العوائق البدنية على تعزيز مهاراته الحركية الكبرى وقدرته على حل المشكلات.') WHERE id = '67533bf8-42c4-4684-8990-79465e5ffca9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة «التسمية» في تطور النطق: أصبح طفلكِ قادرًا الآن على الإشارة إلى أجزاء جسمه، مثل الأنف والعين والفم. أثناء الاستحمام أو ارتداء الملابس، سمّي كل شيء بقولكِ مثلًا: «سنُدخل الآن يدك اليمنى في الكم» أو «هذا أنفك الصغير». يساعده ذلك على إدراك مخطط جسمه وربط الكلمات الموجودة في حصيلته اللغوية بصورها المرئية.') WHERE id = '616b6164-3d66-4e8e-8eaa-1c418d285de7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'فضّلي الألعاب التي توضّح علاقة «السبب والنتيجة». مثلًا، الألعاب التي تصدر صوتًا عند الضغط على زر، أو الصناديق التي يظهر شيء من داخلها عند فتح غطائها. يدرك طفلكِ أن أحد أفعاله يؤدي إلى حدوث تغيير في البيئة المحيطة به. ويُنمّي هذا الاكتشاف لديه الشعور بأنه «قادر على التأثير في العالم»، كما يعزز ثقته بنفسه.') WHERE id = '8d3ed7f3-9547-466c-ba26-2f33141101eb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في ما يتعلق بالتغذية، أصبح بإمكان طفلكِ تناول كل ما يُقدَّم تقريبًا على مائدة الأسرة، شرط أن يكون قليل الملح وخاليًا من الإضافات. امنحيه حرية استخدام شوكته وملعقته الصغيرتين بنفسه. إن لمس الطعام بيديه مباشرةً والتعرّف إلى قوامه يقللان من انتقائيته تجاه الطعام. من الطبيعي أن تتسخ المنطقة المحيطة به، فالأهم أن يكتسب مهارة تناول الطعام باستقلالية.') WHERE id = '724fdd08-1982-44c9-81ad-e2e9e494133c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مهارة "النَّظم" ضمن المهارات الحركية الدقيقة: أصبح طفلكِ يحاول نظم الخرز الكبير في خيط (تحت إشرافكِ!) أو إدخال الحلقات في لعبة الهرم. تعزز هذه الحركات تناسق عضلات الأصابع بدرجة كبيرة. قدّمي له حلقات بألوان وأشكال مختلفة، واذكري له أيضًا أسماء الألوان والأحجام (كبير-صغير).') WHERE id = '9a5df16b-402c-4293-a449-95f97975e102';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح "التقليد" في السلوك الاجتماعي أكثر وعيًا. فعندما تتحدثين عبر الهاتف، يمسك طفلكِ شيئًا ويضعه على أذنه، وعندما تمشطين شعركِ، يقلّد الحركة نفسها. بهذه الطريقة يتعلم طفلكِ طقوس الحياة اليومية. اسمحي له باللعب بأدوات منزلية آمنة، مثل مشط بلاستيكي أو هاتف لعبة، لتساعديه على اكتشاف العالم من حوله.') WHERE id = 'ffb2b034-66cc-4cea-967c-b8e6e4f363c4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبحت قراءة الكتب نشاطًا تفاعليًا. يرغب طفلكِ في تقليب الصفحات بنفسه، ويتفاعل بفرح مع الأشياء المألوفة التي يراها في الصور. وعندما تسألينه: "أين السيارة هنا؟" ويشير إليها بإصبعه، فهذا يدل على مدى تطور ذاكرته البصرية وانتباهه. اجعلي تخصيص بضع دقائق للقراءة كل مساء عادةً يومية.') WHERE id = 'c199a72c-c2fe-4afe-b5cc-41415b0a5808';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تذكير بالسلامة: أصبح طفلكِ ميّالًا جدًا إلى التسلق. فقد يستخدم الكراسي كدرجات ويصعد فوق الطاولة. تأكدي من تثبيت جميع قطع الأثاث الثقيلة في المنزل بالحائط، ومن تغطية الزوايا الحادة بوسائل الحماية. ينبغي أن تتوفر له حرية الحركة في بيئة آمنة، حتى تتمكني من مراقبته براحة من مسافة مناسبة.') WHERE id = '4ee9c2b3-c8ac-4ff5-98d9-426713c0d86e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"اختبار الإرادة" في التطور العاطفي: قد يحتج طفلكِ بالبكاء أو بإلقاء نفسه على الأرض عندما لا يحصل على ما يريد. في هذه المرحلة، يكون تحويل انتباهه إلى شيء آخر ممتع أكثر فاعلية من مجادلته. سمّي مشاعره بصوت هادئ قائلةً: "أنت غاضب الآن، لكن علينا إعادة اللعبة". هدوؤكِ هو أفضل قدوة له.') WHERE id = '3cd65486-2777-46ac-9963-b43596b260f8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبحت ذاكرة طفلكِ الآن قادرة على الاحتفاظ بالأحداث مدة أطول. فقد يتذكر مكان لعبة أخفيتِها قبل بضع ساعات، أو حتى قبل يوم، ويعثر عليها. العبي معه لعبة «اعثر على الشيء المفقود». فهذا يساعده على تنمية ذاكرته ومهارات البحث البصري لديه. وعندما يعثر عليه، امدحيه بحماس ليستمتع بالنجاح.') WHERE id = '41a34496-6a48-46a1-9bab-58d653fd4147';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تزداد محاولات طفلكِ لارتداء ملابسه بنفسه. فقد يحاول الآن إدخال قدمه في حذائه، أو وضع قبعته على رأسه، أو شد ساقي بنطاله. لا تعيقي هذه المحاولات ولا تستعجليه. وحتى إن ارتدى ملابسه بطريقة معكوسة، فقولي له: «لقد فعلت ذلك بنفسك، أحسنت!». فهذه هي اللبنات الأولى لاستقلاليته الشخصية.') WHERE id = '114533c6-2065-42b8-8349-baf02171f30b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرحلة الأولى من «تركيب الكلمات» في الكلام: قد يبدأ طفلكِ الآن بمحاولة جمع كلمتين معًا (مثلًا: «بابا، مع السلامة» أو «أعطني ماء»). وإذا لم يبدأ بعد بتركيب الكلمات، فكوني له قدوة. عندما يقول «سيارة»، أكملي عبارته بقولكِ: «نعم، سيارة كبيرة». فهذا يساعد دماغه على بناء التراكيب النحوية.') WHERE id = '66c20a78-018b-46e0-a413-b9d7d652fd0b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الحركي: أصبح طفلكِ الآن أكثر ثقة في المشي وهو يحمل شيئًا بيده. ويمكنه أن يمشي ويعرض عليكِ لعبته في الوقت نفسه. اصنعي له مسارًا بسيطًا مليئًا بالعوائق: كأن يلتف حول الوسائد الموضوعة على الأرض أو يخطو فوق صندوق منخفض. فهذا يقوّي توازنه وإحساسه بالتحكم في جسمه (الحس العميق).') WHERE id = '9f5b4f9d-6c12-455d-adaa-8991ef34a4ef';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة «أنا أختار بنفسي!». قدّمي لطفلكِ خيارين آمنين في ما يتعلق بالملابس أو الطعام. مثلًا: «هل تريد ارتداء الجوارب الزرقاء أم الحمراء؟». تمنحه هذه الطريقة شعورًا بالتحكم، وتساعد على الحد مسبقًا من نوبات العناد التي قد تظهر مستقبلًا. فالاختيار هو أساس مهارة اتخاذ القرار.') WHERE id = '3e2f13ff-1204-4de3-91f9-ba0a61eced52';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'ألعاب «التصنيف» لتنمية المهارات الحركية الدقيقة. قد يبدأ طفلكِ الآن بتصنيف المكعبات حسب لونها أو حجمها. أعطيه أوعية بألوان مختلفة، وعلّميه أن يضع الألعاب في الوعاء المطابق للونها. تساعد هذه اللعبة على تنمية تفكيره المنطقي وإدراكه للألوان بسرعة.') WHERE id = '1833bec9-62a3-4273-aaa3-6cb2d5b43918';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح صعود الدرج الآن من أكثر الأمور التي تثير اهتمام طفلكِ. وقد يصعده زحفًا أو واقفًا بينما تمسكين بيده. لا تقوّي هذه الحركة مهاراته الحركية الكبرى فحسب، بل تساعده أيضًا على إدراك الارتفاعات. ابقي دائمًا بجانبه عند الدرج، وتأكدي من إغلاق بوابات الأمان في المنزل.') WHERE id = '74e3ddee-b891-4ccd-91d8-7ed95452703e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ يرسم خطوطًا أكثر وضوحًا وثباتًا عندما «يشخبط» على الورق. وقد يحاول رسم حركات دائرية أو خطوط مستقيمة. أعطيه أوراقًا كبيرة وأقلام تلوين سميكة غير سامة يسهل عليه إمساكها براحة يده. فهذا من أهم الأسس لمهارات الكتابة المستقبلية والتنسيق بين اليد والعين.') WHERE id = '4d091261-3f36-4fe5-bf63-cb391c17abb5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة «سأفعل ذلك بنفسي!»: أصبح طفلكِ الآن متحمسًا لغسل يديه وتنظيف أسنانه (وإن كان لا يزال يكتفي بمضغ الفرشاة) أو مسح المائدة. شجّعي اهتمامه بعادات النظافة هذه. ضعي له مقعدًا صغيرًا ذا درجة ليتمكن من الوصول، واسمحي له بتقليد حركاتكِ. فهذا يساعده على اكتساب مهارات العناية بنفسه.') WHERE id = '1d418a62-b096-44ed-98d7-1fbf38ca6e83';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح «التقليد» في اللعب الاجتماعي أكثر تعقيدًا. فعندما تكنسين المنزل، يرغب طفلكِ أيضًا في الإمساك بشيء والكنس مثلكِ. أعطيه «أدوات تنظيف» صغيرة تناسب حجمه. إن «مساعدته» بهذه الطريقة في الأعمال المنزلية تجعله يشعر بأنه فرد مفيد في الأسرة، وتنمّي لديه حس المسؤولية.') WHERE id = '9c0e73ce-723f-4070-afbc-322de1ae0633';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«مكعبات البناء» في التطور المعرفي: أصبح طفلكِ الآن قادرًا على تكديس 3-4 مكعبات فوق بعضها لصنع «برج». ويتطلب ذلك التركيز والدقة معًا. عندما يسقط البرج، تفاعلي مع الأمر بمرح كي يتعامل مع الإخفاق على أنه جزء من اللعب. فهذا يعزز لديه مهارة حل المشكلات وروح المحاولة من جديد.') WHERE id = '80068b19-aaa1-4996-ba9d-5b3777ebce0c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الموسيقى والإيقاع: أصبح طفلكِ الآن يستجيب للإيقاعات المختلفة بحركات مختلفة؛ فيتحرك بنشاط أكبر مع الموسيقى السريعة، ويتمايل مع الموسيقى الهادئة. العبي معه ألعاب «مجاراة الإيقاع»؛ صفّقي بيديكِ واضربي بقدميكِ على الأرض. فهذا ينمّي قدرته السمعية وتناسق حركات جسمه بدرجة مذهلة.') WHERE id = '83fcfed7-5b83-4a68-8d79-7654a496f70e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'يزداد «التعاطف» في السلوك الاجتماعي. قد يشعر طفلكِ بالانزعاج عندما يرى طفلًا آخر يبكي، أو قد يقترب منكِ ويعانقكِ. وهذا يدل على أنه بدأ يشعر بمشاعر الآخرين. ساعديه على تسمية هذه المشاعر بعبارات مثل: «نعم، صديقك حزين قليلًا الآن». فالتعرّف إلى المشاعر هو الخطوة الأولى في تنمية الذكاء العاطفي.') WHERE id = 'da7ee871-54fe-4caf-9b11-def1fe5482db';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«استخدام الأدوات» أثناء تناول الطعام. أصبح طفلكِ الآن أكثر مهارة في غرز شوكة الأطفال (البلاستيكية/الطرية) في الطعام. قدّمي له قطعًا من الموز الطري أو الجزر المطهو ليغرز فيها الشوكة. يعزّز هذا النشاط التناسق بين اليد والعين، كما يحوّل تناول الطعام إلى «اختبار مهارات» ممتع بالنسبة إليه.') WHERE id = '451ba512-8b9d-44f7-915a-a7f1ea152f7c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تطوّر الخيال: «اللعب التخيلي» (التظاهر بأن شيئًا ما حقيقي). قد يتظاهر طفلكِ الآن بأنه «يشرب الماء» من كوب فارغ، أو يقلّد صوت سيارته اللعبة قائلًا: «فررر-فررر». شاركيه هذه الألعاب واسأليه: «إلى أين تذهب السيارة؟ إلى المتجر؟». فهذا يعزّز إبداعه وقدرته على إدراك الروابط المنطقية بين الأحداث.') WHERE id = '58538226-5b39-4731-8bc6-1e9881002e44';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الإرادة والحدود: أصبح طفلكِ الآن يستجيب لكلمة «لا»، لكنه قد يتعمّد أحيانًا تكرار الفعل نفسه وهو ينظر إليكِ. بهذه الطريقة يختبر مدى صبركِ وثبات القواعد. كوني هادئة ولكن حازمة. لا تسمحي في وقت آخر بشيء سبق أن قلتِ عنه «لا»، حتى تظل القواعد واضحة تمامًا في ذهنه.') WHERE id = 'ccb50bdf-5e11-4253-a1c0-79b7eb2fe4d0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'اكتشف طفلكِ الآن كيفية المشي إلى الخلف أو الدوران في مكانه. ترتقي هذه الحركات بإحساسه بالتوازن وتناسق حركات جسمه إلى مستوى جديد. وفّري له مساحة واسعة وخالية من العوائق ليجرّب فيها مهاراته الجديدة. وكلما ازدادت قدرته على التحكم في جسمه، تعزّزت ثقته بنفسه بالقدر نفسه.') WHERE id = '527b5771-2c14-44f3-9a1f-7d0335d59d5a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'كلمات «النية» في الكلام: لم يعد طفلكِ يكتفي بتسمية الأشياء، بل أصبح يعبّر أيضًا عن رغباته بكلمات مفردة. فمثلًا، قد يعني قوله «باب» وهو ينظر إليكِ: «أريد الخروج». وسّعي عباراته عند الرد عليه، فقولي: «نعم، أنت تشير إلى الباب، أليس كذلك؟ هيا نذهب إلى الفناء». فهذا يزيد حماسه للتواصل.') WHERE id = '1b9f532e-6857-454f-9361-0a20bbd28a5f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يعد طفلكِ يكتفي بجمع الأشياء، بل قد يبدأ أيضًا بتصنيفها حسب ألوانها. أعطيه وعاءين بلونين مختلفين، ووضّحي له كيفية وضع المكعبات ذات اللون نفسه في الوعاء المناسب. تساعد هذه اللعبة على تطوير إدراكه البصري وتفكيره المنطقي بسرعة. شجّعيه عند كل اختيار صحيح.') WHERE id = 'c99fbd76-3509-452c-bb85-8931e45ac6e6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تصبح محاولات ارتداء الملابس باستقلالية أكثر هادفية. قد يستطيع طفلكِ نزع جوربه بشدّه أو يحاول وضع قبعته على رأسه. امنحيه وقتًا لممارسة مهارات "العناية الذاتية" هذه. إن إتاحة الفرصة له لإنجاز شيء بنفسه من دون استعجاله تعزّز ثقته بنفسه أكثر من أي شيء آخر.') WHERE id = '2ee741f0-6ac8-462c-a88b-0f41a8cfe7f1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تطوّر الخيال: تبدأ ألعاب "التظاهر" (Pretend play). قد يتظاهر طفلكِ بالشرب من كوب لعبة فارغ أو يجعل دميته "تنام". هذه هي البوادر الأولى لتفكيره المجرّد. شاركيه هذه الألعاب وحفّزي خياله بأسئلة جديدة، مثل: "هل الدب جائع؟".') WHERE id = 'b84b66d1-b1ba-4c15-8fdd-579e274e0daa';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الرشاقة البدنية: يبدأ طفلكِ بمحاولة القفز في مكانه. قد لا ترتفع قدماه عن الأرض في الوقت نفسه بعد، لكنه يقلّد الحركة بثني ركبتيه ومدّهما. يُعدّ هذا تمرينًا ممتازًا لتقوية عضلات المهارات الحركية الكبرى وتعزيز إحساسه بالتوازن. ارقصي معه على أنغام موسيقى إيقاعية.') WHERE id = 'd53255ec-c9a7-49ab-9a79-7b2313a09598';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة "السؤال والجواب" في تطوّر الكلام. أصبح طفلكِ يشير إلى الأشياء قائلًا: "ما هذا؟" (أو يصدر صوتًا مشابهًا بطريقته الخاصة). سمّي له كل شيء بصبر: "هذه سيارة حمراء"، "هذه شجرة كبيرة". إن عدم ترك فضوله بلا إجابة يساعد على إثراء حصيلته اللغوية بفاعلية.') WHERE id = 'd7ddb1ff-3688-4df3-8111-1494d13b6470';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مهارة "إمساك القلم" ضمن تطوّر المهارات الحركية الدقيقة. يقترب طفلكِ الآن من إمساك قلم التلوين بأصابعه بدلًا من قبضة يده، ويرسم دوائر أو خطوطًا أكثر وضوحًا وثباتًا على الورق. أعطيه أقلام تلوين سميكة وآمنة للأطفال، ووسّعي مساحة "الإبداع" المتاحة له. فهذا هو أساس مهارات الكتابة مستقبلًا.') WHERE id = '785f6c05-389d-4b59-bf24-09d238f78a91';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التغذية: "كوبِي أنا". أصبح طفلكِ قريبًا من إتقان الشرب من كوب مفتوح دون أن يسكب الماء تقريبًا. أعطيه أكوابًا بلاستيكية بحجم مناسب للأطفال، ثابتة وغير قابلة للانقلاب بسهولة (ذات قاعدة ثقيلة). شربه الماء بنفسه يهيئ عضلات فكه للنطق ويعزز لديه الشعور بالاستقلالية.') WHERE id = 'cdcb59ac-ce34-4644-9101-dd165efadbd4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إدراك الفرق بين "أنا" و"أنتِ". عندما يرى طفلكِ نفسه في المرآة، لم يعد يتفاعل مع صورته على أنها "طفل آخر"، بل يدرك أنها صورته هو. إذا وضعتِ علامة صغيرة ملونة على أنفه وجعلتِه ينظر في المرآة، فسيحاول مسح العلامة عن أنفه. ويُعد ذلك من أهم الاختبارات التي تدل على تطور وعيه بذاته (self-awareness).') WHERE id = 'e44171a6-fe71-458b-9f01-6422077e41b3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"التعاون" في السلوك الاجتماعي: أصبح طفلكِ يستمتع بإحضار الأشياء إليكِ والوقوف بجانبكِ في المطبخ كي "يساعدكِ". أعطيه مهام صغيرة وآمنة، مثل: "هل يمكنك وضع هذه الورقة في سلة المهملات؟". عندما يشعر بأنه يساعدكِ، يزداد إحساسه بأهميته وقيمته كفرد.') WHERE id = 'd9f30f7c-bdc1-4054-b9fc-312496a93a19';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الشجاعة الجسدية: قد يتعلم طفلكِ الآن النزول من الأريكة إلى الأرض بمفرده، من خلال الاستدارة والنزول إلى الخلف. أريه كيف يفعل ذلك بأمان. تعلّمه النزول من مكان مرتفع بنفسه يعزز قدرته على التحكم بجسده وتحليل المخاطر. ابقي دائمًا بالقرب منه لحمايته ومساندته.') WHERE id = '594432bd-57c7-413f-839d-cbac2143ecbe';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'نوبات الانفعال و"نوبات الغضب". قد يغضب طفلكِ فجأة عندما يريد فعل كل شيء بنفسه ولا ينجح في ذلك. وينشأ هذا التوتر لأن رغباته لا تتوافق تمامًا بعد مع قدراته الجسدية. في مثل هذه اللحظات، احتضنيه وسمّي مشاعره بهدوء قائلةً: "أنت غاضب لأنك لم تتمكن من إصلاح اللعبة، وأنا أتفهم ذلك".') WHERE id = '52ab2a35-efc6-4dfa-ae8e-dd8d45265cbf';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"تكرار الكلمات" في تطور النطق. يحاول طفلكِ الآن أن يقول بطريقته شيئًا بعد كل كلمة تنطقين بها. وهذه أكثر مراحل تعلم اللغة نشاطًا. استخدمي أمامه جملًا بسيطة وقصيرة وواضحة، فأنتِ نموذجه الأساسي في الكلام. اقرئي معه اليوم قصته المفضلة، وحاولا العثور على التفاصيل الخفية في الصور.') WHERE id = '36237c33-88c9-45f0-bb2f-74a99cfea0e7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ يطالب بمزيد من الاستقلالية أثناء تناول الطعام، وبات أكثر مهارة في ملء ملعقته من طبقه. قدّمي له قطعًا صغيرة يمكنه غرز الشوكة فيها (مناسبة للشوكة). إن تناوله الطعام بنفسه يساعده على التعرّف إلى شعوره بالشبع ويزيد اهتمامه بالأطعمة ذات القوامات المختلفة.') WHERE id = '369e5ef8-dd84-4005-92a0-3547d1d81f03';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الحدود العاطفية: عندما تقولين لطفلكِ "لا"، قد يتعمّد الآن القيام بالفعل نفسه لاختبار رد فعلكِ. أهم ما يمكنكِ فعله في هذه المرحلة هو الحفاظ على هدوئكِ وحزمكِ. إذا قلتِ إن أمرًا ما "غير مسموح"، فكرّري ذلك في كل مرة بالنبرة والطريقة نفسيهما. ثبات القواعد يمنح طفلكِ شعورًا بالأمان والنظام.') WHERE id = '3b03f902-43dc-4352-9de9-99e2a04d004c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ يمشي بسرعة لدرجة أنه يحاول الركض أحيانًا. لكن نظرًا إلى أن قدرته على التوازن لم تكتمل بعد، فقد يسقط كثيرًا. وفّري له مزيدًا من المساحات المستوية والناعمة للاستكشاف، مثل السجاد أو العشب. ومحاولته الحفاظ على توازنه بمد ذراعيه إلى الجانبين أثناء الركض جزء طبيعي من نموه الجسدي.') WHERE id = 'd5bd999f-15a8-4225-95dc-a3e29ec9bb65';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تطور الذاكرة: أصبح طفلكِ يتذكّر الأماكن التي تنتمي إليها الأشياء. فهو يعرف مثلًا أن الأحذية في المدخل وأن الألعاب في الصندوق. وعندما تسألينه: "أين حذاؤك؟"، فإن نظره نحو مكانه أو إشارته إليه يدلّان على تطور قدراته الإدراكية. بعد انتهاء اللعب، أعيدا الألعاب إلى أماكنها معًا لتساعديه على اكتساب عادة الترتيب والانضباط.') WHERE id = '821949a4-99c0-456c-ba4e-1768b6ba56ba';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور النطق: "التمييز بين الحيوانات وأصواتها". لم يعد طفلكِ يكتفي بالتعرّف إلى الحيوان الذي يراه في الصورة، بل قد يقلّد صوته أيضًا من دون أن تسأليه. وعند قراءة كتاب، أطيلي الحوار بقولكِ: "انظر، هذه بقرة. ما الصوت الذي تصدره البقرة؟" فهذا يثري بسرعة ذاكرته السمعية وحصيلته اللغوية.') WHERE id = 'ca9adb43-fa2c-4743-a4c9-e39c4eb29777';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: "الرصّ والتركيب". أصبح طفلكِ قادرًا على رصّ 5-6 مكعبات فوق بعضها وبناء أبراج أعلى. كما أن محاولاته ترتيب الحلقات من الأكبر إلى الأصغر تنمّي إدراكه المكاني. هل ترين مدى استمتاعه بهدم البرج؟ إنه أبهج تعبير عن شعوره بأنه "قادر على تغيير العالم"، أي فهمه لعلاقة السبب والنتيجة.') WHERE id = 'c50f5774-0c5b-40a4-8f99-e817382c1b20';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«استخدام الأدوات بمهارة» أثناء تناول الطعام: أصبح طفلكِ أكثر دقة في غرس شوكة الأطفال في الطعام (مثل الخضراوات المطهية حتى تصبح طرية) ورفعها إلى فمه. تعزز هذه المهارة التنسيق بين اليد والعين، وتساعده أيضًا على الشعور بأنه شخص مستقل. امنحيه هذه الفرصة حتى لو تسبب ذلك ببعض الفوضى على المائدة.') WHERE id = '28156e7f-7e18-4b94-927c-a444469bee3e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الذاكرة المكانية» والبحث: أصبح طفلكِ قادرًا على تذكّر المكان الذي وضعتِ فيه لعبة قبل عدة ساعات والعثور عليها. العبي معه لعبة «العثور على الشيء المفقود». يعزز ذلك ذاكرته البصرية وقدرته على التركيز. وكل غرض يعثر عليه يُعدّ بالنسبة إليه انتصارًا صغيرًا في «مغامرة استكشافية».') WHERE id = '15ff0052-98cf-4d44-8277-9931b5bbd7bd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'يتزايد «التعاطف» في سلوك طفلكِ الاجتماعي. فعندما يرى أن شخصًا آخر (أو لعبته) «يتألم»، قد يعانقه أو يربّت عليه. وهذا يدل على أنه بدأ يفهم مشاعر الآخرين. ادعمي ذكاءه العاطفي بتسمية هذه المشاعر بعبارات مثل: «نعم، صديقك حزين قليلًا الآن».') WHERE id = '6c93684c-6781-4a11-bb15-1580d5f66d36';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: يتعلم طفلكِ الآن الدوران في مكانه والسير إلى الخلف. وهذا تمرين معقد على التوازن. وفّري له مساحة واسعة وخالية من العوائق ليجرّب فيها مهاراته الجديدة. وكلما ازدادت قدرته على التحكم في جسمه، قلّ خوفه من السقوط واتسع نطاق حركته.') WHERE id = '33b5778f-3fe2-440a-8f22-62f63b5a956d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تطور الخيال: تصبح ألعاب «التظاهر» (Pretend play) أكثر تعقيدًا. فقد يقلّد طفلكِ صوت سيارة اللعبة قائلًا «فررر-فررر»، أو يتظاهر بأنه «يأكل» من طبق فارغ. شاركيه هذه الألعاب وحفّزي خياله بأسئلة جديدة. فهذا يعزز إبداعه وقدرته على تكوين الروابط المنطقية.') WHERE id = 'd2fca029-5edb-4176-b69f-5a506afd4a61';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الإرادة والحدود: أصبح طفلكِ يستجيب لكلمة «لا»، لكنه قد يتعمد أحيانًا تكرار الفعل نفسه ثم ينظر إليكِ. إنه بذلك يختبر مدى صبركِ وثبات القواعد. كوني هادئة ولكن حازمة، فثبات القواعد يمنح طفلكِ شعورًا بالأمان والنظام.') WHERE id = '3e76b053-c97c-4476-b999-951be493bb64';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يعد طفلكِ يكتفي بجمع الأشياء، بل يحاول أيضًا تصنيفها حسب لونها. أعطيه وعاءين بلونين مختلفين، ووضّحي له كيفية وضع الألعاب في الوعاء المطابق للونها. تساعد هذه اللعبة على تطوير إدراكه البصري وتفكيره المنطقي بسرعة. شجّعيه عند كل اختيار صحيح ليزداد اهتمامه بالتعلّم.') WHERE id = '7aebe8cd-a4e5-44f9-8f57-fc363b89129a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الخطوة إلى الخلف" في التطور الحركي. لقد اكتشف طفلكِ الآن المشي إلى الخلف. وهذا تمرين معقّد على التوازن، ويُظهر مدى تطور تناسق حركات جسمه. أتيحي له مساحة آمنة وخالية من العوائق وذات أرضية ناعمة ليجرّب فيها هذه المهارة الجديدة. وكلما تحسّنت قدرته على التحكم في جسمه، ازدادت ثقته بنفسه بالقدر نفسه.') WHERE id = '23d55f43-944e-41ff-a1f0-31e749c5ea5d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"السؤال والفضول" في تطور الكلام. أصبح طفلكِ يشير إلى الأشياء قائلًا: "ما هذا؟" (أو يصدر صوتًا مشابهًا بطريقته الخاصة). سمّي له كل شيء بصبر: "هذه سيارة حمراء"، "هذه شجرة كبيرة". إن عدم ترك فضوله دون إجابة يساعد على إثراء حصيلته اللغوية، سواء الكلمات التي يفهمها أو التي يستخدمها.') WHERE id = '741cbef2-ffcd-4b10-9cdf-8e41aa164e28';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"المزاح" في السلوك الاجتماعي. هل يعطيكِ طفلكِ لعبته عن قصد ثم يسحبها فورًا ويضحك؟ يشير ذلك إلى بدء تطور حس الفكاهة لديه وقدرته على التفاعل الاجتماعي بمرح. شاركيه هذه "اللعبة" بحماس. فالضحك معًا يقوّي الرابطة العاطفية بينكما ويساعده على بناء ثقة إيجابية بنفسه.') WHERE id = '5a726b9c-27a1-4456-85ed-e5c0d76d2484';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الهرم والحلقات" في المهارات الحركية الدقيقة. أصبح طفلكِ الآن أكثر مهارة في ترتيب الحلقات من الأكبر إلى الأصغر (أو العكس). يطوّر هذا النشاط فهمه للأحجام (كبير وصغير)، كما يعزّز التناسق بين اليد والعين. اذكري له أسماء الألوان أيضًا أثناء ترتيب الحلقات.') WHERE id = '51378f6a-c746-490d-b2e3-d4da3d093685';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"أنا أشرب بنفسي". أصبح طفلكِ الآن قريبًا جدًا من إتقان شرب الماء من كوب مفتوح من دون أن يسكبه تقريبًا. أعطيه أكوابًا بلاستيكية بحجم مناسب للأطفال، ثابتة وغير قابلة للانقلاب بسهولة (ذات قاعدة ثقيلة). يساعده الشرب بنفسه على تهيئة عضلات شفتيه ولسانه للكلام، كما يعزّز شعوره بالاستقلالية.') WHERE id = '44c70121-397f-4987-8f6a-6aae583c01e5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ يستمتع بتنفيذ التعليمات البسيطة. فعندما تقولين له: «من فضلك، أحضر لي الكرة» أو «خذ قبعتك»، يستطيع فعل ذلك. وهذا يوضح مدى تطور لغته الاستقبالية (قدرته على الفهم). قدّمي له مهام صغيرة وممتعة لتنمية مهاراته اللغوية وشعوره بالمسؤولية.') WHERE id = '44a68c23-5478-40d4-a83c-2dc9f09d429d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'يصبح مفهوم «هذا لي!» أكثر وضوحًا. وقد يُظهر طفلكِ إصرارًا عندما لا يرغب في إعطاء لعبته المفضلة لشخص آخر. وهذا دليل على إدراكه لحدوده الشخصية. لا تجبريه على المشاركة، بل علّميه التناوب على استخدام الألعاب بقولكِ: «الآن دورك، ثم دور أبيك»، وبذلك تغرسين فيه الإحساس بالإنصاف في التعامل مع الآخرين.') WHERE id = '3dc015ff-56bb-4a43-b76e-ffb3ffd6a8c8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إتقان المهارات الحركية الدقيقة: لم يعد طفلكِ يكتفي بتكديس مكعبات البناء بعضها فوق بعض، بل يحاول ترتيبها جنبًا إلى جنب لصنع «قطار» أو «طريق». وهذا يدل على انتقال إدراكه المكاني إلى مستوى أكثر تعقيدًا. قدّمي له مكعبات بناء بأشكال مختلفة لتشجيع إبداعه.') WHERE id = '05f48dd1-b441-4a53-83ad-213693a97b1c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة «الانتقائية في تناول الطعام». قد يرفض طفلكِ فجأة بعض الأطعمة. ويرتبط ذلك بتطور براعم التذوق لديه ورغبته في إظهار إرادته. لا تجبريه على تناولها، بل قدّمي له الطعام الذي رفضه مرة أخرى بعد بضعة أيام بشكل مختلف (مثلًا على هيئة شرائح بدلًا من هريس). وحافظي على أجواء إيجابية على مائدة الطعام.') WHERE id = '01373d24-e28a-437e-998d-4ae78f2851c2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ يقوم بحركات أوسع عند «الخربشة» على الورق. كما يمسك قلم التلوين بثقة أكبر، ويحاول أحيانًا التمييز بين الألوان. قدّمي له أقلام تلوين سميكة وآمنة للأطفال، وأوراق رسم كبيرة. فهذه «الأعمال الفنية» الأولى قيّمة جدًا لتطوير التناسق بين اليد والعين، وكذلك للتعبير عن نفسه.') WHERE id = '10f5c993-c3c9-44f8-a870-3ed80a4cfbed';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح «التقليد» في السلوك الاجتماعي يشمل الأعمال اليومية أيضًا. فعندما تنظفين المنزل، يرغب طفلكِ في مسح شيء ما، وعندما تطهين، يريد هو أيضًا تحريك الطعام. أعطيه قطعة قماش صغيرة لإزالة الغبار أو مكنسة لعبة. فهذا يساعده على الشعور بأنه فرد مهم ونافع في الأسرة، وعلى اكتساب عادات مفيدة.') WHERE id = 'd75c2f77-0a11-4bee-830a-88006d025c3c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«صعوبة المشاركة» في السلوك الاجتماعي. في هذا العمر، يكون مفهوم «هذا لي» قويًا جدًا. عندما لا يرغب طفلكِ في إعطاء لعبته لطفل آخر، فهذا ليس أنانية، بل مرحلة من مراحل النمو. لا تجبريه على المشاركة، بل علّميه قاعدة «اللعب بالتناوب» من خلال تطبيقها أمامه. ومع مرور الوقت، سيتعلم هذه القاعدة الاجتماعية.') WHERE id = '634d745d-5157-4467-b6ab-326f97a6818e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«استخدام أدوات الطعام» أثناء تناول الطعام. أصبح طفلكِ الآن أكثر دقة في غرس شوكة الأطفال في الطعام، مثل الجزر أو البطاطس المطبوخة، ثم رفعها إلى فمه. تعزز هذه المهارة التنسيق بين اليد والعين، كما تساعده على الشعور بأنه فرد مستقل.') WHERE id = '3cb1db52-5d88-4edb-a3ab-0984a9450809';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التنقل في المكان»: يتعلم طفلكِ الآن المرور عبر الأماكن الضيقة، والزحف من تحت العوائق أو تخطيها. اصنعي في المنزل «مسار عوائق» صغيرًا باستخدام الوسائد والصناديق. سيساعده ذلك على إدراك أبعاد جسمه (الحس العميق) والتخطيط لحركاته.') WHERE id = '2b1c5f94-7b82-40ce-9f0d-d663053b5141';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الارتباط العاطفي: أصبح طفلكِ الآن يعبّر عن حبه لكِ بإيماءات أكثر وضوحًا، فقد يأتي فجأة ليعانقكِ أو يربّت على رأسكِ بحنان. بادليه الحنان نفسه. فهذا التبادل العاطفي هو أهم ما يغذي شعوره بالأمان وبأنه محبوب وذو قيمة.') WHERE id = 'de41f735-eeb7-4ab7-ab3c-cfc2d80548ba';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'ندخل الشهر السادس عشر! قد يستطيع طفلكِ الآن أن ينطق بوعي من 5 إلى 10 كلمات مختلفة إلى جانب «بابا» و«ماما». ورغم أنه قد لا ينطق الكلمات نطقًا صحيحًا تمامًا بعد، فإن لكل منها معنى محددًا. شجّعي كل محاولة يقوم بها، وأكّدي الكلمة غير المكتملة التي يقولها بجملة كاملة. فمثلًا، عندما يقول «سا»، أجيبيه: «نعم، هذه سيارة».') WHERE id = 'd807a9a4-6329-44cd-97d5-dae1bf4a8ff6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة جديدة في التطور الحركي: أصبح طفلكِ الآن قادرًا على صعود الدرج واقفًا عند إمساككِ بيده. تقوّي هذه الحركة عضلات الفخذين والحوض. ابقي دائمًا بجانبه عند الدرج وقدّمي له الدعم. ولا تنسي التأكد من إغلاق بوابات الأمان عند مداخل السلالم في المنزل.') WHERE id = '22600f5c-8f2a-4f8d-9f3c-76e5a5fcda2c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تنمية الخيال: لعبة «الطبخ». قد يتظاهر طفلكِ بأنه «يطبخ» شيئًا باستخدام أواني اللعب. شاركيه هذه الألعاب وقولي له: «هل تعطيني بعض الطعام أيضًا؟». يوضح ذلك مدى دقة ملاحظته لروتين الحياة اليومية وكيف ينمو خياله.') WHERE id = '0303ebf1-df3e-4e81-bd4e-6f1dea97c188';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الجرأة الجسدية: يحاول طفلكِ الآن تسلّق الدرجات المنخفضة أو حافة الأريكة بمفرده. ورغم تطور إدراكه للارتفاعات، فإنه لا يفهم المخاطر تمامًا بعد. ابقي دائمًا بالقرب منه لحمايته، وعلّميه طرق النزول الآمنة، مثل النزول إلى الخلف.') WHERE id = '4a36804a-6409-441e-bfa1-5d47aa7ddf64';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تمييز الحيوانات وأصواتها في تطور النطق. أصبح طفلكِ قادرًا على التمييز بين البقرة والقطة اللتين يراهما في الصور، ويمكنه تقليد صوتيهما دون أن تطلبي منه ذلك. وعندما تسألينه أثناء قراءة كتاب: «أين القطة هنا؟»، فإن إشارته إليها بإصبعه تدل على مدى تطور ذاكرته البصرية وانتباهه.') WHERE id = '48266b98-24f4-486a-8c86-5edb343f6455';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الحدود العاطفية وكلمة «لا». قد يغضب طفلكِ فجأة عندما يريد أن يفعل كل شيء بنفسه ولا ينجح في ذلك. في مثل هذه اللحظات، عانقيه وسمّي شعوره بهدوء قائلةً: «أنت غاضب لأنك لم تتمكن من ارتداء حذائك، وأنا أتفهم ذلك». هدوؤكِ هذا هو أفضل قدوة تعلّمه كيفية تنظيم مشاعره.') WHERE id = 'bd6e2ef7-be9f-49e8-9f5a-73c5aca2c6c7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بدأ طفلكِ الآن يُظهر ذوقه الخاص. فقد يختار بإصرار القميص الذي يريد ارتداءه أو الكتاب الذي يريد قراءته. امنحيه في هذه المرحلة فرصة «الاختيار المحدود»، كأن تقولي: «هل تريد ارتداء القميص الأحمر اليوم أم الأزرق؟». يمنحه ذلك شعورًا بالتحكم ويساعد على الوقاية من نوبات العناد مستقبلًا.') WHERE id = 'e2f29ee5-abb0-4ec5-8bfb-7fca6b238c4f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«إتقان الركض» في التطور الجسدي. أصبح طفلكِ الآن يحافظ على توازنه بصورة أفضل أثناء الركض، ويمكنه التوقف فجأة. يوضح ذلك مدى تطور قوة عضلاته والتنسيق بين دماغه وعضلاته. وفّري له في الحديقة أو الفناء مساحات خالية من العوائق ليركض فيها ويفرّغ طاقته.') WHERE id = '85cc1293-16e0-49cd-904b-171804ae1853';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«تركيب الكلمات» في الكلام. أصبح طفلكِ الآن يجمع كلمتين معًا لتكوين جمل بسيطة مثل: «أبي، تعال»، «أعطني تفاحة». وإذا لم يبدأ بعد بربط الكلمات، فوسّعي أنتِ الكلمة المفردة التي يقولها: «نعم، هل تريد تفاحة؟ تفضل، هذه تفاحة لذيذة لك». يساعد ذلك على ترسيخ التراكيب النحوية في دماغه.') WHERE id = '3ec1877f-e8dc-4ba3-893d-678bde1927b1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة «Puzzle» (الأحجية) في المهارات الحركية الدقيقة. يتعلم طفلكِ الآن تركيب أحجيات بسيطة مكونة من 2-3 قطع أو إدخال الأشكال في الفتحات المطابقة لها. تعزز هذه اللعبة إدراكه البصري وقدرته على حل المشكلات إلى حد كبير. وإذا لم ينجح، فساعديه بهدوء وشجعيه.') WHERE id = 'b4b1a4bc-e49d-4497-b688-464c24f79875';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«اللعب المتوازي» في السلوك الاجتماعي. عندما يكون طفلكِ مع أطفال آخرين، فإنه لا يلعب معهم، بل يلعب بمفرده إلى جانبهم. وهذا طبيعي تمامًا في الشهر السابع عشر. فهو يتعلم الكثير من خلال مراقبة الأطفال الآخرين. واصلي اصطحابه إلى أقرانه كي يتكيف مع البيئة الاجتماعية.') WHERE id = '0d8b6018-4d34-41fe-ad70-9143e9c2615f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«أنا أغسل نفسي بنفسي». أثناء الاستحمام أو غسل اليدين، يمسك طفلكِ الصابون أو إسفنجة الاستحمام ويحاول تنظيف نفسه. ادعمي اهتمامه بعادات النظافة الشخصية. إن محاولته «تنظيف» نفسه تساعده على التعرف بشكل أفضل إلى أجزاء جسمه وتعزز شعوره بالاستقلالية.') WHERE id = '3c2bb527-c368-4b69-94c1-76665087b2b9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تقوية الذاكرة: «الأشياء المفقودة». يستخدم طفلكِ طرقًا متعددة للعثور على اللعبة التي أخفيتِها – فيرفع الغطاء وينظر داخل الصندوق. وهذا يدل على أن مفهوم «ديمومة الكائن» قد ترسخ لديه تمامًا. درّبي انتباهه من خلال لعب ألعاب «البحث عن الكنز» الصغيرة معه في المنزل.') WHERE id = 'd0afa5e2-c732-43e9-af9d-2f3d19c36c4e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الخيال و«الأعمال المنزلية». «يتحدث» طفلكِ بهاتفه اللعبة أو يكنس الأرض بمكنسة لعبة. إنه يقلد كل حركة تقومين بها. وهذه المحاكاة هي طريقته في التعرف إلى العالم. امنحيه «أدوات عمل» صغيرة خاصة به، وأتيحي له فرصة الشعور بأنه مهم.') WHERE id = '9dfb3516-1999-4989-989e-9e6fdb3fb9e5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التوازن والتنسيق: بدأ طفلكِ يحاول القفز في مكانه. قد لا يتمكن بعد من رفع كلتا قدميه عن الأرض في الوقت نفسه، لكن ثني ركبتيه والتأرجح صعودًا وهبوطًا يدل على تطور مهاراته الحركية الكبرى. ارقصي معه على أنغام موسيقى إيقاعية. فهذا تمرين ممتع ومفيد جدًا من الناحية البدنية.') WHERE id = '47585bf0-21b2-4948-bcc0-cc0d44631bdd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التعارض بين "الرغبة والقدرة" في التطور العاطفي: عندما يرغب طفلكِ في فعل شيء ولا ينجح فيه، فقد يصرخ أو يغضب. في مثل هذه اللحظات، حافظي على هدوئكِ وعبّري عن مشاعره بالكلمات: "أنت غاضب لأن المكعبات سقطت، أنا أتفهم ذلك". يساعده تفهّمكِ هذا على تعلم تنظيم مشاعره وعدم الاستسلام للإحباط عند مواجهة الصعوبات.') WHERE id = 'a0a20bce-4839-4117-9368-c41ef5150778';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يعد طفلكِ يكتفي بالإشارة إلى أجزاء جسمه (اليد، القدم، البطن)، بل يحاول أيضًا نطق أسمائها. أثناء إلباسه، اسأليه: "أين بطنك؟" وامنحيه وقتًا للإجابة. هذا تمرين ممتاز يساعده على إدراك مخطط جسمه وتنشيط حصيلته اللغوية.') WHERE id = '9f429553-7b9f-4533-9a8c-fa277c16a3ea';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تظهر رغبة طفلكِ في الاستقلال عند ارتداء الملابس. فقد يسحب جوربه ويخلعه، أو يحاول وضع قبعته على رأسه. لا تعيقي محاولاته هذه في "الاعتماد على النفس". إن إتاحة الفرصة له لإنجاز بعض الأمور بنفسه، من دون استعجاله، تعزز تقديره لذاته أكثر من أي شيء آخر.') WHERE id = 'eb7b56da-4f69-416f-ae1f-039fef91ef94';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تظهر في كلام طفلكِ بوادر أولى لتكوين "عبارات من كلمتين": فقد أصبح قادرًا على جمع كلمتين معًا (مثلًا: "أبي، تعال" أو "أعطني ماء"). وإذا لم يبدأ بعد بدمج الكلمات، فكوني قدوة له. عندما يقول "كرة"، أكملي العبارة قائلة: "نعم، كرة كبيرة". يساعد ذلك دماغه على بناء التراكيب النحوية.') WHERE id = '6753f0e0-f84e-40f2-a42e-a2fc56030ffe';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المهارات الحركية الدقيقة و"صفحات الكتب": أصبح طفلكِ أكثر مهارة في تقليب الصفحات السميكة المصنوعة من الورق المقوّى، صفحة تلو الأخرى. قدّمي له كتبًا تفاعلية تحتوي على عناصر حسية يمكن لمسها واستكشافها. إن تقليبه الصفحة بنفسه يمنحه شعورًا بالاستقلالية، ويدرّب في الوقت نفسه عضلات أصابعه الصغيرة استعدادًا للكتابة.') WHERE id = 'ed122971-473f-43f3-a24c-a44303a6f746';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'علامات «التعاطف» في السلوك الاجتماعي. عندما يلاحظ طفلكِ أنكِ حزينة أو أنكِ تألمتِ بسبب ارتطامكِ بشيء ما، فقد يقترب منكِ ويلامسكِ، بل وربما يعانقكِ. وهذا يدل على أنه بدأ يشعر بمشاعر الآخرين. ساعديه على تسمية هذه المشاعر بقولكِ: «شكرًا جزيلًا لأنك ساندتني». فهذا هو أساس الذكاء العاطفي.') WHERE id = '3a9d7d72-ab6c-4777-b054-a56b8986ee74';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«العناية بالنظافة بنفسه». يسعى طفلكِ إلى تقليدكِ بغسل يديه أو مسح وجهه أو تنظيف أسنانه بالفرشاة (وإن كان يكتفي حاليًا بمضغها). لا تكبتي رغبته في الاستقلالية. ضعي له درجًا صغيرًا ليتمكن من الوصول، واسمحي له بتقليد حركاتكِ. فهذا يساعده على اكتساب مهارات العناية بنفسه.') WHERE id = '090f40d7-6abc-46b1-8914-c34325dbcaa0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الذاكرة و«الذاكرة المكانية». أصبح طفلكِ يتذكر لفترة طويلة المكان الذي أُخفيت فيه لعبته. العبي معه في المنزل ألعابًا صغيرة للبحث عن «الكنز». أخفي غرضًا تحت غطاء وراقبيه وهو يعثر عليه. تعلّمه هذه الألعاب التركيز وإيجاد حلول للمشكلات.') WHERE id = '0bfe8ad5-dcd4-46e4-af49-e5c2a87c763e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تطور الخيال: «اللعب التخيلي» (Pretend play). أصبح طفلكِ قادرًا على التظاهر بأنه «يشرب الشاي» من كوب فارغ أو «يطعم» دميته. شاركيه هذه الألعاب. فهذا النوع من اللعب يسرّع نمو إبداعه وفهمه لروتين الحياة اليومية.') WHERE id = '9a097c94-eb06-4b23-b839-a6859f4ee3f2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الشجاعة الجسدية: «التسلق والنزول». أصبح طفلكِ يحاول بمفرده تسلق الدرجات المنخفضة أو حافة الأريكة. وعلى الرغم من تطور إدراكه للارتفاعات، فإنه لا يزال غير قادر على فهم المخاطر بالكامل. علّميه دائمًا أن النزول إلى الخلف أكثر أمانًا. وممارسة هذه المهارات تحت إشرافكِ تعزز قدرته على التحكم بجسمه.') WHERE id = '0f9b9189-8ffa-4276-919f-031f8673dbe8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الحدود العاطفية وكلمة «لا». أصبح طفلكِ يستجيب لكلمة «ممنوع»، لكنه قد يتعمد أحيانًا تكرار الفعل نفسه ثم ينظر إليكِ. إنه بذلك يختبر مدى صبركِ وثبات القواعد. كوني هادئة ولكن حازمة. فثبات القواعد يمنح طفلكِ شعورًا بالأمان والنظام.') WHERE id = '3fbc8bef-6814-4548-b448-0883b201e56d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الجرأة الجسدية: "إتقان التسلّق". أصبح طفلكِ الآن متحمسًا جدًا لصعود الدرج بمفرده (ولو أنه لا يزال يفعل ذلك حبوًا أو ممسكًا بيدكِ). ومع تطور إدراكه للارتفاعات، من الضروري أيضًا تعليمه كيفية النزول. أريه دائمًا أن النزول إلى الخلف أكثر أمانًا.') WHERE id = '15095e09-193b-4e26-bc2e-4f81de7c413d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد أتممنا 500 يوم! لقد تجاوز طفلكِ الآن مرحلة الرضاعة تمامًا وأصبح طفلًا صغيرًا له شخصيته وإرادته الخاصة. اقضي معه اليوم وقتًا في ممارسة نشاط يحبه (مثل الرسم أو التنزه في الحديقة). صبركِ وحبكِ هما أعظم قوة أوصلته إلى هذه المرحلة. أحسنتِ أيتها الأم!') WHERE id = '3427ae53-cf26-4b28-928a-b9787dc9cf32';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ الآن يؤكد مفهوم "الأنا" من خلال تصرفاته. فرغبته في اختيار ملابسه أو تناول طعامه بنفسه علامة على الاستقلالية. أتيحي له هذه الفرصة: "أي قميص تريد أن ترتدي؟". إن منحه خيارات بسيطة ينمّي قدرته على اتخاذ القرارات ويقلل أيضًا من نوبات العناد.') WHERE id = '1f190c82-9146-4726-b79a-d4e22c530f6d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الحركة الجسدية: "تجاوز العقبات". يتعلم طفلكِ الآن تخطي الألعاب والوسائد الموضوعة على الأرض أو الالتفاف حولها. وهذا يعكس تطورًا متقدمًا في الإدراك المكاني. أنشئي له عقبات آمنة في المنزل لتدريب توازنه وقدرته على التحكم في جسمه.') WHERE id = '0762347b-3e67-4f92-a1cc-28fc730be874';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور النطق: "معنى الكلمات". لم يعد طفلكِ يكرر الكلمات فحسب، بل أصبح يستخدمها بما يناسب المواقف المحددة. فعلى سبيل المثال، عندما ترتدين حذاءكِ، قد يقول: "نخرج". وسّعي عباراته بالرد عليه: "نعم، سنرتدي حذاءنا الآن ونذهب إلى الحديقة". فهذا يعزز في دماغه الصلة بين الأحداث والكلمات.') WHERE id = '32725b0c-885a-420b-8b00-82ddb5c437d8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: "التصميم والبناء". لم يعد طفلكِ يكتفي بتكديس المكعبات بعضها فوق بعض، بل يحاول استخدامها لصنع أشكال أفقية مثل "قطار" أو "سياج". وهذا يدل على انتقال تفكيره المكاني إلى مرحلة جديدة. قدّمي له ألعاب تركيب بأشكال مختلفة لدعم خياله.') WHERE id = 'd22bf585-b849-4796-8341-19d360ee9434';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تنمية الخيال: لعبة "الطبخ". قد يتظاهر طفلكِ بأنه "يطبخ" شيئًا باستخدام أواني اللعب. انضمي إليه في هذه الألعاب وقولي: "هل تعطيني قليلًا من الطعام أيضًا؟". يوضح ذلك مدى دقة ملاحظته لطقوس الحياة اليومية وكيف ينمو خياله.') WHERE id = '54cd9ab8-e1d5-4a0e-ab3a-58d28bf66df0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الجرأة الجسدية: يحاول طفلكِ الآن صعود الدرجات المنخفضة أو حافة الأريكة بمفرده. وعلى الرغم من تطور إدراكه للارتفاعات، فإنه لا يفهم المخاطر تمامًا بعد. ابقي دائمًا بالقرب منه لحمايته، وعلّميه طرق النزول الآمن، مثل النزول إلى الخلف.') WHERE id = 'b93116ed-f9b5-4701-8c1f-2fc127b8352c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور النطق: "التمييز بين الحيوانات وأصواتها". أصبح طفلكِ قادرًا على التمييز بين البقرة والقطة اللتين يراهما في الصور، ويمكنه تقليد صوتيهما من دون أن تطلبي منه ذلك. وعندما تسألينه أثناء قراءة كتاب: "أين القطة هنا؟"، فإن إشارته إليها بإصبعه تدل على أن ذاكرته البصرية تزداد قوة.') WHERE id = 'dcd3b6fa-3aa2-4a2f-98c6-4125a36e33d1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الحدود العاطفية وكلمة "لا". قد يغضب طفلكِ فجأة عندما يريد فعل كل شيء بنفسه ولا ينجح في ذلك. في هذه اللحظات، يمكنكِ احتضانه وتسمية شعوره بهدوء قائلة: "أنت غاضب لأنك لم تستطع ارتداء حذائك، وأنا أتفهم ذلك". هدوؤكِ هذا هو أفضل قدوة تعلّمه كيفية إدارة مشاعره.') WHERE id = '352efc53-2735-4313-8ef5-1cd93238bca8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'نخطو الخطوة الأولى نحو الشهر 18، أي نحو عمر عام ونصف! أصبح طفلكِ الآن يحافظ على توازنه بشكل أفضل أثناء الركض، ويمكنه التوقف متى شاء. وهذا تطور كبير في قوته الجسدية وفي التنسيق بين الدماغ والعضلات. وفّري له مساحة خالية من العوائق للركض في الحديقة أو الفناء، حتى يتمكن من تفريغ طاقته بطريقة صحية.') WHERE id = '20741f1b-1447-4efb-94f4-6f3a4844a16e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'يتسارع تطور "تركيب الكلمات" في النطق. أصبح طفلكِ يجمع كلمتين للتعبير عن طلبات أكثر تعقيدًا، مثل: "بابا، تعال"، "أعطني تفاحة"، "الكرة، أين؟". وإذا لم يبدأ بتركيب الكلمات بعد، فلا تقلقي؛ حوّلي كلماته المفردة إلى جمل عند الرد عليه: "نعم، هل تريد الكرة؟ تفضل، هذه كرتك الحمراء".') WHERE id = '81c4a684-a911-49c4-a9d7-1699f6fa7902';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يعد طفلكِ يكتفي بجمع الأشياء، بل يحاول أيضًا تصنيفها حسب اللون. أعطيه وعاءين بلونين مختلفين، ووضّحي له كيفية وضع الألعاب في الوعاء المطابق للونها. تساعد هذه اللعبة على تطوير إدراكه البصري وتفكيره المنطقي بسرعة. شجّعيه عند كل اختيار صحيح.') WHERE id = 'be0ade15-5544-47ec-9b0f-c9482045c9e8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الخطوة إلى الخلف" في التطور الحركي. لقد اكتشف طفلكِ الآن كيفية المشي إلى الخلف. وهذا تمرين معقّد للتوازن، ويُظهر مدى تطور التناسق الحركي لديه. أتيحي له مساحة آمنة وخالية من العوائق وذات أرضية لينة ليجرّب هذه المهارة الجديدة. وكلما تحسّنت قدرته على التحكم في جسمه، ازدادت ثقته بنفسه.') WHERE id = '4090fd14-b660-4e63-9f79-fd22a575576f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"السؤال والفضول" في تطور الكلام. أصبح طفلكِ يشير إلى الأشياء قائلًا: "ما هذا؟" (أو يصدر صوتًا مشابهًا بلغته الخاصة). سمّي له كل شيء بصبر: "هذه سيارة حمراء"، "هذه شجرة كبيرة". إن حرصكِ على الإجابة عن فضوله يساعد على إثراء مفرداته الاستيعابية والتعبيرية.') WHERE id = '4d85c160-6a89-4bf6-8f45-da46fe9e61c0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"المزاح" في السلوك الاجتماعي. هل يتعمّد طفلكِ تقديم اللعبة لكِ ثم يسحبها فورًا ويضحك؟ يدل ذلك على بدء تطور حس الفكاهة لديه وقدرته على التفاعل الاجتماعي. شاركيه هذه "اللعبة" بحماس. فالضحك معًا يقوّي الرابطة العاطفية بينكما ويساعده على بناء ثقة إيجابية بنفسه.') WHERE id = '843dc844-89cf-4311-8b84-968a8aaa47d1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الهرم والحلقات" في المهارات الحركية الدقيقة. أصبح طفلكِ أكثر مهارة في ترتيب الحلقات من الأكبر إلى الأصغر (أو العكس). يطوّر هذا النشاط فهمه للأحجام (كبير وصغير)، كما يعزّز التناسق بين اليد والعين. اذكري أيضًا أسماء الألوان أثناء ترتيب الحلقات.') WHERE id = 'da06e49e-5a35-41bf-9d03-b1f30db1e3f3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"أنا أشرب بنفسي". أصبح طفلكِ قريبًا جدًا من إتقان الشرب من كوب مفتوح من دون أن يسكب الماء تقريبًا. أعطيه أكوابًا بلاستيكية بحجم مناسب للأطفال، ثابتة وغير قابلة للانقلاب بسهولة (ذات قاعدة ثقيلة). يساعده الشرب بنفسه على تهيئة عضلات الشفتين واللسان للكلام، ويعزّز شعوره بالاستقلالية.') WHERE id = '7672591f-bef4-411a-94a3-365d4ae118a3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المهارات الحركية الدقيقة: "الهرم والحلقات". أصبح طفلكِ أكثر مهارة في ترتيب الحلقات من الأكبر إلى الأصغر (أو العكس). يساعده هذا النشاط على تطوير فهمه للأحجام (كبير وصغير)، وكذلك التنسيق بين اليد والعين. اذكري أيضًا أسماء الألوان أثناء ترتيبه للحلقات.') WHERE id = '90eaad7f-688e-4fd5-ac4b-58ae26fd12fd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"أنا أشرب بنفسي". أصبح طفلكِ قريبًا جدًا من القدرة على شرب الماء من كوب مفتوح دون أن يسكبه تقريبًا. قدّمي له أكوابًا بلاستيكية بحجم مناسب للأطفال، ثابتة وذات قاعدة ثقيلة. يساعد شربه الماء بنفسه على تهيئة عضلات شفتيه ولسانه للنطق، ويعزز شعوره بالاستقلالية.') WHERE id = 'ee6a42af-cce1-4d37-af51-df5adf60a403';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تطور الخيال: لعبة "الطبخ". قد يتظاهر طفلكِ بأنه "يطبخ" شيئًا باستخدام أواني اللعب. شاركيه هذه الألعاب وقولي له: "هل تعطيني بعض الطعام أيضًا؟". يوضح ذلك مدى دقة ملاحظته لروتين الحياة اليومية وكيف ينمو خياله.') WHERE id = 'f1803978-8c6d-4ba6-919b-9d07f71e4f23';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الجرأة الجسدية: أصبح طفلكِ يحاول تسلق الدرجات المنخفضة أو حافة الأريكة بمفرده. وعلى الرغم من تطور إدراكه للارتفاعات، فإنه لا يزال غير قادر على فهم المخاطر بالكامل. ابقي دائمًا بالقرب منه لحمايته، وعلّميه طرق النزول الآمنة (مثل النزول إلى الخلف).') WHERE id = '992522f4-e329-4100-a785-ed11e118cc9d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور النطق: "التمييز بين الحيوانات وأصواتها". أصبح طفلكِ يميّز بين البقرة والقطة اللتين يراهما في الصورة، ويمكنه تقليد صوتيهما من دون أن تطلبي منه ذلك. وعندما تسألينه أثناء قراءة كتاب: "أين القطة هنا؟"، فإن إشارته إليها بإصبعه تدل على أن ذاكرته البصرية تزداد قوة.') WHERE id = 'a6dfa03f-81ed-42c6-9520-9c6097e0b191';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الحدود العاطفية وكلمة "لا". عندما يرغب طفلكِ في فعل كل شيء بنفسه ولا ينجح، فقد يغضب فجأة. في مثل هذه اللحظات، احتضنيه وسمّي مشاعره بهدوء قائلة: "أنت غاضب لأنك لم تتمكن من ارتداء حذائك، وأنا أتفهم ذلك". هدوؤكِ هذا هو أفضل قدوة تعلّمه كيفية التحكم في مشاعره.') WHERE id = 'fe5d769a-36f6-497a-abae-90604ca433b9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور النطق: «التمييز بين الحيوانات وأصواتها». أصبح طفلكِ قادرًا على التمييز تمامًا بين البقرة والقطة اللتين يراهما في الصور، ويمكنه تقليد صوتيهما من دون أن تطلبي منه ذلك. وعندما تسألينه أثناء قراءة كتاب: «أين القطة هنا؟»، فإن إشارته إليها بإصبعه تدل على مدى تطور ذاكرته البصرية وانتباهه.') WHERE id = 'c66b2427-57b0-459e-a0a3-0cf6bedf7007';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الحدود العاطفية وكلمة «لا». قد يغضب طفلكِ فجأة عندما يرغب في فعل كل شيء بنفسه ولا ينجح في ذلك. في مثل هذه اللحظات، عانقيه وعبّري بهدوء عن مشاعره قائلةً: «أنت غاضب لأن المكعبات سقطت، وأنا أتفهم ذلك». يساعده تفهّمكِ على تعلم تنظيم مشاعره وعدم الاستسلام للإحباط عند مواجهة الصعوبات.') WHERE id = 'a52afb36-cf2f-4e94-8f57-7e002290fbaf';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بدأ طفلكِ يحاول تصنيف الأشياء وفقًا لألوانها. أعطيه وعاءين بلونين مختلفين، ووضّحي له كيفية وضع الألعاب ذات اللون نفسه في الوعاء المناسب. تسهم هذه اللعبة في تطوير إدراكه البصري وتفكيره المنطقي بسرعة. شجّعيه عند كل اختيار صحيح ليزداد اهتمامه بالتعلم.') WHERE id = '59526637-405e-4f57-afc2-14b281d0bec6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور الحركي: «المشي إلى الخلف». اكتشف طفلكِ الآن كيفية المشي إلى الخلف. وهذا تمرين معقد على التوازن، ويدل على مدى تطور التناسق الحركي لديه. أتيحي له مساحة آمنة وخالية من العوائق وذات أرضية لينة ليجرّب فيها هذه المهارة الجديدة. وكلما تحسنت قدرته على التحكم في جسمه، ازدادت ثقته بنفسه.') WHERE id = '75475781-7679-4745-947b-4230a1dabd3f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور النطق: «الأسئلة والفضول». أصبح طفلكِ يشير إلى الأشياء قائلًا: «ما هذا؟» (أو يصدر صوتًا مشابهًا بلغته الخاصة). سمّي له كل شيء بصبر: «هذه سيارة حمراء»، «هذه شجرة كبيرة». إن حرصكِ على الإجابة عن فضوله يساعد على إثراء حصيلته اللغوية، سواء الكلمات التي يفهمها أو التي يستخدمها.') WHERE id = '428ddabc-76ae-4dd9-8955-566bc3b0021c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: «المزاح». هل يناولكِ طفلكِ اللعبة عن قصد، ثم يسحبها فورًا ويضحك؟ يدل ذلك على بدء تطور حس الدعابة لديه وقدرته على التفاعل الاجتماعي والتأثير في الآخرين. شاركيه هذه «اللعبة» بحماس. فالضحك معًا يقوّي الرابطة العاطفية بينكما ويساعده على بناء ثقة إيجابية بنفسه.') WHERE id = '6f7f5c96-a971-4edb-9629-1420d3e51d5d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة «أحجية التركيب» لتنمية المهارات الحركية الدقيقة. يتعلم طفلكِ الآن تركيب أحاجي بسيطة من 2-3 قطع، أو وضع الأشكال الهندسية في الفتحات المناسبة. تعزز هذه اللعبة إدراكه البصري وقدرته على حل المشكلات إلى حد كبير. وعندما لا ينجح، قدّمي له تلميحًا بهدوء وشجّعيه.') WHERE id = 'f29daf62-95a9-439b-9639-5474aad5c6b0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لا يزال «اللعب المتوازي» هو النمط السائد في السلوك الاجتماعي. فعندما يكون طفلكِ مع أطفال آخرين، يلعب بمفرده إلى جوارهم بدلًا من اللعب معهم. وهذا طبيعي تمامًا لدى الأطفال حتى عمر 18 شهرًا. فهو يتعلم الكثير من خلال مراقبة الأطفال الآخرين. واصلي اصطحابه للقاء أقرانه كي يتأقلم مع البيئة الاجتماعية.') WHERE id = 'b30c9be9-ec87-4316-9f1a-0e4dee84bd75';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«أنا أغتسل بنفسي». أثناء الاستحمام أو غسل اليدين، يمسك طفلكِ بالصابون أو الإسفنجة ويحاول تنظيف نفسه وتقليدكِ. شجّعي اهتمامه بعادات النظافة الشخصية. فمحاولته «تنظيف» نفسه تساعده كثيرًا على التعرف إلى أجزاء جسمه بصورة أفضل وتنمية شعوره بالاستقلالية.') WHERE id = '4e8730af-51d2-460d-ac2a-1e5c1f18dbf2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تعزيز الذاكرة: «الذاكرة المكانية». يستخدم طفلكِ طرقًا متعددة للعثور على اللعبة التي أخفيتِها؛ فيرفع الغطاء، وينظر داخل الصندوق، بل ويمد يده تحت الوسادة. وهذا يدل على ترسخ مفهوم «بقاء الأشياء» لديه تمامًا. درّبي انتباهه من خلال ممارسة ألعاب «البحث عن الكنز» الصغيرة معه في المنزل.') WHERE id = '88dfd514-9103-49dd-80b3-7233dd30fb8c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الخيال و«الأعمال المنزلية». «يتحدث» طفلكِ عبر هاتفه اللعبة أو يكنس الأرض بمكنسة لعبة. إنه يقلد كل حركة تقومين بها في حياتكِ اليومية، وهذا التقليد هو طريقته في التعرف إلى العالم. امنحيه «أدوات عمل» صغيرة خاصة به، لتتيحي له الشعور بأنه مهم.') WHERE id = '86806a6e-92ce-48bc-8348-5f82c21f79d1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الشجاعة الجسدية: «إتقان التسلق». أصبح طفلكِ الآن ميالًا جدًا إلى صعود الدرج بنفسه، مع إمساككِ بيده أو زحفًا في الوقت الحالي. ومع تطور إدراكه للارتفاعات، من الضروري تعليمه كيفية النزول أيضًا. أريه دائمًا أن النزول إلى الخلف أكثر أمانًا، وابقي بالقرب منه باستمرار لحمايته.') WHERE id = 'bdb8a9e0-fbd7-4c99-b8e8-bdcb234283e8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: «تنفيذ التعليمات». أصبح طفلكِ قادرًا على فهم مهام تتكون من خطوتين متتاليتين. مثلًا: «خذ الكرة وضعها في الصندوق». يساعد ذلك على تطوير فهمه للغة وذاكرته العاملة. درّبي انتباهه من خلال إعطائه مثل هذه «المهام» البسيطة المكونة من خطوتين.') WHERE id = 'b9afb514-aca9-4563-b096-907e76f4594a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: «حب الكتب». أصبح طفلكِ يحاول تقليب الصفحات الورقية الرقيقة دون تمزيقها (تحت إشرافكِ). وقد يرغب في سماع حكاياته المفضلة مرارًا وتكرارًا. في كل مرة تقرئينها، أشيري إلى تفاصيل مختلفة في الصورة: «انظر، توجد هنا فراشة صغيرة أيضًا». فهذا يعزز انتباهه البصري وصبره.') WHERE id = 'dd8c337a-acae-4f9f-a64d-1a2e2dbf15fb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«النظافة الشخصية باستقلالية». أصبح طفلكِ يحاول تجفيف يديه أو مسح وجهه أو «غسل» نفسه بإسفنجة. شجّعي اهتمامه بعادات النظافة الشخصية، وقدّمي له منشفة صغيرة خاصة به. إن شعوره بالقدرة على الاعتناء بنفسه يعزز ثقته بنفسه واحترامه لجسده.') WHERE id = '31f5c493-87d9-45d8-950b-ce108414919b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: «المشاركة الرمزية». أصبح طفلكِ قادرًا على أن «يقدّم» لكِ جزءًا من لعبته أو لقمة من طعامه. وحتى إن لم يعطكِ إياها فعلًا، فإن هذه اللفتة تشكّل أساس فهمه لمفهوم المشاركة. احرصي على تشجيع هذا التصرف بقولكِ: «شكرًا جزيلًا، أنت لطيف جدًا».') WHERE id = '10acade6-6a92-4cf8-b728-f33648cdd314';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: «الأشكال الهندسية». بدأ طفلكِ يميّز بين الدائرة والمربع والمثلث (في ألعاب الأحجيات أو ألعاب فرز الأشكال). أخبريه بأسماء هذه الأشكال. وحتى إن لم يتمكن بعد من نطق أسمائها، فإن تمييزها بصريًا بعضها عن بعض يشكّل أساس تفكيره الهندسي.') WHERE id = '36dfa91f-6b4c-45f4-8057-bfc8dec4de87';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الشجاعة الجسدية: «القفز إلى الأسفل». قد يحاول طفلكِ الآن القفز من درجة منخفضة (على ارتفاع بضعة سنتيمترات فقط) إلى الأرض. أمسكي بيده لتدعميه. تساعد هذه الحركة على تقوية كاحليه، كما تعلّمه عمليًا إدراك الارتفاع والمسافة.') WHERE id = '20c66b93-4f9a-4106-b0f1-86263f239cfe';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'يحاول طفلكِ الآن القفز في مكانه. قد لا يتمكن بعد من رفع قدميه عن الأرض في الوقت نفسه، لكن ثني ركبتيه والارتداد بهما دليل على تطور مهاراته الحركية الكبرى. ارقصي معه على أنغام موسيقى إيقاعية. فهذا نشاط ممتع ومفيد جدًا لتقوية عضلات ساقيه.') WHERE id = '11679c4b-f0ae-4e4b-8e36-e62ed51385bb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'اكتشاف كلمة "لي" في الكلام. أصبح طفلكِ يتعرّف الآن على أغراضه ويحاول حمايتها قائلًا "لي" (أو مستخدمًا إشارة خاصة به). هذا ليس أنانية، بل تعبير عن إدراكه لحدوده الشخصية. أتيحي له فرصة الاحتفاظ بأغراضه والدفاع عن ملكيته لها، فهذا يعزز ثقته بنفسه وينمّي لديه مفهوم الملكية.') WHERE id = '76f2d8e6-3dab-4534-8a50-e8454558158c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"التصنيف والمنطق" في المهارات الحركية الدقيقة. بدأ طفلكِ الآن يميّز بين الأشياء ليس بحسب ألوانها فحسب، بل بحسب أحجامها أيضًا (كبير وصغير). أعطيه أوعية بأحجام مختلفة واطلبي منه وضع بعضها داخل بعض. فهذا من أولى الركائز التي سيُبنى عليها تفكيره الرياضي مستقبلًا.') WHERE id = 'c34d1f9d-7805-4ebe-a5ef-2eba5d6e613a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الاستقلالية: "أرتدي ملابسي بنفسي". يحاول طفلكِ الآن رفع سرواله، أو خلع جوربه، أو ارتداء حذائه السهل بنفسه. لا تعيقيه أو تستعجليه خلال هذه العملية. فرؤيته لنفسه وهو ينجح في أداء شيء ما هي أعظم مكافأة له. وامدحيه دائمًا على نجاحاته الصغيرة.') WHERE id = 'e8325a98-332b-4719-b50a-32bc427f8a46';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"انتظار الدور" في السلوك الاجتماعي. أصبح طفلكِ الآن يفهم أنه يحتاج إلى الانتظار قليلًا كي يلعب باللعبة. علّميه الصبر من خلال ألعاب مثل "الآن دوري، ثم دورك". فهذه إحدى أهم المهارات التي تساعده على التكيف مع الحضانة أو البيئات الاجتماعية الأخرى.') WHERE id = 'fb3f5f38-3ad4-4db7-9933-796ef621c2db';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"إتقان استخدام الملعقة باستقلالية" أثناء تناول الطعام. يتعلم طفلكِ الآن ملء الملعقة بالطعام وإيصالها إلى فمه من دون أن يسكب محتواها تقريبًا. ويسهل عليه التدرب باستخدام أطعمة متماسكة مثل الزبادي أو الطعام المهروس. لا تقلقي من اتساخ المائدة؛ فتناوله الطعام بنفسه ينمّي التناسق بين يديه وعينيه، كما يعزز إدراكه للشبع.') WHERE id = 'eb358b29-c8ba-43ce-9ec4-901370abee63';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"التعبير عن المشاعر" من خلال الكلام. أصبح طفلكِ الآن يعبّر عن جوعه أو تعبه أو خوفه من شيء ما باستخدام أصوات مميزة أو كلمات بسيطة. أكّدي له فهمكِ لهذه الإشارات بالكلمات: "نعم، أنت متعب، تعال لنسترح قليلًا". فهذا أكبر دعم يساعده مستقبلًا على تنظيم مشاعره والتعبير عنها بالكلمات.') WHERE id = '402a1eb2-6224-49f3-92d8-6ebdc1c68d75';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تعزيز الخيال: "الألعاب تنبض بالحياة". أصبح طفلكِ الآن ينظّم سباقات بسياراته اللعبة أو يجعل دُماه "تتحدث" مع بعضها. وهذا يدل على إبداعه وقدرته على التفكير المركّب. شاركيه هذه الألعاب التمثيلية ووسّعي أحداثها قليلًا، كأن تقولي: "هل تذهب السيارة للتزوّد بالوقود؟".') WHERE id = '50b52b0c-f730-4500-a2ea-7d50f4678b25';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بلغ طفلكِ الآن ذروة مرحلة "سأفعل ذلك بنفسي!". فهو يريد فتح الباب بنفسه، أو الضغط على الزر بنفسه، أو صعود الدرج بمفرده. هذا ليس عنادًا، بل محاولة لاختبار قدراته. امنحيه بضع ثوانٍ إضافية للمحاولة كلما كان ذلك آمنًا. فرؤيته لنفسه وهو ينجح من أهم العوامل التي تبني ثقته بنفسه.') WHERE id = '0424ded1-f254-419a-bacc-912b20a6465b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور الجسدي: "رمي الكرة نحو الهدف". لم يعد طفلكِ يرمي الكرة على الأرض فحسب، بل يحاول رميها في اتجاه محدد أو نحوكِ. ويشير ذلك إلى تطور ملحوظ في عضلات الكتفين والتنسيق بين اليد والعين. ساعديه على تحسين دقته من خلال اللعب معه بلعبة "ارمِ الكرة في السلة".') WHERE id = 'd62bdbf3-d7fd-43c8-9cef-8ef0c95e0352';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"اكتشاف الصفات" في تطور الكلام. لم يعد طفلكِ يكتفي بتسمية الأشياء، بل أصبح يفهم أيضًا خصائصها، مثل: "ساخن"، و"بارد"، و"كبير"، و"صغير". استخدمي هذه الكلمات كثيرًا أثناء تناول الطعام أو الاستحمام، كأن تقولي: "انظر، هذا الماء فاتر". فهذا يساعده على وصف العالم بمزيد من التفاصيل وتنمية قدرته على التفكير المجرّد.') WHERE id = 'f549d4ea-b5e9-4a79-81eb-61a06771145c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: "النَّظم والإدخال". قد يحاول طفلكِ الآن نظم الخرز في خيط، على أن يكون كبير الحجم وتحت إشرافكِ، أو إدخال المفتاح في القفل. تتطلب هذه الحركات تنسيقًا بالغ الدقة بين عضلات الأصابع. وتُعد هذه التمارين أساسًا مهمًا لاكتساب مهارتي إمساك القلم والكتابة مستقبلًا.') WHERE id = '499eb64f-17b7-4928-a28f-32d77bae69bd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تطور الخيال: «الحوار مع الألعاب». بدأ طفلكِ الآن «يتحدث» مع دميته أو دبه، و«ينوّمهما» أو «يفحصهما». وهذا مؤشر على تطور ذكائه العاطفي ومدى استيعابه العميق للطقوس اليومية. شاركيه ألعاب تقمّص الأدوار هذه.') WHERE id = '966e6ab8-7afb-4514-ac61-ac17ed1b3363';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التطور الجسدي: «ركل الكرة». أصبح طفلكِ الآن يحاول ركل الكرة وهو واقف من دون أن يفقد توازنه. وهذه حركة تتطلب تنسيقًا حركيًا معقدًا. العبي معه بكرة خفيفة في المنزل أو في الفناء. واطلبي منه تمرير الكرة إليكِ لتنمية مهارة اللعب التفاعلي لديه أيضًا.') WHERE id = '074c6e28-5574-4dba-9c17-b0a8532eb39d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بوادر مرحلة «لماذا؟» في تطور الكلام. يشير طفلكِ إلى كل شيء بإصبعه ويقول: «هذا؟»، منتظرًا شرحكِ. اشرحي له اسم كل غرض وفائدته بجمل بسيطة. ترسم تفسيراتكِ خريطة العالم في ذهنه. حافظي دائمًا على فضوله حيًا.') WHERE id = '8bf76af3-3dd5-49ef-bbdd-da6f06260256';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد أكملنا 550 يومًا! أصبح طفلكِ الآن بعمر 1.5 سنة رسميًا. تُعد هذه المرحلة من أكثر الفترات أهمية وتشويقًا في نموه. فهو يفهم الآن التعليمات البسيطة تمامًا، ويُظهر مشاعره بوضوح، وأصبح «مستكشفًا» صغيرًا مستعدًا لاكتشاف العالم. احتفلي بهذا اليوم معه بلعب لعبته المفضلة!') WHERE id = 'f706bcc8-1266-48d0-82ad-7920a5e14e37';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بكِ في الشهر 19! أصبح طفلكِ الآن يتعرف إلى نفسه تمامًا في المرآة، ويدرك أن انعكاسه هو صورته وليس «طفلًا آخر». وهذه خطوة كبيرة في تطور وعيه بذاته (self-awareness). واصلي تعليمه أعضاء الجسم بمزيد من التفصيل، فقفي معه أمام المرآة وقولي: «انظر، هاتان عيناك، وهاتان عينا أمك».') WHERE id = '696f3d72-602f-4dc5-8009-bf57000cd9a2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الخطوة الجانبية» في التطور الحركي. أصبح طفلكِ الآن قادرًا على المشي إلى الجانبين (crab walk)، وليس إلى الأمام والخلف فحسب. وهذا تمرين معقد على التوازن والتنسيق الحركي. أريه كيف يتحرك في اتجاهات مختلفة على أنغام الموسيقى. فهذه رقصة ممتعة، كما أنها تقوّي مجموعات مختلفة من عضلات الساقين.') WHERE id = '29558e25-5ccf-4193-9fb7-c0eb732293d0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الانتقائية" و"التحكّم" في الطعام. قد يرفض طفلكِ الطعام أحيانًا لمجرد رغبته في أن يكون هو صاحب القرار. لا تجبريه. بدلًا من ذلك، قدّمي له خيارين صحيين على المائدة: "هل تريد البروكلي أم الجزر؟". إن منحه فرصة الاختيار يقلّل اعتراضه ويجعله يشعر بأن قراراته موضع احترام.') WHERE id = '597fce8a-7564-428a-aa97-6b8b166f2f7c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الإدراك المكاني" و"الارتفاع". أصبح طفلكِ الآن أكثر وعيًا بمخاطر الارتفاع، ويتوخّى الحذر عند النزول من الأماكن المنخفضة. ذكّريه بالنزول إلى الخلف من الأريكة أو الدرج. فهذا مهم كي يتعلّم قواعد الحفاظ على سلامة جسمه.') WHERE id = '42d59296-b192-45dd-b455-11502c8aeaec';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح "التقليد" في السلوك الاجتماعي يشمل المشاعر أيضًا. فعندما تضحكين يضحك طفلكِ، وعندما تبدين جادّة يلتزم الصمت. أنتِ مرآته العاطفية. أثناء اللعب معه، أظهري له تعابير وجه مختلفة واطلبي منه تقليدها. فهذا يساعد على تنمية ذكائه العاطفي وقدرته على فهم الآخرين.') WHERE id = 'c03e79b5-c416-4e9a-8cda-23ab824d2ea7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'عادة "الترتيب بنفسه": أصبح طفلكِ قادرًا على اعتبار جمع ألعابه ووضعها في الصندوق "مهمّة". بعد انتهاء اللعب، شجّعيه بقولكِ: "هيا نُعِد السيارات إلى بيتها". فهذا ينمّي لديه النظام والانضباط، كما يعزّز شعوره بالمسؤولية عن إتمام ما بدأه. ساعديه دائمًا وامتدحيه.') WHERE id = '4be37208-93a9-4898-b72a-811ae2d7a051';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح حوار "السؤال والجواب" في تطوّر الكلام أكثر تعقيدًا. فهو لم يعد يسأل "ما هذا؟" لمجرد أنه لا يعرف الإجابة، بل أيضًا ليستمر في التواصل معكِ. عند الإجابة، اجعلي الجملة أطول قليلًا: "هذه تفاحة حمراء، وأنت تحبّها". فهذا يُثري حصيلة طفلكِ اللغوية بسرعة.') WHERE id = '59968193-d8d9-46a6-bcc6-77f1e1c44a81';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "إتقان ركل الكرة". أصبح طفلكِ قادرًا الآن على ركل الكرة أمامه أثناء الركض. وهذا يتطلّب التحكّم في الحركة والتوازن في الوقت نفسه. العبي معه "كرة القدم" في المنزل أو في الفناء لتعزيز مهارة التوازن الحركي لديه. فالتحرّك واللعب معكِ هما أكبر متعة بالنسبة إليه.') WHERE id = '591884a7-b1fd-4edf-bb0d-3dca04af2ea4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يعد طفلكِ يكتفي بالتمييز بين الألوان، بل يحاول أيضًا نطق أسمائها. فإذا اختار اللون الصحيح عندما تقولين له: "أعطني السيارة الزرقاء"، فهذا إنجاز كبير في ذاكرته البصرية وفهمه للغة. احرصي على تكرار أسماء الألوان في ملابسه وألعابه اليومية لترسيخ هذه المعرفة.') WHERE id = '1ab53f62-49d6-486d-9a52-ff092cc01b9c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الشجاعة البدنية: أصبح طفلكِ أكثر حماسًا للقفز في مكانه، أي رفع قدميه عن الأرض في الوقت نفسه. ويتطلب ذلك تنسيقًا كبيرًا بين عضلات الساقين والقدرة على التوازن. أتيحي له فرصة تفريغ طاقته باللعب معه على سجادة ناعمة في لعبة "من يقفز أكثر؟".') WHERE id = 'fac02d76-edc4-45d2-ac23-faa60bad4132';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الكلمات الدالة على المكان" في اللغة. أصبح طفلكِ يفهم عمليًا معاني كلمات مثل "فوق" و"تحت" و"داخل". اختبري فهمه بقولكِ: "ضع الكرة تحت الكرسي". تساعد هذه المهام على تنمية مهاراته اللغوية وقدرته على إدراك الاتجاهات المكانية. أدرجي هذه المفاهيم في ألعابه لتعزيز تفكيره المنطقي.') WHERE id = '30c8f80f-c5ad-42c7-a784-1930afcd9e96';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الاختيار المستقل" والإرادة. أصبح لدى طفلكِ الآن رأي واضح بشأن ما يريد ارتداءه أو الطبق الذي يريد تناول الطعام منه. إن منحه فرصة للاختيار، كأن تسأليه: "هل تريد أن تأكل اليوم في الطبق الأزرق أم الأخضر؟"، يساعده على الشعور بكيانه واستقلاليته ويحد من العناد غير المبرر.') WHERE id = '6f9d4056-a417-4319-83b2-043809df814a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"التصميم والبناء" في المهارات الحركية الدقيقة. أصبح طفلكِ قادرًا على تكديس 6-8 مكعبات بعضها فوق بعض لبناء برج مرتفع. ويتطلب ذلك التركيز ودقة حركات اليدين. عندما يسقط البرج، استقبلي الأمر بمرح حتى لا يخاف طفلكِ من الإخفاق ويتحمس للمحاولة من جديد.') WHERE id = '17f5c5df-ea05-4d59-8a28-32ffc0cbb3e8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الرعاية والاهتمام" في السلوك الاجتماعي. أصبح طفلكِ قادرًا على "إطعام" دبه المحشو أو "وضعه في سريره" أو "مواساته" عندما يبكي. وهذا دليل على تطور اللعب الرمزي لديه. فالحنان الذي تُظهرينه لطفلكِ يتجلى الآن في ألعابه.') WHERE id = 'bc61e4f6-e294-4033-b040-474d57e5f13b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الاستقلالية: «أنا أرتدي ملابسي بنفسي». أصبح طفلكِ أكثر إصرارًا على خلع جواربه، ووضع قبعته على رأسه، أو ارتداء حذائه السهل بنفسه. امنحيه بضع دقائق إضافية خلال هذه العملية. فإتاحة الفرصة له لإنجاز شيء بنفسه من دون استعجاله تعزز ثقته بنفسه وتنمّي شعوره بالاستقلالية.') WHERE id = '947a00f0-f695-4c17-b833-1f7ad19529e3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'السلوك الاجتماعي: «انتظار الدور». بدأ طفلكِ يفهم أن عليه الانتظار قليلًا لركوب الأرجوحة في الحديقة أو اللعب بلعبة ما. علّميه الصبر من خلال ألعاب مثل: «الآن دوري، ثم دورك». فهذه المهارة من أهم الأسس الاجتماعية التي ستساعده مستقبلًا على التكيف مع بيئة الحضانة والمدرسة.') WHERE id = 'f555abb8-3ed3-4f14-968a-d2f98f543e71';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مهارة استخدام الشوكة والملعقة أثناء تناول الطعام. يتعلم طفلكِ الآن ملء الملعقة بالطعام وإيصالها إلى فمه من دون أن يسكب منها شيئًا تقريبًا. قدّمي له قطعًا صغيرة من الخضراوات والفواكه يسهل التقاطها بالشوكة. فتناوله الطعام بنفسه يساعده على تمييز شعوره بالشبع ويزيد اهتمامه بالأطعمة ذات القوامات المختلفة.') WHERE id = 'a925547f-11ed-45ce-9474-cab706a5ddda';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تطور الخيال: «الحوار مع الألعاب». أصبح طفلكِ «يتحدث» مع دميته أو دبه، و«يطعمهما» أو «ينيمهما». وهذا دليل على نمو ذكائه العاطفي ومدى استيعابه العميق للروتين اليومي. شاركيه ألعاب تقمّص الأدوار هذه، ووسّعي سيناريو اللعب قليلًا.') WHERE id = 'a151a89a-61af-4831-b10f-8a215a565721';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التطور البدني: «ركل الكرة». يحاول طفلكِ الآن الوقوف وركل الكرة أمامه من دون أن يفقد توازنه. تتطلب هذه الحركة تنسيقًا حركيًا معقدًا والقدرة على التوازن على قدم واحدة للحظات. العبي معه بكرة خفيفة في المنزل أو في الحديقة لتنمية سرعة حركته ودقته.') WHERE id = 'deb4ac24-b3c7-4d6b-a7be-c36edea03c4e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد أكملنا 600 يوم! بلغ طفلكِ الآن منتصف شهره العشرين. أصبح يفهم التعليمات البسيطة تمامًا، ويُظهر مشاعره بوضوح، وهو «مستكشف» صغير مستعد لاكتشاف العالم. احتفلي بهذا اليوم بقضاء الوقت معه في حديقته المفضلة أو في غرفة الألعاب. أنتِ أم رائعة!') WHERE id = '1f1a3784-4c01-4fba-825d-ca3fcac15f79';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التغذية: «شرب الماء باستقلالية». أصبح طفلكِ الآن يشرب الماء بثقة من كوب مفتوح، من دون أن يسكبه تقريبًا. وهذا مؤشر على مدى استعداد عضلات شفتيه وفكّه للنطق. واصلي تقديم أكواب بحجم مناسب للأطفال ويسهل عليه إمساكها، حتى يتقن هذه المهارة تمامًا.') WHERE id = 'f0007c08-4f82-470d-976e-b690d945c125';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مخاوف جديدة: قد يبدأ طفلكِ فجأة بالخوف من الظلام أو الأصوات المرتفعة أو الشخصيات المقنّعة. يرتبط ذلك بتطوّر خياله وإدراكه لما حوله. لا تسخري من خوفه، بل ابقي بجانبه واحتضنيه وأشعريه بالأمان. ومع مرور الوقت، ستفسح هذه المخاوف المجال للفضول.') WHERE id = 'c56b4f54-c6b4-4285-a227-6cdf7c49e75e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في النطق: «الجمل المركّبة الأولى». قد يستخدم طفلكِ الآن تراكيب بسيطة بصيغة الماضي، مثل «جاء أبي» و«شربتُ الماء». شجّعي محاولاته بتكرار عباراته باستخدام قواعد صحيحة. فحديثكِ هو نموذجه الأساسي، لذا تواصلي معه دائمًا بلغة واضحة وصادقة.') WHERE id = 'ec0cb279-7627-42fd-8c4b-82e97e640420';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «إتقان المشي إلى الخلف». أصبح طفلكِ الآن قادرًا على السير بضع خطوات إلى الخلف من دون أن ينظر وراءه. وهذه مهارة مهمة لتنمية إحساسه بوضعية جسمه في المكان (الحس العميق). حوّلي هذه الحركة إلى لعبة بقولكِ له: «لنمشِ مثل السلطعون». فالتحرّك واللعب معكِ هما أمتع ما في العالم بالنسبة إليه.') WHERE id = '891890ba-7797-463a-90b9-18dda87b2142';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'نخطو إلى الشهر 20! بدأ طفلكِ الآن بتكوين «ذوقه» الخاص. فقد يصرّ على اختيار الحذاء الذي يريد ارتداءه أو الطعام الذي يرغب في تناوله. وهذا دليل على تنامي إرادته. أتيحي له الاختيار بين خيارين آمنين: «هل ستأكل التفاح اليوم أم الكمثرى؟». فهذا يعزّز ثقته بنفسه ويقلّل أيضًا من نوبات العناد.') WHERE id = '9857fafb-dba1-41f5-bd34-455d5b939f6f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التناسق الجسدي: «التوازن الديناميكي». أصبح طفلكِ الآن قادرًا على الانحناء لالتقاط شيء من الأرض، ثم الوقوف مجددًا من دون أن يقع. وهذا يدل على أن عضلات ظهره وساقيه قد أصبحت أقوى بكثير. رتّبي له ألعابًا على الأرض بارتفاعات مختلفة، واطلبي منه جمعها ووضعها في صندوق. يساعد هذا النشاط على صقل قدرته على التحكّم بجسمه.') WHERE id = '21286f36-7532-41d3-a58d-4d4ecfb6df25';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'يتسارع تطور "العبارات الكلامية". أصبح طفلكِ الآن قادرًا على التعبير عن رغباته بكلمتين أو ثلاث، مثل: "أبي، أعطني الكرة"، "أمي، أريد ماءً". عندما يتحدث، أنصتي باهتمام إلى كل كلمة يقولها وحافظي على التواصل البصري معه. أجيبيه بجمل أطول قليلًا من جمله، كي تزداد حصيلته اللغوية ثراءً.') WHERE id = '4a36674f-0b66-41a0-beba-daa82b8d9f0b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في مجال المهارات الحركية الدقيقة: "الأحجيات والألغاز". أصبح طفلكِ الآن أسرع في تركيب الأحجيات البسيطة المكونة من 3-4 قطع، أو إدخال الأشكال في الفتحات المناسبة لها. يساعد ذلك على تنمية إدراكه المكاني وقدرته على التحليل البصري. عندما تكون المهمة صعبة، قدّمي له تلميحات بسيطة حتى لا يفقد حماسه.') WHERE id = 'cce26ca5-c2df-4a63-a452-8753ade9a3fe';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: "المشاركة الرمزية". قد يعرض عليكِ طفلكِ الآن جزءًا من لعبته (أو قد يسترده فورًا). هذه من أولى بوادر فهمه لمفهوم المشاركة. احرصي على مدح هذه اللفتة بقولكِ: "شكرًا جزيلًا لأنك أريتني لعبتك". فهذا يرسّخ لديه أسس العادات الاجتماعية الإيجابية.') WHERE id = '35b68ddd-9074-4a9a-97b7-0fddbf831df1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"أنا أنظف بنفسي". يسعى طفلكِ إلى تقليدكِ، فيحاول تجفيف يديه أو مسح وجهه أو تنظيف المائدة بقطعة قماش مخصصة للعب. لا تكبتي رغبته في الاستقلال. أعطيه منشفة صغيرة أو فرشاة خاصة به وأشركيه في "الأعمال المنزلية". فهذا ينمّي لديه الشعور بالمسؤولية.') WHERE id = '37a69b03-aa17-4bad-982a-11091970591b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بلغت الذاكرة و"الذاكرة المكانية" ذروتهما. أصبح طفلكِ الآن قادرًا على تذكّر مكان اللعبة التي أخفيتِها حتى بعد مرور عدة ساعات. العبي معه في المنزل لعبة "البحث عن الكنز". ضعي لعبة تحت الوسادة وراقبيه وهو يعثر عليها. تساعد هذه اللعبة على تعزيز تركيزه ومهاراته في حل المشكلات.') WHERE id = '105285fc-eb7a-4111-ad71-74ef8c1d89b9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تطور الخيال: "الحوار مع الألعاب". يتحدث طفلكِ مع دميته أو دبه المحشو، ويطعمهما أو يضعهما في الفراش. وهذا مؤشر على نمو الذكاء العاطفي واستيعاب العادات اليومية. شاركيه ألعاب تقمّص الأدوار هذه واسأليه: "إلى أين يذهب الدب الآن؟". فهذا يسرّع نمو تفكيره الإبداعي.') WHERE id = '1d1a3072-a955-4f0c-b97e-45be9ab5c292';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الشجاعة الجسدية: "الصعود والنزول". أصبح طفلكِ قادرًا على صعود الدرج بسرعة أكبر، درجة تلو الأخرى (مع إمساككِ بيده). ومع تطور إدراكه للارتفاعات، أريه مرارًا الطرق الآمنة للنزول، مثل النزول إلى الخلف. تأكدي من أن حواجز الأمان ما زالت في مكانها ومغلقة بإحكام.') WHERE id = '3dfce46e-871b-4ff0-b52c-ef4021fb63e3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الحدود العاطفية: أصبح طفلكِ يستجيب الآن لكلمة "ممنوع"، لكنه قد يظل أحيانًا يخالف القواعد لاختبار رد فعلكِ. الأهم هو أن تحافظي على هدوئكِ مع الحزم. إذا قلتِ "لا" لشيء ما، فكرري موقفكِ بالطريقة نفسها في كل مرة. ثبات القواعد ينمّي لدى طفلكِ الشعور بالنظام الداخلي والأمان.') WHERE id = '3d5db953-53d5-41ac-96c7-0de1abf8d13a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يعد طفلكِ يكتفي بالتمييز بين الألوان، بل أصبح قادرًا أيضًا على مطابقتها. إذا نفّذ بشكل صحيح طلبكِ: "ضع الكرة الزرقاء في الصندوق الأزرق"، فهذا إنجاز كبير في تطور منطقه البصري. عززي هذه المعرفة في الحياة اليومية باستخدام عبارات تبرز الألوان، مثل "تفاحة حمراء" و"ورقة خضراء".') WHERE id = '7bf7487b-3d3e-49a7-9bc5-a3a917c3fbbf';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في مجال الحركة الجسدية: "القفز في المكان". بدأ طفلكِ يحاول رفع كلتا قدميه عن الأرض في الوقت نفسه (القفز). ويتطلب ذلك قوة في عضلات الساقين وتناسقًا حركيًا معقدًا للحفاظ على التوازن. العبي معه لعبة "لنقفز مثل الأرنب". فهي ممتعة ومفيدة جدًا لنموه الجسدي.') WHERE id = '37a6e358-9a9e-40cc-aab7-74b540fd0681';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور النطق: "زيادة استخدام الصفات". أصبح طفلكِ لا يفهم أسماء الأشياء فحسب، بل خصائصها أيضًا (ساخن، بارد، كبير، صغير، ناعم، صلب). أثري مفرداته الحسية بقولكِ أثناء تناول الطعام: "هذا المهروس ساخن"، أو عند لمس لعبته: "هذا الدب ناعم". سيساعده ذلك على وصف العالم بمزيد من التفاصيل.') WHERE id = 'e5f3d411-7714-4b52-b440-c00913f921c9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تتحسن مهارة "إمساك القلم" ضمن المهارات الحركية الدقيقة. يحاول طفلكِ الآن إمساك قلم التلوين بالقرب من أصابعه بدلًا من قبضته كاملة. ويرسم على الورق دوائر أكثر ثباتًا أو خطوطًا عشوائية لكنها قوية. وسّعي مساحة "الإبداع" لديه بتقديم أقلام تلوين وأوراق كبيرة له.') WHERE id = '286d8a77-5c51-4a8f-96ae-733178c15fb0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'نبدأ الأيام العشرة الأخيرة من الشهر العشرين. لم يعد طفلكِ يكتفي بالإشارة إلى أعضاء جسمه، بل بدأ أيضًا يفهم وظائفها. فعندما تسألينه: "ماذا تفعل بقدميك؟"، قد يُريكِ كيف يركض أو يدوس بهما. العبي معه لعبة "ما فائدة هذا؟"، فهي تنمّي حصيلته اللغوية وقدرته على التفكير الوظيفي.') WHERE id = 'dee4db38-d5ad-4ab8-80a6-e91df1c6234f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في مجال الحركة الجسدية: "المرور من تحت العوائق". يتعلم طفلكِ الآن، إلى جانب الوقوف منتصبًا، الانحناء والمرور من تحت الطاولة أو الكرسي وتقدير حجم جسمه بالنسبة إلى المكان. وهذا يعزز وعيه بجسمه (body awareness). اصنعي له في المنزل "أنفاقًا" من الوسائد والكراسي ليتدرّب على هذه المهارة.') WHERE id = '4db05b48-52f1-4673-a7b9-28436103d6d9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: "البوادر الأولى لاستخدام الضمائر". يحاول طفلكِ الآن أن يقول عن نفسه "أنا"، وأن يخاطبكِ بـ"أنتِ"، أو قد يستخدم أصواتًا مختلفة تحمل المعنى نفسه بلغته الخاصة. وهذا دليل على أنه بدأ يدرك نفسه فردًا مستقلًا تمامًا عن العالم المحيط به. عندما ينطق اسمه، قولي له: "نعم، أنتَ (اذكري اسمه) هنا"، لتعززي شعوره بهويته وذاته.') WHERE id = '15ef8b0a-68af-41c5-881d-ef1aaddc31ca';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: "لفّ الأغطية وفتحها". يحاول طفلكِ الآن فتح أغطية الزجاجات أو إغلاقها عن طريق لفّها. وتُعد هذه الحركة تمرينًا ممتازًا لعضلات الرسغ على الحركة الدورانية. قدّمي له أوعية آمنة بأحجام مختلفة، واسمحي له بتجربة هذه "المهارة" الجديدة.') WHERE id = 'eca36160-9ece-4da0-80c8-687ec7c51745';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: "الرغبة في المساعدة". أصبح طفلكِ متحمسًا لإخراج شيء من حقيبة التسوق أو إحضار شيء لكِ. أعطيه مهام صغيرة، مثل: "من فضلك، أعطني هذه الحفاضة". وعندما يُنجز المهمة، قولي له: "لقد ساعدتني كثيرًا، شكرًا جزيلًا لك". فهذا ينمّي لديه حس المسؤولية الاجتماعية ويجعله يشعر بأنه مفيد.') WHERE id = 'ee7370f4-6eb2-48da-aebb-00ccc3c2ad1b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"تنظيف الأسنان بمفرده". أصبح طفلكِ يقلّدكِ، فيضع فرشاة الأسنان في فمه ويحركها. لا يزال الأمر مجرد لعبة في الوقت الحالي، وعليكِ أنتِ تنظيف أسنانه، لكن شجّعي اهتمامه بهذه العادة. فامتلاكه فرشاة خاصة به ومحاولته استخدامها بنفسه يمهّدان لاكتساب عادات صحية جيدة.') WHERE id = '183dc3b9-e225-46b4-b630-b164f5414528';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«المطابقة» في التطور المعرفي: أصبح طفلكِ قادرًا على مطابقة صورتين مختلفتين للحيوان أو الشيء نفسه. العبي معه لعبة «اعثر على الصورة المطابقة» باستخدام بطاقات بسيطة. فهذا يُعزّز انتباهه البصري وذاكرته بدرجة كبيرة. وعندما يختار الصورة الصحيحة، أظهري فرحتكِ حتى لا يفقد حماسه.') WHERE id = '45e380ad-6559-467d-84f4-eced81427f7d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الحركي: «نزول الدرج درجةً تلو الأخرى». عندما تمسكين بيد طفلكِ، يصبح قادرًا على محاولة نزول الدرج بثقة أكبر، واضعًا قدمًا تلو الأخرى. فالنزول أصعب من الصعود ويتطلب توازنًا أكبر. ابقي دائمًا بجانبه لحمايته، واسمحي له بالإمساك بدرابزين الدرج.') WHERE id = '9b3b0e2c-c4cd-4d64-a63f-e74713052b56';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«تسمية المشاعر» في تطور الكلام: عندما يغضب طفلكِ أو يفرح أو يشعر بالخجل، عبّري عن هذه المشاعر بالكلمات: «أنت سعيد جدًا الآن!»، «هل تشعر ببعض الحزن لأن لعبتك سقطت؟». تساعد تسمية المشاعر طفلكِ مستقبلًا على التحكم في نفسه بسهولة أكبر أثناء نوبات الغضب.') WHERE id = 'da0fa9b2-9fec-47fb-a56d-5e0c384540ea';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تعزيز الخيال: «اللعب التخيلي». أصبح طفلكِ قادرًا على استخدام شيء بدلًا من شيء آخر؛ فقد يتظاهر مثلًا بأن المكعب «هاتف» ويضعه على أذنه. وهذا دليل بارز على تطور تفكيره المجرّد وإبداعه. شاركيه هذه الألعاب وشجّعي خياله.') WHERE id = 'f71a9e64-80ca-4672-869a-4b4e2012c4b5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ يستخدم كلمتي «أنا» و«لي» بوتيرة أكبر. وهذه علامة على إدراكه لهويته وحدوده الشخصية. ومن الطبيعي أن يقول «لي!» وهو يحتضن لعبته المفضلة. امنحيه فرصة الحفاظ على أغراضه الخاصة، فهذا يضع أساسًا مهمًا لاحترامه حدود الآخرين مستقبلًا.') WHERE id = 'b7d51937-c7a2-4d6d-b732-4b494fc952b3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور الجسدي: «إتقان المشي إلى الخلف». أصبح طفلكِ قادرًا على الرجوع بضع خطوات إلى الخلف من دون أن ينظر وراءه أو يفقد توازنه. وهذا تمرين رائع لتنمية إحساسه بوضعية جسمه في المكان (الحس العميق). العبي معه لعبة «لنمشِ مثل السلطعون». فهذا نشاط ممتع، كما أنه يُمرّن عضلات ساقيه بطريقة مختلفة.') WHERE id = '513f1229-f55a-4c5d-a40b-fc0fd9f8ae37';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«دمج الصفات» في الكلام. لم يعد طفلكِ يكتفي بتسمية الأشياء، بل يضيف إليها لونًا أو حجمًا، مثل: «كرة كبيرة»، «سيارة حمراء». شجّعي محاولاته ووسّعي جملته قليلًا: «نعم، هذه كرتك الكبيرة والناعمة».') WHERE id = 'b2c7d131-58dd-486b-9609-a0affe8ae4df';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الخطوط العمودية والأفقية» في المهارات الحركية الدقيقة. أصبح طفلكِ يمسك قلم التلوين بثقة أكبر ويحاول رسم خطوط مستقيمة على الورق بقصد ووضوح. أعطيه أقلام تلوين سميكة وأوراق رسم كبيرة. فكل خط يرسمه يعزز التآزر بين اليد والعين ويمهّد لاكتساب مهارات الكتابة مستقبلًا.') WHERE id = 'cc6fb892-8f1f-42d8-95a3-eba0a72b0349';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الاختيار المستقل» والملابس. أصبح لدى طفلكِ رأي واضح بشأن الجوارب أو القبعة التي يريد ارتداءها. قدّمي له خيارين آمنين: «هل سترتدي اليوم قبعتك الخضراء أم الزرقاء؟». تساعد هذه القرارات الصغيرة طفلكِ على الشعور بأهميته وتقلل نوبات العناد إلى أدنى حد.') WHERE id = '38af9059-ae27-4644-b4e5-977b53c68250';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التعاون» في السلوك الاجتماعي: أصبح طفلكِ يستمتع بجمع ألعابه معكِ. عندما تقولين له: «هيا نُعِد السيارات معًا إلى مكانها»، سيساعدكِ. فهذا يرسّخ عادة النظام والانضباط، ويمنحه في الوقت نفسه متعة العمل المشترك. لا تنسي أن تمدحيه بعد كل مساعدة يقدمها.') WHERE id = '49ba697d-2e60-439d-966b-ca621530805d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«تركيب الأجزاء» في التطور المعرفي. أصبح طفلكِ قادرًا على حل أحاجي الصور البسيطة المكوّنة من قطعتين أو ثلاث بمفرده. يساعده جمع القطع ورؤية الصورة كاملة على تنمية التفكير البصري المكاني. وإذا لم ينجح، قدّمي له تلميحًا بهدوء: «انظر، ذيل الكلب هنا». فهذا يعزز لديه المثابرة على حل المشكلات.') WHERE id = '1bcc9149-af08-4bbd-bac4-e8848b1380ea';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الحركي: «ركل الكرة والجري». أصبح طفلكِ قادرًا على ركل الكرة أمامه أثناء الجري. ويتطلب ذلك التحكم في سرعة الحركة والتوازن الديناميكي في آنٍ واحد. العبي معه «كرة القدم» في المنزل أو الحديقة لتعزيز دقة حركاته.') WHERE id = '56be9450-be4f-4da2-bbc6-79d6b2c42f94';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الرعاية الرمزية» في السلوك الاجتماعي. قد يسقي الطفل دبدوبه اللعبة «الماء»، أو يغطيه ببطانية، أو يربّت عليه عندما يبكي. يدل ذلك على تطور ذكائه العاطفي وقدرته على فهم مشاعر الآخرين. لا تنسي أن تمدحي تصرفاته الحنونة هذه.') WHERE id = '4c44b890-83ea-41cb-99e6-72cdc0b1bf1f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'عادة «الترتيب من تلقاء نفسه»: بدأ الطفل ينظر إلى جمع ألعابه ووضعها في الصندوق بوصفه نهاية للعبة. اجعلي العملية ممتعة بقولكِ: «هيا نضع السيارات في سريرها». يساعده ذلك على اكتساب الانضباط والشعور بالمسؤولية. وعندما يساعدكِ، يشعر بأنه شخص كبير ونافع.') WHERE id = 'a363f89b-584e-494b-8c74-513903336560';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مفهوم «المتشابه والمختلف» في التطور المعرفي. أصبح الطفل قادرًا على تصنيف الأشياء ذات اللون نفسه أو النوع نفسه في مجموعات. اختبري هذه المهارة لديه بقولكِ: «هيا نجمع كل الأشياء الحمراء هنا». تضع هذه الألعاب الأساس لتفكيره المنطقي وقدرته على التحليل البصري.') WHERE id = 'f0afc0a3-b89f-4803-b20f-1fd14e1c84af';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الحركي: «المشي نزولًا من أعلى». يتطلب المشي على الأسطح المنحدرة، مثل التلال الصغيرة، نوعًا جديدًا من التوازن لدى الطفل. ويقوي ذلك كاحليه وقدرته على التحكم في مركز ثقل جسمه. أتيحي له فرصة خوض مثل هذه التحديات البدنية البسيطة أثناء التنزه في الحديقة.') WHERE id = 'c7f6bf36-ec3f-4dad-b529-a2a1c67afd8f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'العلاقة بين الاسم والضمير في تطور الكلام. قد يبدأ الطفل الآن بالانتقال من ذكر اسمه إلى استخدام ضمير «أنا». فإذا أجابكِ بـ«أنا» أو «لي» عندما تسألينه عن شيء ما، فهذا دليل على ترسخ وعيه بذاته. تحاوري معه حول ذلك، مثل: «لمن هذه الكرة؟ لي!».') WHERE id = 'da725a7e-8a5a-4880-b76d-f59275696659';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تطور الخيال: «المحاكاة المركبة». أصبح الطفل الآن يقلد أفعالًا تتكون من عدة خطوات. فقد يتظاهر مثلًا بأنه «يذهب إلى السوق»، ثم «يتسوق»، ثم «يطبخ الطعام». يكشف ذلك عن قوة ذاكرته ومدى عمق ملاحظته للروابط المنطقية بين الأحداث.') WHERE id = '385dd8e9-365e-4aee-b063-18466c68a303';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الألغاز والمنطق» في التطور المعرفي. أصبح طفلكِ يسعى إلى حل الألغاز البسيطة المكوّنة من 4-5 قطع بمفرده. يساعده الربط البصري بين الصور على تعزيز تركيزه ومهاراته في حل المشكلات. عندما لا ينجح، أرشديه بهدوء، لكن لا تحلّيها بدلًا منه. هذه «الانتصارات» الصغيرة تعزز قدراته المعرفية.') WHERE id = '39e90e4b-782c-46d9-9e9f-4cff4dfc1e98';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «المشي إلى الخلف». أصبح طفلكِ قادرًا على المشي إلى الخلف بضع خطوات بثقة. هذا نوع معقّد من التوازن، ويتطلب تناسق حركة الجسم في المكان. العبي معه لعبة «لنمشِ مثل السلطعون». فهي تمرّن مجموعات العضلات بطرق مختلفة، وتصنع أيضًا لحظات مليئة بالضحك.') WHERE id = 'f9c866fa-1063-46f8-bd49-769efa10ff9a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'يزداد حوار «السؤال والجواب» تعقيدًا في تطور الكلام. فقد يسأل: «ما هذا؟» ليس فقط ليتعلم اسم الشيء، بل أيضًا لمواصلة الحديث معكِ. وعندما تجيبين، اذكري أيضًا وظيفة الشيء: «هذا مشط، نستخدمه لتمشيط شعرنا». إن شروحاتكِ المفصّلة توسّع مداركه بسرعة.') WHERE id = 'b9cee91c-b40d-4bad-a4d5-c04129fdcf20';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الحدود العاطفية وكلمة «لا». قد يغضب طفلكِ عندما يريد القيام بكل شيء بنفسه أو عندما لا يحصل فورًا على ما يريده. في هذه اللحظات، حافظي على هدوئكِ وسمّي شعوره قائلةً: «أنت غاضب جدًا الآن، لكن لا يجوز (اذكري القاعدة)». إن ثباتكِ وشرحكِ بنبرة هادئة هما أفضل درس يعلّمه كيفية إدارة مشاعره.') WHERE id = '4c29e86c-55c8-4844-9903-13a58d0c9468';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ قادرًا على تنفيذ التعليمات المكوّنة من خطوتين بسهولة. على سبيل المثال: «خذ اللعبة وضعها على الرف». يشير هذا إلى أن ذاكرته العاملة وفهمه للغة قد بلغا مستوى جديدًا. أعطيه خلال اليوم «مهام» صغيرة كهذه لتدريب إحساسه بالمسؤولية وتعزيز انتباهه.') WHERE id = '63b64ef1-0e7a-45db-8f97-702657621c76';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«إتقان صعود الدرج» ضمن التطور الحركي. قد يحاول طفلكِ الآن صعود الدرج خطوةً خطوةً (بوضع قدم واحدة على كل درجة) عندما تمسكين بإحدى يديه. وهذا يعني أن عضلات فخذيه وحوضه تزداد قوة. ابقي دائمًا بالقرب منه لحمايته، وصفّقي لإنجازاته.') WHERE id = '4d704d6f-6be2-478b-b2bb-0363d0dde71b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بوادر ظهور سؤال «لماذا؟» في الكلام. يشير طفلكِ إلى كل شيء ويسأل: «ما هذا؟»، منتظرًا منكِ التوضيح. اشرحي له اسم كل شيء وفائدته بجمل بسيطة. مثلًا: «هذه فرشاة، نستخدمها لتنظيف أسناننا». تساعد إجاباتكِ دماغه على تصنيف العالم من حوله بطريقة أكثر تنظيمًا.') WHERE id = 'cd8ca16e-d97a-4620-91cf-5f294687b3b5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«محاولات ضبط النفس» في التطور العاطفي. عندما يغضب طفلكِ، قد ينظر إليكِ وينتظر رد فعلكِ. حافظي على هدوئكِ في هذه اللحظات وسمّي شعوره قائلة: «أنت غاضب الآن لأن اللعبة لم تعمل». هدوؤكِ هو أفضل درس له في تنظيم مشاعره. أنتِ أم رائعة!') WHERE id = '10a65a4a-b905-4a99-8c90-141b7917fa27';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ أكثر مهارة في استخدام الملعقة والشوكة. ويمكنه إيصال معظم الطعام إلى فمه من دون سكبه. يدل ذلك على مستوى متقدم من المهارات الحركية الدقيقة والتنسيق بين اليد والعين. أتيحي له فرصة تناول أطعمة ذات قوام متنوع بنفسه. يساعده هذا الاستقلال على فهم شعوره بالشبع بصورة أفضل.') WHERE id = 'cd235f0e-55bc-496a-a89f-89523cd7e8fe';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التسلق والنزول» في التطور البدني. أصبح طفلكِ قادرًا على الصعود إلى الأريكة أو الدرجات المنخفضة بمفرده. ذكّريه دائمًا بالنزول من الأماكن المرتفعة إلى الخلف، بحيث تنزل قدماه أولًا. هذه مهارة مهمة تساعده على تعلّم قواعد سلامة الجسم وتحليل المخاطر بصريًا.') WHERE id = 'b1b72a87-fa8e-4ffe-811e-9806f2ea1d7c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الكلمات الدالة على الحركة» في تطور الكلام. أصبح طفلكِ يستخدم أفعالًا مثل «اذهب» و«تعال» و«نم» و«كُل» في المواقف المناسبة. وسّعي عباراته عند الرد عليه، فقولي مثلًا: «نعم، سنذهب الآن إلى الحديقة». يسرّع ذلك بناء التراكيب النحوية في كلامه.') WHERE id = '275f2048-2ec2-445d-b693-5c34e41e7b83';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الرصّ والتركيب» في المهارات الحركية الدقيقة. أصبح طفلكِ قادرًا على رصّ 8-10 مكعبات فوق بعضها وبناء أبراج ثابتة. يتطلب ذلك تركيزًا ودقة في حركة أطراف الأصابع. عندما ينهار البرج، استقبلي الأمر بمرح حتى يتحمس طفلكِ للمحاولة مجددًا. فهذا يعزز مثابرته على حل المشكلات.') WHERE id = '97370ca6-2fbc-4894-81aa-9ab979d2d27e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ الآن في منتصف شهره الثاني والعشرين، وما زال يشهد «طفرة في اكتساب الكلمات». ولم يعد يحاول تسمية الأشياء فحسب، بل يحاول أيضًا التعبير عن المشاعر والأفعال المعقدة. عندما تتحدثين معه، اجعلي جملكِ أكثر تعقيدًا قليلًا، مثل: «تعالَ، لنرتدِ قبعتك الحمراء ونخرج». فهذا يقوّي ذاكرته السمعية وفهمه للقواعد اللغوية.') WHERE id = '9ec78a78-6722-4c40-af92-d0238d028cd3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في النمو الجسدي، يكتسب طفلكِ «مهارة القفز في مكانه». فقد أصبح أكثر ثقة في رفع كلتا قدميه عن الأرض في الوقت نفسه. تساعد هذه الحركة على تقوية عضلات ربلة الساق لديه وتطوير توازنه. نظّمي معه مسابقة للقفز على أنغام الموسيقى، فهي من أكثر الطرق متعة لتفريغ طاقته.') WHERE id = '43c73105-af4e-4d3a-b15d-a50b903d4d3e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور اللغة، تبدأ مرحلة «تنوّع الصفات». فقد أصبح طفلكِ أقدر على التمييز بين خصائص الأشياء، مثل اللون والشكل والطعم. أدرجي في حياته اليومية عبارات مثل «ليمون حامض» و«تفاحة حلوة» و«ماء بارد». فهذا يساعده على ربط إدراكه الحسي بالكلمات ووصف العالم بطريقة أكثر تنوعًا وحيوية.') WHERE id = '39e55b53-a529-49e6-9321-ad14c32b7c7c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور المهارات الحركية الدقيقة، تظهر مهارة «فكّ الأغطية وفتحها». فقد بدأ طفلكِ يهتم بفتح أغطية الزجاجات أو العبوات المختلفة الأحجام عن طريق تدويرها. وتُعد هذه الحركة تمرينًا ممتازًا لعضلات الرسغ والحركة الدورانية. ادعمي هذا الفضول «الميكانيكي» لديه بمنحه عبوات بلاستيكية فارغة وآمنة.') WHERE id = 'be39779f-3011-4da7-aa56-861a48e906e9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بلغ إصرار طفلكِ على قول «سأرتدي ملابسي بنفسي» ذروته. فقد بدأ يحاول سحب السراويل سهلة الارتداء أو إدخال قدميه في حذائه. امنحيه بضع دقائق إضافية لإتمام هذه العملية. إن إتاحة الفرصة له لإنجاز شيء بنفسه من دون استعجاله تعزز تقديره لذاته (self-esteem) أكثر من أي شيء آخر. صبركِ هو أعظم دعم لاستقلاليته.') WHERE id = 'f0ed327b-3dc6-4a59-97ba-d4b77cc256ae';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي، تبدأ «الدروس الأولى في المشاركة». فقد أصبح طفلكِ يدرك أن إعطاء لعبته لشخص آخر لبعض الوقت لا يعني فقدانها إلى الأبد. ومع ذلك، لا يزال شعوره بأنها «ملكه» قويًا جدًا. لا تجبريه على المشاركة، بل عرّفيه إلى مفهوم «اللعب بالتناوب» من خلال التطبيق العملي. فهذا يسهّل تكيّفه الاجتماعي.') WHERE id = 'ea8bf74e-874e-47bc-9e0f-7dc3094dfe1c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الكلام: "الطلب بأدب". عندما يريد طفلكِ شيئًا، لم يعد يكتفي بالإشارة إليه بإصبعه، بل أصبح قادرًا على قول "أعطني" أو "من فضلك" (أو تعبير مشابه). كوني له دائمًا قدوة في استخدام عبارات التهذيب. فسماعه منكِ عبارات مثل "شكرًا جزيلًا" و"من فضلك" يرسّخ أسس أسلوبه المهذب في التواصل مستقبلًا.') WHERE id = '0ffa5444-e49f-4507-b5e7-cc95f08b1d36';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تنامي قوة الخيال: "ألعاب تقمّص الأدوار تصبح أكثر تعقيدًا". لم يعد طفلكِ يتظاهر بالطهي فحسب، بل يدعو ألعابه إلى زيارته، أو "يعالجها"، أو "يُركبها السيارة ويأخذها إلى العمل". يوضح هذا كيف يربط بين الأحداث المخزنة في ذاكرته. شاركيه ألعاب تقمّص الأدوار، فهذا سيعزز إبداعه إلى أقصى حد.') WHERE id = '24d4307d-0d0c-428b-a2fb-db25c78400d8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يعد طفلكِ يكتفي بالتعرّف على الألوان، بل أصبح بارعًا في مطابقتها. إذا استطاع تنفيذ طلبكِ عندما تقولين له: "اعثر على الجورب المطابق لجوربك الأحمر"، فهذا دليل على تطور منطقه البصري. أكّدي على أسماء الألوان كثيرًا عند اختيار ملابسه اليومية، مثل: "هل نرتدي اليوم قميصك الأخضر؟". فهذا يعزز معرفته بالصفات ضمن حصيلته اللغوية.') WHERE id = '179a1147-4671-4989-8a35-24a67964487b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الجسدية: "التوازن على قدم واحدة". أصبح طفلكِ يحاول رفع إحدى قدميه عن الأرض والحفاظ على توازنه، ولو لبضع ثوانٍ فقط. ويتطلب ذلك تنسيقًا حركيًا معقدًا للتحكم في مركز ثقل الجسم. العبي معه "لعبة اللقلق"؛ فهي ممتعة ومفيدة جدًا لنموه الجسدي في الوقت نفسه.') WHERE id = '6a2ac5db-ce06-4c8b-b0f1-21122d14d9a3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الكلام: "البوادر الأولى لفهم الزمن". يبدأ طفلكِ بفهم الفرق بين كلمات مثل "الآن" و"لاحقًا". وعندما تقولين له: "لنأكل أولًا، ثم نذهب إلى الحديقة" ويستطيع الانتظار، فهذا تقدم كبير. واصلي شرح تسلسل الوقت من خلال أفعالكِ، حتى يكتسب عادة التحلي بالصبر.') WHERE id = '91b2f1d2-b8e0-4586-beb2-1ed7668e668d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: "إتقان تركيب الأحجيات". أصبح طفلكِ قادرًا على حل أحجيات بسيطة مكوّنة من 5-6 قطع بمفرده. ويساعد جمع الصور بصريًا على تعزيز قدرته على التركيز وحل المشكلات. إذا لم ينجح، فأرشديه بهدوء، لكن لا تنجزي المهمة بدلًا منه. فهذه "الانتصارات" الصغيرة تعزز قدراته الإدراكية.') WHERE id = 'feada4a3-1665-4491-8ec1-8dc39ef9224c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'عبارات "السبب والنتيجة" في الكلام. أصبح طفلكِ قادرًا على محاولة قول "لأن" (أو نطق صوت قريب منها) ليشرح سبب رغبته في شيء ما. اشرحي له الأسباب أيضًا: "لن نأكل المثلجات الآن لأن الطقس بارد". فهذا يشكّل أساس تفكيره المنطقي وقدرته على بناء الحجج.') WHERE id = 'f2f8883c-9f63-473e-95a0-d34bd2a07048';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الفك والتدوير" ضمن المهارات الحركية الدقيقة. أصبح طفلكِ قادرًا على فتح أغطية الزجاجات وإغلاقها وتدوير براغي الألعاب بثقة. ويُعد ذلك من أفضل التمارين لتنمية حركة الدوران في عضلات المعصم. قدّمي له أوعية بلاستيكية بأحجام مختلفة لدعم اهتمامه بهذه الآلية. فهذه المهارة مهمة لأداء مهام أكثر تعقيدًا مستقبلًا، مثل الإمساك بالقلم.') WHERE id = '691bb5ce-e086-4aaa-85cf-679930593155';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"أنا أغسل نفسي". أثناء الاستحمام، يحاول طفلكِ أخذ الصابون أو الإسفنجة وفرك جسمه مقلدًا إياكِ. لا تثبطي اهتمامه بعادات النظافة. فمحاولته "تنظيف" نفسه تساعده على التعرّف إلى أعضاء جسمه بصورة أفضل، كما تعلّمه تحمّل مسؤولية نظافته الشخصية منذ سن مبكرة.') WHERE id = 'd4a78241-9e41-44ca-8bb9-8ed66f07c05f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"صعوبة المشاركة" في السلوك الاجتماعي. من الطبيعي جدًا في هذا العمر أن يصرخ طفلكِ: "هذا لي!"، فهو يتعلم حماية ممتلكاته. لا تجبريه على المشاركة، بل طبّقي مبدأ "لنلعب بالتناوب". فهذا يمنحه شعورًا بالأمان لأنه يعلم أنه سيستعيد لعبته. ويسهم صبركِ هذا في تنمية ذكائه الاجتماعي.') WHERE id = '6ff62ac3-5f68-4753-ac59-118eb1c39c2b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"المطابقة" (Matching) في التطور المعرفي. أصبح طفلكِ قادرًا على مطابقة صور مختلفة للحيوان نفسه، أو الأشياء التي لها اللون نفسه. العبي معه لعبة "اعثر على المطابق" باستخدام بطاقات بسيطة. فهذا يطوّر بسرعة انتباهه البصري وقدرته على التفكير وفق الفئات.') WHERE id = '63ba4843-04a1-423b-8338-e5d3a90cedb9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "رمي الكرة بعيدًا". لم يعد طفلكِ يكتفي بإسقاط الكرة على الأرض، بل يحاول رميها إلى الأمام من فوق كتفه (overhand). تتطلب هذه الحركة تناسق الجسم بأكمله. العبي معه في الحديقة أو في مكان واسع لعبة "من يرمي الكرة إلى مسافة أبعد؟". فهذا يقوّي ذراعيه ويعزّز إدراكه للمسافات.') WHERE id = '972bc93a-ef8b-4efd-af66-730802aaa073';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الفصول والطقس» في التطور المعرفي. أصبح طفلكِ يلاحظ تغيرات الطقس في الخارج (المطر، الشمس، الرياح) ويتفاعل معها. انظري معه من النافذة وسمّي الظواهر قائلةً: «إنها تمطر». فهذا يعزز ارتباطه بالبيئة المحيطة ويضيف مصطلحات جديدة عن الطبيعة إلى حصيلته اللغوية.') WHERE id = 'e5dc7560-975f-4493-9ff3-ea6744e46ec0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «تسديد الكرة نحو الهدف». لم يعد طفلكِ يركل الكرة أمامه فحسب، بل يحاول توجيهها نحو هدف محدد (كالمرمى مثلًا). ويجمع ذلك بين الانتباه البصري والتناسق الحركي. نظّمي معه في المنزل مباراة «كرة قدم» صغيرة باستخدام كرة طرية.') WHERE id = 'f701f5d4-0488-45fc-bf57-a9b74d61b0af';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الذاكرة والحكايات» في تطور الكلام. أصبح طفلكِ يعرف حكايته المفضلة جيدًا لدرجة أنه يستطيع إكمال الجملة عندما تتوقفين في منتصفها. توقفي قليلًا أثناء قراءة الحكاية وانتظري منه أن يتابعها. فهذا ينمّي ذاكرته وقدرته على فهم تسلسل الأحداث بدرجة مذهلة.') WHERE id = 'c61438a5-bdff-4ed0-b914-6e977fdb2bc1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الاستعداد العاطفي: لم يتبقَّ سوى أيام قليلة على بلوغ طفلكِ عامه الثاني! أصبح الآن يعبّر عن مشاعره بطرق أكثر تعقيدًا. فقد يطلب العناق فجأة، أو يركض ويختبئ ليثبت استقلاليته. في هذه المرحلة، يُعد التواصل معه بصبر وإشعاره بأنكِ إلى جانبه في كل خطوة من أهم ما يعزز شعوره بالأمان العاطفي.') WHERE id = 'bcd3ac04-2293-413d-8bfd-ba0e21e03fe2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ يُظهر ذوقه وخياراته بحزم. فهو يريد أن يقرر أي كتاب ستقرآن أو بأي لعبة ستلعبان. امنحيه هذه الفرص الصغيرة للقيادة؛ فهي تنمّي قدرته على اتخاذ القرار وتساعده أيضًا على الشعور بأنه شخص مهم وذو قيمة.') WHERE id = 'b41a09b6-e8fc-4b09-b81c-400b678af920';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التوازن الديناميكي» في التطور الجسدي. أصبح طفلكِ يحاول المشي على خط أو السير على حافة رصيف منخفضة (عندما تمسكين بيده). وهذا تمرين ممتاز للتحكم في مركز ثقل الجسم. عززي تناسقه الحركي أثناء التنزه في الحديقة من خلال اللعب معه بالمشي على الخطوط المرسومة على الأرض.') WHERE id = '5d42a805-244d-4112-9107-40ebc50ef785';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«أشرب بنفسي». أصبح طفلكِ الآن يشرب الماء بثقة من كوب مفتوح، من دون أن يسكبه تقريبًا. وهذا مؤشر على مدى استعداد عضلات شفتيه وفكّه للنطق. واصلي إعطاءه أكوابًا بحجم مناسب للأطفال يسهل عليه إمساكها، حتى يتقن هذه المهارة تمامًا.') WHERE id = '20e5b03d-5d16-4142-97b2-3cffec7b0034';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«روح الدعابة» في السلوك الاجتماعي. قد يتعمد طفلكِ فعل شيء «خاطئ» (كأن يضع قبعته في قدمه مثلًا)، ثم ينظر إليكِ ويضحك. وهذا يدل على بدء تطور فهمه للمزاح وقدرته على التفاعل الاجتماعي بمرح. شاركيه هذه «اللعبة» بحماس؛ فالضحك معًا يعمّق الرابطة العاطفية بينكما.') WHERE id = '0f7fea0c-bb47-4b7d-9391-ab4589f33670';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الارتفاع والمسافة» في التطور المعرفي. أصبح طفلكِ الآن أقدر على تقدير المسافة عند نزول الدرج أو الأريكة. ذكّريه دائمًا بتوخي الحذر وبطرق النزول الآمنة، مثل النزول إلى الخلف. فهذه مرحلة مهمة في تعلّمه قواعد سلامة الجسم.') WHERE id = '6dd30633-3c9b-4455-9878-c9a89b329928';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «تغيير الاتجاه أثناء القفز». لم يعد طفلكِ يكتفي بالقفز في مكانه، بل يحاول تغيير اتجاهه أثناء القفز. وهذا يدل على مستوى متقدم من التناسق في المهارات الحركية الكبرى. العبي معه ألعابًا حركية على سجادة ناعمة؛ فهذا يساعده على تفريغ طاقته والتحكم في جسمه بصورة أفضل.') WHERE id = '85fd0d24-866e-4847-be35-912d99da58df';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الحيوانات وصغارها» في تطور النطق. أصبح طفلكِ يعرف أسماء الحيوانات، وقد يبدأ الآن بإظهار اهتمام بالتمييز بينها وبين صغارها (مثل القطة والهريرة). تحدّثي عن هذه التفاصيل عند قراءة الكتب له. فهذا ينمّي قدرته على التفكير وفق الفئات، ويزيد اهتمامه بالطبيعة أيضًا.') WHERE id = 'ce938ec0-b1a1-418d-9c79-f5996a2ee822';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الإرادة والحدود» في التطور العاطفي. أصبح طفلكِ الآن يدرك تمامًا قوة كلمة «لا» ويستخدمها كثيرًا. في هذه المواقف، حافظي على هدوئكِ وحاولي تحويل «لا» إلى «نعم» بمنحه خيارات. إن حزمكِ ونهجكِ اللطيف في الوقت نفسه هما أفضل وسيلة لتعليمه كيف يكون حرًا ضمن القواعد والحدود.') WHERE id = '699f4641-31b9-4174-a887-f0cb838a43e4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'نبدأ الأيام العشرة الأخيرة من الشهر الثالث والعشرين! أصبح طفلكِ الآن يستخدم ضمير "أنا" وهو مدرك لمعناه تمامًا. فجمل مثل "أنا جئت" و"أنا أكلت" تدل على أنه يرى نفسه فردًا مستقلًا عن محيطه. ادعمي تعبيراته المستقلة ووسّعي حواراته: "نعم، لقد أكلتَ طعامك اللذيذ، أحسنت!".') WHERE id = '7aacd700-e4fe-464f-89ef-4b8e3945aa5a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في النشاط البدني: "المناورة أثناء الجري". أصبح طفلكِ قادرًا على تغيير اتجاهه فجأة أثناء الجري بسرعة أو الالتفاف حول العوائق. وهذا يدل على قوة عضلاته وقدرته على اتخاذ قرارات سريعة. عزّزي رشاقته باللعب معه في الحديقة بلعبة "أمسكني".') WHERE id = 'a492f1d5-4125-4356-ab32-a3a06c3ae006';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: "مفهوم الكثرة". يبدأ طفلكِ الآن في فهم الفرق بين "واحد" و"كثير". أريه ألعابه وقولي: "توجد هنا سيارات كثيرة"، لتضعي الأسس الأولى لتعلّم العد. وحتى إن لم يكن قادرًا بعد على ذكر الأرقام بالترتيب، فإن إدراكه البصري للاختلاف في الكمية يمثل بداية تفكيره الرياضي.') WHERE id = '6541c63d-d78c-444c-93ac-32836d55b462';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: "أعمال فنية". أصبح طفلكِ يمسك قلم التلوين بدقة أكبر ويحاول رسم "خطوط مغلقة" (أشكال تشبه الدائرة). أعطيه أقلام تلوين بألوان مختلفة وشجّعيه بتشبيه كل شكل يرسمه بشيء ما: "انظر، هذا يشبه الكرة!".') WHERE id = 'de8e6a20-ca58-4eb3-bdc2-7db3ed5bcda2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"أنا أساعد بنفسي". يستمتع طفلكِ كثيرًا بمساعدتكِ في الأعمال المنزلية. أعطيه مهام حقيقية مثل: "ساعدني في وضع الملابس في السلة". فهذا ينمّي مهاراته الحركية وشعوره بالمسؤولية داخل الأسرة. وبعد أن يساعدكِ، قولي له: "أنت أكبر مساعد لي".') WHERE id = 'f2819b1a-b1cb-4ed8-b546-aae23641438e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: "قواعد اللباقة". قد يبدأ طفلكِ الآن باستخدام عبارتي "شكرًا جزيلًا" و"من فضلك" في موضعهما الصحيح. وبالطبع، يعتمد ذلك على كونكِ قدوة له. استخدمي هاتين العبارتين أمامه في كل مرة تعطينه فيها شيئًا أو تأخذين منه شيئًا. فهذا يضع أفضل الأسس لآداب التواصل لديه مستقبلًا.') WHERE id = 'eb0307cc-cb5a-49a5-b989-e572cad76794';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الكلام: «الذاكرة والأحداث». يستطيع طفلكِ تذكّر حدث بسيط وقع خلال اليوم (مثلًا: «رأيت كلبًا في الحديقة») وإخباركِ به. استمعي إلى حكاياته باهتمام، وساعديه على ترتيب الأحداث بسؤاله: «وماذا حدث بعد ذلك؟». فهذا يقوّي ذاكرته وقدرته على التعبير.') WHERE id = '9fdcc45e-2b1e-4d3c-95a7-d7f5adca9ccb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الاستعداد العاطفي: لم يتبقَّ سوى ٥٠ يومًا على بلوغ طفلكِ عامين! أصبح طفلكِ يعبّر عن مشاعره بعمق أكبر. وقد يُظهر حبّه لكِ بعناق أو قبلة مفاجئة. بادليه الحنان نفسه. فهذا التبادل العاطفي هو أهم ما يغذّي شعوره بالأمان، والأهم من ذلك، شعوره بأنه «شخص محبوب».') WHERE id = '78317024-ad5b-4a00-86b5-ab43a417337b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يعد طفلكِ يكتفي بالتمييز بين الألوان، بل أصبح ينطق أسماء كثير منها نطقًا صحيحًا. إذا لم يخطئ عندما تقولين له: «أحضر السيارة الزرقاء»، فهذا يعكس تكامل ذاكرته البصرية واللفظية. واصلي إثراء عالمه بالألوان خلال جولاتكما اليومية، باستخدام أوصاف مثل «ورقة خضراء» و«شمس صفراء».') WHERE id = '85496aa4-c911-4bb2-8f2e-3e5a32779858';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الحركة الجسدية: «الاستقلالية على الدرج». أصبح طفلكِ يحاول صعود الدرج، ممسكًا بيد واحدة فقط، ويضع قدمًا على كل درجة بالتناوب. وهذا إنجاز مهم في تطور المهارات الحركية الكبرى. ابقي دائمًا بالقرب منه لحمايته، لكن امنحيه الثقة ليخطو بنفسه.') WHERE id = 'e1b72aca-8d9f-4f33-aedd-ed905b733dbf';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الكلام: «الكلمات الدالة على المكان». أصبح طفلكِ قادرًا على إظهار فهمه لمفاهيم مثل «فوق» و«تحت» و«خلف» من خلال أفعاله. العبي معه لعبة صغيرة بأن تقولي له: «ضع الكرة تحت الكرسي». تُسرّع هذه المهام تطور فهمه للغة وقدرته على تحديد الاتجاهات في المكان.') WHERE id = '455a2119-ac1e-44e4-8b8c-20b0405c50d6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: «إتقان الفكّ والتدوير». أصبح طفلكِ قادرًا على فتح أغطية الزجاجات وإغلاقها، وكذلك فكّ براغي الألعاب وشدّها بثقة. وهذا تمرين ممتاز لمرونة عضلات الرسغ. ادعمي اهتمامه بهذا الاستكشاف «الميكانيكي» من خلال إعطائه أوعية آمنة بأحجام مختلفة.') WHERE id = '61305052-b44e-493c-a6f8-ffe876e0e01e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الجمل المكوّنة من ثلاث كلمات" في الكلام. أصبح طفلكِ الآن قادرًا على تكوين جمل أكثر تعقيدًا مثل: "ماما، أعطيني ماءً" و"بابا، اذهب إلى الحديقة". وبات يستطيع التعبير عن احتياجاته بوضوح. أكّدي كلامه ووسّعي جمله قليلًا، مثل: "نعم، تعالَ نشرب الماء الآن، ثم نذهب إلى الحديقة". فهذا يعزّز فهمه للقواعد اللغوية.') WHERE id = '8ba75ebe-7968-4c36-9120-369b2e5d0ec2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تتطور "مهارة تركيب الأحجيات" ضمن المهارات الحركية الدقيقة. أصبح طفلكِ قادرًا على تركيب أحجيات بسيطة مكوّنة من 6-8 قطع بمفرده. ويتطلب ذلك التحليل البصري ودقة حركة عضلات الأصابع معًا. أظهري فرحتكِ في كل مرة يُكمل فيها الصورة، حتى يزداد اهتمامه بالمهام الأكثر تعقيدًا.') WHERE id = '527f78da-7fbc-42ab-a36c-6bee3afe966e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"أنا أرتّب بنفسي". لم يعد إعادة الألعاب إلى مكانها مجرد مهمة بالنسبة إلى طفلكِ، بل أصبحت مسؤولية. إذا كان يساعدكِ عندما تقولين له: "هيا، لنضع السيارات في مكان نومها"، فهذا يشكّل أساس الانضباط والنظام. وستكون هذه العادة مهمة جدًا لتنظيمه الشخصي في المستقبل.') WHERE id = '4cae5197-2921-4caa-b98c-16f64a7694c8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"المشاركة وتبادل الأدوار" في السلوك الاجتماعي. أصبح طفلكِ يفهم الآن أنه عندما تقولين: "حان دورك الآن"، فعليه الانتظار قليلًا. ويُعد تعلّم الصبر إنجازًا كبيرًا في هذا العمر. ادعميه في الألعاب التي تعتمد على تبادل الأدوار، مثل تمرير الكرة بينكما. فأسلوبكِ الصبور يسهّل تكيّفه الاجتماعي.') WHERE id = 'e3e7be7f-e682-47f1-bdf9-05213d301d28';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"المتشابه والمختلف" في التطور المعرفي. أصبح طفلكِ قادرًا الآن على تصنيف الأشياء المتشابهة، مثل وضع جميع الحيوانات في مكان وجميع السيارات في مكان آخر. اختبري منطقه البصري بطرح أسئلة مثل: "أي لعبة هنا مختلفة؟". فالتفكير وفق الفئات ينقل قدراته المعرفية إلى مستوى جديد.') WHERE id = '9960803a-4e47-4edd-b50d-dc62d848c875';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "القفز في المكان والدوران". لم يعد طفلكِ يكتفي بالقفز، بل يحاول تدوير جسمه أثناءه. وهذا يدل على مستوى متقدم من التناسق في المهارات الحركية الكبرى. نظّمي معه أوقاتًا حركية "للرقص" على أنغام الموسيقى. فهذا نشاط ممتع وتمرين ممتاز لمرونة الجسم في آنٍ واحد.') WHERE id = 'b8a638df-098e-4767-9ebb-0f4df5304a5e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'يقترب طفلكِ الآن من نهاية شهره الثالث والعشرين. وقد أصبح يفهم تمامًا أنه لا يُشار إليه بضمير «أنا» فحسب، بل يُنادى أيضًا باسمه. عندما تسألينه أثناء الحديث: «هل فعلتَ هذا؟» فيجيب بفخر: «نعم»، فهذا دليل على تطور وعيه بذاته. امدحي إنجازاته بذكر اسمه: «أحسنتَ يا (اسم الطفل)، لقد نجحتَ في فعل ذلك!».') WHERE id = '9459dc0c-afe8-45b3-b94d-dd65b48126f2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الجسدية، تبرز مهارة «الجري والتوقف بحرية». أصبح طفلكِ الآن قادرًا على التوقف فجأة أثناء الجري من دون أن يسقط. وهذا يدل على مدى تطور التحكم التثبيطي لديه وعضلاته. العبي معه في الحديقة لعبة «اركض وتوقف!»؛ فهي ممتعة ومفيدة أيضًا لتنمية التناسق الحركي.') WHERE id = 'ecf7ae38-688c-4cbe-90a0-7112da130536';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام، تبدأ «مرحلة طرح الأسئلة». بعد أن تعرّف طفلكِ إلى أسماء الأشياء، أصبح يميل إلى السؤال عن استخداماتها. عندما يشير إلى شيء ويقول: «ما هذا؟»، لا تكتفي بذكر اسمه، بل اشرحي له وظيفته أيضًا: «هذه مظلة، نستخدمها للاحتماء من المطر». تساعد إجاباتكِ المفصّلة على توسيع مداركه بسرعة.') WHERE id = 'cb8ab97b-604a-4728-ac40-ae0675a2ce85';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة، تظهر «الخطوط الرأسية والأفقية». أصبح طفلكِ يمسك قلم التلوين بثقة أكبر ويرسم خطوطًا مستقيمة مقصودة على الورق. ادعمي مهاراته «الفنية» بتزويده بأقلام تلوين مختلفة الألوان وأوراق كبيرة. فهذا يشكّل أساسًا مهمًا لمهارات الكتابة مستقبلًا.') WHERE id = 'b5be883e-3ec9-4583-905f-d5eaa6d996f3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بلغت «القدرة على الاختيار المستقل» ذروتها. أصبح طفلكِ يرغب في أن يقرر بنفسه ما سيأكله، وبأي لعبة سيلعب، وحتى أي طريق سيسلك. قدّمي له خيارات محدودة: «هل ستأكل تفاحة اليوم أم موزة؟». فهذا يعزز قدرته على اتخاذ القرار، ويجعله يشعر بأنه شخص يتحكم في اختياراته لا شخص تتحكم فيه القرارات.') WHERE id = 'd071c76a-b155-43af-a2a1-de9194ca4c11';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي، يظهر «التقليد الرمزي». أصبح طفلكِ يقلّد أدواركِ في المنزل؛ فيتظاهر بأنه «يطبخ»، و«يتحدث عبر الهاتف»، و«ينظف المنزل». هذا التقليد هو طريقته في التعرّف إلى العالم. قدّمي له مكنسة صغيرة للعب أو بعض أواني اللعب، وأتيحي له فرصة أن يكون «مساعدكِ».') WHERE id = 'ee398ccc-6f29-41df-b0a4-1bb95b88b1a5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تزداد مرحلة "أنا أرتدي ملابسي بنفسي" تعقيدًا. فقد أصبح طفلكِ يحاول الآن رفع السحّاب (بعد أن تبدئي بإدخاله) أو فك الأزرار الكبيرة. لا تعيقيه أو تستعجليه خلال هذه العملية. فرؤيته لنفسه وهو ينجح في فعل شيء ما هي أكبر مصدر لثقته بنفسه. احرصي على تشجيعه عند كل نجاح صغير.') WHERE id = 'f6d69242-03a3-4cc8-a444-aac7bbd07185';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'يزداد "التعاطف" في سلوك طفلكِ الاجتماعي. فعندما يراكِ حزينة أو يرى طفلًا آخر حزينًا، قد يأتي ليعطيكِ لعبته أو يعانقكِ. وهذا مؤشر جميل على ذكائه العاطفي (EQ). كافئي اهتمامه هذا بقولكِ: "شكرًا جزيلًا لأنك ساندتني".') WHERE id = '98c8accf-ca7d-4901-b417-a3bce7f325f2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: "الشكل والحجم". أصبح طفلكِ قادرًا الآن على التمييز بين النسختين الكبيرة والصغيرة من الشكل نفسه (مثل الدائرة). أريه كيف يضع أوعية مختلفة الأحجام بعضها داخل بعض. فهذا ينمّي مهارة "الترتيب" لديه، وهي أساس تفكيره الرياضي مستقبلًا.') WHERE id = 'bfdb17de-cc0d-437c-870c-13801051e507';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "ركل الكرة نحو هدف". لم يعد طفلكِ يركل الكرة فحسب، بل يحاول توجيهها نحو اتجاه محدد. وهذا يجمع بين الانتباه البصري والتناسق الحركي. أنشئي معه "مرمى صغيرًا" في المنزل أو الحديقة، والعبا معًا لعبة ركل الكرة نحوه. فهذا يقوّي عضلات ساقيه ويحسّن دقته.') WHERE id = 'a17dc9b7-c84f-4802-8431-7aad7b966067';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: "محاولات سرد القصص". يتحمس طفلكِ ليخبركِ عن شيء مثير للاهتمام رآه خلال اليوم (مثل: "رأيت كلبًا كبيرًا"). استمعي إلى قصته حتى النهاية وساعديه على توسيعها بالأسئلة، مثل: "ما لون الكلب؟". فهذا يقوّي ذاكرته وقدرته على التعبير عن نفسه.') WHERE id = 'daff24e3-d7cd-46e0-9c7d-75e6a3417d53';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الحدود العاطفية: قد يعبّر طفلكِ الآن عن إرادته بوضوح وحزم قائلًا: "لا أريد". في هذه اللحظات، بدلًا من الدخول معه في صراع عناد، امنحيه خيارات وشتّتي انتباهه. إن صبركِ وثبات القواعد يمنحانه شعورًا بالأمان. لم يتبقَّ سوى 40 يومًا على بلوغه عمر 2 سنوات – أنتِ تقومين بعمل رائع!') WHERE id = '30c55932-1036-4bc0-a31f-1b927f46a841';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: «تكوين الكل من الأجزاء». أصبح طفلكِ قادرًا الآن على تركيب أحجيات بسيطة مكوّنة من 3-4 قطع بالاعتماد على الرؤية. ويساعد ذلك على تنمية قدرته على التركيز وحل المشكلات. عندما لا ينجح، ساعديه بنبرة هادئة: «انظري، هذا ذيل الكلب، أين يمكن أن يكون مكانه؟». هذه الانتصارات الصغيرة تعزز قدراته المعرفية.') WHERE id = '6ae9f735-9ae2-46e6-8771-fa1ead2cea34';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق البدني: «ركل الكرة والجري». أصبح طفلكِ قادرًا الآن على ركل الكرة أمامه أثناء الجري من دون أن يفقد توازنه. وهذا يعني التحكم في سرعة الحركة والتوازن الديناميكي في الوقت نفسه. عززي دقة حركاته من خلال لعب «كرة القدم» معه في الفناء أو الحديقة. فالحركة واللعب معكِ هما أكبر متعة بالنسبة إليه.') WHERE id = '17868f49-652d-4efe-940b-fac27063768e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: «التعبير عن الذكريات». يستطيع طفلكِ تذكّر حدث رآه أو مرّ به بالأمس وإخباركِ عنه، مثل: «رأيتُ طائرًا في الحديقة». استمعي باهتمام إلى قصصه ووسّعي الحوار بسؤاله: «ماذا كان الطائر يفعل؟». فهذا يعزز ذاكرته وقدرته على التعبير عن نفسه بدرجة مذهلة.') WHERE id = 'd99ef035-085a-4da0-b18e-ddf8dda326d1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد أتممنا 700 يوم! لم يتبقَّ على بلوغ طفلكِ عامين سوى شهر واحد (30 يومًا). لقد تجاوز طفلكِ الآن مرحلة الرضاعة تمامًا، وأصبح «إنسانًا» صغيرًا له شخصيته ورغباته ومهاراته الخاصة. احتفلي اليوم بهذه الرحلة الطويلة من خلال مشاركته لعبته المفضلة. لقد قطعتِ شوطًا رائعًا يا أمي!') WHERE id = '0e3a52c6-9f66-42e2-994a-692b5b642618';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'نبدأ الخطوات الأخيرة نحو الشهر 24، أي نحو إتمام طفلكِ عامه الثاني! أصبح طفلكِ الآن يعرف أغراضه وملابسه جيدًا جدًا. إذا نفّذ طلبكِ عندما تقولين له: «أحضر قميصك من خزانة الملابس»، فهذا يدل على تطور ذاكرته وشعوره بالملكية والانتماء. مثل هذه المهام الصغيرة تعزز ثقته بنفسه.') WHERE id = 'f1337afd-8cd4-4800-85b9-83874ec33ec8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور البدني: «التوازن على حواف الأرصفة». أصبح طفلكِ الآن يُبدي اهتمامًا بالمشي فوق حواف الأرصفة المنخفضة عندما تمسكين بيده. ويساعد ذلك على تنمية قدرته المتقدمة على التوازن. ادعمي هذا الاهتمام في الأماكن الآمنة، لأنه يشكّل أساسًا لأداء حركات بدنية أكثر تعقيدًا في المستقبل.') WHERE id = '48e8258d-7e1b-417f-861b-84e4a830fb92';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«المشاركة والحدود» في السلوك الاجتماعي. بات طفلكِ يفهم أن بعض الأشياء تخصه، بينما تخص أشياء أخرى أشخاصًا غيره. وقد يظل يجد صعوبة في مشاركة ألعابه. علّميه مفهوم تبادل الأدوار بقولكِ: «هذه لك الآن، وبعد قليل سيلعب بها صديقك». وهذه من أهم الخطوات للتكيف الاجتماعي.') WHERE id = '0337bbc8-021f-48c3-b2d6-9d07615b2eb6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«أنا أساعد». يستمتع طفلكِ كثيرًا بمساعدتكِ في الأعمال المنزلية. فالمهام الصغيرة، مثل وضع الملابس في السلة أو الخبز على المائدة، تجعله يشعر بأنه «فرد مهم» في الأسرة. امدحي حماسه بقولكِ: «لولاك، لاستغرقتُ وقتًا أطول لإنجاز هذا!».') WHERE id = '176cc57c-d49b-4d93-9ce5-5829f43afd94';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«أسماء الألوان» في التطور المعرفي. لم يعد طفلكِ يكتفي بتمييز الألوان، بل أصبح ينطق أسماء كثير منها نطقًا صحيحًا. طبّقي معلوماته عمليًا أثناء التنزه في الحديقة بقولكِ: «أين الورقة الخضراء هنا؟» أو «أرني الزهرة الصفراء». فهذا يربط بين ذاكرته البصرية واللفظية.') WHERE id = 'b1599687-8b9b-4b36-972d-e646da9ca057';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «رمي الكرة من فوق الكتف». لم يعد طفلكِ يرمي الكرة على الأرض فحسب، بل يحاول رميها عمدًا إلى الأمام أو نحوكِ. وهذا دليل على تطور عضلات ذراعه وقدرته على تقدير الهدف. حسّني دقته باللعب معه لعبة «من يستطيع إدخال الكرة في السلة؟».') WHERE id = 'a5dba3a5-d849-43ef-ab12-3acff84027fc';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الطلب والتهذيب» في تطور الكلام. عندما يريد طفلكِ شيئًا، لم يعد يكتفي بالإشارة إليه بإصبعه، بل يحاول أن يقول «أعطني» أو «من فضلك» (حتى لو قالها بطريقته الخاصة). وأسلوبكِ المهذب أمامه يشكّل طريقة تواصله. وكلما قلتِ «شكرًا جزيلًا»، اكتسب هو أيضًا هذا السلوك المهذب بصورة طبيعية.') WHERE id = 'd8b07d2d-d5ae-44e4-8e83-13117a3ef758';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الاستعداد العاطفي: لم يتبقَّ سوى 10 أيام على إتمام طفلكِ عامه الثاني! بات طفلكِ يعبّر بوضوح شديد عن مشاعره، مثل الفرح والغضب والخجل. تقبّلي هذه المشاعر بصبر وسمّيها له بقولكِ: «أنت سعيد الآن لأننا ذاهبان إلى الحديقة». فتسمية المشاعر تساعد الطفل على فهم عالمه الداخلي وتطوير قدرته على ضبط نفسه مستقبلًا.') WHERE id = '5b177d90-0a27-4e2b-8501-6cbcb2351fef';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الاستخدام الدقيق للضمائر» في الكلام. أصبح طفلكِ يضع ضمائر مثل «أنا» و«أنتَ» و«هو» في مواضعها الصحيحة داخل الجملة. مثلًا: «أنا جائع» أو «تعالَ أنتَ». ولدعم هذا التطور، شدّدي أنتِ أيضًا على الضمائر عند مخاطبته. فهذا يساعده على تطوير مهارات التواصل الاجتماعي بسرعة أكبر.') WHERE id = '6c0e87a6-05f9-4b6b-826c-adb939561dc2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«مهارة البناء» في المهارات الحركية الدقيقة. لم يعد طفلكِ يكتفي برصّ المكعبات بعضها فوق بعض، بل أصبح يبني بها أشكالًا مثل «منزل» أو «قطار» أو «سياج». وهذا يدل على انتقال تفكيره البصري المكاني إلى مرحلة جديدة. أظهري اهتمامكِ «بمبانيه» واطرحي عليه أسئلة مثل: «من سيأتي إلى هنا؟».') WHERE id = 'd0a7b08b-aa7f-465e-8cfb-7b1cbe914d24';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«ازدياد تعقيد لعب الأدوار» في السلوك الاجتماعي. أصبح طفلكِ ينظّم ألعابًا تتضمن عدة حركات متتالية؛ فمثلًا «يغسل» دبدوبه اللعبة، ثم «يجففه»، وبعد ذلك «يضعه في السرير». وهذا يوضح كيف يربط بصورة منظّمة بين سيناريوهات الحياة اليومية المحفوظة في ذاكرته.') WHERE id = '290cdbcc-b930-4c04-ac8f-c9e9a99f2bd8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«إتقان تناول الطعام باستقلالية». أصبح طفلكِ ماهرًا جدًا في التقاط الطعام بالشوكة ووضعه في فمه. امنحيه مزيدًا من الفرص لتناول الطعام بنفسه. فبعض الفوضى على المائدة ثمن بسيط مقابل تطوير مهاراته الحركية الدقيقة وتعزيز مسؤوليته عن الاعتناء بنفسه.') WHERE id = 'a907e23d-d22f-4f12-8eba-ed2e00af2852';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«كبير-صغير-متوسط» في التطور المعرفي. قد يبدأ طفلكِ الآن بالتمييز بين ثلاثة أحجام مختلفة بدلًا من حجمين فقط. قدّمي له ثلاث نسخ من اللعبة نفسها بأحجام مختلفة، واختبريه بقولكِ: «أعطني الأكبر». فهذا يشكّل أساس مهارات المقارنة الرياضية لديه. وشجّعيه كلما اختار الإجابة الصحيحة.') WHERE id = '228f5557-8af1-45e0-8eea-dab6d6ab319d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق البدني: «القفز إلى الأمام بكلتا القدمين». لم يعد طفلكِ يقفز في مكانه فحسب، بل أصبح قادرًا أيضًا على القفز مسافة قصيرة إلى الأمام. ويتطلب ذلك قوة اندفاعية في عضلات الساقين وتناسقًا جسديًا جيدًا. العبي معه في الحديقة لعبة «الأرانب تقفز في المرج». فهي ممتعة، كما أنها تمرين ممتاز للمهارات الحركية الكبرى.') WHERE id = 'fed4cb8e-d23c-4ef3-9fb0-62697ac89488';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«استنتاج النتائج» في تطور الكلام. أصبح طفلكِ قادرًا على توقّع نتائج بعض الأحداث. فعلى سبيل المثال، عندما تأخذين حذاءكِ يسأل: «هل سنخرج؟». وهذا يدل على مدى قدرته على تكوين الروابط المنطقية. أكّدي له صحة استنتاجاته وقدّمي له معلومات إضافية: «نعم، سنخرج لنطعم الطيور بعض الخبز».') WHERE id = '0aaeb1eb-0155-44f3-b404-be39c9061780';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الاستعداد العاطفي: لم يتبقَّ سوى 20 يومًا على بلوغ طفلكِ عامين! أصبح الآن يعبّر عن مشاعره بوضوح أكبر، ويُظهر تعلّقه بكِ من خلال قول «أحبكِ» أو بإيماءات تحمل معنى مشابهًا بلغته الخاصة. كل لحظة تقضينها معه في هذه الأيام تترك أثرًا خالدًا في عالمه العاطفي. أنتِ أم ومرشدة رائعة!') WHERE id = 'f640772a-39c6-4d33-9c3f-64bd16ad5ed0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بلغ طفلكِ الآن أكثر مراحل «سأرتدي ملابسي بنفسي» إصرارًا. فرغبته في ارتداء سرواله أو انتعال حذائه بنفسه، حتى لو كان ذلك صعبًا، هي تعبير عن استقلاليته. امنحيه بضع دقائق إضافية ليحاول. إن صبركِ هذا هو أعظم استثمار في ثقته بنفسه مستقبلًا.') WHERE id = 'e264db36-ff8b-4ffc-8d0c-2a9a86b8e80e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الدوران في المكان» ضمن التطور الحركي. أصبح طفلكِ يستمتع بالدوران حول نفسه ويستكشف بفضول الشعور بـ«الدوار» الناتج عنه. وهذا جزء من تطور جهازه الدهليزي المسؤول عن التوازن. هيّئي له مساحة آمنة وناعمة، وارقصي معه لتتيحي له فرصة استكشاف هذا الإحساس الجديد.') WHERE id = 'c1b5ac77-3624-4a68-8f84-6255305e6a71';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الجمل متعددة الكلمات» في تطور الكلام. أصبح طفلكِ قادرًا على جمع 3-4 كلمات للتعبير عن أفكار أكثر تعقيدًا، مثل: «ماما، أريد سيارة كبيرة». لا تصحّحي جمله مباشرة، بل أجيبيه بتكرار الصيغة الصحيحة: «نعم، هل تريد أن تلعب بتلك السيارة الحمراء الكبيرة؟». فهذا يساعده على استيعاب بنية اللغة بسلاسة.') WHERE id = '4ada0942-f71a-4215-a9a2-e770a9dcbe42';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الإبداع الفني» ضمن تطور المهارات الحركية الدقيقة. أصبح طفلكِ يمسك قلم التلوين بثقة أكبر ويحاول رسم خطوط دائرية على الورق. وهذا أساس التناسق العضلي اللازم للكتابة مستقبلًا. قدّمي له ألوانًا متنوعة وأوراقًا كبيرة، وأطلقي العنان لخياله.') WHERE id = 'c206267a-2d42-4d2c-8a75-f79f89a1455a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يتبقَّ سوى ١٠ أيام على إتمام طفلكِ عامه الثاني! أصبح طفلكِ الآن مدركًا تمامًا لهويته. ينظر إلى نفسه في المرآة ويقول اسمه أو يشير قائلًا: "هذا أنا!". يشكّل هذا الوعي بالذات أساس ثقته بنفسه في المستقبل. قفي معه أمام المرآة واحتفلا معًا بمدى نموه وبكل ما أصبح قادرًا على فعله.') WHERE id = '391d8114-3346-495b-b8f3-45861173d919';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة "الجري المركّب" في النمو البدني. أصبح طفلكِ قادرًا على تفادي العقبات التي تعترض طريقه أثناء الجري بمناورات سريعة. وهذا يجمع بين القوة البدنية والقدرة على اتخاذ القرارات بسرعة. أنشئي له "مسار عقبات" صغيرًا في المنزل أو الفناء، وأتيحي له فرصة اختبار رشاقته.') WHERE id = '23f145d6-39f1-4e1e-84f1-49d36b707443';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة "راوي القصص" في تطور الكلام. أصبح طفلكِ قادرًا على تذكّر حدث بسيط وقع خلال اليوم وروايته لكِ، مثل: "طار الطائر" أو "أكلتُ المثلجات". أنصتي باهتمام إلى قصصه الصغيرة وساعديه على توسيعها بطرح الأسئلة. فهذا يقوّي ذاكرته وقدرته على بناء تسلسل منطقي بين الأحداث.') WHERE id = 'c8794b59-4f44-4d01-9dfd-9f86547c80bb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة "حب الكتب" في تطور المهارات الحركية الدقيقة. أصبح طفلكِ قادرًا على تقليب الصفحات الورقية الرقيقة واحدة تلو الأخرى من دون تمزيقها. وقد يُحضر كتاب القصص المفضّل لديه ويضعه على ركبتيكِ لتقرئيه له. هذا الطقس مهم للغاية لتطور لغته ولتعزيز الرابط العاطفي بينكما. اطرحي عليه أسئلة حول الصور أثناء القراءة.') WHERE id = '25aab72e-4248-42bb-9009-a3467dd34bf8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة "الصداقات الأولى" في السلوك الاجتماعي. لم يعد طفلكِ يكتفي باللعب بجوار الأطفال الآخرين، بل أصبح يعرض عليهم ألعابه أو يركض معهم. هذه هي أولى الخطوات الحقيقية نحو التعاون الاجتماعي. شجّعي تفاعلاته الاجتماعية الإيجابية واثني عليه عندما يُبدي استعدادًا للمشاركة.') WHERE id = 'fbc5e912-7941-46bd-9137-7aea112e7d13';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"العناية المستقلة بالنظافة الشخصية". أصبح طفلكِ حريصًا على غسل يديه بالصابون وتجفيفهما بالمنشفة. تعزّز مهارات العناية الذاتية هذه شعوره بالاستقلالية. وفّري له بيئة تناسب طوله ليتمكّن من جعل ممارسات النظافة هذه جزءًا طبيعيًا من حياته اليومية.') WHERE id = 'e689f8a3-742e-457c-849e-63c06d7af7c0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بداية مرحلة طرح سؤال "لماذا؟" في الكلام. يبدأ طفلكِ بالاهتمام بأسباب كل ما يحيط به. قدّمي إجابات بسيطة وصادقة عن أسئلته مثل: "لماذا هذا هكذا؟". ترسم تفسيراتكِ في ذهنه خريطة منطقية للعالم. لا تتركي فضوله بلا إجابة أبدًا، فهذا يعزز شغفه بالتعلّم.') WHERE id = 'f3d92e61-3d30-4ede-90d4-27478dd2115f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التطور العاطفي: "الاستقلالية والحدود". قد يبدي طفلكِ أحيانًا رد فعل حادًا عندما يرغب في فعل كل شيء بنفسه ولا ينجح. حافظي على هدوئكِ في هذه اللحظات وسمّي شعوره قائلةً: "أنا أتفهم أنك تريد فعل ذلك بنفسك". يساعد تفهّمكِ على تنمية قدرته على تنظيم مشاعره.') WHERE id = '1f37d9cd-995a-4d88-97e4-8b7fdb37e3d8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ يستخدم ضمير "أنا" مدركًا معناه تمامًا. فجمل مثل "أنا جئت" و"أنا أكلت" تدل على أنه يرى نفسه فردًا مستقلًا عن محيطه. ادعمي تعبيراته المستقلة ووسّعي حواراته بقولكِ: "نعم، لقد أكلت طعامك اللذيذ، أحسنت!".') WHERE id = 'bf78ea68-2a1f-4194-9ef3-62146ea4799d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الجسدية: "القفز إلى الأمام بكلتا القدمين". لم يعد طفلكِ يقفز في مكانه فحسب، بل أصبح قادرًا أيضًا على القفز قليلًا إلى الأمام. وهذا يدل على مستوى متقدم من التناسق الجسدي. العبي معه في الحديقة لعبة "الأرانب تقفز في المرج". فهذا تمرين ممتاز للمهارات الحركية الكبرى.') WHERE id = 'ce99df1c-1b81-4d41-b95d-9180c49c6d9f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'علاقات "السبب والنتيجة" في الكلام. أصبح طفلكِ يفهم العلاقة بين الأحداث، فيقول مثلًا: "إنها تمطر، لقد ابتللت" أو "الطعام ساخن، انفخ عليه". أثني على استنتاجاته المنطقية هذه، فهي تُظهر مدى تطور قدراته اللغوية وقدرته على التفكير المجرد.') WHERE id = 'bcee9d16-cb48-4f63-9295-23b44110e7d6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: "إتقان الفك والتدوير". أصبح طفلكِ قادرًا على فتح أغطية الزجاجات وإغلاقها وفك براغي الألعاب وربطها بثقة. وهذا تمرين ممتاز لمرونة عضلات المعصم. ادعمي شغفه بالاستكشاف من خلال إعطائه أوعية آمنة بأحجام مختلفة.') WHERE id = 'bff29c40-0fa8-45dd-982c-f35a2f18ac52';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الترتيب والمنطق» في التطور المعرفي. أصبح طفلكِ الآن قادرًا على ترتيب 4-5 أشياء حسب حجمها (من الأكبر إلى الأصغر). وهذه إحدى أولى لبنات التفكير الرياضي. أعطيه مكعبات أو أوعية بأحجام مختلفة ليتدرّب على مهارة الترتيب. فكل «ترتيب» ناجح ينجزه يُنشئ روابط عصبية جديدة في دماغه.') WHERE id = 'd3ed6715-8284-423a-bbce-cfe0156fda68';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «القفز إلى الأمام بكلتا القدمين». لم يعد طفلكِ يقفز في مكانه فحسب، بل أصبح قادرًا على القفز إلى الأمام بضعة سنتيمترات. ويتطلب ذلك قوة اندفاعية في عضلات الساقين وتوازنًا ممتازًا. العبي معه في الحديقة لعبة «القفز فوق البركة». فهي ممتعة، وتساعده أيضًا على تعلّم التحكم في جسمه.') WHERE id = '710d761b-996a-4661-a9e2-1515ed31c7a0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«من أنا؟» في تطور الكلام. أصبح طفلكِ الآن قادرًا على قول اسمه وعمره (حتى إن عبّر عنه بأصابعه) وجنسه. وهذه مرحلة مهمة في تطور وعيه بهويته. تحدثي معه عن يومه الكبير غدًا: «غدًا ستصبح طفلًا كبيرًا في عمر 2 سنة!».') WHERE id = 'ee27a56e-6e80-46b6-8a93-8ee183712978';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا! يُتمّ طفلكِ اليوم عامه الثاني! لقد أظهرتِ على مدار 730 يومًا صبرًا وحبًا وتفانيًا مذهلًا. لقد تجاوز طفلكِ الآن مرحلة الرضاعة، وأصبح شخصية صغيرة مستعدة لاكتشاف العالم. احتفلي معه بهذا اليوم الكبير من خلال ألعابه المفضلة. أحسنتِ يا أمي!') WHERE id = '493d8af7-6247-4790-9dba-5fe6ecd538f7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بكِ في اليوم الأول من عامه الثالث! لقد أتمّ طفلكِ عامه الثاني، وأصبح يشعر بأنه «كبير». في هذه المرحلة، يبدأ بالتمسك أكثر بأغراضه وألعابه. اسمحي له بوضع بعض القواعد البسيطة في غرفته أو ركن اللعب الخاص به. فهذا يساعده على تنمية حس المسؤولية.') WHERE id = 'e1193c8b-9caf-42cc-b0d1-380bfd68848e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الاستقلالية على الدرج» في التطور الحركي. أصبح طفلكِ الآن قادرًا على صعود الدرج بخطوات متتابعة، مع تبديل القدم عند كل درجة، وبمساعدتكِ عبر الإمساك بيد واحدة فقط. وهذا يوضح مدى قوة عضلات فخذيه وتطور قدرته على التوازن. امنحيه الثقة مع تذكيره بقواعد السلامة.') WHERE id = '23cbdeb8-6ec7-49eb-b8f0-c4ae1a3cb46c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الطفرة في الحصيلة اللغوية». يتعلم طفلكِ الآن عدة كلمات جديدة يوميًا، ويكوّن جملًا مترابطة من 3-4 كلمات. مثلًا: «أريد أن أذهب إلى الحديقة». اطرحي عليه أسئلة مفتوحة عند التحاور معه، مثل: «ماذا تريد أن تفعل في الحديقة؟». فهذا ينمّي خياله ويصقل قدرته على التعبير.') WHERE id = 'c49d7f6c-cef1-458f-99cb-da68585b7ac5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«رسم دائرة» ضمن تطور المهارات الحركية الدقيقة. يمسك طفلكِ الآن القلم بثقة أكبر، ويحاول رسم دوائر تقريبية على الورق. وهذا يمثل مستوى جديدًا في تطور التناسق بين يديه وعينيه. قدّمي له أقلامًا ملوّنة وأوراقًا كبيرة، وأتيحي له فرصة رسم «رسوماته الأولى».') WHERE id = '448009d5-07ef-4006-89f4-993bbe989179';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الاستقلالية: «أرتدي ملابسي بنفسي». لم يعد طفلكِ يكتفي بخلع جواربه، بل يحاول أيضًا ارتداءها أو رفع سرواله سهل الارتداء. حتى لو استغرقت هذه العملية وقتًا طويلًا، فلا تستعجليه. إن نجاحه في فعل شيء بنفسه هو أعظم «مكافأة» بالنسبة إليه. وصبركِ يعزز ثقته بنفسه.') WHERE id = 'ae5217ae-ff5f-4178-a4dd-001e8d391224';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«مفهوم انتظار الدور» في السلوك الاجتماعي. يفهم طفلكِ الآن ضرورة انتظار دوره عند الأرجوحة أو الزحليقة. وتصبح عبارة «الآن دورك، ثم دور صديقك» أوضح معنى بالنسبة إليه. وهذه من أهم مراحل التكيف الاجتماعي وتعلّم الصبر.') WHERE id = 'fd888eb3-7169-4c50-bc0d-f0696ed103ff';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«تصنيف الألوان» في التطور المعرفي. يستطيع طفلكِ الآن التمييز تمامًا بين 4-5 ألوان مختلفة، ويعرف أسماء الكثير منها. اختبريه اختبارًا صغيرًا بقولكِ: «أعطني جميع الألعاب الزرقاء». تعزز هذه الألعاب قدرته على التحليل البصري وذاكرته.') WHERE id = '6aeca11f-b490-4362-b41c-539703e28816';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «ركل الكرة». يستطيع طفلكِ الآن، أثناء الركض، ركل الكرة التي أمامه نحو الهدف من دون أن يفقد توازنه. ويتطلب ذلك تنسيق الحركة وتركيز الانتباه على نقطة واحدة. نظّمي معه مباراة «كرة قدم» صغيرة في ساحة المنزل لتنمية رشاقته.') WHERE id = 'da17a594-1250-4f85-98b1-50f0b6588294';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: "ازدياد تعقيد لعب الأدوار". أصبح طفلكِ الآن يؤلف ألعابًا تتكون من عدة أفعال متتالية؛ فمثلًا "يحمّم" دبه اللعبة، ثم "يجففه"، وبعد ذلك "يضعه في السرير". يوضح هذا كيف يربط بصورة منظمة بين سيناريوهات الحياة اليومية المحفوظة في ذاكرته.') WHERE id = 'd343f65f-f46a-44dd-a5fc-a51c1510c094';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"تناول الطعام باستقلالية". أصبح طفلكِ الآن ماهرًا في استخدام الشوكة والملعقة إلى درجة أنه لا يسكب شيئًا تقريبًا. أتيحي له الفرصة الكاملة لتناول طعامه بنفسه. فهذا مهم جدًا ليتعلم إدراك شعوره بالشبع ويعزز ثقته بنفسه.') WHERE id = '61ba4f1e-aa7b-426a-97ad-a9a4240347af';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: "تكوين الكل من الأجزاء". أصبح طفلكِ الآن قادرًا على تجميع صور بصرية بسيطة مقسمة إلى 4-6 قطع (أحاجٍ). يساعد ذلك على تنمية قدرته على التركيز وحل المشكلات. إذا لم ينجح، فساعديه بنبرة هادئة: "انظري، هذا ذيل الكلب، أين يمكن أن يكون مكانه؟".') WHERE id = 'd008eb87-e4b7-4791-98e4-80774b7e5fc4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الحركي: "رمي الكرة من فوق الكتف". لم يعد طفلكِ يكتفي بإسقاط الكرة على الأرض، بل يحاول رميها إلى الأمام من فوق كتفه (overhand). تتطلب هذه الحركة تناسق الجسم بأكمله. العبي معه في الحديقة لعبة "من يرمي الكرة إلى مسافة أبعد؟".') WHERE id = '018d47a4-b94c-4bab-a923-24c091f9e302';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: "الطلب واللباقة". عندما يريد طفلكِ شيئًا، لم يعد يكتفي بالإشارة إليه بإصبعه، بل يحاول أن يقول "أعطني" أو "من فضلك" (حتى لو قالها بطريقته الخاصة). أسلوبكِ المهذب هو النموذج الذي يشكل طريقته في التواصل. وكلما قلتِ "شكرًا جزيلًا"، اكتسب هو أيضًا هذا السلوك المهذب بصورة طبيعية.') WHERE id = '11cb7320-ce82-47a0-a231-8d9923b30f4a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الاستعداد العاطفي: "الخوف والخيال". قد يبدأ الأطفال في هذا العمر أحيانًا بالخوف من الظلام أو من أصوات معينة. وهذه علامة على تطور الخيال. لا تسخري من خوف طفلكِ، بل ابقي بجانبه واحتضنيه واجعليه يشعر بأنه في أمان. دعمكِ يعزز مرونته العاطفية.') WHERE id = '4edde2f0-76ee-4d3a-a2af-2d7d71d87764';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يعد طفلكِ يكتفي بالتعرّف على الألوان، بل أصبح بارعًا في مطابقتها. فإذا طلبتِ منه: "اعثر على الجورب المطابق لجوربك الأحمر" وفعل ذلك بشكل صحيح، فهذا دليل على تطور تفكيره البصري المنطقي. أكّدي على أسماء الألوان كثيرًا عند ارتدائه ملابسه اليومية، كأن تقولي: "هل نرتدي قميصك الأخضر اليوم؟". فهذا يعزز الصفات في حصيلته اللغوية.') WHERE id = 'f4611a68-9983-4caf-808b-4616cf4c60d5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في مجال الحركة الجسدية: "التوازن على قدم واحدة". يحاول طفلكِ الآن رفع إحدى قدميه عن الأرض والحفاظ على توازنه، ولو لبضع ثوانٍ فقط. ويتطلب ذلك تنسيقًا حركيًا معقدًا للتحكم في مركز ثقل الجسم. العبي معه "لعبة اللقلق". فهي ممتعة ومفيدة جدًا لنموه البدني في الوقت نفسه.') WHERE id = 'c7634c82-b4b5-450c-9811-7e5cbdc218af';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: "البوادر الأولى لفهم الزمن". يبدأ طفلكِ في إدراك الفرق بين كلمات مثل "الآن" و"لاحقًا". فإذا قلتِ له: "لنأكل أولًا، ثم نذهب إلى الحديقة" واستطاع الانتظار، فهذا تقدم كبير. واصلي توضيح تسلسل الأحداث من خلال أفعالكِ حتى تتكوّن لديه عادة الصبر.') WHERE id = '2c927604-0f3e-4615-94c5-86dc48b7896a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: "التركيب المتقن". أصبح طفلكِ الآن يركّب قطع ألعاب البناء الصغيرة أو المكعبات بعضها ببعض بدقة أكبر. ويتطلب ذلك تركيز الانتباه ودقة حركة أطراف الأصابع معًا. شجّعي محاولاته "الهندسية" واسأليه: "لمن هذا البيت؟".') WHERE id = '92d8aec4-818c-4b3a-abd3-dd724c129df5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الشرب باستقلالية". أصبح طفلكِ الآن يشرب الماء بثقة من كوب مفتوح، من دون أن يسكبه تقريبًا. وهذا مؤشر على مدى استعداد عضلات شفتيه وفكّه للنطق. واصلي إعطاءه أكوابًا بحجم مناسب للأطفال يسهل عليه إمساكها، حتى يتقن هذه المهارة تمامًا.') WHERE id = '659e2094-8141-4a5a-bed6-c6f715c75799';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: "الفكاهة والمزاح". قد يتعمّد طفلكِ فعل شيء "خاطئ"، مثل وضع قبعته على يده، ثم ينظر إليكِ ويضحك. وهذا يدل على بدء تطور حس الفكاهة لديه وقدرته على التأثير في تفاعلاته الاجتماعية. شاركيه هذه "اللعبة" بحماس. فالضحك معًا يعمّق الرابطة العاطفية بينكما.') WHERE id = 'c1045492-8f8e-491f-a86f-8a5ceb126f15';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«البحث عن السبب» في الكلام. حتى إن لم يكن طفلكِ يقول «لماذا؟» بوضوح بعد، فهو يستفسر عن أسباب الأحداث من خلال تصرفاته. اشرحي له: «نرتدي السترة لأن الجو في الخارج عاصف». إن توضيح الروابط المنطقية بين الأحداث له يشكّل أهم أساس لقدرته على الاستدلال المنطقي مستقبلًا.') WHERE id = 'f63d183c-6b97-43da-8c82-1a87c629cc0d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«مهارة الفكّ واللفّ» ضمن المهارات الحركية الدقيقة. أصبح طفلكِ قادرًا على فتح أغطية الزجاجات وإغلاقها أو فكّ براغي الألعاب وربطها بثقة. تمثّل هذه الحركة تمرينًا ممتازًا لمرونة عضلات المعصم. ادعمي شغفه بهذا الاستكشاف الميكانيكي عبر إعطائه أوعية آمنة بأحجام مختلفة.') WHERE id = '583cd090-6bc1-4438-afd7-8703fd352e08';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الاختيار المستقل» وقوة الإرادة. أصبح لدى طفلكِ الآن رأي واضح بشأن ما سيرتديه أو الوعاء الذي سيأكل منه. إن منحه فرصة الاختيار بقولكِ مثلًا: «هل سترتدي اليوم القميص الأزرق أم الأخضر؟» يساعده على الشعور بأنه شخص مستقل ويقلّل نوبات العناد إلى أدنى حد.') WHERE id = '5377658a-72e7-437d-b697-abdb7c76bfcd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التعاون» في السلوك الاجتماعي. أصبح طفلكِ يستمتع كثيرًا بمساعدتكِ. عندما تقولين له: «تعالَ، لنُخرج الخبز من كيس المشتريات» وينضم إليكِ، فهذا يعني أنه بدأ يدرك دوره في الأسرة. يعزّز ذلك شعوره بالمسؤولية ويقوّي أيضًا الرابطة بينكما.') WHERE id = '57201085-ec92-4795-8598-90d9a04fb33a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التصنيفات» في التطور المعرفي. أصبح طفلكِ قادرًا على تجميع الأشياء المتشابهة في فئات (مثل وضع جميع الحيوانات في مكان وجميع السيارات في مكان آخر). اختبري منطقه البصري بطرح أسئلة مثل: «أيّ لعبة مختلفة هنا؟». ينقل التفكير وفق التصنيفات قدراته المعرفية إلى مستوى جديد.') WHERE id = 'ffdc805c-2aad-4971-afc7-9cb3c0053b5c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «إتقان القفز بكلتا القدمين». أصبح طفلكِ أكثر ثقة في القفز عاليًا في مكانه أو إلى الأمام قليلًا. تدل هذه الحركة على تقوّي عضلات ساقيه. العبي معه لعبة «الأرانب في المرج»؛ فهي ممتعة ومفيدة أيضًا للمهارات الحركية الكبرى.') WHERE id = 'dcd7700f-4c1a-40e7-9469-0739827e396d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تزداد مرحلة «أنا أرتدي ملابسي بنفسي» تعقيدًا. فقد بدأ طفلكِ يحاول إغلاق السحّاب بعد أن تبدئي له، أو فكّ الأزرار الكبيرة. لا تعيقيه أو تستعجليه خلال هذه العملية. فرؤيته لنفسه وهو ينجح في فعل شيء ما تُعدّ أكبر مصدر لثقته بنفسه. احرصي على تشجيعه عند كل نجاح صغير.') WHERE id = '701a4eec-68f9-49ca-9e96-f1cb4b81484e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'يزداد «التعاطف» في سلوك طفلكِ الاجتماعي. فعندما يراكِ أو يرى طفلًا آخر حزينًا، قد يأتي ليقدّم لعبته أو يعانقكِ. وهذا مؤشر جميل على ذكائه العاطفي (EQ). كافئي اهتمامه هذا بقولكِ: «شكرًا جزيلًا لأنك ساندتني».') WHERE id = 'db3deaea-d927-47d7-b65e-09bbf47b377f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الشكل والحجم» في التطور المعرفي: أصبح طفلكِ قادرًا على التمييز بين الأحجام الكبيرة والصغيرة للشكل نفسه، مثل الدائرة. أريه كيف يضع أوعية مختلفة الأحجام بعضها داخل بعض. فهذا ينمّي مهارة «الترتيب»، التي تشكّل أساس تفكيره الرياضي مستقبلًا.') WHERE id = '1317ee1d-1c19-4d58-ab70-d9a1fa691c6f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الحركي: «ركل الكرة نحو هدف». لم يعد طفلكِ يركل الكرة فحسب، بل يحاول توجيهها نحو اتجاه محدد. وهذا يجمع بين الانتباه البصري والتناسق الحركي. اصنعي معه «مرمى صغيرًا» في المنزل أو الحديقة، والعبا معًا لعبة تسديد الكرة نحوه. فهذا يقوّي عضلات ساقيه ويحسّن دقته.') WHERE id = 'c1e87167-2300-4b17-9def-ab985555b55e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«محاولات سرد القصص» في تطور الكلام: يتحمّس طفلكِ ليخبركِ عن شيء مثير رآه خلال يومه، مثل: «رأيت كلبًا كبيرًا». استمعي إلى قصته حتى النهاية، وساعديه على توسيعها بالأسئلة، مثل: «ماذا كان يفعل الكلب؟». فهذا يقوّي ذاكرته وقدرته على التعبير عن نفسه.') WHERE id = '404203bc-920b-47d3-b584-2989b01e93ee';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الحدود العاطفية: قد يعبّر طفلكِ الآن عن إرادته بوضوح وحزم قائلًا: «لا أريد». بدلًا من الدخول معه في صراع عناد في هذه اللحظات، امنحيه خيارات لتشتيت انتباهه. إن صبركِ وثبات القواعد يمنحانه شعورًا بالأمان. أنتِ تقومين بعمل رائع!') WHERE id = '17f5e755-5dec-4458-9be1-0d08e0586eaf';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: «محاولات سرد القصص». يتحمس طفلكِ ليحكي لكِ عن شيء مثير للاهتمام رآه خلال يومه (مثلًا: «رأيت كلبًا كبيرًا في الحديقة»). استمعي إلى قصته حتى النهاية وساعديه على توسيعها بالأسئلة، مثل: «ماذا كان الكلب يفعل؟». فهذا يقوّي ذاكرته وقدرته على التعبير عن نفسه.') WHERE id = 'e7fba00d-ba92-45d4-9c39-8a2e6decdc8c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التطور العاطفي: «ضبط النفس». عندما يغضب طفلكِ، قد ينظر إليكِ وينتظر رد فعلكِ. في هذه اللحظات، حافظي على هدوئكِ وسمّي شعوره قائلةً: «أنت غاضب الآن لأن المكعبات سقطت، وأنا أتفهم ذلك». هدوؤكِ هو أفضل درس له في تنظيم مشاعره. أنتِ أم رائعة!') WHERE id = '4a2f0d04-3378-4296-a224-feb8d41e9254';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يعد طفلكِ يميّز الألوان فحسب، بل أصبح ينطق أسماء الكثير منها نطقًا صحيحًا. إذا لم يخطئ عندما تقولين له: «أحضر السيارة الزرقاء»، فهذا يدل على التكامل بين ذاكرته البصرية واللفظية. واصلي تلوين عالمه خلال نزهاتكما اليومية بأوصاف مثل «ورقة خضراء» و«شمس صفراء».') WHERE id = '57505a63-7f8c-48f6-bce2-90daca2c8189';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور الحركي: «الاستقلالية على الدرج». أصبح طفلكِ يحاول صعود الدرج ممسكًا بيد واحدة فقط، واضعًا قدمًا واحدة على كل درجة بالتبادل. وهذا إنجاز مهم في تطور المهارات الحركية الكبرى. ابقي دائمًا بالقرب منه لحمايته، لكن امنحيه الثقة ليخطو بمفرده.') WHERE id = 'e9641593-3c91-4cf3-a6cc-b86c93ef50be';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: «الكلمات الدالة على المكان». أصبح طفلكِ يعبّر بحركاته عن مفاهيم مثل «فوق» و«تحت» و«خلف». العبي معه لعبة صغيرة وقولي له: «ضع الكرة تحت الكرسي». تُنمّي هذه المهام بسرعة قدرته على فهم اللغة وتحديد الاتجاهات في المكان.') WHERE id = '2ff11d89-9e65-4caa-b39f-98e5298d4503';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: «التصنيف والمنطق». بدأ طفلكِ يميّز الأشياء ليس وفقًا لألوانها فحسب، بل وفقًا لأحجامها أيضًا (كبير وصغير). أعطيه أوعية بأحجام مختلفة واطلبي منه أن يضع بعضها داخل بعض. فهذا يشكّل أساس تفكيره الرياضي في المستقبل.') WHERE id = 'cd04a6bc-1fab-4d68-920a-3fa77ebf8503';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الارتفاع والمسافة» في التطور المعرفي: أصبح طفلكِ الآن أقدر على تقدير المسافة عند النزول من الدرج أو الأريكة. ذكّريه دائمًا بضرورة توخي الحذر وبطرق النزول الآمنة (إلى الخلف). هذه مرحلة مهمة في تعلّمه قواعد السلامة الجسدية.') WHERE id = 'c7630ee3-1695-4062-9e13-7540975aa465';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «إتقان المشي إلى الخلف». يستطيع طفلكِ الآن أن يخطو بضع خطوات إلى الخلف من دون أن ينظر. وهذا مهم لتنمية إحساسه بوضعية جسمه في المكان (الحس العميق). حوّلي هذه الحركة إلى لعبة بقولكِ: «لنمشِ مثل السلطعون». فالتحرك معكِ هو أمتع شيء في العالم بالنسبة إليه.') WHERE id = 'e1577858-a1db-40b1-bd39-0ce8d678ff7a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الربط بين الاسم والضمير» في تطور اللغة: ينتقل طفلكِ الآن تمامًا من ذكر اسمه إلى قول «أنا». عندما تسألينه عن شيء فيقول «أنا» أو «لي»، فهذا مؤشر على ترسّخ وعيه بذاته. تحاوري معه حول ذلك، مثل: «لمن هذه الكرة؟ لي!».') WHERE id = 'a37651fe-7cc3-4f59-bbce-f7763c1637a8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الحدود العاطفية: أصبح طفلكِ الآن يستجيب لكلمة «ممنوع»، لكنه قد يواصل أحيانًا مخالفة القواعد لاختبار رد فعلكِ. والأهم أن تظلي هادئة وحازمة. إذا قلتِ «لا» لشيء ما، فالتزمي بالموقف نفسه في كل مرة. ثبات القواعد يمنح الطفل شعورًا بالنظام الداخلي والأمان.') WHERE id = '8f5c35ba-05d9-40e2-a687-7bfe8146f1ee';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'ندخل الشهر ٢٦! أصبح طفلكِ الآن ماهرًا في تنفيذ تعليمات من خطوتين متتاليتين. على سبيل المثال: «خذ اللعبة وضعها على الرف». وهذا يدل على أن ذاكرته وفهمه للغة قد بلغا مستوى جديدًا. امنحيه خلال اليوم «مهام» صغيرة كهذه لتساعديه على الشعور بأنه مفيد.') WHERE id = '86c6ccb4-326d-41d5-81c5-ea4c8d0faf13';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«المناورة السريعة» في التطور الحركي: أصبح طفلكِ الآن قادرًا على تغيير اتجاهه فجأة أثناء الجري أو الالتفاف برشاقة حول العوائق. وهذا دليل على قوة عضلاته وقدرته على اتخاذ القرارات بسرعة. العبي معه لعبة «المطاردة» في الحديقة لتعزيز قدرته على التحكم في جسمه.') WHERE id = 'eb8969ec-bb8d-48c5-8dfb-f818249bf8e8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ يستخدم ضمير «أنا» وهو يدرك معناه تمامًا. فجمل مثل «أنا جئت» و«أنا أكلت» تدل على أنه يرى نفسه فردًا مستقلًا عن محيطه. ادعمي تعبيراته المستقلة ووسّعي حواراته: «نعم، لقد أكلتَ طعامك اللذيذ، أحسنت!».') WHERE id = '12f036fb-3726-4e17-bff9-217ad09dba7b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في النشاط البدني، تظهر مهارة «المشي على حافة الرصيف». أصبح طفلكِ مهتمًا بالمشي على حواف الأرصفة المنخفضة عندما تمسكين بيده. وهذا يساعده على تطوير قدرته على التوازن في الحركات المعقدة. ادعمي هذا الاهتمام في الأماكن الآمنة، لأنه يمهّد لاكتساب مهارات بدنية أكثر تعقيدًا مستقبلًا.') WHERE id = '292c2a9d-2b19-4e22-9095-add20bbbeaf5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام، يزداد استخدام «الجمل المكوّنة من ثلاث كلمات». أصبح طفلكِ يُكوّن جملًا أكثر تعقيدًا مثل «ماما، أعطيني ماءً» و«بابا، اذهب إلى الحديقة». وبات قادرًا على التعبير عن احتياجاته بوضوح. أكّدي جملته ثم وسّعيها قليلًا: «نعم، تعالَ الآن لنشرب الماء، ثم سنذهب إلى الحديقة». فهذا يصقل فهمه للقواعد اللغوية.') WHERE id = '7132fa94-7590-4b27-b006-e5936aaf0907';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تزداد «براعة تركيب الأحجيات» ضمن المهارات الحركية الدقيقة. أصبح طفلكِ قادرًا على تركيب أحجيات بسيطة مكوّنة من 6-8 قطع بمفرده. ويتطلب ذلك التحليل البصري ودقة حركة عضلات الأصابع معًا. أظهري فرحتكِ في كل مرة يُكمل فيها الصورة، كي يزداد اهتمامه بالمهام المعقدة.') WHERE id = 'd4e00b50-79ce-485c-9a88-f514c156f1f6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«أنا أرتّب بنفسي». لم يعد إعادة الألعاب إلى أماكنها مجرد مهمة بالنسبة إلى طفلكِ، بل أصبحت مسؤولية. عندما تقولين له: «هيا نضع السيارات في مكان نومها» ويساعدكِ، فهذا يرسّخ لديه أساس الانضباط والنظام. وستكون هذه العادة مهمة جدًا لتنظيمه الشخصي مستقبلًا.') WHERE id = '03327c5a-8698-4e34-8b71-2d0914f0f88b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي، تظهر مهارة «انتظار الدور». أصبح طفلكِ يفهم أن عليه الانتظار قليلًا ليركب الأرجوحة في الحديقة أو ليلعب بلعبة ما. علّميه الصبر من خلال ألعاب مثل: «الآن دوري، ثم دورك». فهذه المهارة من أهم الأسس الاجتماعية اللازمة لتكيّفه مستقبلًا مع بيئة الروضة والمدرسة.') WHERE id = '3ea5aca0-7734-4b06-864f-00aa21361675';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التطور المعرفي: «المتشابه والمختلف». أصبح طفلكِ قادرًا على تصنيف الأشياء من النوع نفسه في مجموعات، كأن يضع جميع الحيوانات في مكان وجميع السيارات في مكان آخر. اختبري قدرته على الاستدلال البصري بطرح أسئلة مثل: «أي لعبة مختلفة هنا؟». يساعده التفكير ضمن فئات على الارتقاء بقدراته المعرفية إلى مستوى جديد.') WHERE id = '09d14134-1ab9-423c-86bd-46c0a52d2f86';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الحركي: «ركل الكرة والجري». أصبح طفلكِ قادرًا على ركل الكرة أمامه أثناء الجري من دون أن يفقد توازنه. هذا النشاط ممتع ومفيد جدًا لنموه البدني. العبي معه بكرة خفيفة في المنزل أو في الحديقة لتنمية سرعة حركته ودقته.') WHERE id = '39fb4064-3e7d-4aa6-b4d5-c75b564c92cc';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التعبير عن الذكريات» في تطور الكلام. يستطيع طفلكِ تذكّر حدث بسيط وقع خلال اليوم وإخباركِ به، مثل: «رأيت كلبًا في الحديقة». استمعي إلى حكاياته باهتمام وساعديه على ترتيب الأحداث بسؤاله: «ثم ماذا حدث؟». فهذا يعزز ذاكرته وقدرته على التعبير.') WHERE id = '109cbe57-dd82-4d85-b381-3ebd329772ab';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التطور العاطفي: «محاولات ضبط النفس». عندما يغضب طفلكِ، قد ينظر إليكِ وينتظر رد فعلكِ. حافظي على هدوئكِ في هذه اللحظات وسمّي شعوره بقولكِ: «أنت غاضب الآن لأن اللعبة لم تعمل كما أردت». هدوؤكِ هو أفضل درس له في تنظيم مشاعره. أنتِ أم رائعة!') WHERE id = 'cbb6c494-b75d-458c-b798-2ddf1bf9e334';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أهلًا بكِ في الشهر السابع والعشرين! أصبح طفلكِ يتقن الآن تنفيذ التعليمات المكوّنة من خطوتين. فعندما تقولين له: «خذ لعبتك وضعها في الصندوق»، ينفّذ الخطوتين بالترتيب. وهذا يدل على تطور القشرة الجبهية الأمامية في دماغه. قدّمي له خلال اليوم مهام صغيرة ومنطقية لصقل هذه المهارة.') WHERE id = '0b872b3f-49b7-446a-bc7c-dfae010fe461';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المهارات الحركية: «إتقان نزول الدرج». أصبح طفلكِ يحاول نزول الدرج بثقة أكبر، درجةً تلو الأخرى، عندما تمسكين بيده. النزول أصعب من الصعود لأنه يتطلب توازنًا أكبر. ابقي دائمًا بالقرب منه لحمايته، وصفّقي له احتفاءً بنجاحه.') WHERE id = '912ef746-569e-455d-af72-84d6cc3f170e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الكلام: «استخدام الصفات والظروف معًا». لم يعد طفلكِ يقول «سيارة» فحسب، بل أصبح قادرًا على قول «سيارة حمراء سريعة». وهو يستخدم مزيدًا من التفاصيل لوصف العالم. عند التحدث معه، أكّدي على خصائص الأشياء، مثل: «هذا حجر ثقيل»، «هذه وسادة ناعمة». فهذا يُثري حصيلته اللغوية نوعيًا.') WHERE id = 'c940fb90-c1d6-4fa5-8baf-334e41b324f8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: «الفن والتنسيق». أصبح طفلكِ يرسم دوائر أكثر قصدًا على الورق، أو خطوطًا عشوائية لكنها قوية. وفّري له أقلام تلوين وأوراقًا كبيرة لخلق مساحة للإبداع الحر. فهذا يساعد على تكوين الذاكرة العضلية اللازمة للكتابة مستقبلًا.') WHERE id = 'c40de8f9-d507-4cfb-810d-f904e8901ddd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«محاولات ارتداء الملابس باستقلالية». لم يعد طفلكِ يكتفي بخلع جوربه، بل أصبح يصرّ أيضًا على وضع قبعته على رأسه أو إدخال قدميه في حذائه. امنحيه بضع دقائق إضافية خلال هذه العملية. إن إتاحة الفرصة له لإنجاز شيء بنفسه من دون استعجاله تعزّز ثقته بنفسه وشعوره بالاستقلالية.') WHERE id = 'c38e076c-fc5e-4ef7-ba82-49913f3b0c34';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: «الرعاية الرمزية». قد يتظاهر طفلكِ بأنه يسقي دبدوبه اللعبة، أو يغطيه ببطانية، أو يربّت عليه عندما يبكي. وهذا دليل على تطور ذكائه العاطفي وقدرته على فهم مشاعر الآخرين. لا تنسي الثناء على تصرفاته الحنونة هذه.') WHERE id = 'cbccdb44-553a-4ef8-8729-9f35675d89bf';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: «أساسيات العدّ». رغم أن طفلكِ لا يزال غير قادر على عدّ الأرقام بالترتيب، فإنه يبدأ بفهم الفرق بين كميتي «واحد» و«اثنين» بصريًا. أعطيه تفاحتين وقولي: «واحدة لك وواحدة لي»، لتوضحي له المشاركة والعدّ معًا. فهذا هو الأساس الأول لتفكيره الرياضي.') WHERE id = '1953c2df-b74a-440f-aeda-02c40c3b1d9f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التنسيق الجسدي: «القفز إلى الأمام بكلتا القدمين». لم يعد طفلكِ يقفز في مكانه فحسب، بل أصبح قادرًا على القفز قليلًا إلى الأمام أيضًا. ويتطلب ذلك قوة عضلات الساقين وتناسق الجسم. العبي معه لعبة «الأرانب تقفز في المرج». فهي ممتعة وتمرين ممتاز للمهارات الحركية الكبرى في الوقت نفسه.') WHERE id = '9999afba-b8a0-474d-b26c-6136ec804e12';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«حوار الأسئلة والأجوبة» في تطور الكلام. أصبح طفلكِ قادرًا على طرح أسئلة بسيطة عليكِ مثل: «أين أبي؟»، «ما هذا؟». عندما تجيبين، استخدمي جملًا مفصّلة مثل: «ذهب أبي إلى العمل وسيعود مساءً». تساعد شروحاتكِ المفصّلة على ترسيخ الروابط المنطقية بين الأحداث في دماغه.') WHERE id = 'e0d072d6-3ce1-4139-b80e-a94b53d2fc54';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد أكملنا 800 يوم! لقد تجاوز طفلكِ الآن عامه الثاني بمدة لا بأس بها، ويكتشف شيئًا جديدًا كل يوم. أصبح يفهم القواعد البسيطة، ويعبّر عن مشاعره بوضوح، ويتواصل معكِ بشكل متكامل. احتفلي بهذا اليوم معه بقضائه في حديقته المفضلة. أنتِ أم رائعة!') WHERE id = '1df3c116-f7da-4df5-8d7e-4570b51bb9eb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'نقترب من منتصف الشهر 27. أصبح طفلكِ الآن يفهم تسلسل «قبل» و«بعد» بصورة أعمق. عندما تقولين له: «ارتدِ ملابسك، ثم نخرج»، يدرك أن الفعل الثاني بمثابة مكافأة. هذه هي البذور الأولى لمهارتي الصبر والتخطيط لدى طفلكِ. ذكّريه كثيرًا بهذا التسلسل خلال الروتين اليومي.') WHERE id = 'bf2725f4-a91c-46df-b906-cbe0eca9ab09';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«إتقان التسلّق» في التطور البدني. أصبح طفلكِ يصعد بثقة أكبر السلالم الصغيرة في الحديقة أو الأماكن المرتفعة الآمنة في المنزل. ويتطلب ذلك عمل عضلات الذراعين والساقين بتناسق. ابقي دائمًا بالقرب منه، لكن أتيحي له فرصة اختبار قدراته بنفسه.') WHERE id = '03ce58c6-bf39-4cb2-86c0-fb921289cb85';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الروابط المنطقية» في تطور الكلام. أصبح طفلكِ الآن يربط بين حدثين في جملة واحدة، مثل: «الجو بارد، ارتدِ السترة». وهذا يدل على أنه لا يكتفي بالتقليد، بل يفكّر أيضًا. أكّدي استنتاجاته المنطقية بقولكِ: «نعم، كلامك صحيح»، حتى يتحمس أكثر للتعبير عن أفكاره.') WHERE id = '70d20b90-08cb-4a3d-b635-39b5e961b0df';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التعامل مع الورق» ضمن تطور المهارات الحركية الدقيقة. قد يبدأ طفلكِ الآن بإظهار اهتمام بطيّ الورق أو قصّه ببساطة، باستخدام مقص أطفال كبير وتحت إشرافكِ. ترتقي هذه الحركات بقدرته على التحكم في عضلات أصابعه إلى مستوى جديد. وفّري له بيئة مناسبة للتعامل مع الأوراق الملوّنة.') WHERE id = '1867a29d-cdef-4c25-9fb4-31fe661ffbe5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: «تطوّر تعقيد لعب الأدوار». أصبح طفلكِ الآن يتقمّص دور «الطبيب» أو «الطاهي» أو «السائق». ومن خلال هذه الألعاب، يتعرّف إلى مهام الأشخاص من حوله وينمّي قدرته على التعاطف. شاركيه هذه الألعاب وتصرّفي بما يتناسب مع «الدور» الذي يمنحكِ إياه.') WHERE id = '09d954dd-f762-40e1-8030-11d38ef87b47';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مهارة «النظافة الشخصية المستقلة». أصبح طفلكِ الآن قادرًا على غسل يديه بالصابون وشطفهما بمفرده تقريبًا. ومن المهم جدًا ترسيخ عادات النظافة في هذا العمر. وفّري له مسندًا متدرجًا (step stool) مناسبًا لطوله ليستمتع بهذه العملية.') WHERE id = '8f3c97e4-28e2-4575-994c-03b54f2a86ed';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: «العثور على العنصر المختلف». أصبح طفلكِ الآن قادرًا على تمييز العنصر المختلف بصريًا ضمن مجموعة من الأشياء (مثل تفاحة بين السيارات). وهذا يصقل قدرته على التحليل. أعدّي له في المنزل ألعابًا بسيطة بعنوان «ما العنصر الزائد؟». فهذا إعداد ممتاز للمهام الرياضية والمنطقية مستقبلًا.') WHERE id = '0c2d9534-6a6b-4045-844a-9433e0a69d75';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «محاولات الوقوف على قدم واحدة». أصبح طفلكِ الآن يحاول رفع إحدى قدميه عن الأرض والحفاظ على توازنه، ولو لبضع ثوانٍ فقط. وهذا مهم ليتعرّف جسمه إلى مركز ثقله. العبي معه «لعبة اللقلق» وتحقّقا ممن يستطيع الوقوف مدة أطول.') WHERE id = '5d944b43-095b-4d92-b030-b834a56949f2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: «التعبير عن المشاعر». أصبح طفلكِ الآن قادرًا على التعبير بالكلمات عن شعوره بالحزن أو الفرح أو الخوف، فيقول: «أنا خائف» أو «أنا سعيد». وتسمية المشاعر هي أساس الذكاء العاطفي لدى الطفل. عندما يعبّر عن مشاعره، أنصتي إليه وأكّدي له مشروعية ما يشعر به بقولكِ: «نعم، أنا أفهمك».') WHERE id = 'cb48e516-3844-4090-848b-2afd50d005de';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قوة الخيال: «الأصدقاء والأشياء الخيالية». قد يتخيّل طفلكِ عصًا على أنها «حصان» ويركض بها كأنه يمتطيه. وهذه مرحلة متقدمة من التفكير الرمزي، أي فهم أن شيئًا ما يمكن أن يرمز إلى شيء آخر. وهذه المهارة مهمة جدًا لتعلّم القراءة والرياضيات مستقبلًا (فهم الرموز).') WHERE id = '76d9591a-d7e3-4913-96a8-5d2c420ccc81';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'نبدأ الأيام العشرة الأخيرة من الشهر السابع والعشرين! لم يعد طفلكِ يكتفي بالتعرّف على الألوان، بل أصبح بارعًا في مطابقتها. فإذا طلبتِ منه: "اعثر على الجورب المطابق لجوربك الأحمر" وفعل ذلك بشكل صحيح، فهذا دليل على تطور منطقه البصري. احرصي على لفت انتباهه إلى الألوان في ملابسه اليومية باستمرار.') WHERE id = '5063e9dc-6139-4c88-93fd-950678f58bde';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور الحركي، تبدأ مرحلة "الاستقلالية على الدرج". يحاول طفلكِ الآن صعود الدرج ممسكًا بيد واحدة فقط، واضعًا قدمًا واحدة على كل درجة بالتناوب. وهذا إنجاز مهم في المهارات الحركية الكبرى. ابقي دائمًا بالقرب منه لحمايته، لكن امنحيه الثقة ليخطو بمفرده.') WHERE id = 'd4f943d2-bf71-4b16-b7d0-f1be4b723a37';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام، تظهر "البوادر الأولى لفهم ظروف الزمن". يبدأ طفلكِ في فهم الفرق بصورة أفضل بين كلمات مثل "الآن" و"لاحقًا" و"بعد قليل". فإذا استطاع الانتظار عندما تقولين له: "لنأكل أولًا، ثم نذهب إلى الحديقة"، فهذا دليل على تنامي قوة إرادته. واصلي توضيح التسلسل الزمني من خلال أفعالكِ.') WHERE id = 'ad12a2ff-a0f6-446e-a287-18ac0e3ed236';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة، يصل طفلكِ إلى مرحلة "إتقان الأحجيات". أصبح قادرًا الآن على حل أحجيات بسيطة مكوّنة من 6-9 قطع بمفرده. إن تجميع الصور بصريًا يعزز قدرته على التركيز وحل المشكلات. وعندما لا ينجح، قدّمي له تلميحات بنبرة هادئة.') WHERE id = 'ca532b10-de2c-4db5-9614-e001b1908ea1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بلغ "الاختيار المستقل" ذروته. أصبح لدى طفلكِ الآن رأي واضح بشأن ما سيرتديه أو اللعبة التي سيلعب بها. إن منحه فرصة للاختيار، مثل: "هل سترتدي اليوم قبعتك الزرقاء أم الخضراء؟"، يساعده على الشعور بأنه شخص مستقل ويقلل نوبات العناد إلى أدنى حد.') WHERE id = 'fb9fc561-26c7-41b4-bbe1-31eada18c85f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي، يتعلم طفلكِ "انتظار دوره". أصبح يدرك الآن أنه عليه الانتظار قليلًا ليركب الأرجوحة في الحديقة. علّميه الصبر من خلال ألعاب تقولين فيها: "الآن دوره، وبعده دورك". هذه المهارة من أهم الأسس للتكيف الاجتماعي.') WHERE id = '9df47b2e-3d86-40c8-a4bd-0d995655814b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الارتفاع والمسافة» في التطور الإدراكي. أصبح طفلكِ الآن أقدر على تقدير المسافة عند النزول من الدرج أو الأريكة. ذكّريه دائمًا بتوخي الحذر وبطرق النزول الآمنة، مثل النزول إلى الخلف. تُعدّ هذه مرحلة مهمة في تعلّمه قواعد السلامة الجسدية.') WHERE id = '0f7477b8-a1ff-4761-b386-ffe1e44a9a7a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التنسيق الحركي: «ركل الكرة نحو الهدف». لم يعد طفلكِ يركل الكرة فحسب، بل يحاول توجيهها في اتجاه محدد. وهذا يجمع بين الانتباه البصري والتنسيق الحركي. اصنعي معه «مرمى صغيرًا» في المنزل أو الحديقة، والعبا معًا لعبة ركل الكرة نحوه.') WHERE id = '050cfb5f-db53-4311-8b9f-fbb09f54e915';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«محاولات سرد القصص» في تطور الكلام. يتحمس طفلكِ لإخباركِ عن شيء ممتع رآه خلال يومه، مثل: «رأيت كلبًا كبيرًا». أنصتي إلى قصته حتى النهاية وساعديه على توسيعها بالأسئلة، مثل: «ما لون الكلب؟». فهذا يعزز ذاكرته وقدرته على التعبير عن نفسه.') WHERE id = 'd7af8a5b-1016-4dc8-921f-52af71c3d954';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الحدود العاطفية: قد يعبّر طفلكِ الآن عن إرادته بقوة قائلًا: «أنا لا أريد». في هذه اللحظات، بدلًا من الدخول معه في صراع عناد، امنحيه خيارات وحاولي تحويل انتباهه. صبركِ وثبات القواعد يمنحانه شعورًا بالأمان. أنتِ تقومين بعمل رائع!') WHERE id = '80c062ac-b271-45ec-b67c-016fb884ca5b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'ندخل الشهر الثامن والعشرين! أصبح طفلكِ الآن قادرًا على تنفيذ التعليمات «المكوّنة من خطوتين» بسهولة، مثل: «خذ لعبتك وضعها على الرف». وهذا يدل على أن ذاكرته وفهمه للغة قد بلغا مستوى جديدًا. كلفيه خلال اليوم بمهام صغيرة ومنطقية لتنمية شعوره بالمسؤولية.') WHERE id = 'a1060bb5-066a-438b-aafd-d9c5d706c7bc';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«إتقان نزول الدرج» في التطور الحركي. عندما تمسكين بيده، يحاول طفلكِ الآن نزول الدرج بثقة أكبر، واضعًا قدمًا واحدة على كل درجة. النزول أصعب من الصعود لأنه يتطلب توازنًا أكبر. ابقي دائمًا بالقرب منه لحمايته، وصفّقي له احتفاءً بنجاحه.') WHERE id = '05b34d22-95f5-4000-aee3-08f747372e4d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«حوار السؤال والجواب» في الكلام. أصبح طفلكِ قادرًا على طرح أسئلة بسيطة عليكِ مثل: «أين أبي؟»، «ما هذا؟». أجيبي بجمل مفصّلة مثل: «ذهب أبي إلى العمل وسيعود مساءً». تساعد تفسيراتكِ المفصّلة على ترسيخ الروابط المنطقية بين الأحداث في ذهنه.') WHERE id = '12f65b1a-8cde-4d4d-842d-5197bc6d6352';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قوة الخيال: «تبادل الأدوار». قد يقلّدكِ طفلكِ فيؤدي دور «الأم»، أو قد «يأخذ ألعابه إلى العمل». وهذا يعكس قوة ذاكرته ومدى دقة ملاحظته للروابط المنطقية بين الأحداث. أنتِ أم رائعة!') WHERE id = '1d0c6c5d-a275-43bf-bb3b-a961c2f6805e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يعد طفلكِ يكتفي بالتعرّف على الألوان، بل بدأ أيضًا بتسمية ما لا يقل عن 3-4 ألوان أساسية (الأحمر، الأزرق، الأخضر، الأصفر). وعندما تسألينه: «ما هذا اللون؟»، فهناك احتمال كبير أن يجيب إجابة صحيحة. عزّزي هذه المعرفة بسؤاله عن ألوان السيارات أو الزهور أثناء التنزّه.') WHERE id = '44e5c106-bbab-44d6-a4ac-bc4a1418e1eb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التوازن على قدم واحدة» ضمن المهارات الحركية الجسدية. أصبح طفلكِ يحاول رفع إحدى قدميه عن الأرض والحفاظ على توازنه، ولو لبضع ثوانٍ فقط. ويتطلب ذلك تنسيقًا معقدًا للتحكم في مركز ثقل الجسم. العبي معه «لعبة اللقلق». فهي ممتعة ومفيدة جدًا لنموه الجسدي في آنٍ واحد.') WHERE id = 'fbfbb0b9-9b09-4a23-9066-c80337eab4d6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«البدايات الأولى لفهم الزمن» في الكلام. رغم أن طفلكِ لا يفهم بعد تمامًا كلمتَي «أمس» و«غدًا»، فإنه يدرك الفرق بين كلمات مثل «الآن» و«بعد ذلك» و«بعد قليل». إذا كان يستطيع الانتظار عندما تقولين له: «لنغسل أيدينا أولًا، ثم نأكل الخبز»، فهذا دليل على تنامي قوة إرادته. واصلي شرح تسلسل الزمن من خلال أفعالكِ.') WHERE id = 'a4ffacc2-0d5e-4231-a5d0-f90a33b4d6f5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«إتقان الدوائر والخطوط» ضمن المهارات الحركية الدقيقة. أصبح طفلكِ يرسم على الورق دوائر أكثر تعمدًا، أو خطوطًا مستقيمة عشوائية ولكن واثقة. وفّري له أقلام تلوين وأوراقًا كبيرة ليتمكن من رسم «رسوماته الأولى». فهذا من أهم التمارين لاكتساب مهارات الكتابة مستقبلًا.') WHERE id = 'efd8c509-5660-43d7-a555-e496a390e478';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'استخدام «الصفات والظروف معًا» في الكلام. لم يعد طفلكِ يقول «سيارة» فقط، بل أصبح قادرًا على قول «سيارة حمراء سريعة». فهو يستخدم مزيدًا من التفاصيل لوصف العالم. عند التحدث معه، سلّطي الضوء على خصائص الأشياء: «هذا حجر ثقيل»، «هذه وسادة ناعمة». فهذا يثري حصيلته اللغوية بصورة نوعية.') WHERE id = '5838f818-d4e0-42c7-ba01-7e6420078ed2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الرصّ والبناء» ضمن المهارات الحركية الدقيقة. لم يعد طفلكِ يبني من المكعبات برجًا فحسب، بل أصبح يصنع أشكالًا هادفة مثل «سياج» أو «قطار» أو «منزل». ويجمع ذلك بين التفكير البصري المكاني والخيال لديه. اطرحي عليه أسئلة عن مبانيه، مثل: «من يعيش هنا؟».') WHERE id = '46a64e62-d979-410f-9a15-a2c7bbeb1ba9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الاختيار المستقل» وقوة الإرادة. أصبح لدى طفلكِ الآن رأي واضح بشأن ما سيرتديه أو الطبق الذي سيأكل منه. إن منحَه فرصة للاختيار، مثل: «هل سترتدي اليوم القميص الأزرق أم الأخضر؟»، يساعده على الشعور بأنه شخص مستقل ويقلل نوبات العناد إلى أدنى حد.') WHERE id = 'f2f6cbfc-bdac-4534-9233-ecd8a693e212';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الرعاية الرمزية» في السلوك الاجتماعي. قد يسقي طفلكِ دبدوبه اللعبة، أو يغطيه ببطانية، أو «يعالجه». وهذا دليل على تطور ذكائه العاطفي وقدرته على فهم مشاعر الآخرين. احرصي على مدح هذه التصرفات الحنونة.') WHERE id = '8ddc104a-ab8a-4e5a-943d-543dc807df66';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«العثور على المختلف» في التطور المعرفي. أصبح طفلكِ قادرًا على تمييز العنصر المختلف بصريًا ضمن مجموعة من الأشياء، مثل تفاحة بين مجموعة من السيارات. وهذا يصقل قدرته على التحليل. نظّمي له في المنزل ألعابًا بسيطة بعنوان «ما العنصر الزائد؟». فهي إعداد ممتاز للمهام المنطقية مستقبلًا.') WHERE id = 'a2b9980c-2bf2-401b-8655-ae5a31b2d842';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «القفز إلى الأمام بكلتا القدمين». لم يعد طفلكِ يقفز في مكانه فقط، بل أصبح قادرًا على القفز مسافة قصيرة إلى الأمام أيضًا. ويتطلب ذلك قوة عضلات الساقين وتناسق حركة الجسم. العبي معه لعبة «الأرانب تقفز في المرج». فهي ممتعة وتمرين رائع للمهارات الحركية الكبرى في الوقت نفسه.') WHERE id = '3b71e4fe-1f75-478c-bb70-76e4d5347b3d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الإصرار على «ارتداء الملابس باستقلالية». لم يعد طفلكِ يكتفي بخلع جوربيه، بل يصرّ أيضًا على وضع قبعته على رأسه أو ارتداء حذائه السهل بنفسه. امنحيه بضع دقائق إضافية خلال هذه العملية. فإتاحة الفرصة له لإنجاز شيء بنفسه دون استعجاله تعزز ثقته بنفسه وشعوره بالاستقلالية.') WHERE id = 'ea6058fd-22cb-454f-b6df-36b6c6f564fd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الفكاهة والمزاح» في السلوك الاجتماعي. قد يتعمد طفلكِ فعل شيء «خاطئ» (كأن يضع قبعته على يده مثلًا)، ثم ينظر إليكِ ويضحك. يدل ذلك على بدء تطور حس الفكاهة لديه وقدرته على التفاعل الاجتماعي بطريقة مرحة. شاركيه هذه «اللعبة» بحماس. فالضحك معًا يعمّق الرابطة العاطفية بينكما.') WHERE id = '90539d1c-30bc-43ec-8cb5-e89edef1568e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الارتفاع والمسافة» في التطور المعرفي. أصبح طفلكِ الآن أقدر على تقدير المسافة عند نزول الدرج أو الأريكة. ذكّريه دائمًا بتوخي الحذر وبطرق النزول الآمنة، مثل النزول إلى الخلف مع تقديم القدمين أولًا. هذه مرحلة مهمة ليتعلم قواعد سلامة الجسم ويحلل المخاطر بصريًا.') WHERE id = '00eb14eb-16c9-4d20-9af4-97c177dc49f5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «المشي إلى الخلف». أصبح طفلكِ قادرًا الآن على المشي بضع خطوات إلى الخلف دون أن ينظر وراءه. وهذا مهم لتنمية إحساسه بوضعية جسمه في المكان (الحس العميق). حوّلي هذه الحركة إلى لعبة بقولكِ: «لِنمشِ مثل السلطعون». فهذا يمرّن عضلات ساقيه بطريقة مختلفة.') WHERE id = '2b4f1496-5d34-4f25-9ad5-91b67ba2967b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«العلاقة بين الاسم والضمير» في تطور الكلام. ينتقل طفلكِ الآن بشكل كامل من الإشارة إلى نفسه باسمه إلى استخدام ضمير «أنا». فإذا أجابكِ بـ«أنا» أو «لي» عندما تسألينه عن شيء، فهذا يدل على ترسخ وعيه بذاته. تحاوري معه حول ذلك، مثل: «لمن هذه الكرة؟ لي!». أنتِ مرشدة رائعة!') WHERE id = '61b67af6-b8e7-43c0-aeec-e2ba32964d5a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الحدود العاطفية: أصبح طفلكِ قادرًا الآن على التعبير عن إرادته بوضوح قائلًا: «أنا لا أريد». في هذه اللحظات، بدلًا من الدخول معه في صراع عناد، امنحيه خيارات وحاولي تحويل انتباهه. صبركِ وثبات قواعدكِ يمنحانه شعورًا بالأمان. لقد أتممنا 840 يومًا بنجاح، وأنتِ تستحقين كل ما هو أفضل!') WHERE id = 'f92d1e9f-889d-441d-90aa-ab2a51e762a4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'نبدأ الأيام العشرة الأخيرة من الشهر الثامن والعشرين! أصبح طفلكِ قادرًا على تنفيذ التعليمات المكوّنة من خطوتين بسهولة. مثلًا: "خُذ اللعبة وضعها على الرف". يشير ذلك إلى أن ذاكرته العاملة وقدرته على فهم اللغة قد بلغتا مستوى جديدًا. أعطيه خلال اليوم "مهام" صغيرة كهذه لتنمية إحساسه بالمسؤولية وتدريب قدرته على التركيز.') WHERE id = '1fed649f-83be-432e-bf3b-958f939d1d57';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في مجال النشاط البدني: "إتقان صعود الدرج". قد يحاول طفلكِ الآن صعود الدرج بخطوات متتالية، واضعًا قدمًا واحدة على كل درجة، عندما تمسكين بإحدى يديه فقط. وهذا يعني أن عضلات الفخذين والحوض لديه أصبحت أقوى. ابقي دائمًا بالقرب منه لحمايته، وصفّقي له احتفاءً بإنجازاته.') WHERE id = '2104ca19-971d-4ad2-bad2-4fb0d5fce478';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: عبارات "السبب والنتيجة". قد يحاول طفلكِ الآن أن يقول "لأن" (أو يصدر صوتًا قريبًا منها) ليشرح سبب رغبته في شيء ما. اشرحي له الأسباب أيضًا: "لن نأكل المثلجات الآن لأن الجو بارد". فهذا يضع أساس تفكيره المنطقي وقدرته على بناء الحجج.') WHERE id = '9a1ea5be-b73b-4171-a8a3-6f9f06ff6d11';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: "الفكّ والتدوير". أصبح طفلكِ الآن قادرًا على فتح أغطية الزجاجات وبراغي الألعاب وإغلاقها بثقة عن طريق تدويرها. تُعدّ هذه الحركة تمرينًا ممتازًا لعضلات الرسغ المسؤولة عن الدوران. قدّمي له أوعية آمنة بأحجام مختلفة لدعم اهتمامه بهذه الآلية.') WHERE id = '326af733-89d5-4b18-a86d-69d50b560d32';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"أنا أغتسل بنفسي". أثناء الاستحمام، يحاول طفلكِ أخذ الصابون أو الإسفنجة وفرك جسمه تقليدًا لكِ. لا تثبّطي اهتمامه بعادات النظافة. فمحاولته "تنظيف" نفسه تساعده على التعرّف إلى أجزاء جسمه بصورة أفضل، وعلى تعلّم تحمّل مسؤولية نظافته الشخصية منذ سن مبكرة.') WHERE id = '059ef4bc-ae23-4023-aa71-ac7bfd7a180d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: "صعوبة المشاركة". في هذا العمر، من الطبيعي جدًا أن يصرخ طفلكِ قائلًا: "إنه لي!". فهو يتعلّم حماية ممتلكاته. لا تجبريه على المشاركة، بل طبّقي مبدأ "لنلعب بالتناوب". إن صبركِ هذا يسهم في تشكيل ذكائه الاجتماعي.') WHERE id = '89f6ed5e-1781-4f77-8a89-eea339ecb1d6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الكلام: «وصف الذات». أصبح طفلكِ الآن يصف حاله بعبارات مثل: «أنا كبير» و«أنا أركض». قفي معه أمام المرآة واجعلي عملية إدراكه لذاته ممتعة بطرح أسئلة مثل: «ما لون عينيك؟» و«أين أنفك؟».') WHERE id = 'eca2c14e-98c5-475b-94e6-e55601d2febb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التطور العاطفي: «أزمات الاستقلالية». عندما يرغب طفلكِ في فعل كل شيء بنفسه ولا ينجح، قد ينتابه غضب شديد. حافظي على هدوئكِ في هذه اللحظات وادعميه بقولكِ: «أنت غاضب الآن لأن هذا صعب، تعالَ لنفعله معًا». هدوؤكِ هو أقوى ملاذ يهدّئ عواصفه العاطفية.') WHERE id = '9fa6b04b-2e13-4b5c-ba62-6d1e0398948e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ الآن قادرًا على التمييز بصريًا بين الدرجات المتقاربة للألوان، وليس فقط بين ألوان مثل «الأحمر» و«الأزرق». أريه أوراقًا بدرجات مختلفة من اللون الأخضر واسأليه: «أيها أغمق؟». فهذا يصقل قدرته على التحليل البصري.') WHERE id = '1d89cf33-54f4-473a-9dbf-869b4e96ac30';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في النشاط البدني: «محاولات القفز على قدم واحدة». يحاول طفلكِ الآن أداء قفزة صغيرة على قدم واحدة. وهذه حركة معقدة جدًا تتطلب قوة الكاحل والتوازن. صفّقي لمحاولاته الشجاعة وادعميه حتى لا يشعر بالإحباط، حتى إن سقط.') WHERE id = 'c09edac9-8b37-4347-a8dd-3e14699e7139';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الكلام: «البوادر الأولى لاستخدام الزمن الماضي». أصبح طفلكِ الآن يستخدم أفعالًا مثل «ذهبت» و«رأيت» و«أكلت» للتعبير عن أحداث وقعت في الماضي. تحدثي معه في المساء عن سؤال: «ماذا فعلنا اليوم؟». فهذا يعزز ذاكرته وفهمه للزمن معًا.') WHERE id = '5e30771f-35e9-43cb-9e6c-1bfc3d0ea335';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: «التلوين الهادف». يحاول طفلكِ الآن تلوين المساحة داخل شكل كبير على الورق، مثل الدائرة، من دون تجاوز حدوده كثيرًا. وهذا تقدم كبير في التحكم بعضلات اليد. قدّمي له أوراق تلوين بسيطة ذات حدود كبيرة وواضحة.') WHERE id = '30b62203-ae1a-48ab-82d9-d252856f8bcb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«المطابقة» في التطور المعرفي. أصبح طفلكِ قادرًا الآن على مطابقة الصور المختلفة للحيوان نفسه أو الأشياء ذات اللون نفسه. العبي معه لعبة «اعثر على المطابق» باستخدام بطاقات بسيطة. فهذا يطوّر بسرعة انتباهه البصري وقدرته على التفكير وفق الفئات.') WHERE id = '1b1a5af3-541e-4a8b-826b-94504ae0251e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الحركي: «رمي الكرة بعيدًا». لم يعد طفلكِ يُسقط الكرة على الأرض فحسب، بل يحاول رميها إلى الأمام من فوق كتفه (overhand). تتطلب هذه الحركة تناسق الجسم كله. العبي معه في الحديقة لعبة «من يرمي الكرة إلى مسافة أبعد؟». فهذا يقوّي ذراعيه ويُحسّن إدراكه للمسافات.') WHERE id = '985bce91-74bc-40ac-bdc4-be9aa7dbfeab';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الطلب» في تطور الكلام. عندما يريد طفلكِ شيئًا، لم يعد يكتفي بالإشارة إليه بإصبعه، بل أصبح قادرًا على قول «أعطني» أو «من فضلك» (أو تعبير مشابه). كوني دائمًا قدوة له في استخدام الكلمات المهذبة. فسماعه منكِ عبارات مثل «شكرًا جزيلًا» أو «من فضلك» يضع أساس آداب التواصل لديه مستقبلًا.') WHERE id = 'edefb696-9b37-48b2-bf5d-42c196545bf4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تعزُّز الخيال: «ألعاب تقمّص الأدوار تصبح أكثر تعقيدًا». لم يعد طفلكِ يكتفي بالتظاهر بالطهي، بل يدعو ألعابه كضيوف، أو «يعالجها»، أو «يُركبها السيارة ويأخذها إلى العمل». يوضح ذلك كيف يربط بين الأحداث المخزّنة في ذاكرته. شاركيه ألعاب تقمّص الأدوار هذه، فهي ستعزّز إبداعه إلى أقصى حد.') WHERE id = '22acecd0-67df-4601-b0d7-23a57c3444c3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بكِ في الشهر التاسع والعشرين! بدأ طفلكِ الآن بتقديم إجابات أكثر تعقيدًا من «نعم» و«لا». فقد يجيب عن سؤال «لماذا تريد هذا؟» بعبارات مثل «لأنه لذيذ» أو «لأنه أحمر». وهذه بداية قدرته على التعبير بالكلمات عن دوافعه الداخلية. أنصتي باهتمام إلى كل مرة يقول فيها «لأن».') WHERE id = '0e94d08f-2dfb-49bd-b8dc-5b547bbc54de';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التوازن الديناميكي» في الحركة الجسدية. أصبح طفلكِ مهتمًا الآن بالمشي مثل «لاعب الحبل» فوق خط منخفض أو حبل موضوع على الأرض. يساعد ذلك على تطوير وعيه بوضعية جسمه (proprioception). ادعمي هذه المهارة في المنزل برسم مسارات باستخدام أشرطة ملوّنة.') WHERE id = '82c3b72a-274b-4062-9adf-7e5cce134bd3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«صيغ الجمع» في الكلام. أصبح طفلكِ يفهم الفرق بين «تفاحة» و«تفاحات»، ويحاول استخدام صيغ الجمع في كلامه. عزّزي لديه مفهوم الجمع بالإشارة إلى ألعابه وقولكِ: «انظر، توجد هنا سيارات كثيرة». يشير ذلك إلى أن بنيته النحوية تزداد تعقيدًا.') WHERE id = '64529c1d-caa7-4ac1-a772-2e82ed067453';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«قوة الأصابع» في المهارات الحركية الدقيقة. أصبح طفلكِ قادرًا على الضغط على مشابك تعليق الملابس (ملاقط الغسيل) لفتحها، أو اقتطاع قطع أصغر عند اللعب بالصلصال. تقوّي هذه الحركات عضلات أصابعه الصغيرة وتهيئه لإمساك القلم بطريقة صحيحة مستقبلًا.') WHERE id = 'e1008078-204c-4a5c-bac1-d07adf97ca32';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«المشاركة الرمزية» في السلوك الاجتماعي. بدأ طفلكِ يحاول ألّا يأخذ اللعبة فورًا من يد طفل آخر، بل يقول: «أعطني» وينتظر. هذه هي البدايات الأولى لمهارة التنظيم الذاتي. عندما تلاحظين هذا السلوك الصبور، احرصي على مدحه بقولكِ: «شكرًا جزيلًا لأنك انتظرت دورك».') WHERE id = '7f709f10-5a18-4150-b7b4-fa822721b9c8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«أنا أُحضّر بنفسي». يستمتع طفلكِ كثيرًا بمساعدتكِ في المطبخ، مثل عجن العجين بيديه، أو تقطيع الخضراوات (بسكين آمن)، أو وضع الملاعق على المائدة. يساعد ذلك على تطوير مهاراته الحركية ويزيد اهتمامه بالطعام أيضًا.') WHERE id = '53d5b167-fe89-4403-8e4d-0684f94ae9c5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التسلسل والذاكرة» في التطور المعرفي. أصبح طفلكِ يعرف تسلسل أحداث قصته أو فيلمه الكرتوني المفضل. فإذا رويتِ الأحداث بترتيب خاطئ، فقد يصحح لكِ قائلًا: «لا، لقد جاء الدب!». يشير ذلك إلى قوة ذاكرته طويلة المدى وقدرته العالية على استيعاب تسلسل الأحداث.') WHERE id = '51d45576-0732-4e17-9d1f-994a457d540c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «القفز في المكان والدوران». لم يعد طفلكِ يقفز إلى أعلى فحسب، بل يحاول أيضًا تدوير جسمه في الهواء أثناء القفز. يتطلب ذلك تناسقًا دهليزيًا معقدًا. العبي معه ألعاب «الأكروبات» على سجادة ناعمة.') WHERE id = '9536e69d-203e-4017-ae80-dbe2f9eab99b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"أنا مساعد". يبدأ طفلكِ في التعامل مع مهام التنظيف المنزلية البسيطة (مثل إزالة الغبار وترتيب ألعابه في الصندوق) بوصفها مسؤولية، لا مجرد لعبة. أعطيه قطعة قماش صغيرة خاصة به للتنظيف. فهذا يعزز لديه بشكل كبير الشعور بالمسؤولية والانتماء داخل الأسرة.') WHERE id = '75e40c4f-895e-4725-bab2-0bb5ec9f1edc';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"العلامات الأولى للصداقة" في السلوك الاجتماعي. أصبح طفلكِ يفرح عندما يرى طفلًا يعرفه في الحديقة، ويعرض عليه لعبته. تمثل هذه المرحلة انتقالًا من مجرد اللعب جنبًا إلى جنب إلى اللعب معًا (اللعب التفاعلي). ادعمي خطواته الاجتماعية هذه بكلمات إيجابية.') WHERE id = '73a7095e-32dd-413f-b911-0ace0be7e88d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الارتفاع والسعة" في التطور المعرفي. أصبح طفلكِ قادرًا على المقارنة بصريًا بين الأكواب لمعرفة أيها يتسع لكمية أكبر من الماء، أو بين الأبراج لمعرفة أيها أعلى. العبِي معه بالماء مستخدمةً أوعية بأحجام مختلفة أثناء الاستحمام. إن سؤاله: "أي وعاء سيمتلئ أولًا؟" يعزز معرفته بالعالم المادي.') WHERE id = '3cf32da0-166e-4863-bf9c-f4ea80d66e98';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "التحكم في الكرة أثناء الجري". يحاول طفلكِ الآن دفع الكرة إلى الأمام بقدمه أثناء الجري (المراوغة). ويتطلب ذلك مزامنة سرعة الحركة مع دقة حركة القدم. العبِي معه ألعاب كرة قدم حركية في الهواء الطلق لمساعدته على تفريغ طاقته بطريقة مفيدة.') WHERE id = 'c300bf1e-a81a-4d08-9bfb-583735c02aab';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الأسئلة المجرّدة" في تطور الكلام. لم يعد طفلكِ يسأل فقط: "ما هذا؟"، بل أصبح يطرح أسئلة عن أحداث لا يراها، مثل: "إلى أين طار الطائر؟" أو "إلى أين ذهبت الشمس؟". أضيفي لمسة من الخيال إلى إجاباتكِ، مثل: "ذهبت الشمس لتنام". وهذا مؤشر على نمو خياله وازدياد عمق فهمه للأحداث.') WHERE id = '5d13e772-b0dc-414e-be1a-eb306de1058d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: عندما يسمع طفلكِ الآن إجابة "لا"، لا يبكي فورًا كما كان يفعل من قبل، بل يحاول فهم السبب. اشرحي له القواعد بنبرة هادئة: "لن نأكل الحلوى الآن، لأن موعد العشاء قد حان". إن تصرفكِ المتسق والمنطقي يساعد طفلكِ على اكتساب مهارتي ضبط النفس والصبر.') WHERE id = 'd426c7f4-84e8-442d-bd5f-c6c23fc0839f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'نبدأ الأيام العشرة الأخيرة من الشهر التاسع والعشرين! أصبح طفلكِ يستخدم ضميري «أنا» و«أنت» من دون أخطاء تقريبًا. وخلال الحديث، يعبّر عن رغباته بوضوح وحزم قائلًا: «أنا أريد هذا». ادعمي وعيه بذاته وأظهري له احترامكِ لقراراته؛ فهذا يشكّل أساس ثقته الصحية بنفسه.') WHERE id = '4a584dfd-3b1f-4ba7-b2c3-765c25e1ca50';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«القفز والهبوط» ضمن المهارات الحركية الكبرى. أصبح طفلكِ يجرؤ على القفز بكلتا قدميه في الوقت نفسه من درجة منخفضة، مثل حافة الرصيف، والهبوط على الأرض. وهذا إنجاز كبير من حيث قوة عضلات الساقين والإحساس بالتوازن المكاني. ابقي دائمًا بالقرب منه لحمايته ومساندته.') WHERE id = '55d65f2d-a7aa-455b-9e97-2b3375627fc7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«استخدام أدوات الربط» في الكلام. أصبح طفلكِ يربط بين فكرتين باستخدام كلمات مثل «و» و«لكن» و«لأن»: «ركضتُ ووقعتُ». وهذا يدل على أن أفكاره أصبحت أكثر تنظيمًا وترابطًا. وعندما تتحدثين معه، استخدمي أنتِ أيضًا أدوات الربط هذه لتجعلي جملكِ أكثر تعقيدًا قليلًا.') WHERE id = 'a1740f48-0bf0-4597-985c-859e4a235e6b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الاهتمام بـ«العُقَد والربط» ضمن المهارات الحركية الدقيقة. أصبح طفلكِ يحاول شد أربطة الحذاء، وفك الأزرار، أو تمرير خيط عبر خرزات كبيرة. وتُنمّي هذه الأنشطة تناسق حركة أصابعه بدرجة كبيرة. ادعمي اهتمامه بتقديم خيوط ذات خامات مختلفة وألعاب تحتوي على ثقوب.') WHERE id = '17adcdf9-4e22-4431-92cb-4bcd0b67e350';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إتقان «ارتداء الملابس باستقلالية». أصبح طفلكِ ماهرًا في رفع سرواله أو ارتداء قميص بسيط بعد إدخال رأسه فيه. شجّعيه بقولكِ: «هيا، حاوِل الآن ارتداء جواربك». تساعده هذه الخطوات الصغيرة نحو الاستقلالية على الشعور بأنه شخص قادر في حياته اليومية.') WHERE id = '306f738c-086a-4ef8-9272-59796c9176d7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«فهم القواعد» في السلوك الاجتماعي. أصبح طفلكِ يفهم بعض القواعد في المنزل أو الحديقة، مثل «غسل اليدين قبل الأكل» و«انتظار الدور عند الزحليقة». وعلى الرغم من أنه قد يرغب أحيانًا في مخالفة هذه القواعد، فإن ثباتكِ يساعده على تحويل الأعراف الاجتماعية إلى انضباط ذاتي.') WHERE id = '4a18c5ac-a958-4970-b854-89448eb42394';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الترتيب والمقارنة" في التطور المعرفي. أصبح الطفل قادرًا الآن على ترتيب 3-4 أشياء وفقًا لحجمها. قدّمي له مكعبات بأحجام مختلفة وقولي له: "ضع أصغرها في الأعلى". يساعد هذا النشاط على تطوير كلٍّ من التحليل البصري والتفكير الرياضي المبكر. حفّزيه عند كل خطوة صحيحة بقولكِ: "ما أشد انتباهك!".') WHERE id = '4204844b-c0b2-424d-bc6a-7ddffcbc310c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "تصويب الكرة نحو هدف بعيد". لم يعد الطفل يرمي الكرة عشوائيًا، بل أصبح يوجّهها بدقة أكبر نحو نقطة محددة (مثل سلة أو نحوكِ). وهذا يجمع بين التناسق بين اليد والعين وإدراك العمق (إدراك المسافة).') WHERE id = '2d64c34e-bf0d-4efe-9c0e-d67a9a461b59';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"سلسلة الأسئلة والأجوبة" في تطور الكلام. لم يعد الطفل يجيب عن أسئلتكِ بكلمتي "نعم/لا" فقط، بل أصبح يجيب بجمل كاملة. فقد يجيب عن سؤال "ماذا رأيت اليوم؟" قائلًا: "رأيت شجرة كبيرة". عندما تتحاورين معه، حفّزي تطور كلامه بطرح أسئلة متابعة مثل: "ما لونها؟" و"أين كانت؟".') WHERE id = 'e8d19883-dd1e-49e0-bcde-510b73e5bdc1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أكملنا 880 يومًا! أوشك الطفل الآن على بلوغ عامين ونصف (30 شهرًا). وقد أصبح أكثر قوة جسديًا وعاطفيًا، وبات قادرًا على تسمية مشاعره ("أنا سعيد"، "لقد غضبت"). كل لحظة تقضينها معه اليوم تترك في ذاكرته آثارًا إيجابية لا تُمحى. أنتِ أم رائعة!') WHERE id = '6218d94c-c601-40e6-8296-e74639caa069';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بكِ في الشهر 30، أي عند بلوغ طفلكِ عامين ونصف! في هذه المرحلة، يبدأ الطفل في تأكيد ذاته بوصفه فردًا مستقلًا تمامًا. فهو يرسم حدوده الخاصة بقوله: "هذا لي" أو "سأفعل ذلك بنفسي". تقبّلي محاولاته للاستقلال بصبر؛ فهذا مهم جدًا لتشكّل شخصيته.') WHERE id = '8c2026bd-7655-4fc6-8c90-c09af022e3d7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"التوازن الديناميكي" في التطور الجسدي. أصبح الطفل قادرًا الآن على الوقوف بثبات على قدم واحدة لبضع ثوانٍ (3-5 ثوانٍ). وهذا مؤشر على تطور المخيخ لديه وتناسق عضلاته. العبي معه "لعبة اللقلق" واختبرا مَن يستطيع الوقوف مدة أطول.') WHERE id = '59136234-e72e-461f-a081-2d86fdd6b1f1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«المفاهيم المجرّدة» في الكلام. يبدأ طفلكِ الآن بتسمية مشاعر مثل «الحب» و«السعادة» و«الخوف». فعندما يقول «أحبكِ» أو يأتي إلى حضنكِ قائلًا «لقد خفت»، فهذا يدل على التطور السريع لذكائه العاطفي (EQ). تقبّلي مشاعره دائمًا وأكّدي له أنها طبيعية.') WHERE id = '2c9c993e-8ed6-4bde-970b-e837e161f321';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الخطوط الرأسية والأفقية» في المهارات الحركية الدقيقة. يمسك طفلكِ قلم الرصاص الآن بثقة أكبر، ويرسم على الورق خطوطًا مستقيمة هادفة بدلًا من الخطوط العشوائية المتداخلة. قدّمي له أقلام تلوين بألوان مختلفة واقترحي عليه رسم «طرق» أو «سلالم».') WHERE id = '2e6c20d2-ff7f-4e05-b377-0a03f81606ea';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«النظافة الشخصية المستقلة». يتحمّس طفلكِ الآن لتنظيف أسنانه بالفرشاة (تحت إشرافكِ)، وغسل يديه بالصابون وشطفهما جيدًا. إن ترسيخ هذه العادات في هذا العمر بأسلوب مرح سيساعده مستقبلًا على تحمّل مسؤولية نظافته الشخصية.') WHERE id = '9f592616-f0c7-4018-8751-de7b0540a2d9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«لعب الأدوار» في السلوك الاجتماعي. أصبح طفلكِ الآن يبتكر «سيناريو»: فيدعو ألعابه إلى زيارته، أو «يقدّم لها الشاي»، أو «يضعها في الفراش». ومن خلال هذه الألعاب، يتعلم الأدوار والقواعد الاجتماعية بعمق عبر محاكاة عالم الكبار.') WHERE id = 'b497facf-4e33-44ce-bb8d-95b34db2194a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التعرّف على الأشكال المختلفة» في التطور المعرفي. أصبح طفلكِ الآن يعرف الفرق بين الدائرة والمربع والمثلث، ويضع كل شكل في الفتحة المناسبة له. فإذا لم يخطئ عندما تقولين له: «أعطني المربع»، فهذا دليل على تطور قدراته البصرية المكانية.') WHERE id = 'e423f075-63ff-4c05-92b5-4ab5ac29b6be';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «المشي إلى الخلف». يستطيع طفلكِ الآن أن يخطو بضع خطوات إلى الخلف من دون أن ينظر وراءه. هذه الحركة مهمة لإدراكه موضع جسمه في المكان (الحس العميق). حوّلي هذه الحركة إلى لعبة بقولكِ: «لِنمشِ مثل السلطعون»؛ فهي تمرّن عضلات ساقيه بطريقة مختلفة.') WHERE id = '4e7bdd0e-7517-4dbe-a3fb-4614d6b6754f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الجمل متعددة الكلمات» في الكلام. أصبح طفلكِ الآن قادرًا على تكوين جمل معقدة من 4-5 كلمات، مثل: «ماما، أريد أن أذهب إلى الحديقة وألعب». كما أصبحت أدوات الربط وصيغ الأزمنة تظهر في جمله بوتيرة أكبر. اطرحي عليه أسئلة مفتوحة أثناء حديثكِ معه لتشجيعه على التحدث أكثر.') WHERE id = 'd51c61a3-3310-47cc-be33-4e2fc01a2f12';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الحدود العاطفية: بدأ طفلكِ الآن يفهم كيف تؤثر بعض تصرفاته فيكِ، وأصبح قادرًا على قراءة الحزن أو الفرح على وجهكِ. اشرحي له علاقة السبب والنتيجة العاطفية بقولكِ: «أشعر بسعادة كبيرة عندما تشارك الآخرين». سيساعده ذلك على أن يكبر ليصبح شخصًا عطوفًا ومراعيًا لمشاعر الآخرين.') WHERE id = '00079201-58ca-47e2-bd9f-428f9b22aea3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يتبقَّ سوى 10 أيام للوصول إلى الإنجاز الكبير في اليوم 900! بدأ طفلكِ الآن يبتعد قليلًا عن التفكير المتمحور حول «الأنا»، وأصبح يفهم احتياجات الآخرين أيضًا. فمثلًا، قد يسألكِ: «هل تريدين ماءً؟». احرصي على الإشادة بمحاولاته الدالة على الاهتمام؛ فهي تشير إلى نضج ذكائه الاجتماعي والعاطفي (EQ).') WHERE id = '54cacacb-5f6d-4f6a-b6ea-082797db1faf';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الحركة الجسدية: «نزول الدرج بتبديل القدمين». يحاول طفلكِ الآن نزول الدرج خطوةً تلو الأخرى مع تبديل القدم في كل درجة. وهذه الحركة أصعب من صعود الدرج وتتطلب قدرًا كبيرًا من التوازن. انتظري بصبر وأشعريه بثقتكِ به.') WHERE id = 'ce4fa5fc-7dc5-4de0-b4e5-b9c6bb215fb4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«مرحلة الأسئلة المعقدة» في الكلام. لم يعد طفلكِ يكتفي بالسؤال: «ما هذا؟»، بل أصبح يطرح أسئلة مثل: «لماذا هو هكذا؟» و«إلى أين نحن ذاهبون؟». كوني صادقة وبسيطة في إجاباتكِ؛ فتفسيراتكِ ترسم في دماغه خريطة منطقية للعالم. حفّزي فضوله دائمًا بسؤاله: «لماذا تعتقد أنه هكذا؟».') WHERE id = 'b47ac63c-a31b-4cfe-b3d9-64f08edba2f8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: «رسم الدائرة وعلامة الزائد». بدأ طفلكِ الآن يمسك القلم بطريقة أقرب إلى طريقة «الكبار» مستخدمًا ثلاثة أصابع، ويحاول تقليد أشكال مثل الدائرة وعلامة الزائد على الورق. وهذه من أهم المهارات الحركية اللازمة لاكتساب مهارات الكتابة مستقبلًا. أعطيه قطع طباشير ملوّنة.') WHERE id = '4c756f1e-f764-4f55-8535-6552dafc167f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الاستقلالية في تناول الطعام والاختيار». يريد طفلكِ الآن أن يقرر بنفسه مقدار ما سيأكله على المائدة. تجنبي إجباره على تناول الطعام. ومع تطور مهاراته في الاعتماد على نفسه، اقترحي عليه أن يحمل طبقه إلى المطبخ بنفسه (إذا كان ذلك آمنًا). فهذا ينمّي لديه الشعور بالمسؤولية داخل الأسرة.') WHERE id = '04c3f7db-69bb-44ed-8348-5d4d92cb8c92';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«رفاق اللعب الخياليون» في السلوك الاجتماعي. أصبح طفلكِ الآن يتحدث مع ألعابه، ويوجّه إليها المهام، ويتعامل معها كما لو كانت كائنات حية. وهذا دليل على قوة خياله وقدرته على تكوين روابط مجردة بين الأحداث.') WHERE id = '2c67e108-3cf8-4072-89be-1ff519eaddcc';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التمييز بين درجات الألوان» في التطور المعرفي. أصبح طفلكِ الآن قادرًا على التمييز بصريًا بين الأخضر الفاتح والأخضر الداكن، وليس مجرد معرفة اللون «الأخضر». العبي معه لعبة «أيهما أغمق؟» بأن تعرضي عليه أوراقًا أو أقلام تلوين بدرجات لونية مختلفة. فهذا يصقل قدرته على التحليل البصري.') WHERE id = 'dcddf5f8-faa5-4048-a797-208e9715f0bf';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «الاهتمام بالدراجة ثلاثية العجلات». يحاول طفلكِ الآن تدوير الدواسات أو دفع نفسه إلى الأمام بارتكاز قدميه على الأرض. تقوّي هذه الحركة عضلات ساقيه، وتنمّي أيضًا قدرته على تحديد الاتجاه والتحكم فيه أثناء الحركة.') WHERE id = 'a4633b77-b5aa-45ed-9da1-475ae9482abc';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الزمن الماضي والمستقبل» في تطور النطق. يحاول طفلكِ الآن استخدام الفروق الزمنية في كلامه، مثل «سنذهب غدًا» أو «ذهبنا أمس»، حتى وإن لم يكن دقيقًا تمامًا. تحدثي معه في نهاية اليوم قائلة: «ماذا فعلنا اليوم؟» و«ماذا سنفعل غدًا؟». فهذا يقوّي ذاكرته ومهاراته في التخطيط.') WHERE id = '3e7a62e8-608e-4fd7-88f9-177ba74dcb48';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد أكملنا 900 يوم! بلغ طفلكِ الآن عامين ونصف (30 شهرًا). وقد أصبح أكثر قوة واستقلالية وإبداعًا، جسديًا وعاطفيًا. كان حبكِ وتفانيكِ خلال هذه الأيام الـ900 أساسًا لحياته المستقبلية بأكملها. لقد أنجزتِ عملًا مذهلًا يا أمي!') WHERE id = '3d5a9ac6-ec3e-4630-b503-91b84d5fef32';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«إدراك الحجم» في التطور المعرفي. أصبح طفلكِ يفهم بصريًا أن الصندوق الصغير يمكن وضعه داخل الصندوق الكبير، بينما لا يمكن العكس. قدّمي له أوعية بأحجام مختلفة واسأليه: «أيٌّ منها يمكن أن يتّسع داخل هذا؟». هذا هو الإدراك المكاني الذي يُعدّ أساس التفكير الرياضي والهندسي مستقبلًا.') WHERE id = '615744e3-fb18-42f6-8110-3e9a2d54709c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التنسيق الحركي: «رمي الكرة نحو الهدف». لم يعد طفلكِ يرمي الكرة عشوائيًا، بل أصبح يصوّبها بدقة نحوكِ أو نحو صندوق (سلة) محدد. وهذا يجمع بين التآزر بين اليد والعين وإدراك العمق. العبوا معًا «كرة السلة المصغّرة».') WHERE id = '8fa193ab-3d15-4b10-9608-9e3d2bd116d1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«المفاهيم المجرّدة» في تطور اللغة. أصبح طفلكِ يستخدم كلمات مثل «الحب» و«الشعور بالأذى» و«الاشتياق» في مواضعها الصحيحة. وقوله «اشتقت إليكِ» علامة بارزة على تطور ذكائه العاطفي. احرصي على التجاوب مع هذه المشاعر، وعبّري أنتِ أيضًا عن مشاعركِ بالكلمات: «وأنا أيضًا أفرح كثيرًا عندما أراك».') WHERE id = '13cc3bef-f498-4191-9d8c-212c97c4c3e8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قوة الخيال: «الضيوف غير المرئيين». أصبح طفلكِ يدعو ألعابه للزيارة ويقدّم لها أطعمة خيالية. ألعاب التظاهر هذه هي طريقته في تطبيق المواقف الاجتماعية المخزّنة في ذاكرته. انضمّي أنتِ أيضًا إلى عالمه الخيالي كضيفة!') WHERE id = 'a44149c1-0e64-49a3-936a-9d1d3a595e97';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يعد طفلكِ يميّز الألوان بصريًا بوصفها «حمراء» أو «زرقاء» فحسب، بل بدأ أيضًا يفرّق بين درجاتها الداكنة والفاتحة. قدّمي له أقلام تلوين بألوان مختلفة وقولي: «أعطني اللون الأغمق» لاختبار قدرته على التحليل البصري. فهذا ينمّي انتباهه وإدراكه الجمالي معًا.') WHERE id = '5bd4135a-236e-4d8e-8be3-3ebc28e05d9e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«المشي إلى الخلف» ضمن المهارات الحركية. أصبح طفلكِ قادرًا على الرجوع بضع خطوات إلى الخلف من دون أن يفقد توازنه. تعزّز هذه الحركة وعيه بجسمه (الحس العميق) وقدرته على تحديد الاتجاهات في المكان. العبي معه لعبة «لنمشِ مثل السلطعون».') WHERE id = '54996f87-c947-4849-9084-027fb47fcd81';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لقد تجاوزنا محطة الـ900 يوم الكبيرة، ونبدأ الآن مرحلة جديدة! فقد دخل طفلكِ شهره الحادي والثلاثين. وأصبح الآن ينطق اسمه وأسماء أفراد الأسرة بدقة تامة. تصفّحي معه ألبوم العائلة والعبا لعبة «من هذا؟». فهذا يعزّز لديه الشعور بالانتماء والذاكرة اللفظية.') WHERE id = '5482dfbc-7126-4e7c-8510-4a2cfbf55aee';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية: «القفز على قدم واحدة». أصبح طفلكِ يحاول الآن القفز على قدم واحدة، ولو قفزة صغيرة جدًا. وهذا يدل على تطور ملحوظ في عضلات الكاحل وربلة الساق. ادعمي هذه المهارة بتنظيم مسابقة «قفز الأرانب» معه في الحديقة.') WHERE id = '2840aa13-bbb5-476f-ad1f-11685bbcd555';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الكلام: «تقديم الحجج». لم يعد طفلكِ يكتفي بالتعبير عن رغباته، بل أصبح يبررها أيضًا، مثل: «أريد هذه الدمية لأنها جميلة». أنصتي باهتمام إلى عباراته التي تبدأ بـ«لأن». فهذا يوضح مدى تطور تفكيره المنطقي وقدرته على التعبير عن نفسه.') WHERE id = 'dd18fee0-7070-455b-a654-1c5450138cd5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: «التلوين الهادف». أصبح طفلكِ الآن يدرك حدود الأشكال الكبيرة على الورق، مثل صورة تفاحة كبيرة، ويحاول ألّا يتجاوزها أثناء التلوين. وهذه خطوة مهمة في التحكم بعضلات اليد. قدّمي له أوراق تلوين ذات حدود عريضة وواضحة.') WHERE id = '25d06f6c-6efb-491d-ac80-8bbd8fa74917';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«ارتداء الملابس باستقلالية» والأزرار. أصبح طفلكِ يُبدي اهتمامًا بفك الأزرار الكبيرة أو سحب السحّاب إلى أعلى بعد أن تبدئي بإغلاقه. أتيحي له هذه الفرصة وقولي: «هيا، جرّب بنفسك». إن قدرته على ارتداء ملابسه بنفسه تعزز لديه بدرجة كبيرة شعور «أنا أستطيع» وثقته بنفسه.') WHERE id = 'e6e7a26c-5b45-4894-8a1d-19ed6e362c71';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: «التعاون والمشاركة». أصبح طفلكِ يدرك الآن أن إعارة لعبته للآخرين أمر مؤقت. وقد حان الوقت ليتعرف إلى مبدأ: «العب بها قليلًا، ثم يأتي دوري». فهذا ينمّي لديه الصبر والتعاطف الاجتماعي.') WHERE id = '79abc2a4-51b0-4f9f-8334-d1eb1d4ea6eb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"تناول الطعام باستقلالية وآداب المائدة". أصبح طفلكِ يستخدم الملعقة والشوكة من دون أن يسكب شيئًا تقريبًا. كما بدأ يستخدم عبارات المائدة في موضعها الصحيح، مثل "صحة وعافية" أو "شكرًا". احرصي دائمًا على مدح هذا السلوك المهذب؛ فهو أساس آداب التواصل مستقبلًا.') WHERE id = '43e9a2b0-67bf-44dc-b37a-1d4a9e1b3e86';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: "ازدياد تعقيد ألعاب تقمّص الأدوار". قد يتصرف طفلكِ الآن كأنه معلّم أو طبيب أو أحد الوالدين، ويعطيكِ "تعليمات". ومن خلال هذه الألعاب، يستوعب الأدوار الاجتماعية. شاركي في "دروسه"، فهذا يساعده على تنمية مهاراته القيادية.') WHERE id = 'd218ecc4-3eae-4f6a-ba4c-e1f3fc1576d0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: "الربط الأول بين العدد والكمية". رغم أن طفلكِ قد يحفظ العد من 1 إلى 5، فإنه بدأ أيضًا يفهم الكمية عندما تقولين مثلًا "تفاحتان". اطلبي منه مطابقة العدد بالكمية بقولكِ: "أعطني قلمين". وهذه إحدى أهم مراحل تطور التفكير الرياضي.') WHERE id = 'e77c9dc0-0ffc-4afa-af6f-98372ac9412c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "مهارات ركل الكرة". أصبح طفلكِ قادرًا على ركل الكرة أمامه أثناء الجري وتغيير اتجاهها من دون أن يفقد توازنه. وهذا يدل على تطور التوازن الديناميكي لديه. إنه أفضل وقت للعب "كرة القدم" معه في الهواء الطلق.') WHERE id = 'f27d93f9-9b8c-4331-9608-1f9403361289';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور النطق: "مفردات جديدة: ازدياد استخدام الصفات". أصبح طفلكِ يستخدم كلمات مثل "ناعم" و"صلب" و"ساخن" و"بارد" و"ثقيل" عند وصف الأشياء. أعطيه أشياء ذات ملمس مختلف واسأليه: "كيف يبدو ملمس هذا؟". تساعد زيادة استخدام الصفات طفلكِ على إدراك العالم بمزيد من التفاصيل.') WHERE id = '2a117057-8af9-4f1a-8e6e-3d0291275ec5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'النضج العاطفي: أصبح طفلكِ أحيانًا يدرك غضبه ويستطيع أن يقول: "أنا غاضب". وهذه قفزة كبيرة في الوعي الذاتي العاطفي. في مثل هذه اللحظات، عانقيه وقولي له: "أتفهم شعورك، هيا نهدأ معًا". لقد أتممنا رحلة 930 يومًا بنجاح، وأنتِ رفيقة درب رائعة!') WHERE id = '9e7e7732-10aa-4ec3-9e8d-653645d590eb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الكلمات المقفّاة والأغاني» في تطور النطق. يحب طفلكِ الآن إكمال الكلمات الأخيرة من الأغاني التي سمعها بقوافٍ مناسبة. وهذا يدل على تطور قدرته على التمييز السمعي للأصوات. اقرئي معه القصائد وتوقفي قبل نهاياتها ليكملها بنفسه. يساعد ذلك على تقوية ذاكرته وتنظيم وتيرة كلامه.') WHERE id = 'acf4d772-adf5-4683-b12b-56ef67f21202';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«نظم الخرز في الخيط» ضمن المهارات الحركية الدقيقة. أصبح طفلكِ الآن ماهرًا في تمرير الخيط عبر حبات الخرز ذات الثقوب الكبيرة أو قطع المعكرونة. تتطلب هذه الحركة الصبر والتنسيق الدقيق بين الأصابع. وبهذه الطريقة، يبني ذاكرة عضلية تمهّد لاكتساب مهارات الكتابة مستقبلًا.') WHERE id = 'acfd54f8-89c0-45e8-b646-d1e1362647ed';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تقدّم في «العناية الشخصية المستقلة». يستطيع طفلكِ الآن تجفيف يديه بالمنشفة بمفرده بعد غسلهما، ثم تعليق المنشفة في مكانها. تعزز خطوات «إتمام المهمة» الصغيرة هذه شعوره بالمسؤولية عن العناية بنفسه. كافئي سلوكه المنظم بقولكِ: «ما أرتبك!».') WHERE id = 'd2072154-6990-473d-aae5-34ace20cbb48';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«فهم مشاعر الآخرين» في السلوك الاجتماعي. قد يلاحظ طفلكِ الآن الحزن أو التعب على وجهكِ ويسألكِ: «ماذا حدث؟». وهذا من أنقى أشكال التعاطف. اشرحي له مشاعركِ بكلمات بسيطة: «أنا متعبة قليلًا، تعالَ لنسترح معًا». فهذا يغذي ذكاءه العاطفي (EQ).') WHERE id = '146ce216-737a-480c-9a11-95c561e541a4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الترتيب والمقارنة» في التطور المعرفي. يستطيع طفلكِ الآن ترتيب 3-4 من ألعابه حسب الحجم (من الأصغر إلى الأكبر). وهذا أساس التفكير الرياضي المبكر. أعطيه مهام مثل: «ضع أكبر دمية دب في مقدمة الصف». فهذا يعلّمه التحليل البصري وتركيز الانتباه معًا.') WHERE id = 'a0704d4b-bb47-4a9f-8d8c-90add9dfed0e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «التوازن الديناميكي». يبدي طفلكِ الآن اهتمامًا بالمشي مثل «لاعب السير على الحبل» فوق حبل منخفض أو خط مرسوم على الأرض. وهذا يدل على نضج جهازه الدهليزي (مركز التوازن). ادعمي شجاعته في الحديقة بإمساك يده أثناء سيره فوق حواف الرصيف.') WHERE id = '536458a4-4f3e-423b-9a13-cba42297d147';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: «مفهوم الزمن: الأمس والغد». رغم أن طفلكِ لا يستخدم هاتين الكلمتين بعد للدلالة على الوقت بدقة تامة، فإنه يحاول التمييز بين أحداث الماضي والمستقبل. تحدثي معه في نهاية اليوم قائلةً: «إلى أين سنذهب غدًا؟». فهذا يعزز قدرته على التخطيط وفهم العلاقة الزمنية بين الأحداث.') WHERE id = '6849680a-6227-4b9c-ad36-2d8926dfdf15';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: عندما لا ينجح طفلكِ في أداء مهمة ما، كأن تنهار مكعباته مثلًا، فقد لا يبكي فورًا، بل يبدأ المحاولة من جديد. إن «روح المثابرة» هذه مهمة جدًا لنجاحه في التعلم مستقبلًا. امدحي جهده لا النتيجة، وقولي له: «أرى أنك تحاول بجد».') WHERE id = '86a0403c-8de6-429b-885d-6a2141aa02c8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'نبدأ الأيام العشرة الأخيرة من الشهر 31! أصبح طفلكِ يستخدم كلمتي «أنا» و«ملكي» بإحساس قوي بالتملك. من المهم خلال هذه المرحلة احترام شعوره بالملكية. أوضحي له أن المشاركة خيار بقولكِ: «هذه لعبتك، لكن لنجرّب أن تتناوبا على اللعب بها أنت وصديقك».') WHERE id = '84330770-7540-4b55-849d-a1cc950ead4d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الحركة الجسدية: «إتقان القفز إلى الأمام بكلتا القدمين». لم يعد طفلكِ يقفز في مكانه فحسب، بل أصبح قادرًا على القفز قليلًا إلى الأمام (نحو 10-20 sm). وهذا يدل على ازدياد القوة الانفجارية لعضلات ساقيه. اصنعي له «عوائق» صغيرة على الأرض، مثل الأشرطة الملونة، والعبا معه لعبة القفز فوقها.') WHERE id = '5741e7d1-1ed4-44c7-a88a-391b61cdae5d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: «تراكيب الجمل المعقدة». أصبح طفلكِ يربط بين فكرتين مختلفتين باستخدام أدوات الربط، مثل: «أريد الذهاب إلى الحديقة واللعب على الأرجوحة». كما أصبحت أهدافه ونواياه أوضح في جمله. شجعيه على تقديم تفسيرات أطول بطرح سؤال «لماذا؟» عليه أثناء حديثكِ معه.') WHERE id = '1e35c889-6f4c-4fd3-ae21-e3389ec8548d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: «الطيّ المنظم». أصبح طفلكِ يحاول تقليدكِ في طيّ ورقة أو منشفة صغيرة. تسهم هذه الحركة في تطوير كل من التناسق بين اليد والعين والإحساس بالتناظر البصري. اطلبي منه طيّ مناديله الصغيرة أثناء ترتيب الملابس.') WHERE id = '3690ca7a-82f5-4004-93ab-5126e1011625';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ الآن يستوعب بصورة أعمق تسلسل «قبل» و«بعد». فعندما تقولين له: «ارتدِ ملابسك، ثم نخرج»، يفهم أن النشاط الثاني بمنزلة مكافأة. هذه هي البذور الأولى لمهارتي الصبر والتخطيط لديه. ذكّريه بهذه التسلسلات كثيرًا خلال الروتين اليومي.') WHERE id = '97310562-0cc9-4922-aab5-bb0de93781d6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في النمو البدني: «إتقان التسلّق». أصبح طفلكِ الآن يصعد سلالم الحديقة أو الأماكن المرتفعة الآمنة في المنزل بثقة أكبر. ويتطلب ذلك عمل عضلات الذراعين والساقين معًا بتناسق. ابقي دائمًا بالقرب منه، لكن أتيحي له فرصة اختبار قدراته بنفسه.') WHERE id = '5e669269-1aa2-4602-9a6d-be602f929f7a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: «الروابط المنطقية». أصبح طفلكِ الآن يربط بين حدثين في جملة واحدة، مثل: «الجو بارد، ارتدِ سترتك». وهذا يدل على أنه لا يكتفي بالتقليد، بل يفكر أيضًا. أكّدي صحة استنتاجاته المنطقية بقولكِ: «نعم، أنت محق»، حتى يتحمس أكثر للتعبير عن أفكاره.') WHERE id = 'c578b6d7-6027-41d3-bcb5-015328604f79';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: «التعامل مع الورق». قد يبدأ طفلكِ الآن بإبداء اهتمام بطيّ الورق أو قصّه بأشكال بسيطة، باستخدام مقص أطفال كبير وتحت إشرافكِ. تنقل هذه الحركات قدرته على التحكم في عضلات أصابعه إلى مستوى جديد. وفّري له بيئة مناسبة للعمل بالأوراق الملوّنة.') WHERE id = '369aa3fa-b6a2-4869-aff0-584c7cb30be3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: «تطوّر ألعاب تقمّص الأدوار». أصبح طفلكِ الآن يتقمّص دور «الطبيب» أو «الطاهي» أو «السائق». ومن خلال هذه الألعاب، يتعرّف إلى مهام الأشخاص من حوله وينمّي قدرته على التعاطف. شاركيه هذه الألعاب وتصرّفي وفق «الدور» الذي يمنحكِ إياه.') WHERE id = '71802808-c37b-439f-8b0c-227ce432a07a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مهارة «النظافة باستقلالية». أصبح طفلكِ الآن قادرًا إلى حدّ كبير على وضع الصابون على يديه وشطفهما بنفسه عند غسلهما. ومن المهم جدًا ترسيخ عادات النظافة في هذا العمر. وفّري له درجة ثابتة وآمنة تناسب طوله ليتمكن من الاستمتاع بهذه العملية.') WHERE id = '916356ea-060f-4a2e-8be7-98dcab3ad0ee';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: "العثور على العنصر المختلف". أصبح الطفل قادرًا الآن على تمييز العنصر المختلف بصريًا من بين مجموعة من الأشياء (مثل التفاحة بين السيارات). وهذا يصقل قدرته على التحليل. نظّمي له في المنزل ألعابًا بسيطة مثل "ما العنصر الزائد؟". فهذا إعداد ممتاز للمسائل الرياضية والمنطقية مستقبلًا.') WHERE id = '9c6d24fc-1a56-41e1-93ca-e94c8c830e4f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "محاولات الوقوف على قدم واحدة". أصبح الطفل الآن يحاول رفع إحدى قدميه عن الأرض والحفاظ على توازنه، ولو لبضع ثوانٍ فقط. وهذا مهم ليتعرف جسمه إلى مركز ثقله. العبي معه "لعبة اللقلق" وتحققا من يستطيع الوقوف مدة أطول.') WHERE id = '1769bf32-48e2-40a7-b480-c6f396b19e4b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في النطق: "التعبير عن المشاعر". أصبح الطفل الآن قادرًا على التعبير بالكلمات عن شعوره بالحزن أو الفرح أو الخوف، فيقول: "لقد خفت" أو "أنا سعيد". وتسمية المشاعر هي أساس الذكاء العاطفي لدى الطفل. عندما يعبّر عن شعوره، أنصتي إليه وأكّدي له مشروعية مشاعره بقولكِ: "نعم، أنا أتفهمك".') WHERE id = '7f6f2c0c-ef35-4291-8d3c-3c98cbe7cfa1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قوة الخيال: "التفكير الرمزي". قد يتخيل الطفل عصًا على أنها "حصان" وينطلق راكضًا بها. وهذه هي القدرة على فهم أن شيئًا ما يمكن أن يرمز إلى شيء آخر. وهي مهارة بالغة الأهمية للقراءة والرياضيات مستقبلًا، إذ تساعد على فهم الرموز. أنتِ مرشدة رائعة!') WHERE id = 'b4910186-9bb2-4fc8-898b-364f4deeed97';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'نبدأ الأيام العشرة الأخيرة من الشهر الثاني والثلاثين! بدأ الطفل الآن يفهم مفهوم "نحن". فعندما يقول: "هل سنذهب إلى الحديقة؟"، فإنه يعبّر عن شعوره بأنه جزء لا يتجزأ من الأسرة. شاركيه خطط الأسرة أثناء الحديث معه، مثل: "سنذهب اليوم إلى بيت الجدة". فهذا يعزز لدى الطفل الشعور بالانتماء والأمان.') WHERE id = '1b278c24-eef1-4629-acd4-d211ef0e2e61';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الحركة الجسدية: "الاستقلالية على الدرج". أصبح الطفل الآن يصعد الدرج بثقة، واضعًا قدمًا على كل درجة بالتناوب، مع الإمساك بيد واحدة فقط. وهذا يدل على اكتمال نضج مهاراته الحركية الكبرى. يكفي أن تبقي بجانبه وتقدمي له الدعم المعنوي.') WHERE id = '275df927-814f-46e6-87b1-244d3e43ae78';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: "الأسئلة المجرّدة". قد يطرح طفلكِ أسئلة مثل: "من أين تأتي الغيوم؟" و"إلى أين ذهب القمر؟". عند الإجابة، وازني بين الخيال والمعلومات الواقعية، مثل: "تأتي الغيوم من مكان بعيد وتحمل إلينا المطر". توسّع مثل هذه الحوارات نظرته إلى العالم وتعزز شغفه بالتعلّم بدرجة مذهلة.') WHERE id = 'a8a1120b-b774-4f04-89b0-c124a8cbf647';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: أصبح طفلكِ الآن أكثر قدرة على تحمّل الإخفاق. فعندما تنهار مكعباته، لا يبكي فورًا، بل يمكنه أن يقول: "سأبنيها من جديد". ادعمي روح المثابرة لديه. لقد قطعنا رحلة 950 يومًا، ولم يتبقَّ سوى القليل للوصول إلى 1000 يوم! أنتِ في هذه الرحلة معلمته وصديقته المقرّبة في آنٍ واحد!') WHERE id = 'c5fe4618-aa8a-4004-b14e-8472a1232fc2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ قادرًا على تصنيف الأشياء ليس حسب نوعها فحسب، بل حسب درجات ألوانها أيضًا. قدّمي له ألعابًا بدرجات مختلفة من اللون الأخضر وقولي: "لنرتبها من الأفتح إلى الأغمق"، لتنمّي قدرته على التحليل البصري. يساعد ذلك على صقل حسّه الجمالي وانتباهه.') WHERE id = '4cccdb9f-0090-4953-be45-4aac0e3ecdc0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في النشاط البدني: "القفز على قدم واحدة". يحاول طفلكِ الآن أداء قفزة صغيرة جدًا على قدم واحدة. ويشير ذلك إلى تطور قوة الكاحل والجهاز الدهليزي المسؤول عن التوازن. العبي معه لعبة "الأرنب الصغير". ابقي دائمًا بالقرب منه كي يتحرك بحرية من دون خوف من السقوط.') WHERE id = '611c7f89-d565-4c80-b60a-401386c94dd3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: "الكلمات المتضادة". أصبح طفلكِ الآن يفهم تمامًا أوجه التضاد مثل "كبير-صغير" و"ساخن-بارد" و"ثقيل-خفيف"، ويستخدمها في كلامه. اطرحي عليه أسئلة مثل: "هذا الحجر ثقيل، فكيف يكون هذا القطن؟". يثري ذلك حصيلته اللغوية نوعيًا ويعزز قدرته على التفكير بالمقارنة.') WHERE id = '8c5fde41-64b4-4f6a-8c4b-9b0a4470f2ce';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: "تركيبات أكثر تعقيدًا". لم يعد طفلكِ يبني بالمكعبات برجًا فحسب، بل أصبح يصنع أشكالًا تحتوي على فراغات، مثل "درج" أو "سياج" أو "باب". وهذه أولى العلامات الحقيقية على تطور تفكيره المكاني وحدسه الهندسي.') WHERE id = '8323ecc8-fdd4-4a47-acab-de738c3b3b74';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"بناء القصة" في تطور الكلام. أصبح طفلكِ قادرًا على ابتكار قصص بسيطة بالنظر إلى الصور. فالجمل المتسلسلة مثل: "جاءت القطة، وشربت الحليب، ثم نامت" تجمع بين ذاكرته وخياله. قدّمي له كتبًا تحتوي على صور شيقة، واسأليه: "ماذا يحدث هنا؟" فهذا يشعل تفكيره الإبداعي.') WHERE id = '904512e9-992f-4497-b856-79751b10de80';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الوضع الدقيق" في المهارات الحركية الدقيقة. أصبح طفلكِ أكثر قدرة على وضع مجسمات الألعاب الصغيرة في أماكنها أو تمرير الخيط في الخرز، مع ارتكاب أخطاء أقل. تزداد حساسية أطراف أصابعه خلال هذه المرحلة. قدّمي له ألعابًا تتضمن أشياء صغيرة ذات ملمس متنوع، مع الإشراف عليه.') WHERE id = 'd9171a51-69d8-4d0a-829c-7db5c26a601f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الإصرار على "ارتداء الملابس باستقلالية". يصر طفلكِ الآن على ارتداء قمصانه الخالية من الأزرار أو سرواله بنفسه. عندما يقول: "سأفعلها بنفسي!"، امنحيه الوقت. فمحاولاته للاستقلالية هي من أقوى أسس ثقته بنفسه وتحمله للمسؤولية مستقبلًا. احتفي بإنجازاته الصغيرة بقولكِ: "أرأيت؟ لقد نجحت بمفردك!"') WHERE id = 'b1c5306b-77bb-4136-8d44-3c944e44a9e3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"قواعد اللباقة" في السلوك الاجتماعي. لم يعد طفلكِ يكرر عبارات مثل "من فضلك" و"شكرًا لك" و"أرجوك" فحسب، بل بدأ يستخدمها عن قصد وفي مواضعها المناسبة. سلوككِ المهذب هو أفضل قدوة له. عززي آداب التواصل لديه بالثناء على هذه التصرفات.') WHERE id = '9e1b06c8-d4a2-4b28-b3bc-ad2c39ab7cb0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"ظروف الزمان" في التطور المعرفي. يبدأ طفلكِ باستخدام كلمات مثل "لاحقًا" و"بعد قليل" و"الآن" في مواضعها الصحيحة. عندما تقولين له: "سآتي بعد قليل"، يفهم أن الوقت سيمضي. وهذا يعزز قدرته على الانتظار وتنظيم سلوكه. استخدمي هذه الكلمات كثيرًا ضمن روتينكما اليومي.') WHERE id = '6f964b8f-02b2-4bed-adce-f35ba0656a6a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "ركل الكرة نحو هدف". لم يعد طفلكِ يركل الكرة فحسب، بل يحاول توجيهها نحو مسار محدد، مثل تمريرها بين لعبتين. وهذا يدل على التزامن بين التناسق البصري الحركي لليدين والتناسق بين العينين والقدمين. نظّمي معه في المنزل بطولة "كرة قدم مصغّرة".') WHERE id = '61ba305a-b8ae-4528-9ce2-bd394666ba9a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ يستخدم ضمائر "أنا" و"أنت" و"نحن" في مواضعها الصحيحة. وعندما يقول: "هل نأكل الآن؟"، فإنه يشعر بأنه فرد فاعل في الأسرة. عند التحدث معه، أشركيه في خططكِ أيضًا: "هيا نُعِدّ المائدة معًا". فهذا يعزز لديه الشعور بالانتماء والمسؤولية.') WHERE id = '0088ee7c-73a0-42ed-a073-c3d4d5a577af';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الحركة الجسدية، مرحلة "الاستقلالية على الدرج". أصبح طفلكِ يصعد الدرج بثقة، واضعًا قدمًا واحدة على كل درجة بالتناوب، مع الإمساك بيد واحدة فقط. وهذا يدل على نضج مهاراته الحركية الكبرى. يكفي أن تبقي بجانبه وتقدمي له الدعم المعنوي.') WHERE id = 'bf415e92-93fc-4c0c-8e41-d0e69018f7ba';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام، مرحلة "تأليف القصص". أصبح طفلكِ يبتكر قصصًا بسيطة بالنظر إلى الصور. وجمل متسلسلة مثل: "جاءت القطة، وشربت الحليب، ثم نامت" تجمع بين ذاكرته وخياله. قدّمي له كتبًا ذات صور ممتعة واسأليه: "ماذا يحدث هنا؟". فهذا يشعل تفكيره الإبداعي.') WHERE id = 'e900e935-8ccc-4908-bf87-10603eb74cda';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة، مرحلة "الوضع الدقيق". أصبح طفلكِ أكثر قدرة على وضع مجسمات الألعاب الصغيرة في أماكنها أو تمرير الخيط في الخرز، مع ارتكاب أخطاء أقل. وفي هذه المرحلة تزداد حساسية أطراف أصابعه. قدّمي له ألعابًا تتضمن أشياء صغيرة ذات ملمس متنوع، مع الإشراف عليه.') WHERE id = '6c732ec0-7e78-45c4-a464-029d46e20701';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الإصرار على "ارتداء الملابس باستقلالية". أصبح طفلكِ يصر على ارتداء قمصانه الخالية من الأزرار أو سرواله بنفسه. وعندما يقول: "سأفعلها بنفسي!"، امنحيه الوقت. فمحاولات الاستقلال هذه هي أقوى أساس للثقة بالنفس وتحمل المسؤولية الشخصية مستقبلًا. واحتفي بنجاحاته الصغيرة بقولكِ: "انظر، لقد فعلتها بمفردك!".') WHERE id = '3fe4a18c-cebd-45f6-88ed-6acbe7109fd0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي، مرحلة "قواعد اللباقة". لم يعد طفلكِ يكرر كلمات مثل "من فضلك" و"شكرًا جزيلًا" و"أرجوك" فحسب، بل أصبح يستخدمها عن قصد. سلوككِ المهذب هو أفضل قدوة له. عززي آداب التواصل لديه بالثناء على هذه السلوكيات.') WHERE id = 'e6b8bd35-5e9c-4328-a121-a6fecf7c7d62';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الاختيار المستقل: الطقس والملابس". أصبح الطفل يدرك الآن أنه إذا كان الطقس باردًا في الخارج، فعليه ارتداء ملابس دافئة. قدّمي له خيارين قائلةً: "الجو بارد اليوم، أي سترة تريد أن ترتدي؟". إن ارتداء الطفل ما يختاره بنفسه يعزز لديه الشعور بالمسؤولية ومهارة اتخاذ القرار.') WHERE id = 'b6331bb4-9640-46b8-a4de-673e4569b48f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"المشاركة الرمزية" في السلوك الاجتماعي. أصبح الطفل الآن قادرًا على أن يعطي صديقه طوعًا لعبة ليست ذات قيمة كبيرة بالنسبة إليه. وهذا يمثل بداية خروجه من مرحلة التمركز حول الذات (كل شيء لي) وبدء التعاون الاجتماعي. احرصي على الإشادة بكرمه بقولكِ: "ما أروع اهتمامك بالآخرين!".') WHERE id = '7a5cc16d-c4e3-465c-94b4-27327272c867';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الترتيب والعدّ" في التطور المعرفي. بالإضافة إلى ترديد الأرقام من 1 إلى 10 عن ظهر قلب، يبدأ الطفل الآن في عدّ الأشياء مشيرًا إليها بإصبعه وقائلًا: "واحد، اثنان، ثلاثة". اسأليه: "كم سيارة توجد هنا؟". هذه هي المرحلة التي تبدأ فيها الأرقام المجرّدة بالارتباط فعليًا بالعالم الحقيقي للمرة الأولى.') WHERE id = '27d58f54-7d91-4fc1-9abe-0e7741238b0e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "المشي والجري إلى الخلف". أصبح الطفل الآن يمشي إلى الخلف بثقة من دون أن ينظر، بل ويمكنه أن يركض بضع خطوات إلى الخلف. تُظهر هذه الحركة مدى تطور التناسق الحركي لجسمه. العبي معه لعبة "سباق السلطعون" لتستمتعا معًا وتساعديه على تمرين عضلاته بطريقة مختلفة.') WHERE id = '5835a9f7-31b7-47bc-af3b-fbaf1eae167a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"استخدام أدوات الربط" في الكلام. أصبح الطفل يعبّر عن أفكاره بصورة أوضح من خلال إدخال كلمات مثل "و" و"لكن" و"لأن" في جمله، فيقول مثلًا: "أنا جائع، لكنني لا أريد أن آكل". استمعي إلى جمله وأجيبيه أنتِ أيضًا بجمل مركبة مشابهة. فهذا يساعده على إتقان فهم القواعد النحوية بشكل كامل.') WHERE id = 'e679f00c-7a2a-4673-af5d-88a6f4d8128e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة النفسية: عندما لا ينجح الطفل في أداء مهمة ما، لم يعد يطلب مساعدتكِ فورًا، بل يحاول بنفسه عدة مرات. ادعمي هذا الإصرار لديه بالمعنى الإيجابي. فقولكِ: "أرى أنك تحاول جاهدًا" يساعده على تقدير المحاولة نفسها أكثر من النتيجة. لم يتبقَّ على إكمال 1000 يوم سوى 40 يومًا!') WHERE id = '73811b23-1334-47b6-aa32-fe16ca9f7dfe';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«ظروف الزمان» في التطور المعرفي. يبدأ طفلكِ باستخدام كلمات مثل «لاحقًا» و«بعد قليل» و«الآن» في مواضعها الصحيحة تمامًا. فعندما تقولين له: «سآتي بعد قليل»، يدرك أن بعض الوقت سيمضي. وهذا يعزز قدرته على الانتظار وتنظيم مشاعره وسلوكه. استخدمي هذه الكلمات كثيرًا خلال روتينكما اليومي.') WHERE id = 'eac1461c-042b-436c-8d00-465739e12f49';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الحركي: «ركل الكرة نحو هدف». لم يعد طفلكِ يركل الكرة فحسب، بل يحاول توجيهها نحو مسار محدد، كأن يمررها بين لعبتين مثلًا. وهذا يتطلب تزامن التناسق بين اليد والعين وبين القدم والعين. نظّمي معه بطولة «كرة قدم مصغّرة» في المنزل.') WHERE id = '3ddf5bfb-d5a6-4b94-8ee2-f4ce76892d43';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الأسئلة المجرّدة» في تطور الكلام. قد يطرح طفلكِ أسئلة مثل: «من أين تأتي السحب؟» و«إلى أين ذهب القمر؟». وعند الإجابة، وازني بين الخيال والمعلومات الواقعية، مثل: «تأتي السحب من بعيد وتجلب لنا المطر». توسّع مثل هذه الأحاديث نظرته إلى العالم وشغفه بالتعلّم بدرجة مذهلة.') WHERE id = '1a341992-7717-4fca-abe1-d703ab6a7a2f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: أصبح طفلكِ أكثر قدرة على تحمّل الإخفاق. فعندما تسقط مكعباته، لا يبكي فورًا، بل يستطيع أن يقول: «سأبنيها من جديد». ادعمي فيه روح المثابرة هذه. لقد قطعنا رحلة امتدت 970 يومًا، ولم يتبقَّ للوصول إلى 1000 يوم سوى 30 يومًا! أنتِ في هذه الرحلة معلّمته وأقرب صديقة له في آنٍ واحد!') WHERE id = 'e1da111f-ccec-436b-a492-b6e924de37bf';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يعد طفلكِ يميّز الألوان بصريًا على أنها «حمراء» أو «زرقاء» فحسب، بل بدأ أيضًا في التمييز بين درجاتها الداكنة والفاتحة. أعطيه أقلام تلوين بألوان مختلفة واختبري قدرته على التحليل البصري بقولكِ: «أعطني اللون الأغمق». فهذا ينمّي انتباهه وإدراكه الجمالي معًا.') WHERE id = '1fa9d3d6-a970-457d-af04-c009e72b5e1b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«المشي إلى الخلف» في التطور الحركي. أصبح طفلكِ قادرًا على السير بضع خطوات إلى الخلف من دون أن يفقد توازنه. تعزز هذه الحركة وعيه بجسده وقدرته على تحديد الاتجاهات في المكان. العبي معه لعبة «لنمشِ مثل السلطعون».') WHERE id = '21db9a7e-7c35-47c7-9f2e-7e03f72a88a3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الكلمات المقفّاة والأغاني» في تطور النطق. يحب طفلكِ الآن إكمال الكلمات الأخيرة من الأغاني التي سمعها بقوافٍ مناسبة. وهذا يدل على تطور وعيه الصوتي. اقرئي معه القصائد وتوقفي قبل نهاياتها ليكملها بنفسه. يساعد ذلك على تقوية ذاكرته وتنظيم إيقاع كلامه.') WHERE id = '6ee138fb-22b9-41f6-a232-d405003097d3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«نظم الخرز في خيط» لتنمية المهارات الحركية الدقيقة. أصبح طفلكِ الآن ماهرًا في تمرير الخيط داخل الخرز ذي الثقوب الكبيرة أو قطع المعكرونة. تتطلب هذه الحركة الصبر والتناسق الدقيق بين الأصابع. وبهذه الطريقة، يبني ذاكرة عضلية تمهّد لاكتساب مهارات الكتابة مستقبلًا.') WHERE id = 'e27670af-3f91-498b-a727-68765b4a34c6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تقدّم في «العناية المستقلة بالنظافة الشخصية». أصبح طفلكِ الآن قادرًا على تجفيف يديه بالمنشفة بعد غسلهما، ثم تعليقها في مكانها بمفرده. تعزز خطوات «إتمام المهمة» الصغيرة هذه شعوره بالمسؤولية عن العناية بنفسه. كافئي سلوكه المنظم بقولكِ: «ما أرتبك!».') WHERE id = '41467e61-a2ce-4e56-9659-81bc3b54b05e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«فهم مشاعر الآخرين» في السلوك الاجتماعي. قد يلاحظ طفلكِ الآن الحزن أو التعب على وجهكِ ويسألكِ: «ما الأمر؟». وهذا من أنقى أشكال التعاطف. اشرحي له مشاعركِ بلغة بسيطة: «أنا متعبة قليلًا، تعالَ لنسترح معًا». فهذا ينمّي ذكاءه العاطفي.') WHERE id = '639f97f3-6003-448b-9622-c5dde4b5cec4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الترتيب والمقارنة» في التطور المعرفي. يستطيع طفلكِ الآن ترتيب 3-4 من ألعابه حسب الحجم، من الأصغر إلى الأكبر. وهذا أساس مبكر للتفكير الرياضي المنطقي. أعطيه مهام مثل: «ضع أكبر دب في البداية». فهذا يعلّمه التحليل البصري وتركيز الانتباه.') WHERE id = '370bff62-25e0-4406-b269-39b56f69516b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «التوازن الديناميكي». أصبح طفلكِ الآن مهتمًا بالمشي مثل «لاعب السير على الحبل» فوق حبل منخفض أو خط مرسوم على الأرض. وهذا يدل على نضج جهازه الدهليزي المسؤول عن التوازن. ادعمي شجاعته في الحديقة بإمساك يده أثناء سيره فوق حواف الأرصفة.') WHERE id = '7d0f18e8-75ea-46a5-ae28-0011a1c178d0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الكلام: «مفهوم الزمن: الأمس والغد». رغم أن طفلكِ قد لا يستخدم هاتين الكلمتين بعدُ للدلالة على الوقت بدقة تامة، فإنه يحاول التمييز بين أحداث الماضي والمستقبل. تحدثي معه في نهاية اليوم قائلةً: «إلى أين سنذهب غدًا؟». فهذا يعزز قدرته على التخطيط وفهم التسلسل الزمني بين الأحداث.') WHERE id = 'a8b25b83-9fde-45e1-b976-1cd3459165f2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: عندما لا ينجح طفلكِ في إنجاز أمر ما (مثل سقوط المكعبات)، قد لا يبكي فورًا، بل يبدأ المحاولة من جديد. هذه «الروح المثابرة» مهمة جدًا لنجاحه في التعلم مستقبلًا. قولي له: «أرى أنك تبذل جهدًا كبيرًا»، وامدحي جهده لا النتيجة.') WHERE id = '0db561dc-233c-4544-804a-8f5b95ba51b9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'يبدأ طفلكِ الآن في فهم مفهوم «نحن». فعندما يقول: «هل سنذهب الآن إلى الحديقة؟»، فإنه يرى نفسه جزءًا لا يتجزأ من الأسرة. شاركيه خطط الأسرة أثناء حديثكِ معه، مثل: «سنذهب اليوم إلى بيت الجدة». فهذا يعزز لديه الشعور بالانتماء والأمان.') WHERE id = 'cb75068e-4a47-4582-8cce-0e1abcdf18e0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الحركة الجسدية: «الاستقلالية على الدرج». يستطيع طفلكِ الآن صعود الدرج بثقة، واضعًا قدمًا على كل درجة بالتناوب، مع الإمساك بيد واحدة فقط. وهذا يدل على أن مهاراته الحركية الكبرى قد تطورت جيدًا. يكفي أن تبقي إلى جانبه وتقدمي له الدعم المعنوي.') WHERE id = 'c4f997be-e1af-4807-8fcf-d6afc3087197';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الكلام: «تأليف القصص». يستطيع طفلكِ الآن ابتكار قصص بسيطة بالنظر إلى الصور. فالجمل المتسلسلة مثل: «جاءت القطة، وشربت الحليب، ثم نامت» تجمع بين الذاكرة والخيال. قدّمي له كتبًا تحتوي على صور شيقة، واسأليه: «ماذا يحدث هنا؟». فهذا يشعل تفكيره الإبداعي.') WHERE id = '8a750939-d6ea-4327-ae01-fe2febf3e561';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: «الوضع بدقة». يستطيع طفلكِ الآن وضع مجسمات الألعاب الصغيرة في أماكنها أو تمرير الخيط عبر الخرز بأخطاء أقل. وتزداد حساسية أطراف أصابعه خلال هذه المرحلة. قدّمي له ألعابًا تتضمن أشياء صغيرة ذات ملمس متنوع، مع الإشراف عليه.') WHERE id = 'b81dacf6-43a1-47b5-b976-b04cc72c15b8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إصرار "ارتداء الملابس باستقلالية". يصرّ طفلكِ الآن على ارتداء قمصانه الخالية من الأزرار أو سرواله بنفسه. عندما يقول: "سأفعل ذلك بنفسي!"، امنحيه الوقت الكافي. فمحاولات الاستقلال هذه هي أقوى أساس لثقته بنفسه وتحمله المسؤولية الشخصية في المستقبل. احتفي بنجاحاته الصغيرة بقولكِ: "أرأيت؟ لقد فعلتها بمفردك!".') WHERE id = '5b370f66-ddd3-45df-8b72-80322e3b54c6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"قواعد اللباقة" في السلوك الاجتماعي. لم يعد طفلكِ يكرر عبارات مثل "من فضلك" و"شكرًا جزيلًا" و"أرجوك" فحسب، بل بدأ يستخدمها بقصد وفي مواضعها المناسبة. سلوككِ المهذب هو أفضل قدوة له. امدحي هذه التصرفات لديه لترسّخي آداب التواصل.') WHERE id = 'fb257145-0061-4b1c-8bd6-415874362912';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"ظروف الزمان" في التطور المعرفي. يبدأ طفلكِ باستخدام كلمات مثل "لاحقًا" و"بعد قليل" و"الآن" في مواضعها الصحيحة تمامًا. عندما تقولين: "سآتي بعد قليل"، فإنه يفهم أن بعض الوقت سيمضي. وهذا يعزز قدرته على الانتظار وتنظيم ذاته. استخدمي هذه الكلمات كثيرًا ضمن روتينكما اليومي.') WHERE id = '2d2fd92a-c54e-421a-b575-674a4add6e64';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التنسيق الحركي: "ركل الكرة نحو الهدف". لم يعد طفلكِ يركل الكرة عشوائيًا، بل يحاول توجيهها في اتجاه محدد، كأن يمررها بين لعبتين مثلًا. وهذا دليل على عمل التناسق بين اليد والعين وبين القدم والعين بشكل متزامن. نظّمي معه في المنزل بطولة "كرة قدم مصغّرة".') WHERE id = '4639b4f7-f878-413c-9ed9-f5c72fb301e3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الأسئلة المجرّدة" في تطور اللغة. قد يطرح طفلكِ أسئلة مثل: "من أين تأتي الغيوم؟" و"إلى أين ذهب القمر؟". عند الإجابة، وازني بين الخيال والمعلومات الواقعية، كأن تقولي: "تأتي الغيوم من بعيد وتحمل إلينا المطر". توسّع هذه الحوارات نظرته إلى العالم وشغفه بالتعلم بدرجة مذهلة.') WHERE id = 'bc37e242-95d7-44a8-8a20-2eacd0325914';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: أصبح طفلكِ الآن أكثر قدرة على تحمّل الإخفاق. فعندما تسقط مكعباته، لا يبكي فورًا، بل يستطيع أن يقول: "سأبنيها من جديد". ادعمي فيه روح المثابرة هذه. لم يتبقَّ على بلوغه 1000 يوم سوى 10 أيام! لقد قطعتِ هذه الرحلة الرائعة يدًا بيد مع طفلكِ. أحسنتِ!') WHERE id = 'a124273d-b639-4f61-aa7d-a589a92dd962';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بكِ في الأيام العشرة الأخيرة من ماراثون الألف يوم! أصبح طفلكِ الآن مدركًا تمامًا لذاته ويتصرف بشعور «لقد كبرت». استعرضي الأيام الـ991 التي قضيتِها معه؛ خطوته الأولى، وكلمته الأولى... لقد أصبح الآن فردًا مكتملًا جسديًا وذهنيًا. حبكِ هو الأساس الأكثر متانة لهذا البناء.') WHERE id = 'b5b8d286-f3be-458e-9da0-f739ba54a527';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«المناورات المعقدة» في التطور البدني. أصبح طفلكِ الآن قادرًا على التوقف فجأة أثناء الركض، أو تغيير اتجاهه، أو القفز فوق عائق. يدل ذلك على نضج جهازه العصبي وتناسق عضلاته. واصلي ممارسة الألعاب الحركية معه في الهواء الطلق.') WHERE id = '40ef129f-5b1b-4e7a-8bf0-78a6953a2417';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الحوار المنطقي» في تطور الكلام. أصبح طفلكِ الآن قادرًا على مناقشتكِ قائلًا: «لا أريد النوم لأنني لم أنتهِ من اللعب». هذا ليس مجرد عناد، بل هو قدرة على تبرير رأيه. عززي لديه الاحترام المتبادل من خلال تقديم تفسيرات منطقية مثل: «أنت محق، لكن الجو سيُظلم بعد قليل».') WHERE id = 'b9aae384-2df5-41c3-b46c-488d1b02a6ae';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الرسومات الإبداعية» في المهارات الحركية الدقيقة. لم يعد طفلكِ يرسم مجرد خطوط، بل يحاول رسم «إنسان» (عادةً على شكل شخص بسيط مكوّن من دائرة وخطوط)، أو «منزل»، أو «شمس». تمثل هذه الرسومات انتقال الرموز الموجودة في دماغه إلى الورق. احرصي على الاحتفاظ بهذه «الأعمال الفنية».') WHERE id = '28f47857-a1db-40ef-a9e2-553a55c8a841';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الاهتمام بالآخرين» في السلوك الاجتماعي. عندما يلاحظ طفلكِ أنكِ متعبة أو يرى أحد أصدقائه يبكي، يقترب منه ويحاول مواساته. وهذا من أرقى مظاهر الذكاء العاطفي (EQ). إن قلبه النقي مرآة للحنان الذي منحتِه إياه.') WHERE id = 'ad204761-7be7-4b3d-9813-46b7f3ddfbf5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الربط بين العدد والرمز» في التطور الإدراكي. أصبح طفلكِ الآن قادرًا على التعرّف بصريًا إلى رموز الأعداد (1، 2، 3) وربطها بالكميات. أعطيه مهام صغيرة مثل: «توجد هنا 3 تفاحات، أرني الرقم ''3''». تُعد هذه إحدى أكثر مراحل الاستعداد لمرحلة ما قبل المدرسة متعةً وأهميةً.') WHERE id = '277f876e-8768-4106-82f9-f67a9aa287de';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الحركي: «الاستقلالية في أوجها». أصبح طفلكِ الآن شجاعًا بما يكفي لركوب الدراجة، أو التأرجح وحده، أو الانزلاق من الزحاليق العالية. احرصي على سلامته في أثناء مغامراته، لكن لا تعيقيه. فثقته بقدراته تقوّي شخصيته.') WHERE id = '27b9a0e5-6b83-4460-8a15-0df9cab1dff0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«فهم عمق الزمن» في الكلام. بدأ طفلكِ الآن يدرك موقعه على الخط الزمني من خلال صياغة جمل مثل: «عندما كنت رضيعًا...» أو «عندما أكبر...». أريه صور طفولته المبكرة، وحدّثيه عن مدى تطوره منذ ذلك الحين. فهذا يساعده على تكوين تاريخه الشخصي ووعيه بهويته الذاتية (self-identity) بصورة متكاملة.') WHERE id = '3439184d-c674-4353-b4d8-24d477730a8a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بقي يوم واحد على الختام الكبير! انظري اليوم إلى ما حققتِه وافتخري بنفسكِ. لقد اكتمل 80% من نمو دماغ طفلكِ خلال أول 1000 يوم. علّمتِه الكلام والحب والثقة واستكشاف العالم. وغدًا تبدأ صفحة جديدة ومشرقة في حياته. أنتِ أم رائعة!') WHERE id = '6f7bcab0-f835-4b32-baa1-c34bfb4bf5a9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا! لقد أتممتما أول 1000 يوم بنجاح! 🌟 إنها أهم مرحلة من مراحل نمو الإنسان. لقد تجاوز طفلكِ الآن مرحلة الرضاعة وأصبح بطلًا صغيرًا مستعدًا لاستكشاف العالم. وبصفتنا عائلة Anacan، كنا إلى جانبكِ في كل خطوة، ونشارككِ هذا الإنجاز. اليوم احتفال كبير، إنه يوم انتصاركِ وانتصار طفلكِ!') WHERE id = 'df76a0b6-eddc-484e-b6f0-24845f214e66';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إنه يومنا الأول بعد ماراثون 1000 يوم الكبير! يدخل طفلكِ الآن عامه 4. وفي هذه المرحلة، تكتسب أسئلة «لماذا؟» بُعدًا جديدًا؛ فهو لا يبحث عن المعلومات فحسب، بل يحاول فهم الروابط المنطقية بين الأحداث. أجيبيه بصبر، فهذه الأسئلة ترسي أسس نموه الفكري.') WHERE id = '458401f2-485d-418a-8b89-143f552eb250';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«المناورات الحركية» في النمو البدني. أصبح طفلكِ الآن قادرًا على تغيير اتجاهه بحدة في أثناء الركض أو تجاوز العوائق بسرعة. وهذا دليل على بلوغ قدرته على التحكم في جسمه مستوى متقدمًا. نظّمي له سباقات صغيرة لتجاوز العوائق في فناء المنزل.') WHERE id = '1242feeb-5e2f-4d55-aa93-952aedfbe568';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الأزمنة المركبة» في الكلام. بدأ الطفل يُدخل في كلامه صيغًا زمنية مركبة مثل «كنتُ قد فعلتُ» و«سأفعل». ناقشي معه أحداث الماضي: «ماذا حدث عندما ذهبنا إلى منزل جدتك بالأمس؟». فهذا يعزّز ذاكرته ودقته النحوية في الكلام.') WHERE id = '5e199122-f8a1-4104-82fd-2c91af60c12f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«محاولات التناظر» في المهارات الحركية الدقيقة. يحاول الطفل طيّ الورقة من منتصفها تمامًا، أو وضع التفاصيل في رسوماته بدقة أكبر، مثل رسم عينين وذراعين للشخص. سلّطي الضوء على انتباهه البصري هذا بقولكِ: «انظر، لقد رسمتَ كلتا الذراعين!».') WHERE id = '9dfe80c5-1c6a-4ec4-852c-1433440d5b52';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«استيعاب القواعد» في السلوك الاجتماعي. أصبح الطفل يتذكر بعض القواعد من دون أن تذكّريه بها، فيسأل مثلًا: «هل أغسل يديّ قبل الأكل؟». وهذه بداية تحوّل الانضباط الخارجي إلى انضباط ذاتي. احرصي على الثناء على تحمّله المسؤولية باستقلالية؛ فهذه خطوة كبيرة في بناء شخصيته.') WHERE id = '5760ce33-81a1-4f8c-a7a0-f30c320a688a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«أنا وصديقي». لم يعد الطفل يكتفي باللعب إلى جوار الأطفال الآخرين، بل بدأ يشاركهم اللعب وفق سيناريو مشترك، مثل: «أنتِ الأم وأنا الطفل». وهذه أولى تجاربه الجادة في التعاون الاجتماعي وتوزيع الأدوار.') WHERE id = 'e6c24a0b-d760-47b5-90b8-f6d05b42625b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«إتقان التصنيف» في التطور المعرفي. يستطيع الطفل تصنيف الأشياء وفق خاصيتين في الوقت نفسه، مثل: «الأشياء الحمراء والصغيرة معًا». أعطيه ألعابًا متنوعة وقولي له: «اجمع كل السيارات الصغيرة هنا». فهذا يطوّر نظام الفرز المنطقي في دماغه.') WHERE id = '083c5f31-3fe0-44d9-b65b-c4b92bb36ae4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «الاستقلال في ركوب الدراجة ثلاثية العجلات». أصبح الطفل قادرًا على توجيه المقود وتحريك الدوّاسات بإيقاع منتظم في الوقت نفسه. وهذا تناغم رائع بين تناسق الجزء السفلي والجزء العلوي من الجسم. لقد حان الوقت لجعل النزهات في الحديقة أكثر نشاطًا.') WHERE id = 'e81ab935-f108-46cd-a88f-e53e09ed924f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«ظروف المكان» في الكلام. أصبح طفلكِ يفهم مفاهيم «بجانبه» و«خلفه» و«تحته» و«فوقه» بدقة تامة ويستخدمها. فإذا قال: «الكرة تحت الأريكة»، فهذا يعني أن قدرته على تحديد الاتجاهات المكانية قد اكتملت. ساعديه على صقل هذه المفاهيم أكثر من خلال لعب الغميضة معه.') WHERE id = '64ca65c7-1a28-48d4-beca-77b3f217471c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: «اختبار الصبر». أصبح طفلكِ يدرك أن عليه الانتظار بضع دقائق للحصول على شيء يريده، ولا يبدأ بالبكاء فورًا. في هذه اللحظات قولي له: «شكرًا جزيلًا لأنك انتظرت، فهذا دليل على أنك أصبحت كبيرًا». أنتِ رفيقة درب رائعة!') WHERE id = 'd29729c2-dd1d-4552-9d6e-3a6745ad9680';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ يصف العالم من خلال الجمع بين الألوان والأشكال. فإذا قال: «أعطيني تلك القطعة الصفراء المربعة»، فهذا يدل على أن دماغه يعالج عدة خصائص في الوقت نفسه. ادعمي هذه المهارة في الحياة اليومية بمهام صغيرة (مثل: «اعثر على جواربك الزرقاء»).') WHERE id = '6e9a3917-235a-4638-821e-7544b6f6fd44';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التوازن الديناميكي» في النمو البدني. أصبح طفلكِ قادرًا على الوقوف على ساق واحدة لمدة تصل إلى 5 ثوانٍ. وهذا يدل على تقوّي الجهاز الدهليزي (مركز التوازن) وعضلات الساقين. العبي معه لعبة «طائر اللقلق» لتعرفا من يستطيع الوقوف مدة أطول.') WHERE id = 'bf8d8f80-94a0-4e9e-beaa-a9027d0e8ae4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«علاقات السبب والنتيجة» في الكلام. بدأ طفلكِ يفهم الجمل من نوع «إذا... فـ...». فعندما تقولين له: «إذا رتّبت ألعابك، يمكننا مشاهدة الرسوم المتحركة»، فإنه يفهم الشرط. وهذه خطوة مهمة في تنمية التفكير المنطقي والانضباط الذاتي (self-discipline).') WHERE id = 'b1f57847-eeec-4119-b2fc-2905b91fb26b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التجارب الأولى مع المقص» ضمن المهارات الحركية الدقيقة. أصبح طفلكِ يُبدي اهتمامًا بقص الورق على طول خط مستقيم (باستخدام مقص آمن للأطفال). تسهم هذه الحركة في تطوير التناسق بين اليد والعين والمهارات الحركية الدقيقة للأصابع بدرجة كبيرة. لا تتركيه دون مراقبة، ولكن لا تقيّدي استقلاليته.') WHERE id = 'bc3bff7e-368e-485f-8abd-ee144e6a6477';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: "رفقاء اللعب الخياليون". أصبح طفلكِ يتحدث بصوت مرتفع حتى عندما يلعب بمفرده، ويسند أدوارًا إلى ألعابه. يُسمّى هذا "الكلام المتمركز حول الذات"، وهو يساعده على تنظيم أفعاله بالكلمات. ومن خلال الاستماع إلى هذه "المونولوجات"، يمكنكِ فهم ما يدور في عالمه الداخلي.') WHERE id = '9f4b387f-964e-4bb9-856d-1ac035b357f4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الاختيار المستقل: اتخاذ القرار". أصبح طفلكِ يعرف بوضوح ما يريد تناوله أو اللعبة التي يرغب في لعبها. قدّمي له كل يوم خيارين: "هل تريد تفاحة أم موزة؟". يمنحه ذلك شعورًا بالتحكم في حياته ويعزز ثقته بنفسه.') WHERE id = '7022c99f-3026-41d3-8d24-5d2da8ff257d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: "ثبات الحجم والكمية". قد يظن طفلكِ حتى الآن أن كمية الماء في الوعاء الطويل والضيق أكبر من كميته في الوعاء العريض. وهذه حالة طبيعية تتوافق مع مرحلة "بياجيه". العبي معه ألعاب الماء واسكبا الماء في أوعية مختلفة. يساعده ذلك على تسريع فهمه للمنطق من خلال التجربة.') WHERE id = '63894550-7c88-4d80-827d-abe697cce597';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "القفز إلى الأمام بكلتا القدمين". أصبح طفلكِ قادرًا على القفز فوق العوائق (مثل حبل موضوع على الأرض) بكلتا قدميه في الوقت نفسه. يتطلب ذلك تناسق الجسم بالكامل والقوة الانفجارية. أنشئي له مسارات صغيرة وآمنة تضم بعض العوائق.') WHERE id = 'cab49b1b-46a8-46fe-9575-6cef46f13add';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور اللغة: "المفهوم المجرد للوقت". أصبح طفلكِ يدرك الفروق بين "الصباح" و"الظهيرة" و"المساء" من خلال الروتين اليومي. فعندما تقولين: "عندما يعود الأب مساءً..."، يمكنه أن يتصور هذه الفترة من اليوم في ذهنه. يساعد التزامكِ بروتينكما اليومي على ربط هذا المفهوم الزمني لديه بالشعور بالأمان.') WHERE id = '50a38f0a-e830-42a7-9b23-0d529496ee7f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'النضج العاطفي: معنى كلمة "آسف". أصبح طفلكِ يفهم الأهمية الاجتماعية للاعتذار عندما يؤذي شخصًا عن قصد أو من دون قصد. كوني دائمًا قدوة له؛ فعندما تخطئين، اعتذري منه كي ينظر إلى هذا السلوك بوصفه قوة لا ضعفًا.') WHERE id = 'f7b6ee04-7015-4382-abaa-03462e452408';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ قادرًا على تأليف قصص بسيطة بالنظر إلى الصور. فالجمل المتسلسلة مثل: «ذهب الدب إلى الغابة، وكان جائعًا فأكل العسل» تدل على أنه يفهم التسلسل المنطقي. قدّمي له كتبًا تحتوي على صور ممتعة واسأليه: «برأيك، ماذا سيحدث بعد ذلك؟». فهذا ينمّي خياله الإبداعي إلى أقصى حد.') WHERE id = '5b5539ed-db72-44da-bf5f-8b147bfb9b43';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في مجال الحركة الجسدية، تأتي مرحلة «إتقان صعود الدرج ونزوله». أصبح طفلكِ ينزل الدرج بثقة، واضعًا قدمًا على كل درجة بالتناوب، وممسكًا بيد واحدة فقط أو من دون مساعدة. وهذا يدل على نضج مهاراته الحركية الكبرى. يكفي أن تبقي إلى جانبه وتقدّمي له الدعم المعنوي.') WHERE id = 'e1ab27cc-4713-481c-b52f-32935f62d3d2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام، تظهر «سلسلة الأسئلة والأجوبة». لم يعد طفلكِ يجيب عن أسئلتكِ بمجرد «نعم/لا»، بل أصبح يجيب بجمل كاملة. فقد يقدّم إجابة مفصّلة عن سؤال: «مع مَن لعبت اليوم في الحديقة؟». وعندما تتحاورين معه، حفّزي كلامه بطرح أسئلة متابعة مثل: «ما لونه؟» و«ماذا فعلتم؟».') WHERE id = '7d186d1a-0812-440c-b07e-ee9ed0da127d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة، تأتي مرحلة «التلوين بدقة أكبر». أصبح طفلكِ يدرك حدود الأشكال الصغيرة أيضًا، ويحاول ألّا يتجاوزها كثيرًا أثناء التلوين. وهذا تقدّم كبير في قدرته على التحكم في عضلات اليد. وفّري له أقلام تلوين بسماكات مختلفة لتتيحي له فرصة التجربة.') WHERE id = 'a7b0a891-2fdb-4521-b60b-98a992dcf545';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«ارتداء الملابس باستقلالية: السحّاب والأزرار». أصبح طفلكِ ماهرًا في فك الأزرار الكبيرة ورفع السحّاب بعد أن تساعديه على تثبيت بدايته. قولي له: «هيا، جرّب بنفسك»، وانتظري بصبر. إن قدرته على ارتداء ملابسه بنفسه تعزّز لديه بدرجة كبيرة شعوره بأنه «قادر على فعل ذلك»، كما تعزّز ثقته بنفسه.') WHERE id = '9893a146-5d99-48e6-ae6a-1f46520795f5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي، يظهر «فهم منطق المشاركة». أصبح طفلكِ يحاول ألّا ينتزع اللعبة فورًا من يد طفل آخر، بل يقول: «أعطني» وينتظر. وهذا يدل على ترسّخ مهارة التنظيم الذاتي لديه. وعندما تلاحظين هذا السلوك الصبور، احرصي على مدحه بقولكِ: «شكرًا جزيلًا لأنك انتظرت دورك».') WHERE id = '71a96327-cfe2-4ab5-bb79-d332a1ff5de4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«العام والخاص» في التطور المعرفي. أصبح طفلكِ يدرك أن التفاح والكمثرى والموز كلها «فواكه». اعرضي عليه مجموعة متنوعة من الأشياء واسأليه: «ماذا نسمّي كل هذه الأشياء مجتمعة؟». يساعده التفكير وفق الفئات على تنظيم نظام تخزين المعلومات في دماغه بشكل أفضل.') WHERE id = 'f440da85-66a5-444d-9191-5dceb0b51d20';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الحركي: «رمي الكرة من فوق الكتف». لم يعد طفلكِ يُسقط الكرة على الأرض فحسب، بل أصبح قادرًا على رميها إلى الأمام من فوق كتفه نحو هدف محدد. يتطلب ذلك تناسق الجسم بأكمله. العبي معه في الحديقة ألعاب «التصويب نحو الهدف».') WHERE id = '5a9ea9e5-b06c-4aa9-b965-a6664f7442e8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«المكان والاتجاه» في تطور الكلام. رغم أن طفلكِ لم يتقن بعد مفهومي «اليمين» و«اليسار» تمامًا، فإنه ينفذ بدقة تعليمات «إلى الأمام» و«إلى الخلف» و«إلى الأعلى» و«إلى الأسفل». العبي معه «لعبة الروبوت»: «خطوتان إلى الأمام، وخطوة واحدة إلى الخلف!». هذه اللعبة ممتعة، كما أنها تعزز قدرته على تحديد الاتجاهات في المكان.') WHERE id = '6ef1e101-45d4-451a-8710-b32b9878cd2e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: «التعامل مع الإخفاق». لم يعد طفلكِ يبكي فورًا عندما تنهار مكعباته، بل أصبح قادرًا على أن يقول: «سأبنيها من جديد». ادعمي فيه روح المثابرة هذه. لقد اجتزنا 1030 يومًا، وأصبح طفلكِ الآن بطلًا صغيرًا!') WHERE id = '1293c75f-beda-4513-88cc-b7951ec10777';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ قادرًا على تصنيف الأشياء وفق خاصيتين في الوقت نفسه، مثل اللون والشكل معًا. إذا كان يستطيع تنفيذ طلبكِ عندما تقولين له: «أعطني جميع السيارات الحمراء الصغيرة»، فهذا يمثل مستوى جديدًا في تطوره المعرفي. كلّفيه بمثل هذه المهام البسيطة التي تتطلب «الاختيار» أثناء الأعمال المنزلية اليومية.') WHERE id = 'fa3d103a-9bc8-44ef-b8d5-cab5337e7b60';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«القفز نحو الهدف» في التطور الحركي. أصبح طفلكِ يحاول القفز إلى وسط دائرة مرسومة على الأرض أو هدف ملوّن. يساعد ذلك على تحسين توازنه وقدرته على تقدير المسافات في المكان. العبي معه في الحديقة لعبة «القفز من حجر إلى آخر».') WHERE id = '4bbc0ebb-e4d4-4fb1-9a60-923e8fae76b3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«توسّع فهم الكلمات المتضادة» في تطور النطق. أصبح طفلكِ يفهم الآن أوجه التضاد المجرّدة، مثل «سريع-بطيء» و«مظلم-مضيء» و«فارغ-ممتلئ». أريه كوبًا فارغًا وآخر ممتلئًا واسأليه عن الفرق بينهما. يساعده ذلك على تعزيز قدرته على تحليل العالم من حوله من خلال المقارنة.') WHERE id = 'a89f9de3-ed84-4cfa-95a8-cf4c5d345de7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«إتقان الأحجيات» في المهارات الحركية الدقيقة. أصبح طفلكِ الآن قادرًا على إكمال أحجيات معقدة مكوّنة من 10-12 قطعة، إذ يستطيع التمييز بين حواف الصورة ووسطها. يعزز ذلك ذاكرته البصرية وقدرة أصابعه على أداء الحركات الدقيقة. عندما يتعذّر عليه إكمالها، قدّمي له تلميحات بنبرة هادئة.') WHERE id = '81c4bfcb-e5df-4929-b621-91e622f18ac6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التنظيف والمساعدة باستقلالية». أصبح طفلكِ الآن متحمسًا جدًا للمشاركة في مهام مثل حمل طبقه ومسح الفتات عند ترتيب المائدة. وفّري له أدوات تنظيف مناسبة لطوله. يعزز ذلك شعوره بالمسؤولية والانتماء داخل الأسرة. ورؤية نتيجة جهده تجعله سعيدًا جدًا.') WHERE id = '9ef3f34d-a63f-4f49-9005-c854d4303909';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«القواعد والحدود» في السلوك الاجتماعي. أصبح طفلكِ الآن يفهم بصورة أفضل قليلًا المنطق الكامن وراء كلمة «لا»، لكنه لا يزال يحب اختبار الحدود. يمنحه صبركِ وثباتكِ شعورًا بالأمان. حاولي تطبيق القواعد بالطريقة نفسها دائمًا.') WHERE id = 'c4d24c3e-4601-4235-8cdc-f39b3aa35149';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الأعداد الترتيبية» في التطور المعرفي. أصبح طفلكِ الآن يفهم مفاهيم «الأول» و«الثاني» و«الأخير». رتّبي السيارات في صف واسأليه: «أي سيارة هي الأولى؟». ينمّي ذلك فهمه للتسلسل والتفكير الرياضي. كما أن قولكِ له في السباقات: «لقد وصلتَ أولًا!» يمنحه حافزًا كبيرًا.') WHERE id = 'b0d3eed0-e639-4528-9c81-8601b70e54bd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الحركي: «المشي إلى الخلف وإلى الجانب». أصبح طفلكِ الآن قادرًا على التحرك بمرونة في اتجاهات مختلفة. العبي معه «لعبة المرآة»: خذي خطوة إلى الجانب واجعليه يقلّدكِ. فهذا ممتع ويساعد أيضًا على الارتقاء بتناسق حركات جسمه إلى مستوى جديد.') WHERE id = 'da0e2216-17ef-49f2-83ad-1599f6a6e332';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: "التعمق في الأسئلة المجرّدة". قد يفاجئكِ طفلكِ بأسئلة مثل: "إلى أين تذهب الغيوم؟" و"لماذا تظهر النجوم ليلًا؟". وعندما تجيبين، حفّزي خياله أيضًا بسؤاله: "برأيك، ماذا تفعل النجوم الآن؟". فهذا يغذّي تفكيره الإبداعي.') WHERE id = '1f153d5c-5da7-4c69-b731-2dc34e06cb4f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: "متعة المشاركة". عندما يشارك طفلكِ لعبته أو حلواه طوعًا، فإنه يرى سعادتكِ بذلك ويرغب في تكراره. سلّطي الضوء على كرمه بعبارة: "شكرًا جزيلًا لأنك أسعدت صديقك". لقد أتممنا 1040 يومًا بنجاح — أنتِ أم رائعة!') WHERE id = '3c9e08eb-1969-4283-90ec-97d2de26fd19';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'ندخل الشهر الخامس والثلاثين! ينتقل طفلكِ الآن من تنفيذ المهام المكوّنة من "خطوتين" إلى المهام المكوّنة من "ثلاث خطوات". فإذا نفّذ طلبكِ: "خذ اللعبة، وضعها في الصندوق، ثم أغلق الغطاء" مع الحفاظ على الترتيب، فهذا إنجاز كبير لذاكرته العاملة (working memory). قدّمي له خلال اليوم مهام صغيرة ومنطقية ومتسلسلة لصقل هذه المهارة.') WHERE id = 'b4ed41fc-fc60-439e-82df-81e0242123d3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في النشاط البدني: "الجري السريع والمناورة". أصبح طفلكِ قادرًا على الالتفاف حول العائق الذي يراه أمامه أثناء الجري دون أن يخفّف سرعته. وهذا يدل على اكتمال تطور وعيه بوضعية جسمه (proprioception). نظّمي له في الحديقة سباقات "الجري مع العوائق" لتوجيه طاقته نحو نشاط مفيد.') WHERE id = '140764ec-2a00-4bc6-b514-5e093357430f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: "درجات المقارنة". أصبح طفلكِ يستخدم تعبيرات مثل "أكبر" و"الأصغر" و"لذيذ جدًا" في مواضعها الصحيحة. تحدّثي معه وقارني بين الأشياء، مثلًا: "هل هذه التفاحة أحلى أم الأخرى؟". إن إتقان درجات الصفات هذه يثري لغته الوصفية ويزيد دقة تعبيره عن أفكاره.') WHERE id = '5868f762-ea68-431f-855d-54c5a04efe50';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: "النحت". عندما يلعب طفلكِ بالصلصال أو الرمل الحركي، لم يعد يكتفي بالضغط عليهما، بل يصنع منهما أشكالًا يمكن تمييزها مثل "كرة" أو "ثعبان" أو "رغيف خبز". وهذا تمرين ممتاز لتنمية التفكير الإبداعي وتقوية العضلات الدقيقة في أطراف الأصابع.') WHERE id = '060a9ae6-7e66-446f-800a-a74eb2d502d9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح الطفل الآن يدرك تسلسل "قبل" و"بعد" بعمق أكبر. فعندما تقولين له: "ارتدِ ملابسك، ثم نخرج"، يفهم أن الفعل الثاني مكافأة. وهذه هي البذور الأولى لتنمية الصبر والقدرة على التخطيط لديه. ذكّريه بهذه التسلسلات كثيرًا خلال الروتين اليومي.') WHERE id = '2add65f7-d33c-4b48-a1e7-f388a5549421';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور البدني، تظهر "مهارة التسلق". أصبح الطفل الآن يصعد سلالم الحديقة أو الأماكن المرتفعة الآمنة في المنزل بثقة أكبر. ويتطلب ذلك عمل عضلات الذراعين والساقين بتناسق. ابقي دائمًا بالقرب منه، لكن أتيحي له فرصة اختبار قدراته بنفسه.') WHERE id = '25d5eedf-59a2-4e4e-8131-39a811d36fe6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام، تظهر "الروابط المنطقية". أصبح الطفل الآن يربط بين حدثين في جملة واحدة، مثل: "الجو بارد، ارتدِ السترة". وهذا يدل على أنه لا يقلّد فحسب، بل يفكر أيضًا. أكّدي صحة استنتاجاته المنطقية بقولكِ: "نعم، أنت محق"، حتى يتحمس أكثر للتعبير عن أفكاره.') WHERE id = '90469c76-8fc0-41db-a7e9-3862f12f4d6b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة، يظهر "التعامل مع الورق". قد يبدأ الطفل الآن بإبداء اهتمام بطيّ الورق أو قصّه بطريقة بسيطة (باستخدام مقص كبير مخصص للأطفال وتحت الإشراف). تنقل هذه الحركات قدرته على التحكم في عضلات أصابعه إلى مستوى جديد. هيئي له بيئة مناسبة للعمل بالورق الملون.') WHERE id = '8f149cc4-a06e-4928-a8cb-2b953480c3af';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي، تصبح "ألعاب تمثيل الأدوار أكثر تعقيدًا". يتقمص الطفل الآن دور "الطبيب" أو "الطاهي" أو "السائق". ومن خلال هذه الألعاب، يتعرف إلى مهام الأشخاص من حوله وينمّي قدرته على التعاطف. شاركيه هذه الألعاب وتصرّفي وفقًا "للدور" الذي يمنحكِ إياه.') WHERE id = 'c9bd395e-c3c2-46e2-abf3-1f924d619000';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مهارة "النظافة باستقلالية". أصبح الطفل الآن قادرًا إلى حد كبير على غسل يديه بالصابون وشطفهما بمفرده. ومن المهم جدًا ترسيخ عادات النظافة في هذا العمر. وفّري له درجة آمنة مناسبة لطوله ليتمكن من الاستمتاع بهذه العملية.') WHERE id = 'dd1b7d3a-2552-45df-81c5-cf8e1914b882';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"ارتداء الملابس باستقلالية: التمييز بين الوجه الصحيح والمقلوب". يحاول طفلكِ الآن التمييز بين الوجه الصحيح والمقلوب للقميص أو البنطال، وبين الحذاء الأيمن والأيسر (حتى لو أخطأ أحيانًا). قدّمي له تلميحات بسيطة: "انظر، الجهة التي تحمل الرسمة تكون في الأمام". يساعده ذلك على التركيز على التفاصيل وتحسين مهارات العناية بنفسه.') WHERE id = 'a1a89564-b6bb-483a-bd10-bb44b24484a4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"روح الفريق" في السلوك الاجتماعي. أصبح طفلكِ قادرًا الآن على اللعب مع أطفال آخرين لتحقيق هدف مشترك (مثل بناء قلعة كبيرة). وهذا انتقال من "اللعب المتوازي" إلى "اللعب التعاوني". راقبي كيفية تواصله وتفاهمه مع الأطفال الآخرين، وساعديه في المواقف الصعبة على بناء "جسر" اجتماعي معهم.') WHERE id = '999ddf88-03eb-4dd0-856d-79ce3e7385df';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الربط بين الرقم والكمية" في التطور المعرفي. يعرف طفلكِ العد من 1 إلى 5، وأصبح الآن قادرًا على رؤية الرقم "3" ثم اختيار 3 ألعاب ووضعها جانبًا. تُعد هذه من أهم مراحل تطور التفكير الرياضي. عزّزي هذا الربط في الحياة اليومية من خلال مهام مثل: "أعطني ملعقتين".') WHERE id = '8193ed91-5f04-4955-a4b1-522d5a941870';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "التقاط الكرة الملقاة من أعلى". يحاول طفلكِ الآن التقاط كرة كبيرة تُرمى نحوه ببطء بكلتا يديه. تتطلب هذه الحركة التناسق بين اليد والعين، إلى جانب سرعة الاستجابة. العبي معه لعبة رمي الكرة والتقاطها من مسافة قريبة.') WHERE id = '575cf871-23de-446e-8398-4dd4c0ff6773';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"ذروة الأسئلة المجرّدة" في تطور الكلام. يطرح طفلكِ الآن أسئلة عن الوجود والظواهر الطبيعية، مثل: "لماذا تهب الرياح؟" و"إلى أين تذهب الشمس لتنام؟". عند الإجابة، أضيفي لمسة من الخيال أيضًا: "لقد تعبت الشمس وذهبت لترتاح حتى توقظنا من جديد غدًا". فهذا يغذّي نظرته إلى العالم وشغفه بالتعلم.') WHERE id = 'fdfb7732-94cf-4e6c-8519-4e6877b4ad89';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'النضج العاطفي: "الإقرار بمشاعر الآخرين". عندما يلاحظ طفلكِ الآن أنكِ متعبة أو أن طفلًا آخر قد تأذى، يسأل: "ماذا حدث؟" ويحاول مواساته. وهذا يدل على أنه ينمو ليصبح شخصًا عطوفًا. أنتِ أم رائعة!') WHERE id = '9721a15c-607b-4236-9999-231bdd0b4e99';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: «العثور على العنصر المختلف». أصبح طفلكِ الآن قادرًا على تمييز العنصر المختلف بصريًا ضمن مجموعة من الأشياء، مثل تفاحة بين سيارات. وهذا يصقل قدرته على التحليل. نظّمي له في المنزل ألعابًا بسيطة بعنوان «ما العنصر الزائد؟». إنها تهيئة ممتازة للمهام الرياضية والمنطقية في المستقبل.') WHERE id = 'f8163db2-8f81-44fa-bc05-1057d8b42f15';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «محاولات الوقوف على قدم واحدة». أصبح طفلكِ الآن يحاول رفع إحدى قدميه عن الأرض والحفاظ على توازنه، ولو لبضع ثوانٍ فقط. وهذا مهم ليتعرّف جسمه إلى مركز ثقله. العبي معه «لعبة اللقلق»، وتحقّقا ممن يستطيع الوقوف مدة أطول.') WHERE id = '0dbea1ae-3808-4d99-b129-68ed1447a173';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: «التعبير عن المشاعر». أصبح طفلكِ الآن قادرًا على التعبير بالكلمات عن شعوره بالحزن أو الفرح أو الخوف، فيقول مثلًا: «لقد خفت» أو «أنا سعيد». وتسمية المشاعر هي أساس الذكاء العاطفي لدى الطفل. عندما يعبّر عن مشاعره، أنصتي إليه وأكّدي له تفهّمكِ لمشاعره بقولكِ: «نعم، أنا أفهمك».') WHERE id = '384f5938-24c1-4dc2-8691-403780565471';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قوة الخيال: «التفكير الرمزي». قد يتخيّل طفلكِ عصًا على أنها «حصان» ويركض بها كأنه يمتطيه. وهذه هي القدرة على فهم أن شيئًا ما يمكن أن يمثّل شيئًا آخر. تُعد هذه المهارة مهمة جدًا لتعلّم القراءة والرياضيات مستقبلًا، إذ تساعده على فهم الرموز. أنتِ مرشدة رائعة!') WHERE id = '94697180-1105-4fe0-9d68-ffdaab53705e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ الآن يستخدم ضمائر «أنا» و«أنت» و«نحن» في مواضعها الصحيحة. وعندما يقول: «هل نتناول الطعام الآن؟»، يشعر بأنه فرد فاعل في الأسرة. عند التحدث معه، أشركيه في خططكِ وقولي له مثلًا: «تعالَ، لنُعِدّ المائدة معًا». فهذا يعزّز لديه الشعور بالانتماء والمسؤولية.') WHERE id = '38010093-f42b-4818-a3db-81219f590eee';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الحركة الجسدية: «الاستقلالية على الدرج». أصبح طفلكِ الآن يصعد الدرج بثقة، واضعًا قدمًا على كل درجة بالتناوب، مع الإمساك بيد واحدة فقط. وهذا يدل على نضج مهاراته الحركية الكبرى. يكفي أن تبقي بجانبه وتقدّمي له الدعم المعنوي.') WHERE id = '8503d4e9-2c78-4879-9d8c-ef7c6d2a467c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«بناء القصص» في تطور الكلام. أصبح طفلكِ قادرًا على ابتكار قصص بسيطة بالنظر إلى الصور. فالجمل المتسلسلة مثل: «جاءت القطة، وشربت الحليب، ثم نامت» تجمع بين ذاكرته وخياله. قدّمي له كتبًا تحتوي على صور شيقة واسأليه: «ماذا يحدث هنا؟». فهذا يشعل تفكيره الإبداعي.') WHERE id = 'ebe63eb5-d3b9-410d-8ddc-267b97751075';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الوضع الدقيق» ضمن المهارات الحركية الدقيقة. أصبح طفلكِ قادرًا على وضع مجسمات الألعاب الصغيرة في أماكنها أو تمرير الخيط في الخرز مع أخطاء أقل. وتزداد حساسية أطراف أصابعه في هذه المرحلة. قدّمي له ألعابًا تتضمن أشياء صغيرة ذات ملمس متنوع، مع الإشراف عليه.') WHERE id = '9acc3fd3-37ec-4b80-9709-ac31444a2801';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الإصرار على «ارتداء الملابس باستقلالية». أصبح طفلكِ يصرّ على ارتداء قمصانه الخالية من الأزرار أو سرواله بنفسه. وعندما يقول: «سأفعلها بنفسي!»، امنحيه الوقت الكافي. فمحاولات الاستقلال هذه هي أقوى أساس لثقته بنفسه وتحمله المسؤولية الشخصية مستقبلًا. واحتفي بنجاحاته الصغيرة بقولكِ: «انظر، لقد فعلتها بمفردك!».') WHERE id = '48d41fa6-6f48-4a84-a2b6-f82cae4ce209';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«قواعد اللباقة» في السلوك الاجتماعي. لم يعد طفلكِ يكرر كلمات مثل «من فضلك»، و«شكرًا جزيلًا»، و«أرجوك» فحسب، بل بدأ يستخدمها عن قصد وفي مواضعها المناسبة. إن تعاملكِ المهذب هو أفضل قدوة له. عززي آداب التواصل لديه بالثناء على هذه السلوكيات.') WHERE id = 'fe3ec85d-8b47-408d-a0ad-870b3b58db94';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«ظروف الزمان» في التطور المعرفي. يبدأ طفلكِ باستخدام كلمات مثل «لاحقًا»، و«بعد قليل»، و«الآن» في مواضعها الصحيحة تمامًا. فعندما تقولين: «سآتي بعد قليل»، يفهم أن بعض الوقت سيمضي. وهذا يعزز قدرته على الانتظار وتنظيم سلوكه. استخدمي هذه الكلمات كثيرًا ضمن روتينكما اليومي.') WHERE id = 'df8b2f32-9f00-4805-8e4c-c754c399be31';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «ركل الكرة نحو هدف». لم يعد طفلكِ يركل الكرة عشوائيًا، بل يحاول توجيهها في اتجاه محدد، كأن يمررها بين لعبتين مثلًا. وهذا يدل على عمل التناسق بين اليد والعين وبين القدم والعين بصورة متزامنة. نظّمي معه بطولة «كرة قدم مصغّرة» في المنزل.') WHERE id = '852439ac-fd00-4ba1-aa13-d519b9407d5f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يعد طفلكِ يرى نفسه مجرد "أنا"، بل شخصًا "يمتلك مهارات". ويصف نفسه بعبارات مثل: "أنا سريع في الركض" أو "أنا أجيد التلوين". ادعمي هذا التصور الإيجابي لذاته. انتبهي إلى الطريقة التي يصف بها نفسه؛ فهي صوت ثقته المستقبلية بنفسه.') WHERE id = '24b05457-5c55-4e7e-93bd-e8e2e24e7b8c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الشجاعة الجسدية: "التغلب على الخوف من المرتفعات". يرغب طفلكِ الآن في تجربة الزحاليق أو السلالم الأعلى في الحديقة. فقد أصبحت قدراته الجسدية منسجمة تمامًا مع فكرة "أستطيع فعل ذلك" الراسخة في ذهنه. ما عليكِ سوى الوقوف بجانبه بوصفكِ "شبكة أمان غير مرئية".') WHERE id = 'a48cb007-600a-438e-b8fd-ac64a32480ba';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: فلسفة سؤال "لماذا؟". لم يعد يقول "لماذا" لمجرد الحصول على إجابة، بل لمواصلة الحديث معكِ أيضًا. إذا قال مجددًا "لماذا؟" بعد انتهاء إجابتكِ، فأعيدي السؤال إليه: "وماذا تعتقد أنت؟". ستجعلكِ تفسيراته الخيالية تضحكين وتندهشين في آنٍ واحد.') WHERE id = 'a7f2070c-4631-4744-b176-d7bba5b19ea6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: "ولادة الرموز". أصبح طفلكِ يرسم الآن "أشكالًا مغلقة" على الورق. فقد تمثل الدائرة التي يرسمها الشمس أو الكرة أو حتى الأم. وهذه قمة التفكير التجريدي: إذ يمكن لرمز واحد أن يعبّر عن أشياء كثيرة. احرصي على الاحتفاظ بهذه "الأعمال الفنية" الأولى مع تدوين تاريخها.') WHERE id = '8291f627-bff8-4ae0-9fda-966d1f2e80ac';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"مختبِر الحدود". قد يتعمد طفلكِ فعل شيء طلبتِ منه ألّا يفعله، ثم يراقب رد فعلكِ. هذا لا يعني أنه "سيئ"، بل إنه يختبر حدودكِ العاطفية ومدى ثبات القواعد. إن حفاظكِ على هدوئكِ وحزمكِ يبعث إليه بأقوى رسالة للشعور بالأمان: "لا يزال العالم مستقرًا وآمنًا".') WHERE id = 'a9bf7bd3-b390-48c2-b220-67d40659de03';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الذكاء الاجتماعي: "قواعد اللعب". أصبح طفلكِ يفهم الآن ضرورة اتباع القواعد كي تستمر اللعبة. فعلى سبيل المثال، يعرف أن عليه إغماض عينيه عند لعب "الغميضة". وهذه أولى "عقوده الاجتماعية" داخل المجتمع. ابدئي بلعب ألعاب الطاولة ذات القواعد البسيطة معه.') WHERE id = '6de77e4c-02d9-4646-a638-e1f9881237a4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"القرارات المستقلة". أصبح طفلكِ يختار بحزم اللعبة التي يريد اللعب بها أو الكتاب الذي يريد قراءته. أتيحي له فرصة اتخاذ هذه الخيارات. فرؤيته أن اختياره يحظى بالاحترام تعزز ثقته بنفسه وتساعد على إثراء عالمه الداخلي.') WHERE id = '064446a8-f711-4f01-89fb-101964123929';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"انتظار الدور" في السلوك الاجتماعي. أصبح طفلكِ يدرك أنه لا يمكن للجميع استخدام الأرجوحة في الوقت نفسه. وقدرته على قول: "هو يتأرجح الآن، ثم يأتي دوري" تمثل خطوة كبيرة في تطور ذكائه الاجتماعي. احرصي على مدح صبره حتى يصبح هذا السلوك عادة لديه.') WHERE id = '9280edaf-2356-4dce-a273-2cd4a5d6fd57';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الترتيب والتصنيف" في التطور المعرفي. أصبح طفلكِ يصنف الأشياء ليس حسب لونها فحسب، بل حسب استخدامها أيضًا: "هذه أطعمة، وهذه ألعاب". أعطيه مجموعة من الأشياء المختلطة وقولي له: "اعثر على الأشياء التي تنتمي إلى المطبخ". يساعد ذلك على تنظيم المعلومات في دماغه.') WHERE id = '55b33de4-6e1b-4815-985d-641594c12f05';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "رمي الكرة من فوق الكتف". أصبح طفلكِ قادرًا على رمي الكرة إلى الأمام من مستوى الكتف، لا من الأسفل فحسب. يدل ذلك على أن عضلات ذراعه وكتفه قد أصبحت أقوى، وأنه بات قادرًا على التخطيط لمسار الحركة. العبي معه في الحديقة ألعابًا صغيرة تعتمد على "التصويب نحو الهدف".') WHERE id = 'eb04363a-ab4d-4a94-888d-e7e2e5211e9c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"دقة استخدام الضمائر" في الكلام. أصبح طفلكِ نادرًا ما يخلط بين ضمائر "أنا" و"أنت" و"هو" و"نحن". وهذا يعني أنه بات يفهم تمامًا مكانه في محيطه الاجتماعي وعلاقته بالآخرين. لا تترددي في استخدام جمل مركبة عند التحدث معه.') WHERE id = '4705908e-12af-4329-ab11-ab69b76d1be9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: "التعلم من الأخطاء". عندما لا ينجح طفلكِ في إنجاز شيء ما، لا يبكي فورًا، بل قد ينظر إليكِ ويسأل: "لم أنجح، هل أحاول من جديد؟". وهذا دليل على تنامي قدرته على الصمود العاطفي. شجعيه بقولكِ: "يمكن لأي شخص أن يخطئ، والمهم أن تحاول مرة أخرى". أنتِ مرشدة رائعة!') WHERE id = 'cb464c9f-f6c4-48c0-ab1a-62c435d01c32';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الأسئلة المجرّدة» في الكلام. قد يطرح طفلكِ أسئلة مثل: «من أين تأتي الغيوم؟» أو «إلى أين ذهب القمر؟». عند الإجابة، وازني بين الخيال والمعلومات الواقعية: «تأتي الغيوم من بعيد وتحمل إلينا المطر». مثل هذه الحوارات توسّع نظرته إلى العالم وشغفه بالتعلّم بدرجة مذهلة.') WHERE id = 'fe4cb6a5-1e61-4aaa-9066-7165c1ab72dd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: أصبح طفلكِ الآن أكثر قدرة على تحمّل الإخفاق. فعندما تسقط مكعباته، لا يبكي فورًا، بل يستطيع أن يقول: «سأبنيها من جديد». ادعمي روح المثابرة لديه. لقد تجاوزنا 1070 يومًا، ولم يتبقَّ سوى القليل على إتمام عامه الثالث! أنتِ في هذه الرحلة معلّمته وأقرب صديقة إليه!') WHERE id = '39f0d5e2-0187-4785-9bb9-453ef9250d3e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بدأ طفلكِ الآن يقارن نفسه بالأطفال الآخرين، فيقول مثلًا: «أنا أركض أسرع منه». لا يدل هذا بالضرورة على روح المنافسة، بل هو إحدى طرق إدراكه لقدراته. اشرحي له بلغة بسيطة أن لكل شخص مهارات مختلفة. فهذا يعزّز لديه احترام الذات وتقبّل الآخرين.') WHERE id = 'b9b4b281-d07d-4b24-8be3-a13d61d2de12';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التوقّف السريع» ضمن المهارات الحركية. يستطيع طفلكِ أثناء الركض أن يتوقّف فور سماع أمركِ: «توقّف!». يدل ذلك على قدرته على التحكّم في عضلات جسمه، وكذلك على تطوّر التحكّم في الاندفاعات في الدماغ (التحكّم التثبيطي). إنه وقت رائع للعب لعبة «الضوء الأحمر، الضوء الأخضر» في الحديقة.') WHERE id = '36d86d2b-43c1-4460-afbb-45a783701a53';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الحوارات المركّبة» في الكلام. أصبح طفلكِ الآن قادرًا على سرد حدث لكِ بتسلسل منطقي، مثل: «ذهبنا أولًا إلى الحديقة، ثم أكلنا المثلجات، وبعد ذلك رأينا قطة». تعكس قدرته على بناء القصة تكامل الذاكرة مع مهارات الكلام. شجّعيه على توسيع قصته بسؤاله: «وماذا حدث بعد ذلك؟».') WHERE id = '62cbc2dc-4d91-48c4-8b87-f71ac5555a0a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«نسخ الأشكال الهندسية» ضمن المهارات الحركية الدقيقة. أصبح طفلكِ الآن قادرًا على تقليد دائرة أو علامة صليب ترسمينها. وهذا دليل على تطوّر قدرته على إعادة رسم الشكل الذي تراه عيناه بيده (التكامل البصري الحركي). علّميه رسم الأشكال باستخدام أقلام ملوّنة مختلفة.') WHERE id = 'c219d541-0794-4388-b19c-1b3296bc6f1a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«طقوس الزمن» في التطور المعرفي. رغم أن طفلكِ لم يفهم تمامًا بعدُ مفاهيم «الأمس» و«اليوم» و«الغد»، فإنه يعرف الطقوس اليومية؛ مثل «الذهاب إلى الحديقة بعد تناول الطعام» أو «قراءة قصة قبل النوم». تُشكّل هذه التسلسلات خطًا زمنيًا في ذهنه. ساعديه بسرد الأحداث له بترتيبها.') WHERE id = '3677e8d8-da75-4da9-b002-0343f54de7f8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«المناورات الدقيقة» في التناسق الجسدي. أصبح طفلكِ قادرًا على حمل كوب مملوء بسائل من دون أن يسكب منه الكثير، أو السير في ممر ضيق. وهذا يوضح مدى تطور التناسق البصري الحركي لديه. امنحيه في المنزل أدوار «النادل الصغير».') WHERE id = '24b745fb-d8d2-4191-b523-51bef737292f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«قاموس المشاعر» في تطور الكلام. لم يعد طفلكِ يكتفي بقول «أنا بخير» أو «لست بخير»، بل يستخدم في مواضعها كلمات مثل «غضبتُ» و«اشتقتُ» و«أنا سعيد». تقبّلي مشاعره وأكّدي له أنها مشروعة، كأن تقولي: «من الطبيعي أن تبكي لأنك اشتقتَ». فهذا من أهم ضمانات صحته النفسية.') WHERE id = 'e9c2314b-a8e3-4e87-93f6-fa6cd95e6e36';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'على أعتاب سن الثالثة (1095 يومًا). ابتعد طفلكِ الآن عن شاطئ «الرضاعة» وأبحر في محيط «الطفولة». لم يعد يقلّد تصرفاتكِ فحسب، بل يقلّد حالتكِ العاطفية أيضًا. فأنتِ مرآته الأهم. افتخري بنفسكِ، فقد أمضيتِ 1090 يومًا في تنشئة إنسان رائع!') WHERE id = '6d3a16a2-1643-4f5c-be11-40251b29e16d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يتبقَّ سوى 5 أيام على إتمام طفلكِ عامه الثالث (1095 يومًا)! لقد استوعب الآن مفهوم «الأنا» تمامًا، وأصبح يحمي حدوده بإصرار. إن تكراره لكلمة «لا» في هذه الأيام ليس موجّهًا ضدكِ، بل هو وسيلته لتأكيد شخصيته. سهّلي عليه هذه المرحلة بمنحه خيارات متعددة.') WHERE id = '1dacdad0-c90b-4399-810b-283d367d437c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الاستقلالية الكاملة» في التطور الجسدي. أصبح طفلكِ قادرًا على القفز إلى أعلى بكلتا قدميه في الوقت نفسه، وصعود الدرج ونزوله دون مساعدة، وقيادة دراجة ثلاثية العجلات. لقد تحولت طاقته الجسدية الآن إلى حركات منظّمة.') WHERE id = '0788e284-3cae-46fe-a730-5b0adb5d2052';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التفكير المجرّد» في الكلام. أصبح طفلكِ قادرًا على التحدث مطولًا عن أشياء لم تعد موجودة أمامه أو عن أحداث وقعت في الماضي. فجمل مثل: «هل تتذكرين عندما ذهبنا إلى هناك؟» تجسّد تناغمًا رائعًا بين ذاكرته طويلة المدى وقدرته على الكلام. شاركيه الذكريات القديمة باستمرار.') WHERE id = 'f3f07ee7-1804-4733-8e04-f58c824d1ef9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«مهارات ما قبل الكتابة» في المهارات الحركية الدقيقة. أصبح طفلكِ يمسك القلم بأصابعه بدلًا من راحة يده، ويرسم دوائر مغلقة وعلامات متقاطعة، بل وحتى خطوطًا تشبه بعض الحروف. وهذه أهم مرحلة جسدية تمهّد لاكتسابه مهارات الكتابة مستقبلًا.') WHERE id = '1e35d34e-147e-430a-a51b-7c615ecdd852';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'عيد ميلاد سعيد! 3 سنوات كاملة، أي 1095 يومًا! لقد غادر طفلكِ رسميًا مرحلة «الطفولة المبكرة». وأصبح الآن إنسانًا صغيرًا يتكلم ويفكر ويمزح، وله عالمه الخاص. خلال هذه الأيام الـ1095، بنيتِ في داخله أساسًا راسخًا من الثقة والحب. أحسنتِ يا أمي!') WHERE id = '94af9664-3a01-40cf-b485-6d92b46dd312';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'اليوم الأول من عامه الرابع! يبدأ شعور «المسؤولية» في الظهور لدى طفلكِ. وقد أصبح قادرًا على فهم أن ترتيب ألعابه جزء من اللعب. أوكلي إليه مهام منزلية بسيطة، مثل وضع المناديل على المائدة. فهذا يعزز لديه الشعور بأنه فرد مفيد في الأسرة.') WHERE id = '8a58846e-740c-494e-b055-cca0e1dee700';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«تطور التعاطف» في السلوك الاجتماعي. لم يعد طفلكِ يدرك مشاعره وحدها، بل أصبح يفهم أن الآخرين قد يشعرون بالحزن أيضًا. وسؤاله: «لماذا يبكي ذلك الطفل؟» دليل على أنه بدأ يرى العالم من منظور الآخرين.') WHERE id = '3be5dfbf-e6fa-4586-9735-23266743fb18';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التسلسل المنطقي» في التطور المعرفي. أصبح طفلكِ قادرًا على ترتيب أحداث مكوّنة من 3-4 خطوات ترتيبًا صحيحًا: «غسلت يدي أولًا، ثم أكلت الخبز، وبعد ذلك لعبت». اقترحي عليه أن يخطط يومكما معكِ. فهذا يحوّل «الفوضى» في ذهنه إلى «خط زمني» منظّم.') WHERE id = 'cce49adb-3f97-4be9-9435-40b81895ee05';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«ألعاب تقمّص الأدوار المعقّدة» في الخيال. أصبحت الألعاب الآن أكثر تفصيلًا؛ فلم يعد طفلكِ يكتفي بدور «الطبيب»، بل «يكتب لكِ وصفة طبية» و«يعطيكِ حقنة» أيضًا. تساعده هذه الألعاب على التعامل مع التوتر وفهم المجتمع. شاركيه عالمه في اللعب باحترام.') WHERE id = '63c35556-85c7-4de4-956c-b06072fe14e8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المحطة الأخيرة في رحلة الـ1100 يوم. أصبح طفلكِ يشعر الآن بأنه «كبير». وقد باتت شخصيته وذوقه وطباعه واضحة ومتكاملة. قطعتِ هذه الرحلة بالصبر والمعرفة، والأهم من ذلك كله، بحب لا حدود له. سيظل تطبيق «Anacan» دائمًا إلى جانبكِ وإلى جانب بطلكِ الصغير!') WHERE id = 'b3b1d154-d59c-44d1-8bf7-a6ef75357962';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بكِ في الأيام العشرة الأولى من سن الثالثة! في هذه المرحلة، أصبحت حصيلة طفلكِ اللغوية تقارب 1000 كلمة. ولم يعد يعبّر عن احتياجاته فحسب، بل يشارككِ أحلامه أيضًا. أثناء حديثكِ معه، شجّعيه على التفكير المنطقي بتكرار سؤال: «لماذا برأيك؟».') WHERE id = 'a79f70f3-f350-4b22-984a-7f58dfd4b7fb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«القفزة الدقيقة» في النمو الجسدي. أصبح طفلكِ قادرًا على القفز من مكانه إلى أعلى، وكذلك نحو هدف محدد، مثل القفز فوق سجادة ملوّنة على الأرض. وهذا يدل على قدرته على حفظ التوازن وتقدير المسافات في المكان. وتُعد لعبة «القفز من حجر إلى آخر» في الحديقة تمرينًا رائعًا له.') WHERE id = '05ceca15-09f0-41f4-a54b-99db2b828cc8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الضمائر وصيغ التذكير والتأنيث» في الكلام. أصبح طفلكِ يستخدم ضمائر «أنا» و«أنت» و«هو» بدقة تامة. وإذا كان لا يزال يذكر اسمه أحيانًا بصيغة الغائب، مثل «علي يريد ماءً»، فصحّحي له بلطف: «نعم، أَنْتَ تريد ماءً».') WHERE id = '03d396dd-e487-41b7-9885-73235271ea53';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الأحجيات والبناء» ضمن المهارات الحركية الدقيقة. أصبح طفلكِ قادرًا على تركيب أحجيات مكوّنة من 8-12 قطعة بمفرده، وبناء أبراج وجسور معقّدة بالمكعبات. ويعزّز ذلك قدرته على التحليل البصري والحركات الدقيقة للأصابع. وإذا لم ينجح، فلا تقدّمي له الحل الجاهز، بل أعطيه تلميحًا فحسب.') WHERE id = 'ca591a5d-4734-459d-be9b-3eaadeddb81b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ الآن يصف العالم من خلال الجمع بين الألوان والأشكال. فإذا قال: "أعطيني تلك القطعة الصفراء المربعة"، فهذا يدل على أن دماغه يعالج عدة خصائص في الوقت نفسه. ادعمي هذه المهارة بمهام يومية صغيرة (مثل: "اعثر على جواربك الزرقاء").') WHERE id = 'd8ae8173-4cc7-42b0-8737-2bedce267dcb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"التوازن الديناميكي" في النمو البدني. أصبح طفلكِ الآن قادرًا على الوقوف على قدم واحدة لمدة تصل إلى 5 ثوانٍ. وهذا يدل على تطور الجهاز الدهليزي وتقوّي عضلات الساقين. العبي معه لعبة "اللقلق" لمعرفة مَن منكما يستطيع الوقوف مدة أطول.') WHERE id = '071b03c5-b7b5-42d1-a970-a44e8e806595';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"علاقات السبب والنتيجة" في تطور اللغة. بدأ طفلكِ الآن يفهم الجمل من نمط "إذا... فـ...". فعندما تقولين له: "إذا رتبت ألعابك، فيمكننا مشاهدة الرسوم المتحركة"، فإنه يفهم الشرط. وهذه خطوة مهمة في تنمية التفكير المنطقي والانضباط الذاتي.') WHERE id = 'a7ceb34f-04f4-4303-a5f6-fca236e067db';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"التجارب الأولى مع المقص" في تطور المهارات الحركية الدقيقة. أصبح طفلكِ الآن مهتمًا بقص الورق على طول خط مستقيم (باستخدام مقص آمن للأطفال). تعمل هذه الحركة على تحسين التنسيق بين اليد والعين، كما تنمّي المهارات الحركية الدقيقة للأصابع. لا تتركيه دون مراقبة، لكن لا تقيّدي استقلاليته.') WHERE id = '42cc6ea9-d4af-4873-a31f-be87ca7ae22d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"رفاق اللعب الخياليون" في السلوك الاجتماعي. أصبح طفلكِ الآن يتحدث بصوت مرتفع حتى عندما يلعب بمفرده، ويمنح ألعابه أدوارًا مختلفة. يساعده ذلك على تنظيم أفعاله بالكلمات. ومن خلال الاستماع إلى هذه "المونولوجات"، يمكنكِ فهم ما يدور في عالمه الداخلي.') WHERE id = 'b9a0516e-a5fd-46ab-abb8-4e16e305575b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الاختيار المستقل: اتخاذ القرار". أصبح طفلكِ الآن يعرف بوضوح ما يريد تناوله أو اللعبة التي يريد لعبها. قدّمي له كل يوم خيارين: "هل تريد تفاحة أم موزة؟". يمنحه ذلك شعورًا بالتحكم في حياته ويعزز ثقته بنفسه.') WHERE id = 'd2594413-54bc-4a0b-857c-1959a2b007b2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"ارتداء الملابس باستقلالية: السحّاب والأزرار". أصبح طفلكِ مهتمًا جدًا بفكّ الأزرار الكبيرة أو رفع السحّاب إلى الأعلى (بعد أن تبدئي بإغلاقه له). قولي له: "هيا، جرّب بنفسك" وانتظري بصبر. إن تمكّنه من ارتداء ملابسه بنفسه يعزّز لديه شعور "أنا أستطيع" وثقته بنفسه بدرجة كبيرة.') WHERE id = '9a464aa6-3d95-421a-948d-be4bbc442bbe';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"فهم المشاركة" في السلوك الاجتماعي. بدأ طفلكِ يفهم أن إعطاء لعبته لصديقه لا يعني فقدانها نهائيًا، بل هو مجرد "لعب بالتناوب". وهذه هي البذور الأولى للتعاطف. احرصي على تعزيز هذا السلوك لديه بقولكِ: "شكرًا جزيلًا لأنك تشارك صديقك".') WHERE id = '7f75fc5d-eb6e-4e7a-abdd-f9659116f406';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"العلاقة بين العدد والكمية" في التطور المعرفي. بالإضافة إلى العدّ عن ظهر قلب من 1 إلى 10، يبدأ طفلكِ الآن بعدّ الكمية الفعلية للأشياء، فيشير إليها بإصبعه ويقول: "واحد، اثنان، ثلاثة". أعطيه مهام مثل: "لنضع 3 ملاعق على المائدة". هذه هي المرحلة التي تبدأ فيها الأرقام المجرّدة بالارتباط فعليًا بالعالم الحقيقي.') WHERE id = '6bc8719d-b139-4ea0-af7e-596754bfb254';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "المشي إلى الخلف". أصبح طفلكِ قادرًا على المشي إلى الخلف بثقة لبضع خطوات من دون أن ينظر وراءه. تقوّي هذه الحركة وعيه بجسمه (الإحساس العميق) وقدرته على تحديد اتجاهه في المكان. العبي معه لعبة "سباق السلطعون" لتستمتعا معًا وتساعديه على تمرين عضلاته.') WHERE id = '2fce926c-604e-40c3-aff1-959bf3574903';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الأسئلة المجرّدة" في تطور الكلام. يكتشف طفلكِ العالم الآن من خلال أسئلة مثل "لماذا؟" و"كيف؟". وتُظهر أسئلة مثل "إلى أين تذهب السحابة؟" و"إلى أين تسرع النملة؟" فضوله والروابط المنطقية التي يبنيها مع العالم من حوله. من المهم أن تكون إجاباتكِ بسيطة وبلغة يستطيع فهمها.') WHERE id = '5eb5c186-69a6-483f-9ba1-b6f471501a76';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: "اختبار الصبر". بدأ طفلكِ يفهم أنه يتعيّن عليه الانتظار بضع دقائق للحصول على شيء يريده. فإذا لم يبكِ فورًا عندما تقولين له: "ليس الآن، بعد قليل"، فهذا يدل على تطور قدرته على تنظيم مشاعره. عندما تلاحظين صبره، شجّعيه بقولكِ: "شكرًا جزيلًا لأنك انتظرت".') WHERE id = '6751f01f-eb8d-4bf5-bdeb-fec3d11483e8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: «ثبات الحجم والكمية». قد يظن طفلكِ حتى الآن أن كمية الماء في الإناء الطويل والضيق أكبر منها في الإناء العريض. وهذا طبيعي في هذا العمر. العبي معه ألعاب الماء واسكبا الماء في أوعية مختلفة. يساعده ذلك على تطوير فهمه المنطقي بسرعة من خلال التجربة.') WHERE id = 'c2c7f4f2-7e4e-4f22-9785-bdddbd705503';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «القفز إلى الأمام بكلتا القدمين». أصبح طفلكِ قادرًا على القفز فوق العوائق (مثل حبل موضوع على الأرض) بكلتا قدميه في الوقت نفسه. ويتطلب ذلك تناسق الجسم بأكمله. أنشئي له مسارات صغيرة من العوائق في أماكن آمنة.') WHERE id = '3c4e0869-e516-493c-90a9-df3b2f2e738b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور اللغة: «المفهوم المجرّد للزمن». أصبح طفلكِ يدرك الفرق بين «الصباح» و«الظهيرة» و«المساء» من خلال الأنشطة الروتينية. فعندما تقولين: «عندما يأتي أبي في المساء...»، يمكنه أن يتصور هذه الفترة من اليوم. ويساعد التزامكِ بروتينكما اليومي على ربط مفهوم الزمن لديه بالشعور بالأمان.') WHERE id = 'd719015d-011e-40f6-8ffa-5cdcb4302e71';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'النضج العاطفي: معنى كلمة «آسف». أصبح طفلكِ يفهم الأهمية الاجتماعية للاعتذار عندما يؤذي شخصًا عن قصد أو من دون قصد. كوني دائمًا قدوة له؛ وعندما تخطئين، اعتذري منه حتى ينظر إلى هذا السلوك بوصفه علامة على قوة الشخصية.') WHERE id = 'c8c25e23-7ba2-4ee9-a363-3be20d076417';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ يؤلف قصصًا بسيطة بالنظر إلى الصور. وتُظهر الجمل المتسلسلة مثل: «ذهب الدب إلى الغابة، وكان جائعًا، فأكل العسل» أنه يفهم التسلسل المنطقي. أعطيه كتبًا تحتوي على صور مشوقة واسأليه: «برأيك، ماذا سيحدث بعد ذلك؟». فهذا ينمّي خياله الإبداعي إلى أقصى حد.') WHERE id = 'd67be23e-c203-4809-a7a3-cbfd66266b55';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور الحركي: «الاستقلالية على الدرج». أصبح طفلكِ ينزل الدرج بثقة، واضعًا قدمًا على كل درجة بالتناوب، مع الإمساك بيد واحدة فقط (أو من دون إمساك). وهذا يدل على اكتمال نضج مهاراته الحركية الكبرى. ما عليكِ سوى البقاء بجانبه وتقديم الدعم المعنوي له.') WHERE id = '7b344d73-ef09-40bc-8962-14de04d0a9d1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«المكان والاتجاه» في تطور الكلام. رغم أن طفلكِ لم يتقن بعد مفهومي «اليمين» و«اليسار» تمامًا، فإنه ينفذ بدقة أوامر «إلى الأمام» و«إلى الخلف» و«إلى الأعلى» و«إلى الأسفل». العبي معه «لعبة الروبوت»: «خطوتان إلى الأمام، وخطوة واحدة إلى الخلف!». هذه اللعبة ممتعة وتعزز أيضًا قدرته على تحديد الاتجاهات في المكان.') WHERE id = 'd6a03598-2471-4b13-a839-fb2c51010318';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: «التعامل مع الإخفاق». لم يعد طفلكِ يبكي فورًا عندما يسقط البناء الذي صنعه بالمكعبات، بل أصبح قادرًا على القول: «سأبنيه من جديد». ادعمي روح المثابرة لديه. لقد مضى 1130 يومًا، وأصبح طفلكِ الآن بطلًا صغيرًا!') WHERE id = 'b7ab015d-a4e4-4c1d-a9a5-7f26c5798a69';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ قادرًا على تصنيف الأشياء وفقًا لخاصيتين في الوقت نفسه، مثل اللون والشكل معًا. إذا استطاع تنفيذ طلبكِ عندما تقولين له: «أعطني كل السيارات الحمراء الصغيرة»، فهذا يمثل مستوى جديدًا في تطوره المعرفي. كلّفيه بمهام «اختيار» صغيرة مماثلة أثناء الأعمال المنزلية اليومية.') WHERE id = 'ff1dcdb3-fd81-4345-80ce-058e6b7a0d6b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«القفز نحو الهدف» في التطور الحركي. يحاول طفلكِ الآن القفز إلى وسط دائرة مرسومة على الأرض أو هدف ملوّن. يساعد ذلك على صقل توازنه وقدرته على تقدير المسافات في المكان. العبي معه في الحديقة لعبة «القفز من حجر إلى آخر».') WHERE id = '5d8b4009-8971-48b6-aa55-75a96a823d2d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«توسّع فهم الكلمات المتضادة» في تطور الكلام. أصبح طفلكِ يفهم الآن مفاهيم متضادة مجردة، مثل «مبكر-متأخر» و«مظلم-مضيء» و«فارغ-ممتلئ». أريه كوبًا فارغًا وآخر ممتلئًا، واسأليه عن الفرق بينهما. فهذا يعزز قدرته على تحليل العالم المحيط به من خلال المقارنة.') WHERE id = '18232b0a-482a-40e1-90c7-8a04a56dc3b9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«إتقان الأحجيات» في المهارات الحركية الدقيقة. أصبح طفلكِ قادرًا الآن على إكمال أحجيات معقدة مكوّنة من 10-12 قطعة، مع التمييز بين حواف الصورة ووسطها. يعزز ذلك ذاكرته البصرية وقدرة أصابعه على أداء الحركات الدقيقة. وعندما لا ينجح، قدّمي له تلميحات بنبرة هادئة.') WHERE id = '3045e148-b927-4872-8354-b9edb5116d18';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«سلسلة الأسئلة والأجوبة» في تطور الكلام. لم يعد طفلكِ يجيب عن أسئلتكِ بمجرد «نعم/لا»، بل أصبح يجيب بجمل كاملة. ويمكنه تقديم إجابة مفصلة عن سؤال مثل: «مع من لعبتَ في الحديقة اليوم؟». وعندما تتحاورين معه، حفّزي تطوره اللغوي بطرح أسئلة متابعة مثل: «ما لونه؟» و«ماذا فعلتما؟».') WHERE id = '728c62de-e9bd-4825-a015-839c4ef09ac4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«تلوين أكثر دقة» ضمن المهارات الحركية الدقيقة. أصبح طفلكِ يدرك حدود الأشكال الصغيرة أيضًا، ويحاول ألا يتجاوزها كثيرًا أثناء التلوين. وهذا تقدم كبير في التحكم بعضلات اليد. أتيحي له فرصة التجربة من خلال إعطائه أقلام تلوين بسماكات مختلفة.') WHERE id = '1e2db868-b348-4ed1-a7d7-4e1b235065d6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«ارتداء الملابس باستقلالية: السحّاب والأزرار». أصبح طفلكِ ماهرًا في فك الأزرار الكبيرة ورفع السحّاب إلى الأعلى بعد مساعدته على إدخال طرفه. قولي له: «هيا، جرّب بنفسك»، وانتظريه بصبر. إن قدرته على ارتداء ملابسه بنفسه تعزز لديه بشكل كبير شعور «أنا أستطيع» وثقته بنفسه.') WHERE id = 'd0289832-2e1f-4c80-bf6f-025f04fde8c3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«فهم المشاركة» في السلوك الاجتماعي. أصبح طفلكِ يحاول ألا يأخذ اللعبة فورًا من يد طفل آخر، بل يقول: «أعطني» وينتظر. وهذا دليل على ترسّخ مهارة التنظيم الذاتي لديه. عندما تلاحظين هذا السلوك الصبور، احرصي على مدحه بقولكِ: «شكرًا جزيلًا لأنك انتظرتَ دورك».') WHERE id = '8b0e05af-2727-418a-b763-3601d197e7d0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«العام والخاص» في التطور المعرفي. أصبح طفلكِ يفهم أن التفاح والإجاص والموز كلها «فواكه». اعرضي عليه مجموعة متنوعة من الأشياء واسأليه: «ماذا نسمّي هذه الأشياء مجتمعة؟». يساعده التفكير وفق الفئات على تنظيم نظام تخزين المعلومات في دماغه بصورة أفضل.') WHERE id = 'cfa7be75-1286-4575-9a59-47547f98434d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «رمي الكرة من فوق الكتف». لم يعد طفلكِ يُسقط الكرة على الأرض فحسب، بل أصبح قادرًا على رميها إلى الأمام من فوق كتفه باتجاه هدف محدد. ويتطلب ذلك تناسق حركة الجسم بالكامل. العبي معه في الحديقة ألعاب «التصويب نحو الهدف».') WHERE id = '7ccd147e-b878-45ff-a8c8-f2d12fac2b06';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'ندخل الشهر التاسع والثلاثين! ينتقل طفلكِ الآن من التفكير «ثنائي الخطوات» إلى تنفيذ مهام «ثلاثية الخطوات». إذا قلتِ له: «خذ اللعبة، وضعها في الصندوق، ثم أغلق الغطاء»، ونفّذ الخطوات بالترتيب، فهذا إنجاز كبير لذاكرته العاملة (working memory). ساعديه على صقل هذه المهارة بأن تكلّفيه خلال اليوم بمهام صغيرة ومنطقية ومتسلسلة.') WHERE id = '0f30e0b2-fa18-4fe2-8164-072ae2911569';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في النشاط البدني: «الجري السريع والمناورة». أصبح طفلكِ قادرًا على الالتفاف حول العائق الذي يراه أمامه أثناء الجري من دون خفض سرعته. وهذا يدل على اكتمال تطور وعيه بوضعية جسمه وحركته (proprioception). نظّمي له سباقات «الجري مع الحواجز» في الحديقة لتوجيه طاقته نحو نشاط مفيد.') WHERE id = 'c69b10fa-3ecf-43fd-9d25-d70589994cb8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الكلام: «درجات المقارنة». أصبح طفلكِ يستخدم تعبيرات مثل «أكبر»، و«الأصغر»، و«لذيذ جدًا» في مواضعها الصحيحة. قارني الأشياء وتحدّثي معه عنها، مثلًا: «هل هذه التفاحة أحلى أم الأخرى؟». يساعد إتقان درجات الصفات هذه على إثراء لغته الوصفية وزيادة دقة تعبيره عن أفكاره.') WHERE id = '10874a8b-618a-44ed-9a23-9c2c3bcf6530';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: «النحت». لم يعد طفلكِ يكتفي بضغط الصلصال أو الرمل الحركي، بل أصبح يصنع منه أشكالًا معروفة مثل «كرة» أو «ثعبان» أو «رغيف خبز». وهذا تمرين رائع لتنمية التفكير الإبداعي وتقوية العضلات الدقيقة في أطراف أصابعه.') WHERE id = '8ef81138-3a54-4c5e-ab33-5ab135be888d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«ارتداء الملابس باستقلالية: التمييز بين الجهة الصحيحة والمقلوبة». يحاول طفلكِ الآن التمييز بين الجهة الصحيحة والمقلوبة للقميص أو البنطال، وبين الحذاء الأيمن والأيسر، حتى إن أخطأ أحيانًا. قدّمي له تلميحات بسيطة، مثل: «انظر، الجهة التي تحمل الرسمة تكون في الأمام». فهذا يعزز تركيزه على التفاصيل ويطوّر مهاراته في العناية بنفسه.') WHERE id = '0d252040-b7cf-42d1-8e5c-b4a1ea436608';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: «روح الفريق». أصبح طفلكِ قادرًا على اللعب مع أطفال آخرين لتحقيق هدف مشترك، مثل بناء قلعة كبيرة. وهذا انتقال من «اللعب المتوازي» إلى «اللعب التعاوني». راقبي كيفية تواصله وتفاهمه مع الأطفال الآخرين، وساعديه في المواقف الصعبة على بناء «جسر» اجتماعي للتواصل معهم.') WHERE id = 'b59f81d2-048d-48f5-8c51-231cd1498118';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"التنظيف والمساعدة باستقلالية". أصبح طفلكِ متحمسًا جدًا للمشاركة في أعمال مثل حمل طبقه ومسح الفتات عند رفع المائدة. قدّمي له أدوات تنظيف تناسب طوله. فهذا يعزز لديه الشعور بالمسؤولية والانتماء داخل الأسرة. ورؤية ثمرة جهده تجعله سعيدًا جدًا.') WHERE id = '5fed215f-7140-471a-887f-855f666792ab';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"القواعد والحدود" في السلوك الاجتماعي. أصبح طفلكِ يفهم المنطق الكامن وراء كلمة "لا" بشكل أفضل قليلًا، لكنه لا يزال يحب اختبار الحدود. تحلّيكِ بالصبر والثبات يمنحه شعورًا بالأمان. حاولي دائمًا تطبيق القواعد بالطريقة نفسها.') WHERE id = 'ad322e7c-2c29-48c7-ba0d-376889e0bc86';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الأعداد الترتيبية" في التطور المعرفي. أصبح طفلكِ يفهم مفاهيم "الأول" و"الثاني" و"الأخير". رتّبي السيارات في صف واسأليه: "أي سيارة هي الأولى؟". فهذا ينمّي لديه فهم التسلسل والمنطق الرياضي. وقولكِ له في السباقات: "لقد وصلتَ أولًا!" يمنحه دافعًا كبيرًا.') WHERE id = 'ccdeb036-ba4e-49c8-960c-f4271e0fc740';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "المشي إلى الخلف وإلى الجانب". أصبح طفلكِ قادرًا على التحرك بمرونة في اتجاهات مختلفة. العبي معه "لعبة المرآة": اخطي خطوة إلى الجانب ودعيه يقلّدكِ. فهذا ممتع، كما يرتقي بتناسق حركات جسمه إلى مستوى جديد.') WHERE id = '53f08fbe-8240-4c06-91f5-3a6645fa77af';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"التعمق في الأسئلة المجرّدة" ضمن تطور الكلام. قد يفاجئكِ طفلكِ بأسئلة مثل: "إلى أين تذهب الغيوم؟" و"لماذا تظهر النجوم ليلًا؟". وعندما تجيبينه، حفّزي خياله أيضًا بسؤاله: "برأيك، ماذا تفعل النجوم الآن؟". فهذا يغذّي تفكيره الإبداعي.') WHERE id = 'ca368c4f-966b-4846-b9ca-ff68822b1eca';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: "متعة المشاركة". عندما يشارك طفلكِ لعبته أو الحلوى طوعًا، فإنه يرى سعادتكِ ويرغب في تكرار ذلك. أكّدي على كرمه بقولكِ: "شكرًا جزيلًا لأنك أسعدت صديقك". لقد أتممنا 1140 يومًا بنجاح – أنتِ أم رائعة!') WHERE id = '706c863b-0328-4280-9ae2-b61f0dddff18';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: "الربط بين الرقم والكمية". يستطيع طفلكِ العد من ١ إلى ٥، وأصبح الآن قادرًا على رؤية الرقم "3" ووضع 3 ألعاب جانبًا. هذه إحدى أهم مراحل التفكير الرياضي. عززي هذا الربط في الحياة اليومية بمهام مثل: "أعطني ملعقتين".') WHERE id = '5b8b658c-3ba9-46dd-b7e1-a329bde32c59';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "التقاط الكرة الملقاة من الأعلى". يحاول طفلكِ الآن التقاط كرة كبيرة تُرمى نحوه ببطء بكلتا يديه. تتطلب هذه الحركة التناسق بين اليد والعين وسرعة الاستجابة. العبي معه لعبة "ارمِ الكرة والتقطها" من مسافة قريبة.') WHERE id = '9cbfafe8-e2d3-4b4c-a7dd-a7d50a0d73a4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: "ذروة الأسئلة المجرّدة". أصبح طفلكِ يطرح أسئلة عن الوجود والظواهر الطبيعية، مثل: "لماذا تهب الرياح؟" و"إلى أين تذهب الشمس لتنام؟". عند الإجابة، أشركي خياله أيضًا، فقولي مثلًا: "لقد تعبت الشمس وذهبت لترتاح كي توقظنا من جديد غدًا". فهذا يغذي فهمه للعالم وشغفه بالتعلم.') WHERE id = 'be40f099-56c3-42b3-90d0-8aec32c8e2ca';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'النضج العاطفي: "تقبّل مشاعر الآخرين وإقرارها". عندما يلاحظ طفلكِ أنكِ متعبة أو أن طفلًا آخر قد تأذى، يسأل الآن: "ماذا حدث؟" ويحاول مواساته. وهذا يدل على أنه ينمو ليصبح شخصًا عطوفًا. أنتِ أم رائعة!') WHERE id = '28850826-f8da-4cde-a0f3-c10d2981e7f4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بدأ طفلكِ يختبر مفهومي "أنا" و"ملكي" في السياق الاجتماعي. وعندما لا يرغب في مشاركة لعبته، فهذه محاولة لتحديد حدوده الشخصية أكثر من كونها أنانية. أظهري له احترامكِ لشعوره بالملكية بقولكِ: "هذه لعبتك، ويمكنك إعطاؤها لصديقك عندما تكون مستعدًا". فهذا يساعده مستقبلًا على اكتساب القدرة على احترام حدود الآخرين أيضًا.') WHERE id = '3d0a961f-8311-4c15-82e4-3b93885267b5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الحركة الجسدية: "القفز من مكان مرتفع". أصبح طفلكِ يحب القفز بكلتا قدميه في الوقت نفسه من درجة منخفضة أو من فوق منصة إلى الأرض. وهذه الحركة مهمة لتطور جهازه الدهليزي المسؤول عن التوازن. ضعي بساطًا ناعمًا على الأرض لتدعمي شجاعته بأمان.') WHERE id = '0680b361-8e77-46ad-a0ea-0e96e9759bdc';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: "إتقان التعبير عن المستقبل". لم يعد الطفل يكتفي بقول "سنذهب"، بل أصبح يضع خططًا متسلسلة مثل: "سنذهب غدًا إلى منزل جدتي ونلعب مع القطة". ناقشي معه في نهاية اليوم خطط الغد. فهذا ينمّي قدرته على تصوّر الأحداث مسبقًا والتخطيط لها (الوظائف التنفيذية).') WHERE id = 'e7723585-78f9-489b-95f6-9d306c6417b7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: "أشكال أكثر تعقيدًا". أصبح الطفل يمسك قلم الرصاص بمهارة مستخدمًا القبضة الثلاثية، ويحاول رسم مثلث أو خطوط متقاطعة على الورق. وهذا يدل على أن عضلات يده تكاد تكون مستعدة للكتابة. اقترحي عليه لعبة "هيا نصل بين النقاط".') WHERE id = '23c81011-ddf7-4cf3-aec3-f115d29c3f5e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"النظافة الشخصية المستقلة: تنظيف الأسنان". أصبح الطفل يعرف خطوات تنظيف أسنانه بالترتيب. ورغم أنكِ لا تزالين بحاجة إلى "التحقق" منها في النهاية، اسمحي له بالقيام بهذه المهمة بنفسه. فهذه العادة تعزز لديه الشعور بالمسؤولية عن العناية بجسده.') WHERE id = '94615e85-6da2-44c7-a201-6901c2a92ddf';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: "القصص الخيالية والكذب". قد يروي الطفل أحيانًا أشياء غير حقيقية، مثل: "لقد حلّقت في السماء". هذا ليس خداعًا، بل هو امتزاج الخيال بالكلام. شجّعي خياله بقولكِ: "يا لها من قصة ممتعة!"، لكن اشرحي له أيضًا بلطف الفرق الدقيق بين الواقع والخيال.') WHERE id = 'd70b5fda-77b6-4fb1-bc69-d894fe21ca89';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: "التعمق في التصنيفات". لم يعد الطفل يصنّف الأشياء تحت مسمى عام مثل "سيارة" فحسب، بل أصبح يقسّمها إلى فئات فرعية مثل "سيارة سريعة" و"شاحنة". اقترحي عليه تجربة "أي الأشياء يطفو على الماء وأيها يغرق؟". فهذا يشكّل أساس مهارات الملاحظة العلمية لديه.') WHERE id = '164e0d4f-5849-466c-88ec-e6961c6d0680';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "التحكم بالكرة بالقدم". لم يعد الطفل يركل الكرة فحسب، بل يحاول تحريكها بدفعها قليلًا إلى الأمام بقدمه. وهذا تمرين ممتاز للتوازن الديناميكي. أنشئي معه في الحديقة "مسارًا صغيرًا لكرة القدم".') WHERE id = 'c019ed6e-efde-47c2-b2ac-37c3fbd433b5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«ثراء الصفات» في الكلام. يبدأ طفلكِ باستخدام كلمات مثل «ناعم» و«شائك» و«أملس» و«لامع» عند وصف الأشياء. العبي معه لعبة «المس وخمّن»: اطلبي منه أن يغمض عينيه ويصف لكِ ملمس الشيء.') WHERE id = '0b5835ed-17d3-46e9-b2cd-eb9c92154c53';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'القوة العاطفية: «مساعدة الآخرين». أصبح طفلكِ قادرًا على ملاحظة أنكِ تواجهين صعوبة في أداء مهمة ما أو تبحثين عن شيء، وقد يعرض عليكِ المساعدة. يدل ذلك على أنه بدأ يتجاوز مرحلة التمركز حول الذات ويتحول إلى «شريك اجتماعي» حقيقي. أبرزي أهمية مساعدته بقولكِ: «لولاك، لما استطعت العثور عليه».') WHERE id = '95ef23e6-3a1e-4eb7-bed7-103fc452a1e2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'يبدأ طفلكِ الآن بالتفكير في «النتائج». فمثلًا، يحاول بمساعدتكِ فهم علاقات السبب والنتيجة، مثل: «إذا تناولت الحلوى، فقد تؤلمني أسناني». من المهم جدًا في هذه المرحلة أن تشرحي له أسباب القواعد. فهذا ينمّي لديه انضباطًا قائمًا على المنطق الداخلي، بدلًا من الطاعة العمياء.') WHERE id = '602eea29-96df-4d75-b3f3-a89b088efbe3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التوازن الديناميكي» في الحركة الجسدية. أصبح طفلكِ قادرًا على المشي كأنه «لاعب سيرك» فوق خط مستقيم مرسوم على الأرض أو فوق حبل من دون أن يفقد توازنه. يدل ذلك على اكتمال نضج الجهاز الدهليزي. ويساعد المشي معه فوق حواف الأرصفة في الحديقة، مع إمساككِ بيده، على صقل هذه المهارة أكثر.') WHERE id = '5465b5ac-4749-433f-99e1-222fda8c10bf';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«تفاصيل الحكايات» في الكلام. أصبح طفلكِ قادرًا على رواية حدث وقع له خلال اليوم في 4-5 جمل متتابعة، مثل: «ذهبنا اليوم إلى الحديقة، ورأيت إلجان، ولعبنا بالرمل». استمعي إلى حكاياته باهتمام ووسّعي الحوار بسؤاله: «وماذا حدث بعد ذلك؟». فهذا يعزز ذاكرته اللفظية وطلاقة كلامه.') WHERE id = '7607f78f-a199-4155-af72-552bbd09b140';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«من الدوائر إلى الرموز» في المهارات الحركية الدقيقة. أصبح طفلكِ يرسم دوائر مغلقة ويضيف إليها خطوطًا من الأسفل لتمثيل «إنسان» بهيئة رسم بسيط. وهذه بداية التفكير الرمزي البصري. حفّزي خياله بإعطائه أقلام تلوين وسؤاله: «من سترسم اليوم؟».') WHERE id = 'ead2dac9-db7b-47ae-9b92-23aa29cddd39';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: "المقارنة بين الارتفاع والطول". أصبح طفلكِ قادرًا على ترتيب الأشياء بحسب ارتفاعها. أعطيه ألعابًا من 3-4 أحجام مختلفة وقولي له: "رتّبها من الأطول إلى الأقصر". يساعد ذلك على صقل إدراكه البصري وقدرته على الترتيب المنطقي.') WHERE id = '3281647e-af83-48c8-9e0e-9deebd826a8f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الحركي: "المناورة بالدراجة ثلاثية العجلات". أصبح طفلكِ قادرًا على رؤية العائق أمامه أثناء ركوب الدراجة وتغيير اتجاه المقود لتجنّبه. ويجمع ذلك بين قدرته على تحريك الدواسات (جسديًا) ومتابعة الطريق (بصريًا). ادعمي هذه المهارة بإعداد "مسار للركوب" آمن له في الحديقة.') WHERE id = 'cccc4e73-bd8f-49ce-ac37-8b06ba255913';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الزمن والتسلسل" في الكلام. أصبح طفلكِ يضع خططًا مستقبلية مثل: "سنذهب غدًا إلى بيت جدتي، ثم سأذهب إلى الحديقة". وهذا يدل على تطور قدرته على تصوّر الأحداث مسبقًا (التصور البصري). في نهاية اليوم، تحدّثي معه عن خطط الغد على هيئة "حكاية" حتى يغفو.') WHERE id = '533647bf-c77f-434e-8420-bd22239f3086';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: "الصبر والانتظار". أصبح طفلكِ يدرك أن انتظار دوره لبضع دقائق ليس "نهاية العالم"، بل أمر مؤقت فحسب. وهذا يدل على تطور قدرته على ضبط النفس (الوظائف التنفيذية). 1180 يومًا – أصبح طفلكِ الآن فردًا صغيرًا يفهم العالم ويتكيّف معه. أنتِ رفيقة درب رائعة!') WHERE id = 'fe96ce06-9654-4a3f-8b50-d93363f0cbca';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ يصف نفسه من خلال صفاته الجسدية، فيقول: "أنا سريع في الجري" أو "أنا طويل". وهذه مرحلة جديدة في تطور وعيه بذاته. ادعمي هذه الصورة الإيجابية التي كوّنها عن نفسه. اطرحي عليه أسئلة حول نظرته إلى ذاته، مثل: "برأيك، ما الأشياء الأخرى التي تجيدها؟".') WHERE id = '4f2b9702-c295-43cf-9776-2d9fd4b98c79';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الحركة الجسدية: "القفز الديناميكي". أصبح طفلكِ قادرًا على القفز أثناء الجري فوق عائق صغير يظهر أمامه (مثل حبل موضوع على الأرض) من دون أن يخفّف سرعته. وهذا يدل على تطور قدرة الدماغ على التخطيط المسبق للحركة (التخطيط الحركي).') WHERE id = '63d363dc-9356-4fa8-bbd3-57a0c8ed1083';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ يعبّر عن مشاعره بطريقة أكثر تعقيدًا: "أنا حزين لأن لعبتي انكسرت". وهذه قفزة كبيرة في الذكاء العاطفي. لا تكتفي بتقبّل مشاعره، بل أتيحي له أيضًا فرصة اقتراح حل: "برأيك، كيف يمكننا إصلاحها؟". فهذا يساعده كذلك على تنمية المرونة النفسية.') WHERE id = '72c6a670-175e-4e59-a40a-08a5b3924e43';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في النشاط البدني، تظهر مهارة "القفز الجانبي". لم يعد طفلكِ يقفز إلى الأمام فحسب، بل أصبح قادرًا أيضًا على القفز جانبًا. ويتطلب ذلك أن تعمل عضلات الوركين والساقين بتناسق في اتجاهات مختلفة. نظّمي معه سباقًا "للقفز الجانبي" فوق خطوط مرسومة على الأرض.') WHERE id = '7ad7a096-5914-4eed-80cb-8089f672c249';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور اللغة، تظهر مرحلة "الإتقان الكامل للضمائر". لم يعد طفلكِ يخلط بين مفاهيم "لي" و"لك" و"له". ويبدأ بتحديد حدود الملكية الاجتماعية قائلًا: "هذه لعبتي، أما تلك فهي لعبتك". وتُعد هذه الفترة فرصة ممتازة لتشرحي له الفرق بين الأغراض المشتركة (مثل كتاب العائلة) والأغراض الشخصية.') WHERE id = '2b8c7b62-f908-41ef-8972-07466c4a7bd0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة، تظهر "محاولات التناظر". يحاول طفلكِ طي الورق أو توزيع التفاصيل بشكل متناظر في رسوماته. فعلى سبيل المثال، يضيف أذنًا أو يدًا إلى كل جانب من جانبي الشخص الذي رسمه. وهذا مؤشر على التطور المتناسق لنصفي الدماغ.') WHERE id = 'bd356611-73c3-4619-9883-1f920ac53fa9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"آداب المائدة باستقلالية". أصبح طفلكِ يستخدم الشوكة بمهارة، ويحاول تقطيع الأطعمة الطرية (مثل الموز أو العجة) باستخدام سكين آمنة للأطفال. امنحيه هذه الاستقلالية، فشعوره بالقدرة على خدمة نفسه يعزز ثقته بنفسه من الداخل.') WHERE id = 'a07fbd02-0c2f-49de-ba5e-43f31c0bcc20';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي، تظهر مرحلة "الألعاب ذات القواعد". أصبح طفلكِ مهتمًا بممارسة ألعاب ذات قواعد بسيطة، مثل "الغميضة" أو "المطاردة والإمساك"، دون مخالفة شروطها. وهذه مرحلة مهمة من التكيف الاجتماعي. وعندما يلتزم بالقواعد، احرصي على مدحه بقولكِ: "أحسنت لأنك لعبت بنزاهة".') WHERE id = 'e172dbdc-63ea-4b2b-afac-30588be411eb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«ارتداء الملابس باستقلالية: الأزرار والسحّاب». أصبح طفلكِ متحمسًا الآن لإغلاق الأزرار الكبيرة ورفع السحّاب بمفرده. ويتطلب ذلك تنسيقًا دقيقًا لعضلات الأصابع. امنحيه 5 دقائق إضافية عند ارتداء ملابسه صباحًا ليُكمل هذه العملية بنفسه. فشعوره بالفخر عندما ينجح بمفرده لا يُقدّر بثمن.') WHERE id = '24f54158-6d74-423e-b96c-5270e549d121';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: «انتظار الدور والصبر». أصبح طفلكِ يفهم الآن أن عليه انتظار الطفل الآخر حتى ينزل عن الأرجوحة ليأتي دوره. ويساعد فهم عبارتي «حان دورك» و«حان دوري» على تقليل الخلافات في المواقف الاجتماعية. احرصي على تشجيعه على صبره بقولكِ: «شكرًا جزيلًا لأنك انتظرت دورك».') WHERE id = '97f18e0c-30d0-42a5-aa90-ac6015233d99';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: «إدراك الكمية». بالإضافة إلى قدرته على العد من 1 إلى 10، أصبح طفلكِ الآن قادرًا على معرفة عدد 3 أو 4 أشياء بنظرة واحدة من دون عدّها (subitizing). اسأليه: «كم تفاحة توجد هنا؟»، واطلبي منه أن يعدّها مشيرًا إليها بإصبعه. فهذا هو أساس التفكير الرياضي في المستقبل.') WHERE id = '6e61f63b-18f2-4f84-b98e-0d07b524e3e9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «إمساك الكرة بكلتا اليدين». بدأ طفلكِ الآن يمسك الكرة التي تُرمى نحوه ببطء، وذلك بثني ذراعيه وضم يديه إلى صدره. وهذا دليل على تطور سرعة الاستجابة والتناسق بين اليد والعين. نظّمي معه في المنزل جلسات قصيرة للعب «ارمِ والتقط» باستخدام كرة ناعمة.') WHERE id = 'eb5816aa-f53e-4699-abf2-d1ff0b98f5f9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: «المفاهيم المجرّدة: الزمن». رغم أن طفلكِ لا يفهم بعد سؤال «كم الساعة؟»، فإنه يحاول استخدام كلمات مثل «غدًا» و«أمس» و«لاحقًا» في مواضعها الصحيحة. اشرحي له الزمن من خلال الروتين اليومي، مثل: «عندما تستيقظ من النوم، سيكون قد حلّ الغد». فهذا يساعده على رؤية العالم بصورة أكثر تنظيمًا وقابلية للتوقع.') WHERE id = '6c159ac6-63d6-41de-9c9e-e48fdddeeaef';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: «عدم الخوف من الفشل». عندما لا ينجح طفلكِ في إنجاز شيء ما، مثل بناء برج بالمكعبات، فإنه لم يعد يبكي فورًا، بل قد ينظر إليكِ ويسأل: «هل أحاول مجددًا؟». امدحي جهده لا النتيجة، وقولي له: «لقد بذلت جهدًا كبيرًا وحاولت مجددًا، أحسنت!». أنتِ رفيقة درب رائعة!') WHERE id = '487ce40e-d1a5-42bb-ab35-fd94c37e1b74';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الأسئلة الهادفة» في الكلام. لم يعد طفلكِ يسأل فقط: «ما هذا؟»، بل أصبح يسأل: «كيف يعمل هذا؟». فهو يبدي اهتمامًا بالآلية الداخلية للأشياء. عند الإجابة، لا تدخلي في تفاصيل معقدة جدًا، لكن حافظي على التسلسل المنطقي. هذه الأسئلة هي الشرارات الأولى للتفكير العلمي مستقبلًا.') WHERE id = 'fda8c637-494b-4891-b635-d2a91f4dbd7b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«تركيب الأشكال» في المهارات الحركية الدقيقة. لم يعد طفلكِ يرسم دائرة فحسب، بل يربط الدوائر معًا ليصنع «يرقة» أو «رجل ثلج». وهذا يدل على قدرته على دمج الرموز البصرية لابتكار معانٍ جديدة.') WHERE id = 'c2392a7c-85eb-4d9e-aff3-15371b541a80';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مفاوضات «سياسية». بدأ طفلكِ الآن «يساومكِ»: «إذا رتبتُ ألعابي، فهل ستقرئين لي قصة أخرى؟». وهذا يدل على أنه يتعلم آليات التأثير الاجتماعي. كوني عادلة في هذه «المفاوضات»، لكن حافظي على قواعدكِ الأساسية.') WHERE id = '1c3607b2-8132-49bc-b9ba-d3f310a2378b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«السيناريوهات الخيالية» في السلوك الاجتماعي. أصبحت الألعاب الآن أكثر تعقيدًا: «أنا الطاهي وأنتِ الزبونة، وعليكِ أن تدفعي لي المال». من خلال هذه الألعاب، يختبر طفلكِ الأدوار الاجتماعية والعلاقات الاقتصادية. سايري سيناريوهاته لتحفيز هذه العملية الإبداعية.') WHERE id = '74c3e2b6-b59d-47f7-ac39-b3a6571a3f4e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«وظائف الأشياء» في التطور المعرفي. لم يعد طفلكِ يصنّف الأشياء وفقًا لمظهرها فقط، بل بحسب وظيفتها أيضًا: «هذه أدوات للقطع (المقص والسكين)»، و«هذه أدوات للكتابة». وهذا يدل على أن قاعدة المعلومات في دماغه أصبحت أكثر تنظيمًا وارتباطًا بالوظائف.') WHERE id = '78693b6d-347d-4486-94dc-37e920221a4d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «الاستقلالية على الدرج». أصبح طفلكِ يصعد الدرج بثقة، واضعًا قدمًا على كل درجة بالتناوب، ومن دون الاستناد إلى شيء تقريبًا. وهذا يعكس تطورًا كبيرًا في كل من التوازن وقوة عضلات الساقين.') WHERE id = 'cc0be0ea-ed32-4ad7-a00e-446a9d717d47';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة «لأن» في الكلام. يحاول طفلكِ تبرير تصرفاته، فيقول مثلًا: «لن أرتدي هذا لأنه يزعجني». استمعي إلى عباراته التي تبدأ بـ«لأن»، فهذا يعزز قدرته على التعبير بعقلانية عن احتياجاته وما يزعجه.') WHERE id = '1172f061-c7e1-4517-8b34-e51a76cdf51e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: «الفرح لنجاح الآخرين». أصبح طفلكِ قادرًا على قول «أحسنتِ!» عندما يرى نجاحكِ، أو «أحسنتَ!» عندما يرى نجاح أحد أصدقائه، كالفوز في لعبة مثلًا. وهذا مؤشر على تراجع التمركز حول الذات، أي التفكير في النفس فقط، وبداية الشعور بالفرح الاجتماعي. إنكِ تنشئين شخصًا رائعًا!') WHERE id = 'e58983bd-cd78-4d0a-8590-e07b73fa9e05';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يعد طفلكِ يطرح أسئلة «لماذا؟» لمجرد الحصول على إجابة، بل لفهم تسلسل الأسباب والنتائج. ويزداد اهتمامه بالظواهر الطبيعية، فيسأل مثلًا: «لماذا تتساقط الأوراق على الأرض؟». قدّمي له إجابات بسيطة تستند إلى حقائق علمية، فهذا يساعده على تكوين نظرة تحليلية إلى العالم من حوله.') WHERE id = '8335f345-0d57-482d-b821-779e730295ca';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«إتقان التوازن» في الحركة الجسدية. أصبح طفلكِ يمشي بثقة مع الحفاظ على توازنه فوق ممر ضيق أو حبل موضوع على الأرض. وهذه مرحلة متقدمة من تطور الجهاز الدهليزي المسؤول عن التوازن. العبي معه في المنزل لعبة «السير على الحبل» لتعزيز دقة حركاته.') WHERE id = '00cce1f4-ca47-462d-b84a-6205502d4f13';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الجمع بين الماضي والمستقبل» في الكلام. أصبح طفلكِ يستخدم الفروق الزمنية بصورة صحيحة في الجملة، فيقول مثلًا: «ذهبتُ إلى الحديقة أمس، وسأذهب إلى منزل جدتي غدًا». ولترسيخ مفهوم الزمن لديه، واصلي تذكيره بروتين يومه وفق تسلسل «أولًا، الآن، ثم».') WHERE id = '10538e9b-c203-4dd2-8b24-d807c72fa3fb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«رسم شخص بتفاصيل دقيقة» ضمن المهارات الحركية الدقيقة. أصبح طفلكِ يضيف مزيدًا من التفاصيل، مثل الأصابع أو الشعر أو العينين، عندما يرسم شخصًا بخطوط بسيطة. وهذا يوضح مدى تطور قدرته على الملاحظة البصرية ودقة التنسيق بين اليد والدماغ.') WHERE id = 'e534e280-1b5b-4f3e-b1db-79a0cf64e3af';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: «التصور البصري للزمن». أصبح طفلكِ الآن قادرًا على الإجابة بتسلسل عن سؤال: «ماذا فعلنا أمس؟». أعدّي له «خطة يومية» تعرض أحداث اليوم بالصور. فهذا يحوّل مفهوم الزمن لديه من فكرة مجردة إلى شيء ملموس.') WHERE id = 'ecad2493-1c0b-4ab4-b089-7a992488d7c5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الحركي: «رمي الكرة نحو الهدف». لم يعد طفلكِ يرمي الكرة عشوائيًا، بل يحاول إدخالها في صندوق محدد أو إصابة هدف معين. وهذا ينمّي قدرته على تقدير المسافة وضبط القوة في المكان (التقدير المكاني).') WHERE id = '6f552613-227f-4085-940c-f293c42bd5f1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: «التعمق في الأسئلة». قد يطرح طفلكِ أسئلة وجودية صعبة مثل: «ما الموت؟» و«من أين أتينا؟». عند الإجابة، كوني صادقة دائمًا، لكن اختاري تفسيرات بسيطة ومطمئنة تناسب عمره. فهذه الأسئلة تعكس محاولته لفهم العالم وإضفاء معنى عليه.') WHERE id = '5eb1ed63-47a4-4170-b1fc-b58d4507160b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: «التعبير عن الذات بالإبداع». أصبح طفلكِ يلجأ إلى الرسم أو «الفضفضة» مع ألعابه ليشعر بالارتياح عندما يكون منزعجًا. انتبهي إلى رسوماته؛ فالألوان والأشكال مرآة لعالمه الداخلي. أنتِ ملاذه الأكثر أمانًا، وثقته بكِ هي أعظم مصدر لقوته.') WHERE id = '48efdb3a-063c-40d5-837a-9373492693c6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ مهتمًا بالكتابات من حوله. وقد يفرح عندما يرى في أسماء المتاجر أو عناوين الكتب حروفًا يعرفها، مثل الحرف الأول من اسمه. هذه هي مرحلة «محو الأمية المبكرة». لا تجبريه على تعلم الحروف، بل حفّزي فضوله فحسب.') WHERE id = '4c700caf-0287-4ea7-8bd0-73ca97292800';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور البدني: «نزول الدرج بالتناوب بين القدمين». بدأ طفلكِ الآن ينزل الدرج بوضع قدم واحدة على كل درجة والتبديل بين القدمين. وهذا أصعب من صعود الدرج ويتطلب قدرًا كبيرًا من التوازن. ما عليكِ سوى الوقوف بالقرب منه لتمنحيه شعورًا بالأمان.') WHERE id = '970cfec9-666d-4324-ad8a-2d2689753b64';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بكِ في الشهر الـ٤١! خلال هذه المرحلة، يبدأ مفهوم "النية" بالتشكّل لدى طفلكِ. ويبدأ بالتمييز بين ما إذا كانت الأحداث قد وقعت مصادفةً أم عن قصد. فمثلًا، إذا لمسه أحد، قد يسأل: "هل فعلت ذلك عمدًا؟" وهذه خطوة مهمة لفهم الصدق والنوايا في العلاقات الاجتماعية.') WHERE id = 'be82050e-9ad6-486e-9d98-a2c2c31a243e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في النشاط البدني: "القفز على قدم واحدة". يحاول طفلكِ الآن القفز على قدم واحدة عدة مرات متتالية. ويتطلب ذلك قوةً وقدرةً عالية على التوازن. ادعمي هذه المهارة باللعب معه في الحديقة لعبة "سباق القفز على قدم واحدة".') WHERE id = '59f9bda8-ddf4-49be-ad49-7ae815287273';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الكلام: "أدوات الربط المنطقية". أصبح طفلكِ يستخدم أدوات الربط مثل "لكن" و"لأن" و"إذا" بمهارة في جمله. "أريد الذهاب إلى الحديقة، لكن الجو ممطر". ويُظهر ذلك قدرته على الجمع بين الأفكار المتعارضة في ذهنه. أطيلي حواراتكِ معه باستخدام أدوات الربط هذه.') WHERE id = 'b5dc9cdd-e5bc-4c21-ba9e-2e9fe7dbdaee';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: "قص الورق". أصبح طفلكِ قادرًا على قص الورق باتباع خط مستقيم مرسوم عليه، مستخدمًا مقصًا آمنًا. وهذا دليل على بلوغ التنسيق بين اليد والعين مستوى متقدمًا. قدّمي له أوراقًا ملونة وقوالب لتنفيذ أنشطة القص واللصق.') WHERE id = '93689350-75d1-4dc3-befa-2516fff9cb92';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"التنظيم الذاتي (Self-regulation)". أصبح طفلكِ قادرًا على استخدام الأساليب التي اقترحتِها عليه لتهدئة نفسه عندما يغضب أو يحزن، مثل التنفس بعمق أو احتضان لعبته. ويُعدّ التنظيم الذاتي من أهم المهارات الحياتية المرتبطة بالذكاء العاطفي.') WHERE id = 'cad2a6f6-14d3-4ac8-a455-240edf668e56';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: "الألعاب الجماعية ذات القواعد". أصبح طفلكِ مهتمًا باللعب ضمن مجموعة وفق قواعد موحّدة. فعندما تقولين: "الآن سنقفز جميعًا مثل الأرانب"، يتفاعل مع المجموعة ويلتزم بما تفعله. وهذا أساس مهارة "التصرف ضمن المجموعة"، وهي مهارة مهمة في البيئة المدرسية.') WHERE id = '6f7c2344-f4ee-4701-9810-594e0c930fc0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«حماية الحدود الشخصية». أصبح طفلكِ يحدّد مساحته الخاصة بعبارات مثل «غرفتي» و«طاولتي». احترمي إحساسه بهذه المساحة. فعندما تسألينه: «هل يمكنني الدخول إلى غرفتك؟»، تعلّمينه احترام الحدود الشخصية والتعرّف مستقبلًا إلى حدود الآخرين أيضًا.') WHERE id = '19704700-4f78-4a2f-8063-e34e01705522';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الإحساس بالعدالة» في السلوك الاجتماعي. أصبح طفلكِ يتفاعل مع مخالفة القواعد في الألعاب، فيقول مثلًا: «لقد تجاوز دوره!». وهذا دليل على تطوّر فهمه للعدالة الاجتماعية والقواعد. اشرحي له سبب أهمية القواعد، كأن تقولي إنها تجعل اللعب ممتعًا، وبذلك ترسّخين لديه أسس الأخلاق الاجتماعية.') WHERE id = 'bb50baca-3306-43e8-84f0-8ecfe4ce2ed7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الربط بين الكمية والرقم» في التطور المعرفي. يستطيع طفلكِ العدّ حتى 10، لكنه بدأ الآن يربط الأرقام بالكميات. عندما تقولين: «وضعت هنا 5 حبات من البندق»، يمكنه تقدير الكمية بصريًا. أعطيه في أثناء الأنشطة اليومية مهام مثل: «أعطني 4 ملاعق».') WHERE id = '3b180a00-84f2-4ef7-b180-bb007866d4c3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «السرعة على الدراجة ثلاثية العجلات». أصبح طفلكِ يقود الدراجة بسرعة أكبر ويناور لتجاوز العوائق. وهذا يعكس تطور قوة الجزء السفلي من جسمه والتناسق البصري الحركي. حدّدي له في الحديقة «مسارات للقيادة» تكون آمنة ليختبر سرعته.') WHERE id = 'cf35973e-cf99-454b-b4d7-5058e5466945';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«المزاح والفكاهة» في الكلام. بدأ طفلكِ يتلاعب بالكلمات ويحاول إضحاككِ بتكوين جمل «غريبة». فقد يقول مثلًا: «قال الكلب: مياو» ثم يضحك. وهذا يدل على أنه يعرف قواعد اللغة ويخالفها عمدًا لصنع الفكاهة. اضحكي معه وساعديه على تنمية حسه الفكاهي.') WHERE id = '7856919f-0f1f-4c55-9554-5d9226e933f6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'رحلة رائعة امتدت 1200 يوم! لقد أتمّ طفلكِ الآن 40 شهرًا. وأصبح فردًا متكاملًا، إنسانًا صغيرًا له أفكاره ومزاحه وأحلامه الخاصة. طوال هذه الأيام الـ1200، كنتِ مهندسة عالمه. وفي نظراته الواثقة بصمة حبكِ. أنتِ أم رائعة!') WHERE id = '1104a81e-20a0-469a-b38d-bffb8442b875';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«اللباقة ومراعاة الفروق الدقيقة» في الكلام. بدأ طفلكِ يكيّف نبرة صوته وكلماته وفقًا للشخص الذي يتحدث إليه (فمثلًا يتحدث بلطف أكبر مع الرضيع وبجدية أكبر مع البالغين). وهذه هي بداية اكتساب مهارات علم اللغة الاجتماعي. إن أسلوبكِ المهذب في الحديث هو نموذجه الأساسي والأفضل.') WHERE id = '3eaa8096-e288-4159-9aa2-8223399dd023';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: «الثناء على النفس». عندما ينجح طفلكِ في إنجاز شيء ما، ينتظر منكِ التأكيد قائلًا: «انظري كم أحسنتُ فعل هذا!». استجيبي لشعوره الداخلي بالفخر بقولكِ: «نعم، لقد بذلتَ جهدًا كبيرًا». دعمكِ هو ما يبني ثقته بنفسه في المستقبل!') WHERE id = '97ef6f09-4fed-4fcd-abbe-7756d8045e1e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ قادرًا على تصنيف الأشياء وفق عدة خصائص في الوقت نفسه، مثل: «الألعاب الكبيرة والزرقاء معًا». وهذا مؤشر على المرونة المعرفية (cognitive flexibility). أعطيه مهام بحث ممتعة مثل: «هيا نعثر على جميع الأشياء الناعمة والحمراء».') WHERE id = '0d946fb4-d148-46c8-80fc-f0a7b324c07f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الركض والتوقف بحرية» ضمن المهارات الحركية. أصبح طفلكِ قادرًا على التوقف فورًا عند سماع أمركِ «توقف!» من دون أن يفقد توازنه، حتى عندما يركض بأقصى سرعة. وهذا يوضح مدى تطور تحكمه العصبي العضلي. إن لعبة «الضوء الأحمر، الضوء الأخضر» في الحديقة تمرين ممتع ومفيد في آنٍ واحد.') WHERE id = '824aa9f8-040c-4665-a6d8-64a894fd7261';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الكلمات المتضادة» في الكلام. لم يعد طفلكِ يفهم أزواج الأضداد مثل «ساخن وبارد» و«طويل وقصير» و«ثقيل وخفيف» فحسب، بل يستخدمها أيضًا في حديثه. اطرحي عليه ألغازًا عن الأضداد، مثل: «الفيل كبير، فكيف يكون الفأر؟». فهذا يُثري حصيلته اللغوية ويُنمّي تفكيره القائم على المقارنة.') WHERE id = '56f799be-0231-4113-94ee-9fbaa18f177f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«تفاصيل رسم الإنسان» ضمن المهارات الحركية الدقيقة. أصبح طفلكِ يحاول إضافة الذراعين والساقين، وحتى الأصابع، إلى الشخص الذي يرسمه. وتعكس هذه الرسومات كيفية إدراكه لجسده وللأشخاص من حوله. أنصتي إلى شرحه لكل «عمل فني» كما لو كان قصة صغيرة.') WHERE id = '0006f22d-7d35-4a7c-abab-057194f6402c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«ألعاب الكلمات والقوافي» في تطور النطق. يستمتع طفلكِ بالعثور على كلمات متشابهة في النطق، مثل: «كرة-دُرّة»، «تفاحة-راحة». وهذا دليل على تطور الوعي الصوتي، أي القدرة على التمييز بين الأصوات. اقرئي معه قصائد قصيرة ذات قوافٍ أو العبي معه ألعاب الكلمات. فهذا يبني أساسًا متينًا لمهارة القراءة مستقبلًا.') WHERE id = '2fa13e97-2173-4c5c-afa8-90f8eaedaa8a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«العُقد والحلقات» في المهارات الحركية الدقيقة. بدأ طفلكِ يُبدي اهتمامًا بأربطة الأحذية أو الخيوط، ويحاول لفّها بعضها حول بعض. قدّمي له خرزًا ذا ثقوب كبيرة أو «ألعاب ربط» مخصصة. فهذا يُهيّئ عضلات أصابعه الصغيرة للكتابة وللمهام الأكثر تعقيدًا.') WHERE id = '5b2e2766-e73a-4ec2-b386-7bdc27e2bf73';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«المخاوف الخيالية». يكون خيال طفلكِ في هذه المرحلة قويًا لدرجة أنه قد يخاف من الظلام أو من «وحوش» يتخيلها. لا تسخري من خوفه ولا تقولي له: «هذا غير حقيقي». وبدلًا من ذلك، كوني له ملاذًا عاطفيًا وقولي: «أنا هنا، وسأحميك». فهذا يجعل ثقته بكِ راسخة لا تتزعزع.') WHERE id = 'b420b26f-d658-40bc-93d9-fcbe9a159330';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«محاولات دبلوماسية» في السلوك الاجتماعي. بدأ طفلكِ يحاول حل النزاعات عبر تقديم اقتراحات مثل: «أعطني هذا، وسأعطيك ذاك». وهذه من أوضح علامات الذكاء الاجتماعي. شجّعي جانب «المفاوض» لديه وادعمي الحلول العادلة.') WHERE id = '4ee1a693-af27-4c8f-b294-06b8239d80b9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«تجارب ثبات الكمية» في التطور المعرفي. إذا سكبتِ الكمية نفسها من الماء في أوعية مختلفة الأشكال، فقد يظل طفلكِ يعتقد أن الوعاء الأطول يحتوي على ماء أكثر. العبي معه بالماء أو الرمل، وأتيحي له فرصة اكتشاف أن الكمية لا تتغير بتغيّر شكل الوعاء من خلال التجربة العملية.') WHERE id = '13a54bb2-22dc-4956-ad40-80e7f13eda7c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الحركي: «التوقف والالتفاف السريعان». أصبح طفلكِ قادرًا على التوقف فورًا أو تغيير اتجاهه بسرعة أثناء الجري عندما تقولين له: «توقف!». وهذا ناتج عن العمل المتكامل بين العضلات والجهاز العصبي. العبي معه في الحديقة لعبة «الضوء الأحمر، الضوء الأخضر»؛ فهي تعزز لديه مهارة ضبط النفس (التحكم التثبيطي).') WHERE id = '29ee5396-69c9-428e-9152-0052da7ababd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يعد طفلكِ يصنّف الأشياء حسب لونها فحسب، بل حسب وظيفتها أيضًا: «هذه للأكل»، «وهذه للارتداء». العبي معه في المنزل لعبة «ما الشيء المختلف؟» (ضعي مثلًا ٣ فواكه ولعبة واحدة). يساعد ذلك على تطوير قدرته على التفكير المنطقي والتمييز.') WHERE id = 'c4b0066e-1d1d-4a2d-b280-39f147e134fe';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«المناورة السريعة» في الحركة الجسدية. أصبح طفلكِ قادرًا على رؤية العائق أمامه أثناء الركض بأقصى سرعته والالتفاف حوله دون أن يسقط. ويمثّل ذلك مستوى متقدمًا من مهارة «التخطيط الحركي» في الدماغ. أنشئي له مسارًا صغيرًا للعوائق في الحديقة. فهذا يعزز تحكمه بجسمه ورشاقته.') WHERE id = 'b1971b1f-63a0-40cf-bb46-3ba6bb8689b2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«تفاصيل الماضي» في تطور الكلام. أصبح طفلكِ قادرًا على مشاركة ذكريات معقدة، مثل: «عندما ذهبنا إلى بيت جدتي أمس، تناولنا المثلجات». إن التحدث معه عن اليوم السابق يقوّي ذاكرته العرضية. شجّعيه على توسيع قصته بسؤاله: «ماذا تتذكر أيضًا؟».') WHERE id = 'f5184b0f-58ef-4b72-af3f-546cec7ec971';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«نسخ الأشكال» ضمن المهارات الحركية الدقيقة. يحاول طفلكِ الآن تقليد علامة الجمع (+) أو الدائرة (O) أو بعض الحروف التي ترسمينها. ويعكس ذلك التكامل البصري الحركي، أي التنسيق بين العين واليد. أعطيه أقلام تلوين وشجّعيه على رسم أشكال هندسية متنوعة.') WHERE id = '5ee5e247-d8bd-4375-9669-ceda6b1b0a73';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«العدالة والقواعد». أصبح طفلكِ يعترض عند مخالفة قواعد اللعب قائلًا: «لقد أخذ دوري!». وهذا دليل على تطور وعيه الاجتماعي بذاته. ومن خلال توضيحكِ له أن القواعد تنطبق على الجميع بالتساوي، فإنكِ تعززين لديه حس العدالة الداخلي والانضباط الاجتماعي.') WHERE id = 'd1358d5f-b48d-4121-a736-887203ecfc67';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«محاولات القيادة» في السلوك الاجتماعي. أصبح طفلكِ يرغب في وضع سيناريو اللعب بنفسه، فيقول مثلًا: «سأكون أنا الطبيب، وأنتِ المريضة». ومن خلال ألعاب تقمّص الأدوار هذه، يفهم العالم ويتعلم اتخاذ القرارات. سايريه أحيانًا في السيناريو الذي يضعه؛ فهذا ينمّي لديه حس القيادة والمسؤولية.') WHERE id = 'd27742a4-8533-4759-aff4-185d7dbf081f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التوافق بين الكمية والرقم» في التطور المعرفي. إلى جانب قدرة الطفل على العد حتى 5، أصبح بإمكانه الآن عندما يرى الرقم «3» أن يختار 3 ألعاب ويضعها جانبًا. وهذا هو أساس اكتساب المهارات الرياضية مستقبلًا. أعطيه في المهام اليومية تعليمات مثل: «أعطني 4 تفاحات».') WHERE id = '0f53eb59-1dad-4d39-84e5-43e97150561c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «القفز بكلتا القدمين». أصبح الطفل الآن قادرًا على القفز بحرية فوق العوائق بكلتا قدميه في الوقت نفسه. ويتطلب ذلك قوة الجزء السفلي من الجسم والتناسق الحركي المتزامن. ضعي حبلًا على أرضية المنزل والعبا معًا لعبة «عبور النهر» بالقفز فوقه.') WHERE id = '080c3ee9-a0ea-4062-9f79-5fba44d2d0e4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«المزاح والفكاهة» في تطور النطق. أصبح الطفل الآن يحاول إضحاككِ عن قصد عبر نطق الكلمات بطريقة خاطئة أو إصدار أصوات مضحكة. وهذا أحد أشكال إدراكه لقواعد اللغة. اضحكي على مزاحه وساعديه على تنمية حس الفكاهة لديه.') WHERE id = '9fb34927-219f-4b2d-bb9f-dda7da92c634';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: «الاعتراف بالخطأ». عندما يكسر الطفل شيئًا أو يُحدث فوضى، لم يعد يحاول إخفاء الأمر فورًا، بل يمكنه أن يقول: «أنا فعلت ذلك». لا تعاقبيه في لحظة الصدق هذه؛ بل اقترحي عليه أن تنظفا المكان معًا. أنتِ ملاذه الآمن!') WHERE id = 'c4b6f5da-e09e-4e7a-8e0a-9a60747fa087';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح الطفل الآن قادرًا على تصنيف الأشياء وفقًا للون والشكل في الوقت نفسه. فهو يربط بين التفاصيل قائلًا: «هذا أحمر ودائري أيضًا». ويُعد ذلك مؤشرًا مهمًا على المرونة المعرفية. قدّمي له ألعابًا تحتوي على أشكال هندسية متنوعة.') WHERE id = '2b4289d9-5b1f-4994-a054-e4727135705c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«القفز الديناميكي» في التطور الحركي. أصبح الطفل الآن قادرًا أثناء الركض على القفز فوق عائق صغير يظهر أمامه من دون إبطاء سرعته. ويعكس ذلك تطور قدرته الدماغية على التخطيط المسبق للحركة (التخطيط الحركي). يمكنكِ إعداد عوائق صغيرة له في الحديقة.') WHERE id = 'ae389307-05d6-4296-90e1-0a21e776e282';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«رفيق اللعب الخيالي». قد يبتكر بعض الأطفال في هذه المرحلة أصدقاء خياليين. وهذا يدل على ثراء إبداع الطفل وعالمه العاطفي. لا تلوميه ولا تقولي له إن ذلك «كذب». فمن خلال هذا الصديق، يستكشف الطفل مخاوفه أو رغباته. راقبيه بصبر واهتمام.') WHERE id = '9ce75a82-fd02-47a8-adbb-96eadd2b8653';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«القيادة واتباع الآخرين» في السلوك الاجتماعي. أصبح طفلكِ أحيانًا يضع القواعد أثناء اللعب، وأحيانًا أخرى يتكيف مع قواعد غيره. وهذا هو أساس المرونة الاجتماعية. العبِي معه في المنزل مع تبديل الأدوار: «الآن كن أنت المعلم، وسأكون أنا التلميذة».') WHERE id = 'd0b4ac9e-9bd0-4b78-83ac-e932a23bb3ff';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«سلسلة السبب والنتيجة» في التطور المعرفي. أصبح طفلكِ قادرًا على الاستدلال المنطقي، كأن يقول: «إذا هطل المطر، فلن نتمكن من الذهاب إلى الحديقة». تحدثي معه عن نتائج الأحداث. فهذا ينمّي لديه القدرة على فهم مسؤوليته عن أفعاله مستقبلًا (العواقب المنطقية).') WHERE id = '44001e8a-e9dc-4edd-96dc-e3baba2b5ba4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «إتقان ركوب الدراجة ثلاثية العجلات». أصبح طفلكِ قادرًا على تحريك الدواسات بإيقاع منتظم أثناء توجيه المقود، واستخدام المكابح عند الحاجة. وهذا يعكس التناسق المتزامن بين الجزأين السفلي والعلوي من الجسم. حدّدي له «مسارًا صغيرًا للدراجات» في الحديقة.') WHERE id = 'ec14848a-2298-473c-80f2-13859ca28476';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الطلبات المهذبة» في تطور الكلام. أصبح طفلكِ يستخدم عبارات مثل «هل يمكن؟» و«من فضلكِ» عن قصد للحصول على ما يريده. وأسلوبكِ المهذب هو أفضل قدوة يتعلم منها. عندما يتصرف بأدب، احرصي على الإشادة بذلك: «يسعدني جدًا أن أساعدك لأنك طلبت ذلك بهذه الطريقة الجميلة».') WHERE id = 'c89c5c28-c3bd-46e0-93e1-c16bc60a714b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: «التنظيم الذاتي». عندما لا ينجح طفلكِ في إنجاز شيء ما (مثل تفكك لعبته)، لا يبكي فورًا، بل ينظر إليكِ ويطلب المساعدة أو يحاول مجددًا. وهذه خطوة كبيرة نحو النضج العاطفي. أنتِ أكثر من يدعمه ويمنحه الأمان!') WHERE id = 'a0873db2-259d-4791-a8af-c5e115589858';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الأسئلة الهادفة" في الكلام. لم يعد طفلكِ يسأل فقط: "ما هذا؟"، بل أصبح يسأل: "كيف يعمل هذا؟". فهو يهتم بالآليات الداخلية للأشياء والساعات وعجلات الألعاب. عند الإجابة، حافظي على التسلسل المنطقي؛ فهذه الأسئلة هي الشرارات الأولى للتفكير العلمي مستقبلًا.') WHERE id = 'd2e255d4-c4cb-4992-b207-917bc8c7e987';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"محاولات تحقيق التناظر" في المهارات الحركية الدقيقة. يحاول طفلكِ طي الورق أو توزيع التفاصيل في رسوماته بشكل أكثر تناظرًا (مثل رسم عينين وذراعين للشخص). وهذا يوضح مدى تطور إدراكه البصري المكاني (visual-spatial awareness).') WHERE id = 'b4315b1b-9d62-41cc-a063-b3b09c4c589a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مفاوضات "سياسية". بدأ طفلكِ الآن "يساومكِ": "إذا أكلتُ الخضراوات، فهل يمكننا البقاء مدة أطول في الحديقة؟". وهذا يدل على أنه يتعلم آليات التأثير الاجتماعي. كوني صادقة وثابتة في هذه "المفاوضات"؛ فمن خلالها يتعلم الحدود.') WHERE id = '431cd610-a165-475a-8f4f-464196e237c1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"السيناريوهات الخيالية" في السلوك الاجتماعي. أصبحت الألعاب الآن أكثر تعقيدًا: "أنا البائع، تعالي واشتري مني الخبز". من خلال هذه الألعاب، يختبر طفلكِ الأدوار المختلفة في المجتمع. سايري سيناريوهاته لتحفيز هذه العملية الإبداعية.') WHERE id = '81128f46-ecb8-47f0-aa0b-337c398b3230';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"طقوس الزمن" في التطور المعرفي. رغم أن طفلكِ لم يستوعب تمامًا مفاهيم "الأمس" و"اليوم" و"غدًا"، فإنه يعرف الروتين المتكرر، مثل "الذهاب إلى الحديقة بعد الطعام" أو "حكاية قبل النوم". تساعد هذه التسلسلات على تشكيل الخط الزمني في ذهنه.') WHERE id = '5cb6d50d-147c-44f7-91b0-1d67f401019b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"المناورات الدقيقة" في التناسق الجسدي. أصبح طفلكِ قادرًا على حمل كوب مملوء بسائل دون أن يسكب منه الكثير، أو السير في ممر ضيق. وهذا يوضح مدى تطور التناسق البصري الحركي لديه. عززي انتباهه بمنحه أدوار "المساعد الصغير" في المنزل.') WHERE id = 'efc83589-a712-4c32-9e12-c9ee0f9cee01';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«المخاوف الخيالية». في هذه المرحلة، يكون خيال طفلكِ واسعًا لدرجة أنه قد يخاف من الظلام أو من «وحوش» خيالية. لا تسخري من خوفه ولا تقولي له: «هذا غير حقيقي». وبدلًا من ذلك، كوني ملاذًا عاطفيًا له وقولي: «أنا هنا، وسأحميك». فهذا يجعل ثقته بكِ راسخة لا تتزعزع.') WHERE id = '09cee55c-899d-468c-bef9-66eb86e868c6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«محاولات التفاوض» في السلوك الاجتماعي. أصبح طفلكِ يحاول حل الخلافات من خلال اقتراحات مثل: «أعطني هذا وسأعطيك ذاك». وهذه من أبرز علامات الذكاء الاجتماعي. شجّعي هذا الجانب «التفاوضي» لديه وادعمي الحلول العادلة.') WHERE id = '1f6c2927-0b20-482c-b17f-a447f8fef25d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«تجارب ثبات الكمية» في التطور المعرفي. إذا سكبتِ الكمية نفسها من الماء في أوعية مختلفة الأشكال، فقد يظل طفلكِ يعتقد أن الوعاء الأطول يحتوي على ماء أكثر. أتيحي له فرصة اكتشاف أن الكمية لا تتغير بتغيّر الشكل، وذلك من خلال اللعب معه بالماء أو الرمل.') WHERE id = '73557d3a-6c9c-4c6a-a67f-c5d4bc801f0d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الحركي: «التوقف والالتفاف بسرعة». أصبح طفلكِ قادرًا على التوقف فورًا أثناء الركض عندما تقولين له: «توقّف!» أو على تغيير اتجاهه بحدة. وهذا نتيجة العمل المتكامل بين العضلات والجهاز العصبي. العبي معه في الحديقة لعبة «الضوء الأحمر، الضوء الأخضر»؛ فهي تعزّز قدرته على ضبط النفس.') WHERE id = '2c94b5e7-3f3c-4f5a-97ae-e15891e8c592';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«اللباقة والفروق الدقيقة» في الكلام. بدأ طفلكِ يكيّف نبرة صوته وكلماته وفقًا للشخص الذي يتحدث إليه؛ فمثلًا يتحدث بلطف أكبر مع الرضيع وبجدية أكبر مع الكبار. وهذه بداية اكتساب الكفاءة اللغوية الاجتماعية. إن أسلوبكِ المهذب في الحديث هو النموذج الأهم والأفضل له.') WHERE id = '708f00c5-3974-4a48-b57b-7ac187203dd5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: «الثناء على الذات». عندما ينجح طفلكِ في إنجاز مهمة، يقول: «انظري كم أحسنتُ فعل هذا!» منتظرًا تقديركِ. استجيبي لشعوره الداخلي بالفخر بقولكِ: «نعم، لقد بذلتَ جهدًا كبيرًا». دعمكِ هو الذي يبني ثقته بنفسه في المستقبل!') WHERE id = '1eae35d0-6f20-4979-87f2-c88eacf3b104';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح الطفل الآن يطبّق تسلسل «قبل، الآن، ثم» على الأحداث المعقدة: «أولًا سأغسل يدي، ثم سأتناول الطعام، وفي النهاية سألعب». وهذا دليل على تطور قدرته على التخطيط والتنظيم الذهني (الوظائف التنفيذية). كلّفيه بوضع خطط صغيرة خلال اليوم، فهذا يعزز لديه الشعور بالنظام والانضباط.') WHERE id = 'c4e864cd-f8ff-486c-994b-11d240e723ca';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في مجال الحركة الجسدية: «المناورة بالدراجة ثلاثية العجلات». أصبح الطفل الآن قادرًا على رؤية العوائق التي تعترض طريقه أثناء ركوب الدراجة وإدارة المقود في الوقت المناسب. وهذا يجمع بصورة متكاملة بين مهارة تدوير الدواسات (الجسدية) ومهارة متابعة الطريق (البصرية).') WHERE id = '63226ba2-0699-459a-be66-a4c9af97d876';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في مجال النطق: «حوارات السبب والنتيجة». أصبح الآن يستفسر عن القرارات التي تتخذينها: «لماذا يجب أن أنام؟». عند الإجابة، قدّمي له تفسيرات منطقية: «لأن جسمك يحتاج إلى الراحة حتى تتمكن من اللعب غدًا بنشاط من جديد». يساعد هذا النهج الطفل على اكتساب انضباط قائم على المنطق، لا على الطاعة العمياء.') WHERE id = 'aba02008-e74d-4081-9df9-4e23bad078b6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في مجال المهارات الحركية الدقيقة: «قص الورق». يحاول الطفل الآن قص الورق على طول خط مستقيم (أو قص دائرة بسيطة) باستخدام مقص آمن. ويُعدّ هذا أحد أهم اختبارات التناسق بين اليد والعين. قدّمي له أوراقًا ملونة وقوالب مخصصة للقص لمساعدته على تدريب عضلاته.') WHERE id = 'd337c2b8-8f8a-4037-8a7a-e030f9920b04';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الحدود والمشاركة». أصبح الطفل الآن يفهم أن بعض الأشياء ملك للجميع (مثل الأرجوحة في الحديقة)، بينما تخصه أشياء أخرى وحده. احترمي شعوره بالملكية بقولكِ له: «هذه لعبتك، ومشاركتها خيارك». فالطفل الذي تُحترم ممتلكاته يتعلم بسهولة أكبر احترام ممتلكات الآخرين أيضًا.') WHERE id = '9f384019-50a1-4540-baab-8643e931568a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: «ألعاب الأدوار المعقدة». أصبحت للألعاب الآن حبكة قصصية: «أنت مريض، وأنا الطبيب، وسأعطيك حقنة». ومن خلال هذه الألعاب، يعالج الطفل مخاوفه من مواقف الحياة الواقعية (مثل الخوف من الطبيب). شاركي بفاعلية في السيناريو الذي يضعه.') WHERE id = '9206ce15-0a76-4431-b07b-049bdcbed6b0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: "مطابقة الكمية بالعدد". أصبح طفلكِ يعرف العد حتى 5، كما يستطيع عند سماع الرقم "3" تمييز 3 أشياء بصريًا. أعطيه مهام مثل: "أعطني 4 ملاعق". هذه أول مرحلة مهمة يبدأ فيها بربط الأرقام المجرّدة بالعالم الحقيقي.') WHERE id = 'eaf2d09d-f792-4b9d-ab37-65dbbde32f39';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "القفز بكلتا القدمين". أصبح طفلكِ قادرًا على القفز بحرية فوق العوائق (مثل حبل موضوع على الأرض) بكلتا قدميه في الوقت نفسه. يتطلب ذلك قوة الجزء السفلي من الجسم والتناسق الحركي المتزامن. عززي نشاطه من خلال لعب لعبة "عبور النهر" معه في المنزل.') WHERE id = '9a61025f-abc9-4c98-bf07-819847137992';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: "المزاح والفكاهة". يحاول طفلكِ إضحاككِ من خلال تعمّد نطق الكلمات بطريقة خاطئة أو إصدار أصوات مضحكة. يدل ذلك على أنه يعرف قواعد اللغة ويتعمد مخالفتها ليصنع الفكاهة. ضحككِ على مزاحه يعزز ثقته بنفسه وذكاءه الاجتماعي.') WHERE id = 'b25c4c56-1f97-4223-b20b-689b5e94d1d3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: "التعامل مع الإخفاق". عندما لا ينجح طفلكِ في مهمة ما (مثل بناء برج من المكعبات)، فإنه لم يعد يبكي فورًا، بل قد ينظر إليكِ ويسأل: "هل أحاول مرة أخرى؟". امدحي جهده لا النتيجة: "لقد بذلت جهدًا كبيرًا، أحسنت!". أنتِ أكبر مصدر لتحفيزه!') WHERE id = 'f9148bba-3642-4b13-ad48-62db8da7ed80';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ يميّز الأشياء ليس حسب مظهرها فحسب، بل وفقًا للمادة المصنوعة منها أيضًا: "هذا بلاستيك، أما هذا فمعدن". قدّمي له أشياء ذات ملمس مختلف واسأليه عن الفروق بينها. يساعده ذلك على تحليل العالم المحيط به بمزيد من التفصيل وتنظيم معلوماته عن العالم المادي.') WHERE id = '80e00e5a-2a93-4c1b-a710-db553822e4ae';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية: "التوازن على قدم واحدة". أصبح طفلكِ قادرًا على الوقوف على قدم واحدة لأكثر من 5 ثوانٍ. يدل ذلك على نضج التناسق بين المخيخ والعضلات. العبي معه "لعبة اللقلق" لتعرفا مَن يستطيع الوقوف مدة أطول.') WHERE id = '18ab2c20-2470-41d2-b5e5-3121b8d7e0c1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«قاموس المشاعر» في الكلام. لم يعد الطفل يقول فقط «أنا منزعج» أو «أنا بخير»، بل يستخدم في مواضعها كلمات مثل «غضبت»، و«اشتقت»، و«أنا سعيد». تقبّلي مشاعره وأكّديها بقولكِ: «من الطبيعي أن تبكي لأنك اشتقت». فهذا من أهم ضمانات صحته النفسية والعاطفية.') WHERE id = 'e498f733-de85-4e45-8875-b886111a89f8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في ذروة سن الثالثة والنصف! لقد تجاوز طفلكِ الآن مرحلة الرضاعة تمامًا، ودخل أكثر فترات مرحلة «الطفولة المبكرة» نشاطًا. وأصبح الآن فردًا متكاملًا جسديًا وعاطفيًا. خلال هذه الأيام الـ1250، وضعتِ أساسًا راسخًا لشعوره بالأمان والثقة في عالمه. افتخري بنفسكِ!') WHERE id = 'a45a87d4-253c-4fea-ac32-9cea3f5b1168';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بدأ طفلكِ يهتم الآن بالكلمات المكتوبة من حوله. وقد يفرح عندما يرى في أسماء المتاجر أو عناوين الكتب حروفًا يعرفها، مثل الحرف الأول من اسمه. هذه هي مرحلة «الوعي المبكر بالقراءة والكتابة». لا تجبريه على تعلّم الحروف، بل حفّزي فضوله فحسب.') WHERE id = '0aedbd42-1452-4a3e-aa54-4adb1ad4a556';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في النمو الجسدي: «نزول الدرج بتبادل القدمين». يبدأ طفلكِ الآن في نزول الدرج واضعًا قدمًا مختلفة على كل درجة، أي بالتناوب بين القدمين. وهذا أصعب من صعود الدرج ويتطلب قدرًا كبيرًا من التوازن. ما عليكِ سوى الوقوف بالقرب منه لتمنحيه شعورًا بالأمان.') WHERE id = '4a1598de-455f-4bae-a8b3-0f5696c065c6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«ألعاب الكلمات والقافية» في الكلام. يستمتع طفلكِ بالعثور على كلمات متشابهة في النطق، مثل: «دار-نار» و«قمر-ثمر». وهذا يدل على تطور الوعي الصوتي، أي القدرة على تمييز الأصوات. اقرئي معه قصائد قصيرة ذات قافية أو العبي معه ألعاب الكلمات. فهذا يبني أساسًا متينًا لمهارة القراءة مستقبلًا.') WHERE id = '3f6a6fa9-4e7a-4539-93e7-6da1070ea997';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«العُقد والحلقات» في المهارات الحركية الدقيقة. بدأ طفلكِ يهتم بأربطة الأحذية أو الخيوط، ويحاول لفّها وربط بعضها ببعض. قدّمي له خرزًا ذا ثقوب كبيرة أو «ألعاب الربط» المخصصة لذلك. فهذا يهيئ عضلات أصابعه الصغيرة للكتابة وللمهام الأكثر تعقيدًا.') WHERE id = 'cf6a8a3d-c742-40b0-a3c1-38fd2db89aec';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«ثراء الصفات» في الكلام. عندما يصف طفلكِ الأشياء، لا يكتفي بذكر لونها، بل يستخدم أيضًا كلمات مثل «ناعم» و«شائك» و«أملس». العبي معه لعبة «المس واكتشف»: اطلبي منه أن يغمض عينيه ويلمس الشيء ثم يصف ملمسه.') WHERE id = '6a7056fe-a7e8-4d7e-91b2-4d5b5277e537';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«اكتشاف الرموز» في المهارات الحركية الدقيقة. يحاول طفلكِ الآن نسخ بعض الحروف، ولا سيما الحرف الأول من اسمه، أو الأرقام. وهذا يدل على أنه يفهم العلاقة بين الرموز البصرية والأصوات أو المعاني. شجّعيه على التدرّب على «الكتابة» على الرمل أو باستخدام الأقلام الملوّنة.') WHERE id = 'b57332a7-c381-44a7-bdb8-aef8d6820036';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«ضبط النفس والصبر». أصبح طفلكِ الآن أكثر هدوءًا وتقبّلًا للانتظار مدة 5-10 دقائق للحصول على شيء يريده، مثل انتظار إعداد الطعام. وهو لا يعتبر قولكِ «انتظر قليلًا» عقابًا، بل يتقبّله بوصفه أمرًا يتطلب بعض الوقت. عندما تلاحظين صبره، احرصي على تشجيعه بقولكِ: «شكرًا جزيلًا لأنك انتظرت».') WHERE id = '7374ce80-a74f-4d7f-bb0f-135ec7c6d431';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التعاطف والمواساة» في السلوك الاجتماعي. عندما يلاحظ طفلكِ الآن أنكِ متعبة أو أن أحد أصدقائه حزين، فقد يحضر له لعبته أو يربّت عليه. وهذا يبيّن مدى ثراء عالمه الداخلي وانتقاله من التركيز على «الأنا» إلى الاهتمام بـ«نحن».') WHERE id = '62ab0290-ec13-4b50-86f2-b4a69aba6dda';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«إدراك الحجم والسعة» في التطور المعرفي. يحاول طفلكِ الآن تخمين عدد الألعاب الصغيرة التي يمكن وضعها داخل صندوق كبير. أعطيه أوعية بأحجام مختلفة واسأليه: «برأيك، هل ستتّسع تلك الحاوية لهذه المياه؟». تضع هذه التجارب أسس المفاهيم الرياضية والفيزيائية التي سيتعلمها مستقبلًا.') WHERE id = 'd68476f5-47bc-4622-82c1-31e6c34eeecd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «المشي إلى الخلف». أصبح طفلكِ الآن قادرًا على المشي بضع خطوات إلى الخلف بثقة ومن دون أن يفقد توازنه. تقوّي هذه الحركة وعيه بجسمه (الحس العميق). العبي معه في الحديقة لعبة «سباق السلطعون» لتستمتعا معًا وتساعديه على تمرين عضلاته.') WHERE id = 'ff4d4dbc-967a-48e5-b6f7-ae29e0a5390d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"ضبط النفس والمشاعر". عندما يغضب طفلكِ أو يحزن، قد يستخدم أحيانًا بعض الأساليب التي اقترحتِها عليه لتهدئة نفسه (مثل التنفس بعمق). تُعد هذه من أهم المهارات الحياتية المرتبطة بالذكاء العاطفي. وعندما يهدأ، احرصي على مدحه على هذه الخطوة.') WHERE id = 'cab1e84e-d4d4-48e6-a7cb-8122f2485764';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الألعاب الجماعية" في السلوك الاجتماعي. أصبح طفلكِ قادرًا الآن على التعاون مع طفل آخر لتحقيق هدف مشترك (مثل بناء قلعة رملية كبيرة). وهذا يعني الانتقال الكامل من "اللعب المتوازي" إلى "اللعب الاجتماعي". راقبي محاولاته للتفاهم مع أصدقائه وادعميها.') WHERE id = '35da39d6-0c56-4410-8592-5e1cbd4b1e03';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الربط بين العدد والكمية" في التطور المعرفي. يستطيع طفلكِ العد حتى 10، وأصبح الآن قادرًا على رؤية الرقم "3" واختيار 3 ألعاب ووضعها جانبًا. تُعد هذه من أهم مراحل تطور التفكير الرياضي. عززي هذا الربط في الحياة اليومية بمهام مثل: "أعطني ملعقتين".') WHERE id = '4397b751-5eff-493f-b5d9-774c99d1ca07';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "إمساك الكرة بكلتا اليدين". أصبح طفلكِ يحاول الآن إمساك كرة كبيرة تُرمى نحوه ببطء بكلتا يديه (وأحيانًا يضمها إلى صدره). تتطلب هذه الحركة التنسيق بين اليد والعين وسرعة الاستجابة. العبي معه من مسافة قريبة.') WHERE id = '416872cb-a02b-4d4e-ac74-f040d4ce096b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الطلبات المهذبة" في تطور الكلام. أصبح طفلكِ يستخدم الآن عبارات مثل "هل يمكن؟" و"من فضلكِ" بقصد الحصول على ما يريده. وطريقتكِ المهذبة في التعامل هي أفضل نموذج يتعلم منه. عندما يتصرف بأدب، احرصي على الإشادة بذلك بقولكِ: "يسعدني جدًا أن أساعدك لأنك طلبت ذلك بهذه الطريقة الجميلة".') WHERE id = 'eb838920-fe5c-415a-a9ba-0dabdeaffb4e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: "الاعتراف بالخطأ". عندما يُسقط طفلكِ شيئًا أو يكسره، لم يعد يحاول إخفاء الأمر فورًا، بل قد يقول: "أنا فعلت ذلك". لا تعاقبيه في لحظة الصدق هذه؛ بل اقترحي عليه أن تنظفا المكان معًا. فهذا ينمّي لديه الشعور بالمسؤولية. كل لحظة في رحلة الـ1290 يومًا ثمينة!') WHERE id = 'fba8e58a-849a-4502-b3b8-829b5d503078';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«اللباقة والفروق الدقيقة» في الكلام. بدأ طفلكِ بالفعل بتعديل نبرة صوته وفقًا للشخص الذي يتحدث إليه (فمثلًا يتحدث بلطف أكثر مع الرضيع، وبجدية أكبر مع البالغين). هذه هي بداية اكتساب مهارات علم اللغة الاجتماعي. وطريقتكِ في الحديث هي النموذج الأساسي والأمثل له.') WHERE id = '3f691af2-a53f-4e9e-bda8-73c25f9784e5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '1280 يومًا من التطور المذهل! أصبح طفلكِ الآن في أكثر مراحل «الطفولة المبكرة» ثراءً بالنمو والتعلّم. وقد بات شخصًا متكاملًا له أذواقه ومخاوفه وأسئلته التي لا تنتهي. لقد قطعتِ هذا الطريق بالعلم والحب. تطبيق "Anacan" معكم دائمًا!') WHERE id = 'cb9230b0-c04d-4749-92fd-37201aec8ecd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ قادرًا على تصنيف الأشياء وفق خاصيتين بدلًا من خاصية واحدة، مثل: «السيارات الحمراء والصغيرة معًا». وهذه مرحلة مهمة في تطور المرونة المعرفية. قدّمي له ألعابًا متنوعة ودرّبي ذهنه بقولكِ: «اعثر على كل الأشياء الناعمة والزرقاء».') WHERE id = '7f3f7af2-f05b-47b3-bb9a-bf661d551477';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«القفزة الدقيقة» في المهارات الحركية. أصبح طفلكِ قادرًا على القفز من مكانه إلى أعلى، وكذلك نحو هدف محدد (مثل القفز داخل دائرة مرسومة على الأرض). وهذا يدل على تطور قدرته على التوازن وتقدير المسافات في المكان. ولعبة «القفز من حجر إلى آخر» في الحديقة تمرين رائع له.') WHERE id = 'b66ed3bb-08b0-48a9-9270-0f8d21791b6b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التسلسل الزمني» في الكلام. أصبح طفلكِ يستخدم مفاهيم «قبل، الآن، ثم» بدقة أكبر، فيقول مثلًا: «سأغسل يدي أولًا، ثم سأتناول الطعام». مناقشة خطة اليوم معه تمنحه شعورًا بالنظام والأمان. أجيبي دائمًا عن أسئلته مثل «ماذا سنفعل الآن؟» بذكر الخطوات بالترتيب.') WHERE id = '4a19271e-0252-465e-a5b6-220dfc833dfa';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«نسخ الأشكال: المثلث وعلامة الجمع» في المهارات الحركية الدقيقة. أصبح طفلكِ قادرًا على رسم علامة الجمع (+) بتقاطع خطين مستقيمين، كما يحاول رسم أشكال تشبه المثلث. وهذه من الأسس الأولية لتعلّم الكتابة. قدّمي له أقلام تلوين وأوراقًا فارغة لدعم هذه «الاكتشافات الهندسية».') WHERE id = '5e0bb7b8-fe4c-40a9-87b2-d5ec3dff9314';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تطور الإدراك: "اختبار ثبات الكمية". قد يظل طفلكِ يعتقد أن قطعة الصلصال المفلطحة أكبر من كرة الصلصال. أجري معه تجارب كهذه: افردي الكرة، ثم أعيدي تشكيلها على هيئة كرة. يساعده ذلك على فهم القوانين الثابتة للعالم المادي.') WHERE id = 'ae824ed0-4f75-4515-b7bf-83483a6c043d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التنسيق الحركي: "مراوغة الكرة بالقدم". لم يعد طفلكِ يركل الكرة فحسب، بل يحاول تحريكها بدفعها قليلًا إلى الأمام بقدمه (المراوغة). يتطلب ذلك توازنًا حركيًا وتناسقًا بين العين والقدم. أنشئي له في الحديقة "مسار كرة قدم" صغيرًا، واطلبي منه مراوغة الكرة نحو الهدف.') WHERE id = '6f891729-8e3d-4c9f-bdb3-588b6de557c3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"اللباقة والآداب" في الكلام. لم يعد طفلكِ يستخدم كلمتي "عذرًا" و"من فضلك" عن ظهر قلب فحسب، بل أصبح يستخدمهما عن قصد وفي موضعهما المناسب. نبرة صوتكِ عند التحدث مع الآخرين هي أهم مرجع يتعلم منه. عندما يتصرف بأدب، ساعديه على ملاحظة الأثر الإيجابي الذي يتركه سلوكه في المحيطين به.') WHERE id = '8553307b-a429-4fdd-a8d5-b4776f0fb3d5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'يا لها من رحلة رائعة امتدت 1300 يوم! لقد ترك طفلكِ عادات مرحلة الرضاعة وراءه تمامًا، ويدخل الآن أكثر مراحل ما قبل المدرسة نشاطًا. أصبح يدرك ذاته بوصفه شخصًا مستقلًا، وهو مستعد لتغيير العالم. طوال هذه الأيام الـ1300، كنتِ دليله الأكثر ثقة. اشكري نفسكِ على حبكِ وصبركِ!') WHERE id = '7883dc4b-dac2-42dc-8a35-51e8d5b489b1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بكِ في الشهر الـ44! يعيش طفلكِ الآن بعمق شعور "لقد كبرت". امنحيه في هذه الفترة مسؤوليات صغيرة، مثل اختيار ملابسه أو إعداد المائدة. يوجّه ذلك رغبته في الاستقلال نحو مسار إيجابي ويعزز ثقته بنفسه.') WHERE id = 'aad2ad75-5a11-4a2d-9c7c-2bc5d48aa312';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"المناورة السلسة" في الحركة الجسدية. أصبح طفلكِ قادرًا على رؤية العائق أمامه أثناء الجري بأقصى سرعته والالتفاف حوله دون أن يسقط. يمثّل ذلك ذروة مهارة "التخطيط الحركي" في الدماغ. أنشئي له مسارًا صغيرًا للعوائق في الحديقة. فهذا يعزز قدرته على التحكم بجسمه ورشاقته.') WHERE id = '5ff72db7-e0be-4353-a758-f27d398fc0b7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ الآن يفهم تمامًا منطق «إذا... فـ...»: «إذا كسرتُ اللعبة، فلن تعمل مرة أخرى». وهذه بداية قدرته على توقّع المستقبل. شجّعيه على التفكير مسبقًا في نتائج أفعاله، واسأليه مثلًا: «برأيك، ماذا سيحدث إذا وضعنا الكوب عند الحافة؟». فهذا ينمّي لديه الشعور بالمسؤولية.') WHERE id = '98264d01-8080-47ff-9743-5076f3c1e9fb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بلغ طفلكِ «ذروة التوازن الثابت» في قدراته الحركية؛ إذ أصبح يستطيع الوقوف على قدم واحدة لمدة 5-10 ثوانٍ من دون الاستناد إلى أي شيء. ويشير ذلك إلى تطوّر مركز التوازن في الأذن الداخلية وتقوّي عضلات الظهر والساقين. حوّلي هذه المهارة إلى نشاط ممتع باللعب معه لعبة «تجمّدنا».') WHERE id = 'e5ea1656-41df-45ea-937c-07b3a21bce4f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطوّر اللغة، وصل طفلكِ إلى مرحلة «بناء القصص المعقّدة». فعندما ينظر إلى كتاب مصوّر، لم يعد يكتفي بتسمية الأشياء، بل يشرح أيضًا العلاقة بين الأحداث، مثل: «الأرنب يركض لأن الثعلب قادم». حفّزي خياله بأسئلة مثل: «برأيك، ماذا سيقول الثعلب؟». فهذا يعزّز مرونته المعرفية.') WHERE id = '991395b5-cce5-4484-973b-52ea93850c86';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة، وصل طفلكِ إلى مرحلة «تحريك الأصابع بصورة مستقلة». فقد أصبح قادرًا على أداء مهام معقّدة، مثل النقر بأصابعه بعضها على بعض أو نظم خرزات صغيرة في خيط بأطراف أصابعه. ويتطلّب ذلك تنسيقًا بين نصفي الدماغ. قدّمي له ألعابًا تتضمن إغلاق الأزرار أو فكّ العُقد.') WHERE id = '7718afa5-181a-4995-b727-92bfdea228d9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التعامل مع المخاوف الخيالية». في هذا العمر، قد يخاف الأطفال أحيانًا من الظلام أو من «الوحوش». لا تنكري خوف طفلكِ، بل ابتكري ألعابًا مثل «المصباح السحري الذي يطرد الوحش». فدعمكِ العاطفي يعلّمه أن هذه المخاوف مؤقتة وستزول.') WHERE id = '5da5688a-9254-4a8e-94a4-a6cdb8624f11';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي، وصل طفلكِ إلى مرحلة «التعاون الموجّه نحو تحقيق هدف». فقد أصبح قادرًا على تقاسم «قطع البناء» مع صديق آخر لبناء برج كبير معًا. وهذا يعني أنه لم يعد يلعب إلى جانب الآخرين فحسب، بل يشاركهم اللعب لتحقيق هدف مشترك (اللعب التعاوني). شجّعي جانبه الاجتماعي الدبلوماسي بقولكِ: «لقد شكّلتما فريقًا رائعًا!».') WHERE id = '12a2b82c-6975-4312-a2f7-fbbdcf5d9909';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الكلام: "جودة الأسئلة". لم يعد طفلكِ يسأل فقط: "ما هذا؟"، بل أصبح يسأل: "لماذا يحدث هذا بهذه الطريقة؟". فهو يحاول فهم المنطق الكامن وراء الأحداث. وعندما تجيبين، حفّزي خياله أيضًا بسؤاله: "برأيك، لماذا يهطل المطر؟". فهذا ينمّي تفكيره الإبداعي والعلمي.') WHERE id = '104d37cc-f454-4cee-bc62-45a7dd638317';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: "نسخ الأشكال: المربع والمثلث". بدأ طفلكِ يحاول رسم أشكال ذات زوايا. وهذا أصعب من رسم الدائرة، لأنه يتطلب إيقاف القلم عند نقطة محددة ثم تغيير اتجاهه. أريه كيف يرسم "منزلًا" أو "سيارة" من خلال دمج الأشكال ذات الزوايا.') WHERE id = '72c3574b-2a9a-4755-8727-8d01b439e56e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"العدالة والقواعد". أصبح طفلكِ يتفاعل بشدة عند مخالفة قواعد اللعب، فيقول مثلًا: "لقد تجاوز دوره!". وهذا دليل على تطور هويته الاجتماعية وفهمه الأخلاقي. ومن خلال توضيح أن القواعد تنطبق على الجميع بالتساوي، فإنكِ تعززين لديه الشعور الداخلي بالعدالة والانضباط الاجتماعي.') WHERE id = '6e14d59c-92a1-4b52-9746-19ec45e3a240';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: "محاولات التفاوض". يحاول طفلكِ حل الخلافات من خلال اقتراحات مثل: "أعطني هذا، وسأعطيك ذاك". وهذا من أبرز مؤشرات الذكاء الاجتماعي. شجّعي جانب "المفاوض" لديه وادعمي الحلول العادلة.') WHERE id = '1bc59678-d965-4c53-ad57-e91ac3a6bece';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: "الإدراك الفوري للكمية (Subitizing)". أصبح طفلكِ قادرًا على معرفة عدد 3 أو 4 أشياء بمجرد النظر إليها، من دون عدّها. اعرضي عليه بطاقات تحتوي على أعداد مختلفة من النقاط، واطلبي منه أن يذكر عددها فورًا. فهذه المهارة هي أساس قدرته المستقبلية على إجراء الحسابات الرياضية بسرعة.') WHERE id = '9268aa12-9e8f-498d-a13c-fd38e4e68957';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "رمي الكرة من فوق الكتف". لم يعد طفلكِ يكتفي بإسقاط الكرة على الأرض، بل أصبح قادرًا على رميها بعيدًا من مستوى الكتف باتجاه هدف محدد. ويتطلب ذلك تنسيق حركة الجسم بالكامل والتحكم في القوة. العبي معه في الحديقة ألعاب رمي الكرة نحو هدف.') WHERE id = 'dbdc7993-c5ce-4ff8-a2f5-69daf1b98fea';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تعمّق المزاح والفكاهة في الكلام. أصبح طفلكِ يمزح بتغيير معاني الكلمات؛ فقد يناديكِ مثلًا «بابا» ثم يضحك. يدل ذلك على أنه أصبح يفهم قواعد اللغة جيدًا ويتعمّد مخالفتها لصنع الفكاهة. استمتعي بالمرح معه.') WHERE id = '8c83e3c0-4591-49c2-a059-525f584c28d3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: «اختبار الصبر». أصبح طفلكِ قادرًا على الانتظار بهدوء بضع دقائق للحصول على شيء يريده، مثلًا عندما تتحدثين عبر الهاتف. وهذا دليل على تطور قدرته على ضبط النفس. بعد أن ينتظر، احرصي على شكره بقول: «شكرًا جزيلًا لأنك انتظرتني».') WHERE id = '75df2db1-9a5a-4048-99dc-80b484b6d396';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ قادرًا على التعرّف إلى الشعارات والكتابات من حوله. فعلى سبيل المثال، عندما يرى شعار علامته التجارية المفضلة للمثلجات أو شعار المتجر، ينطق اسمه. وهذا دليل على تطور التفكير الرمزي. أريه إشارات مرور أو رموزًا تصويرية بسيطة مختلفة، واسأليه عن معانيها. فذلك يشكّل الأساس البصري لمهارة القراءة مستقبلًا.') WHERE id = 'bb1f5dc6-7300-4f63-9d44-40f2e54dfb71';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية: «القفز إلى الخلف». أصبح طفلكِ قادرًا على أداء قفزات صغيرة إلى الخلف. ويمثل ذلك مستوى جديدًا في قدرته على حفظ التوازن والتحكم بجسمه في الفراغ. حفّزي نشاطه من خلال اللعب معه في سباق «السلطعون والضفدع».') WHERE id = '2c74b1f3-a8fd-4086-88da-377857855b8c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الكلام: «المقارنة بين الأضداد». أصبح طفلكِ يستخدم صيغ المقارنة والتفضيل في الجمل بشكل صحيح، مثل «الأكبر» و«الأصغر» و«ثقيل جدًا». أعطيه 3 ألعاب مختلفة الأحجام واسأليه: «أيّها الأكبر؟». يدل ذلك على نمو حصيلته اللغوية من الناحيتين الكمية والنوعية.') WHERE id = 'f9bd7f70-01bc-46e8-8391-e80ede82d1cc';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: «التناسب في رسم الإنسان». أصبح طفلكِ يضع أجزاء الجسم في مواضع أكثر منطقية عند رسم شخص؛ فتكون العينان في وسط الوجه والذراعان على جانبي الجسم. تعكس هذه الرسومات تطور وعيه بصورة جسده (body image).') WHERE id = 'b857a3b6-e216-49cf-a9c0-e7adabf3fdba';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ قادرًا على تصنيف الأشياء حسب اللون والخامة في آنٍ واحد: «هذا أزرق وناعم أيضًا». وهذه علامة مهمة على المرونة المعرفية. قدّمي له ألعابًا تحتوي على أشياء ذات خامات مختلفة (الخشب، والقماش، والبلاستيك).') WHERE id = 'b98d1c0b-fdd1-4aeb-a1f1-d636c58ba6b7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«القفز الديناميكي» في النشاط البدني. أصبح طفلكِ قادرًا على القفز فوق عائق صغير يظهر أمامه أثناء الجري من دون أن يخفّف سرعته. وهذا يدل على تطور قدرته على التخطيط المسبق للحركة (التخطيط الحركي) في الدماغ. يمكنكِ إعداد عوائق صغيرة له في الحديقة.') WHERE id = '60d3fdb2-caa2-4bc5-bc84-452616921b80';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«طقوس الزمن» في تطور الكلام. رغم أن طفلكِ لم يستوعب بعد مفاهيم «الأمس» و«اليوم» و«غدًا» بدقة تامة، فإنه يعرف الروتين اليومي، مثل: «الذهاب إلى الحديقة بعد الطعام» أو «قصة قبل النوم». وتساعد هذه التسلسلات على تكوين مفهوم الخط الزمني في دماغه.') WHERE id = '95122e91-e077-4e38-a3b4-27a4e9e756f1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«محاولات التناظر» في المهارات الحركية الدقيقة. يحاول طفلكِ طي الورق أو توزيع التفاصيل في رسوماته بصورة أكثر تناظرًا (مثل رسم عينين وذراعين للشخص). وهذا يوضح مدى تطور إدراكه البصري المكاني.') WHERE id = '27b05f17-57a4-4b79-9091-f702b81309dd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مفاوضات «سياسية». أصبح طفلكِ يساومكِ قائلًا: «إذا أكلتُ الخضراوات، فهل يمكننا البقاء مدة أطول في الحديقة؟». وهذا يدل على أنه يتعلم آليات التأثير الاجتماعي. كوني صادقة وثابتة في هذه «المفاوضات»؛ فهو يتعلم الحدود بهذه الطريقة.') WHERE id = '0875811d-7343-4ba3-a29e-c235cba78b04';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«السيناريوهات الخيالية» في السلوك الاجتماعي. أصبحت الألعاب الآن أكثر تعقيدًا، مثل: «أنا البائع، تعالي واشتري مني الخبز». ومن خلال هذه الألعاب، يجرّب طفلكِ الأدوار المختلفة في المجتمع. سايري سيناريوهاته لتحفيز هذه العملية الإبداعية.') WHERE id = 'c35d44af-1b5b-4a3a-b44c-143278463e37';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"وصف الذات". أصبح طفلكِ قادرًا على وصف نفسه، فيقول مثلًا: "أنا أشقر"، "أنا أركض بسرعة". وهذا دليل على ترسّخ هويته الفردية. ساعديه على فهم ذاته بطرح أسئلة مثل: "ما الأشياء الأخرى التي تحبها؟". فنظرته الإيجابية إلى نفسه هي أساس ثقته بنفسه في المستقبل.') WHERE id = '9ca9132e-1f05-4086-b977-373ac1739718';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الدبلوماسية والتفاوض" في السلوك الاجتماعي. أصبح طفلكِ يقدّم اقتراحات للحصول على شيء ما، مثل: "إذا أعطيتني هذا، فسأعطيك ذاك". وهذا مستوى متقدم من الذكاء الاجتماعي ومهارة حل المشكلات. شجّعي محاولاته العادلة في "التفاوض" وتقبّليها بإيجابية.') WHERE id = '68e14866-1913-4e48-a5b0-15a89d136783';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"تنظيم الوقت ضمن روتين" في التطور المعرفي. أصبح طفلكِ يميّز بين فترات اليوم باستخدام عبارات مثل: "عندما أستيقظ صباحًا" و"عندما أنام مساءً". ناقشي معه خطط اليوم التالي بصيغة "أولًا، ثم، وأخيرًا". فهذا يمنحه شعورًا بالأمان والنظام.') WHERE id = 'fc45f60c-b22c-4712-b519-43e1ec159d0a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "التحكم بالكرة بالقدم". لم يعد طفلكِ يركل الكرة فحسب، بل يحاول تحريكها عبر دفعها قليلًا إلى الأمام بقدمه (المراوغة). وهذا يتطلب توازنًا حركيًا وانتباهًا. أنشئي له "مسارًا كرويًا" صغيرًا في الحديقة، واطلبي منه مراوغة الكرة نحو الهدف.') WHERE id = '27b3b770-0010-4e27-a15b-7e39df48e572';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"اللباقة وآداب التعامل الاجتماعي" في الكلام. أصبح طفلكِ يستخدم عبارات مثل "عذرًا" و"هل تسمح؟" بما يناسب الموقف. وطريقة حواركِ مع الآخرين هي النموذج الأهم بالنسبة إليه. عندما يتصرف بلباقة، ساعديه على ملاحظة الأثر الطيب الذي يتركه سلوكه في الآخرين، وقولي له: "الجميع يبتسم لك لأنك مهذب جدًا".') WHERE id = 'eddeff81-68cf-4451-8b49-9db4335c7821';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: "تقبّل الإخفاق". عندما لا ينجح طفلكِ في إنجاز مهمة ما (مثل عدم تمكنه من تركيب الأحجية)، فإنه لا يغضب فورًا، بل يحاول مجددًا أو يطلب المساعدة. امدحي جهده لا نتيجته، وقولي له: "لقد بذلت جهدًا كبيرًا ولم تستسلم، أحسنت!".') WHERE id = '3c009bb9-dfc9-4682-a20a-9afa3ba74f26';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«مهارة التنبؤ» في تطور اللغة. عندما تقرئين لطفلكِ قصة، أصبح الآن قادرًا على تقديم إجابات منطقية عن سؤال: «برأيك، ماذا سيحدث بعد ذلك؟». وهذا يدل على أنه بدأ يفهم الروابط الخفية بين الأحداث (الاستدلال). حفّزي خياله بسؤال: «ماذا كنت ستفعل لو كنت مكانه؟».') WHERE id = '8651dfdb-b093-4f7c-b25e-9846200e12c4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: «قص الورق وتشكيل الأشكال». يحاول طفلكِ الآن قص دائرة أو مربع بسيط باتباع الحواف باستخدام مقص آمن. ويتطلب ذلك مستوى عاليًا من التحكم في عضلات اليد الصغيرة.') WHERE id = '9727b126-febe-431d-a82a-db6a6416efff';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«حارس العدل والقواعد». لم يعد طفلكِ يتفاعل فقط عندما يخالف هو القواعد، بل ينتبه أيضًا عندما يخالفها الآخرون، فيقول مثلًا: «أبي، لقد تجاوزت دورك!». وهذا دليل على تشكّل الضمير الداخلي والشعور بالعدالة الاجتماعية. اشرحي له لماذا يجب أن تُطبَّق القواعد بالتساوي على الجميع.') WHERE id = 'a0bdfa22-2c16-417c-bc41-62353716c069';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: «الحلول الدبلوماسية». أصبح طفلكِ قادرًا أثناء الخلاف على تقديم اقتراحات مثل: «هيا نلعب بالتناوب». وهذا من أبرز مؤشرات الذكاء الاجتماعي. احرصي على تشجيع نهجه السلمي بقولكِ: «لقد وجدت حلًا رائعًا».') WHERE id = '1c1d5af4-d669-4eee-8938-97dcf06fd2d8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: «تجارب ثبات الكمية». العبي معه بالرمل أو الماء. اسكبي الكمية نفسها من الماء في أوعية مختلفة. قد يظل يعتقد أن الوعاء الأطول يحتوي على ماء أكثر. تهيئ هذه التجارب دماغه لفهم الواقع المادي.') WHERE id = '32e16fdb-1a45-43a1-8bb5-fea77db311d2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «رمي الكرة من فوق الكتف». أصبح طفلكِ الآن قادرًا على رمي الكرة نحو الهدف بقوة ودقة أكبر. وينتج ذلك عن العمل المتناسق لعضلات الذراع والكتف. العبي معه في الحديقة ألعابًا بسيطة مثل «رمي الكرة في السلة». فهذا ممتع ويعزز أيضًا قدرته على التحكم في جسمه.') WHERE id = '5eff2db7-b37a-4ebb-9335-292fea3a6331';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: "وظائف الأشياء". أصبح الطفل يصنّف الأشياء وفقًا لوظيفتها، لا لمظهرها فقط. "هذه أدوات للقطع"، و"هذه أدوات للكتابة". وهذا يدل على أن قاعدة المعلومات في دماغه أصبحت أكثر تنظيمًا وعملية.') WHERE id = '52b43fec-3fc9-4135-bc89-1ca56d2c89c9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التناسق الجسدي: "المناورات الدقيقة". أصبح الطفل قادرًا على حمل كوب مملوء بسائل دون أن يسكب منه الكثير، أو المشي على ممر ضيق. وهذا يوضح مدى تطور التناسق البصري الحركي لديه. عزّزي انتباهه هذا بإسناد مهام "المساعد الصغير" إليه في المنزل.') WHERE id = 'b2a95188-79e5-4c80-963a-2302704140ca';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: "مفردات المشاعر". لم يعد الطفل يكتفي بقول "أنا بخير" أو "لست بخير"، بل يستخدم في مواضعها الصحيحة كلمات مثل "غضبت" و"اشتقت" و"أنا سعيد". تقبّلي مشاعره وأكّدي مشروعيتها، فقولي مثلًا: "من الطبيعي أن تبكي لأنك اشتقت". فهذا من أهم ضمانات صحته النفسية.') WHERE id = '8d118e2f-9e48-4f84-bdd9-4688744f285c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'ذروة اليوم 1330! أصبح الطفل الآن رسميًا في أكثر فترات مرحلة "الطفولة المبكرة" نشاطًا وإدراكًا. وهو الآن فرد متكامل جسديًا وعاطفيًا. لقد قطعتِ هذه الرحلة بالعلم والحب. "Anacan" إلى جانبكما دائمًا!') WHERE id = 'ee7d4f4f-acca-4792-810c-9ebdc339da81';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بكِ في الشهر الـ45! بدأ الطفل يبحث عن الحروف المألوفة في الكلمات المكتوبة من حوله. وقد يتمكن خصوصًا من تمييز الحرف الأول من اسمه أينما رآه. وهذه هي المرحلة الأولى لاكتساب مهارة القراءة. لا تجبريه على تعلّم الحروف، بل اكتفي بتعريفه، من خلال اللعب، باسم كل حرف يراه وصوته.') WHERE id = 'c1854d46-26a3-452c-9eb7-697ec5a92d6c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الحركة الجسدية: "التحكم الكامل بالدراجة ثلاثية العجلات". أصبح الطفل قادرًا على الانعطاف في المنعطفات الضيقة بتحريك المقود، مع الاستمرار في تدوير الدواسات دون توقف. وهذا يعكس مستوى متقدمًا من قوة الجزء السفلي من الجسم والتناسق البصري المكاني.') WHERE id = 'ee3c0b22-95f2-4059-93bc-287ff0eb00cf';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"المخاوف الخيالية والشجاعة". في هذا العمر يكون خيال طفلكِ قويًا لدرجة أنه قد يرى "وحوشًا" في الظلام. لا تنكري خوفه، وابتكرا معًا طقوسًا "لطرد الخوف"، مثل وسادة سحرية أو مصباح يدوي. فهذا يعزز شعوره بالأمان العاطفي.') WHERE id = '30d373fa-79f5-41e2-b2ee-ce7f265298c1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"القيادة والتعاون" في السلوك الاجتماعي. أصبح طفلكِ الآن يبتكر سيناريو اللعبة ويوزع الأدوار على أصدقائه: "أنتَ كن القطة، وأنا سأكون صاحبك". وهذا يدل على فهمه للتسلسل الاجتماعي والأدوار. ادعمي محاولته الإبداعية للقيادة بأن تتبعي السيناريو الذي يضعه أحيانًا.') WHERE id = 'ec5ff997-3ed4-4645-be9c-2d361314cc2f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الكمية ورمز العدد" في التطور المعرفي. أصبح طفلكِ يدرك تمامًا أن الرقم "4" يعني 4 تفاحات، وأن الرقم "1" يعني شيئًا واحدًا. عززي الرابط بين الأرقام المجردة والكميات الحقيقية بإعطائه مهام مثل: "أعطني 5 أقلام".') WHERE id = 'c8eb9b80-1c81-4e02-86f3-e8fdf448ffb9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "إمساك الكرة بكلتا اليدين". بدأ طفلكِ الآن يمسك الكرة التي تُرمى نحوه ببطء، وذلك بثني ذراعيه وضم يديه إلى صدره، وأحيانًا بإمساكها بيديه مباشرة. وهذا يدل على تطور سرعة استجابته ومهارته في التتبع البصري. تدرّبا معًا على مسافة قريبة باستخدام كرة طرية.') WHERE id = 'e3704303-d02a-47ea-9a47-f1164a3046e0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"مفاهيم الزمن" في تطور الكلام. أصبح طفلكِ يستخدم مفاهيم "الأمس" و"اليوم" و"غدًا" في مواضعها بصورة أدق. عندما يقول: "سأذهب غدًا إلى بيت جدتي"، فهو يتصور التسلسل الزمني في ذهنه. في نهاية اليوم، تحدثي معه عن خطط الغد كما لو كانت "حكاية" قبل أن ينام. فهذا يساعده أيضًا على تكوين مفهوم الزمن المستقبل.') WHERE id = '58a4bd7b-b429-45cf-92c2-f503f4e7d474';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تطور كبير خلال 1350 يومًا! لقد ابتعد طفلكِ رسميًا عن شاطئ "مرحلة الرضاعة"، وأصبح يسبح بحرية في محيط "الطفولة المبكرة". وصارت شخصيته المتفردة وروح الدعابة لديه وطباعه أكبر مصدر لاهتمامكِ. طوال هذه الأيام الـ1350، كنتِ الميناء الأكثر أمانًا في عالمه. أحسنتِ يا أمي!') WHERE id = '647eb338-5057-4cf4-a29d-e4970189abc1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور اللغة: «المفاهيم المجرّدة: اليمين واليسار». يُبدي طفلكِ اهتمامًا بتعلّم مفهومي «اليد اليمنى» و«القدم اليسرى». قد يخلط بينهما في الوقت الحالي، وهذا طبيعي. أدرجي هذين المفهومين في حياته اليومية، فقولي له عند إلباسه الجوارب: «الآن مدّ قدمك اليمنى».') WHERE id = 'dcd74d19-3308-4446-89b6-05aecfc53aed';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: «التنظيم الذاتي (Self-regulation)». لم يعد طفلكِ يغضب فورًا عندما لا ينجح في أداء مهمة ما، بل قد ينظر إليكِ ويسأل: «هل أحاول مجددًا؟». هذه إحدى أهم مراحل النضج العاطفي. امدحي صبره والجهد الذي بذله، لا النتيجة التي حققها. أنتِ أم رائعة!') WHERE id = 'b36ad394-fd9c-40bc-963f-954848c1c743';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ يطبّق تسلسل «أولًا، الآن، ثم» على الأنشطة المعقّدة، فيقول مثلًا: «سأرتّب ألعابي أولًا، ثم سأغسل يديّ وأتناول الطعام». يدل ذلك على تطور مهارة التخطيط الاستراتيجي (الوظائف التنفيذية) في الدماغ. امنحيه دورًا فعالًا في وضع خطة اليوم؛ فهذا يعزّز انضباطه الذاتي.') WHERE id = 'a41e3209-8dbf-44ce-98bb-5a5b64b4268c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الحركة الجسدية: «التوازن الثابت والديناميكي». أصبح طفلكِ قادرًا على الوقوف على قدم واحدة لمدة 5-10 ثوانٍ، أو المشي فوق حافة ضيقة من دون أن يفقد توازنه. يدل ذلك على اكتمال نضج الجهاز الدهليزي المسؤول عن التوازن. لقد حان الوقت المناسب للعب لعبة «السير على الحبل» معه.') WHERE id = '696cb686-c625-440d-93fe-4e04eee0ca77';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور اللغة: «سلسلة السبب والنتيجة». أصبح طفلكِ يبحث عن تفسير منطقي لما تمنعينه عنه، فيسأل: «لماذا لا يمكنني تناول الحلوى الآن؟». عند الإجابة، قدّمي له تفسيرًا مثل: «لأنك إذا تناولت الحلوى الآن، فستشبع ولن تتمكن من تناول غدائك المفيد»، بدلًا من قول: «لأنني قلت ذلك». فهذا يصقل تفكيره المنطقي.') WHERE id = '1bdc4f44-d5e0-42ee-9d67-dc1beca39c22';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: «تفاصيل رسم الإنسان». عندما يرسم طفلكِ شخصًا، أصبح يضيف تفاصيل صغيرة مثل الأصابع أو الرموش أو الأزرار أو القبعة. تعكس هذه الرسومات مدى دقة ملاحظته للعالم من حوله، كما أنها ثمرة تطور التناسق بين عينيه ويديه.') WHERE id = 'dd86234a-f54a-432f-bcb2-f0fc25c1a9f2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح الطفل يطبّق الفرق بين "أنا" و"نحن" في الألعاب الاجتماعية. فإذا كان يوزّع المهام قائلًا مثلًا: "هيا نبنِ بيتًا معًا، أحضر أنت المكعبات وسأرتّبها أنا"، فهذا يمثّل ذروة ذكاء التعاون لديه. أتيحي له فرصة تجربة أدوار القائد أو المساعد في الأنشطة الجماعية. فهذا يسهم في تنمية مهارات العمل الجماعي لديه مستقبلًا.') WHERE id = '56b16411-749d-48ab-a1c9-aec6ee4d3f2b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في النشاط البدني: "الجري السريع والانعطاف الحاد". أصبح الطفل قادرًا على الانعطاف بحدة أثناء الجري من دون أن يفقد توازنه. وهذا يوضح مدى تطور وعيه بوضعية جسمه (الحس العميق) وتحكمه في عضلاته. تُعد لعبة "الجري المتعرج" في الحديقة تمرينًا رائعًا له.') WHERE id = '3acf9991-6e18-469c-8243-5255e3b47e73';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: التسلسل المنطقي لأسئلة "لماذا؟". لم يعد يكتفي بإجابتكِ، بل يطرح سلسلة من الأسئلة مثل: "ولماذا هو هكذا؟". وعندما تجيبينه، شجّعيه أيضًا على التفكير بقولكِ: "إلى أين تظن أن الشمس تذهب؟". فهذا يربط خياله بفضوله العلمي. وسّعي عالم اهتماماته باستخدام موسوعات صغيرة.') WHERE id = '09e33fb1-46b4-4ad6-a2f6-bb3ee2d41636';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: "طي الورق (أساسيات الأوريغامي)". أصبح الطفل يحاول طي الورقة من منتصفها تمامًا وجمع زواياها معًا. تقوّي هذه الحركة عضلات يديه، كما ترسّخ مفهوم التناظر الهندسي في ذهنه. علّميه صنع أشكال بسيطة باستخدام الأوراق الملونة.') WHERE id = 'b9689a6f-2bcb-421e-acea-f03b1095905f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"ضبط النفس والتعبير عن المشاعر". عندما يغضب الطفل، لا يكتفي بالصراخ، بل قد يعبّر عن شعوره بالكلمات قائلًا: "أنا غاضب جدًا الآن!". تقبّلي مشاعره وأكّدي له مشروعيتها بقولكِ: "أنا أفهمك، ومن الطبيعي أن تشعر بالغضب". فهذا يعزز نضجه العاطفي.') WHERE id = '7a0c1e64-9ecb-47f6-83f4-aa32390210cd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: "المفاوضات الدبلوماسية". قد يبدأ الطفل بالمساومة للحصول على شيء ما، قائلًا مثلًا: "إذا أعطيتني هذه السيارة، فسأعطيك الشوكولاتة". وهذه بداية تطور مهارات التأثير الاجتماعي والدبلوماسية لديه. جرّبي معه قواعد "التفاوض" العادل في صورة لعبة.') WHERE id = '2dd70517-4599-4775-b1e7-2b11f39244da';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: «ثبات الكمية (الحجم)». جرّبي معه تجربة في المطبخ: اسكبي الكمية نفسها من الماء في وعاء عريض وآخر طويل وضيّق. قد يظل يعتقد أن الوعاء الطويل يحتوي على ماء أكثر. تساعده هذه التجارب على تطوير قدرته على الموازنة بين الإدراك البصري والتفكير المنطقي.') WHERE id = 'eb9fac33-252a-4cde-bb98-95be1aaf831f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الحركي: «مراوغة الكرة بالقدم». لم يعد طفلكِ يركل الكرة فحسب، بل يحاول تحريكها بدفعها قليلًا إلى الأمام بقدمه (المراوغة). يتطلب ذلك توازنًا حركيًا وانتباهًا. أنشئي معه «مسارًا صغيرًا لكرة القدم» في الحديقة واطلبي منه مراوغة الكرة نحو الهدف.') WHERE id = 'f40621db-c962-42bd-85b1-429800b2b4ef';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'رحلة كبيرة استمرت 1360 يومًا! لقد أتم طفلكِ الآن 45 شهرًا. وأصبح اليوم فردًا متكاملًا؛ إنسانًا صغيرًا له أفكاره ودعاباته وأحلامه الخاصة. طوال هذه الأيام الـ1360، كنتِ مهندسة عالمه. وفي نظراته الواثقة بصمة حبكِ. أنتِ أم رائعة!') WHERE id = '333176ec-4bc6-4177-b76d-921996ec28d4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ يميّز الأشياء ليس بحسب مظهرها فحسب، بل بحسب مادتها أيضًا: «هذا من البلاستيك، أما هذا فمن الحديد». أعطيه أشياء ذات ملمس مختلف واسأليه عن الفروق بينها. يساعده ذلك على تحليل العالم من حوله بمزيد من التفصيل وتنظيم معلوماته عن العالم المادي.') WHERE id = '657efc38-ed5e-4e3a-9572-7dbdb9184154';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الحركة الجسدية: «ذروة التوازن الثابت». أصبح طفلكِ قادرًا على الوقوف على قدم واحدة مدة 5-10 ثوانٍ من دون لمس أي شيء. وهذا دليل على تطور مركز التوازن في الأذن الداخلية وتقوّي عضلات الظهر والساقين. حوّلي هذه المهارة إلى متعة باللعب معه لعبة «تجمّدنا».') WHERE id = '2f039b11-24db-4020-90d7-1c5f7a16c171';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«سلسلة السبب والنتيجة» في الكلام. أصبح طفلكِ يبحث عن تفسير منطقي لما تمنعينه عنه: «لماذا لا أستطيع تناول الحلوى الآن؟». عند الإجابة، بدلًا من قول: «لأنني قلت ذلك»، اشرحي له مثلًا: «لأنك إذا تناولت الحلوى الآن، فستشبع ولن تتمكن من تناول غدائك المفيد». فهذا يصقل تفكيره المنطقي.') WHERE id = 'c914eb21-6b42-48f0-8ec0-5b93a47ae392';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التفاصيل في رسم الأشخاص» ضمن المهارات الحركية الدقيقة. عندما يرسم طفلكِ شخصًا، أصبح يضيف تفاصيل صغيرة مثل الأصابع أو الرموش أو الأزرار أو القبعة. وتعكس هذه الرسومات مدى دقة ملاحظته للعالم من حوله، كما أنها ثمرة تطور التناسق بين اليد والعين.') WHERE id = 'fdd8b340-0697-4aeb-8d02-8988eb7da642';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التعامل مع المخاوف الخيالية». في هذا العمر، قد يخاف الأطفال أحيانًا من الظلام أو من «الوحوش». لا تنكري خوف طفلكِ، بل ابتكري ألعابًا مثل «المصباح السحري الذي يطرد الوحش». فدعمكِ العاطفي يعلّمه أن هذه المخاوف مؤقتة وستزول.') WHERE id = 'd0348641-27c7-4875-b24e-5d2722f25676';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التعاون الموجّه نحو تحقيق نتيجة» في السلوك الاجتماعي. أصبح طفلكِ قادرًا على مشاركة «قطع البناء» مع صديق آخر لبناء برج كبير معًا. ولم يعد هذا مجرد لعب جنبًا إلى جنب، بل لعبًا لتحقيق هدف مشترك (اللعب التعاوني). شجّعي جانبه الاجتماعي والدبلوماسي بقولكِ: «لقد شكّلتما فريقًا رائعًا!».') WHERE id = 'bd3e5f00-1925-4d9d-bea8-7fc43abbb171';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«اختبار ثبات الكمية» في التطور المعرفي. قد يظل طفلكِ يعتقد أن قطعة الصلصال المفلطحة أكبر من كرة الصلصال. نفّذي معه تجارب من هذا النوع: افردي كرة الصلصال، ثم أعيدي تشكيلها على هيئة كرة. فهذا يساعده على فهم القوانين الثابتة للعالم المادي.') WHERE id = '34ed2954-3007-40b2-9228-8e5bbced6cd6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «التحكم في الكرة بالقدم». لم يعد طفلكِ يركل الكرة فحسب، بل يحاول تحريكها بدفعها قليلًا إلى الأمام بقدمه (المراوغة بالكرة). ويتطلب ذلك توازنًا حركيًا وتناسقًا بين القدم والعين. أنشئي له في الحديقة «مسارًا صغيرًا لكرة القدم»، واطلبي منه مراوغة الكرة نحو الهدف.') WHERE id = 'f67ac937-be10-4065-8ce0-71169b977a25';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«اللباقة والآداب» في الكلام. لم يعد طفلكِ يستخدم كلمتَي «عذرًا» و«من فضلك» لمجرد أنه حفظهما، بل أصبح يستعملهما عن قصد وفي موضعهما المناسب. ونبرة صوتكِ عند التحدث مع الآخرين هي أهم مصدر يتعلم منه. عندما يتصرف بلباقة، ساعديه على ملاحظة الأثر الإيجابي الذي يتركه هذا السلوك فيمن حوله.') WHERE id = '81b527f9-bc6c-4fa6-a384-bfac0dbe1b99';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'رحلة رائعة امتدت 1370 يومًا! لقد ترك طفلكِ عادات مرحلة الرضاعة وراءه تمامًا، ويدخل الآن أكثر مراحل ما قبل المدرسة نشاطًا. أصبح يدرك ذاته بوصفه شخصًا مستقلًا ويستعد لتغيير العالم. وقد كنتِ خلال هذه الأيام الـ1370 مرشدته الأكثر موثوقية. اشكري نفسكِ على حبكِ وصبركِ!') WHERE id = '7f1e62d7-6f8c-466a-917b-3acd9000a197';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بدأ طفلكِ يبحث عن الحروف المألوفة في الكلمات المكتوبة من حوله، ولا سيما الحرف الأول من اسمه. هذه هي مرحلة «القراءة البصرية». لا تجبريه على تعلّم الحروف، بل عرّفيه إلى الصوت الذي يمثله كل رمز يراه وكأنه اكتشاف ممتع.') WHERE id = '395ee563-1ee4-4a29-8a28-f145933f9a6e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«المناورة الديناميكية» في الحركة الجسدية. أصبح طفلكِ قادرًا على تفادي العوائق أمامه بسهولة أثناء الركض أو تغيير اتجاهه فجأة. يشير ذلك إلى تطور مهارة التخطيط الحركي في دماغه. عززي رشاقته باللعب معه في الحديقة لعبة «سباق التعرّج».') WHERE id = 'cad61f20-8263-4b3a-bfc8-ed14fb447f18';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التوقع والمنطق» في تطور اللغة. عندما تقرئين له قصة، اسأليه: «برأيك، ماذا سيحدث بعد ذلك؟». أصبح طفلكِ قادرًا على وضع توقعات منطقية تتوافق مع تسلسل الأحداث. وهذا يصقل خياله وقدرته على فهم علاقات السبب والنتيجة.') WHERE id = '9337ce82-dd36-4b6f-a92e-336053ee8590';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«نسخ الأشكال: المربع» ضمن المهارات الحركية الدقيقة. بخلاف رسم الدائرة، يتطلب رسم المربع إيقاف القلم عند الزوايا وتغيير اتجاهه. ويُعد ذلك استعدادًا جسديًا مهمًا للانتقال إلى الكتابة. أريه كيف يرسم منزلًا أو سيارة من خلال دمج أشكال هندسية مختلفة.') WHERE id = '90518b08-497d-4de6-998e-df3fea30a1f5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"ضبط النفس والصبر". أصبح طفلكِ يدرك أن انتظار دوره أو عدم تلبية رغبته فورًا ليس "نهاية العالم". ويتقبّل بهدوء أكبر قولكِ: "انتظر 5 دقائق". وبعد أن ينتظر، احرصي على تعزيز هذا السلوك الإيجابي بقولكِ له: "شكرًا لك لأنك كنت صبورًا".') WHERE id = '24183c71-3661-48ff-a107-410bfbd38523';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: "الألعاب الجماعية ذات القواعد". أصبح طفلكِ مهتمًا بمشاركة الأطفال الآخرين في ألعاب لها قواعد، مثل "الغميضة". وهذه مرحلة مهمة في التكيف الاجتماعي. وعندما يلتزم بالقواعد، امدحيه بقولكِ: "أحسنت لأنك لعبت بنزاهة".') WHERE id = '04f3027e-9e30-43e8-bafb-f6c237c97831';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: "الإدراك الفوري للكمية (Subitizing)". أصبح طفلكِ قادرًا على معرفة عدد 4-5 أشياء بمجرد النظر إليها، من دون عدّها. أريه بطاقات تحمل أعدادًا مختلفة من النقاط واسأليه: "كم نقطة توجد هنا؟". فهذه المهارة تمثّل أساسًا لإجراء العمليات الحسابية بسرعة في المستقبل.') WHERE id = '494bf11b-00d7-4571-8a96-04e2a73dc57c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "القفز على قدم واحدة". أصبح طفلكِ يحاول القفز على قدم واحدة عدة مرات متتالية. ويتطلب ذلك قوة بدنية وقدرة متقدمة على التوازن. قوّي عضلات ساقيه وتوازنه من خلال لعب لعبة "القفز على آثار الأقدام" معه في المنزل.') WHERE id = 'e519a6cc-28f9-4dbb-80e3-d4aaf6533df1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور اللغة: "التصور البصري للزمن". أصبح طفلكِ يعرف أجزاء اليوم وتسلسلها جيدًا. "في الصباح، عندما نستيقظ، تشرق الشمس، وفي المساء يظهر القمر". كما أن مناقشة خطط الغد معه بصيغة "أولًا، ثم، وأخيرًا" تمنحه شعورًا بالأمان.') WHERE id = '22058766-30d2-4299-8138-dbe3e33f7a99';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: "الدبلوماسية وإيجاد الحلول". عند حدوث خلاف، لم يعد طفلكِ يكتفي بالبكاء، بل يقدّم اقتراحات مثل: "هيا نتشارك اللعبة" أو "أعطني هذا وسأعطيك ذاك". وهذا يمثّل مستوى متقدمًا من الذكاء الاجتماعي. ادعمي دائمًا نهجه السلمي هذا. أنتِ تربّين شخصًا رائعًا!') WHERE id = '29c7e41f-162a-440d-ad79-c662956e2e8e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تطوّر الإدراك: «تصنيف الأضداد». أصبح طفلكِ يميّز تمامًا بين مفاهيم «ساخن وبارد»، و«طويل وقصير»، و«ثقيل وخفيف». العبي معه لعبة «اعثر على العكس»: قولي أنتِ «كبير»، وليقل هو «صغير». يساعد ذلك على تنمية حصيلته اللغوية وقدرته على التفكير المجرّد والمقارنة.') WHERE id = '96a1b8b4-4a53-4821-8a70-36e9af7db4b1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «المناورة على الدرج». أصبح طفلكِ يصعد الدرج وينزله بثقة، ويمكنه أحيانًا الحفاظ على توازنه حتى عندما يحمل لعبة في يده. يدل ذلك على مستوى متقدّم من التوازن الديناميكي. ابقي دائمًا بالقرب منه، لكن امنحيه الثقة ليتحرّك بحرية.') WHERE id = 'e31518b3-755f-43f6-a042-c5c881774776';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الخيال وسرد القصص» في تطوّر الكلام. قد يروي لكِ طفلكِ حكايات قصيرة من نسج خياله، يمتزج فيها الواقع بالخيال. شجّعيه على مواصلة قصصه بأسئلة تُظهر اهتمامكِ، مثل: «حقًا؟» أو «وماذا حدث بعد ذلك؟». يساعده ذلك مستقبلًا على التحدّث بطلاقة وتعبير.') WHERE id = '1285abea-7296-4d22-a83f-6877ea839c11';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: «الفوز والخسارة». أصبح طفلكِ يتقبّل الخسارة في الألعاب بهدوء أكبر، وإن لم يكن ذلك في كل مرة. ومحاولته مجددًا بقوله: «هيا نلعب مرة أخرى» دليل على قوة إرادته. عزّزي دائمًا هذه المهارة الحياتية المهمة بقولكِ: «المهم هو أن نلعب».') WHERE id = 'ab47da7b-7dd4-423e-bf69-3500dd83cc2f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ يطبّق منطق «إذا... فإن...» على مواقف اجتماعية معقّدة، مثل: «إذا أعطيته لعبتي، فسيعطيني لعبته أيضًا». وهذا أساس العلاقات المتبادلة. العبي معه لعبة «ماذا ستكون النتيجة؟» (مثلًا: «ماذا سيحدث إذا لم نسقِ الزهرة؟»). يساعد ذلك على تنمية قدرته على استشراف النتائج.') WHERE id = 'd6bf3a90-b7f5-4d81-9101-4bd23f1bc25d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«القفز من ارتفاع» ضمن تطوّر الحركة الجسدية. أصبح طفلكِ قادرًا على القفز من ارتفاع محدّد (مثل درجة منخفضة) والهبوط على كلتا قدميه دون أن يفقد توازنه. وهذا مؤشر على ازدياد قوة مفاصل الركبتين والكاحلين. علّميه كيفية «الهبوط برفق» (عن طريق ثني ركبتيه قليلًا).') WHERE id = '2795a26f-4a85-42cd-9860-03afd8411f60';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ قادرًا الآن على تصنيف الأشياء في الوقت نفسه بحسب لونها وحجمها: "لنجمع هنا كل المكعبات الصغيرة والخضراء". وهذا مؤشر مهم على المرونة المعرفية. قدّمي له ألعاب "ابحث واعثر" التي تعتمد على معايير مختلفة، لتساعديه على تحسين انتباهه.') WHERE id = '428720ac-8db6-44a9-825f-ab25eee4d54f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"دقة التصويب" في النشاط الحركي. أصبح طفلكِ الآن قادرًا على رمي الكرة أو كيس صغير نحو هدف محدد (مثل السلة) بدقة أكبر. وهذا يعكس تطور قدرته على تقدير المسافة في الفراغ (التقدير المكاني) والتحكم في قوة الرمي. نظّمي معه في المنزل مسابقة "أصب الهدف"؛ فهذا يعزز أيضًا التناسق بين اليد والعين.') WHERE id = '5a34a884-0d1a-4ecc-8aaf-0538071d5d58';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الانتقال في الكلام من "لماذا" إلى "كيف". لم يعد طفلكِ يسأل عن أسباب الأحداث فحسب، بل أصبح يسأل أيضًا عن كيفية حدوثها: "كيف تسير السيارة؟"، "كيف يهطل المطر؟". وعند الإجابة، حفّزي فضوله العلمي من خلال شرح القوانين الفيزيائية البسيطة (مثل "العجلات تدور").') WHERE id = '43f973d1-c670-48fb-b082-c963d974b2cb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"تكوين مشهد متكامل" ضمن المهارات الحركية الدقيقة. أصبح طفلكِ عند الرسم يجمع عدة عناصر مترابطة في ورقة واحدة: "هذا منزل، وهذه الشجرة الموجودة بجانبه". وهذا يدل على أنه بدأ يدرك العالم البصري بصورة متكاملة ومنظمة.') WHERE id = '4fc62a39-6aec-4659-8e0d-de5a572b7f58';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"التنظيم الذاتي (Self-regulation)". عندما يغضب طفلكِ، أصبح يحاول استبدال رد الفعل الجسدي (مثل الضرب) بالكلمات، فيقول: "أنا غاضب!". وهذه من أكبر القفزات في تطور الذكاء العاطفي. عندما يعبّر عن مشاعره، استمعي إليه وادعميه بقولكِ: "أنا فخورة بك لأنك عبّرت عن شعورك بالكلمات".') WHERE id = '2e78bbc8-d3e0-46e9-b6f4-fd06f0ff0e92';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الحوار في لعب الأدوار" ضمن السلوك الاجتماعي. أصبح طفلكِ الآن يخوض حوارات طويلة أثناء اللعب: "لقد جئت إلى المتجر وتريد مني خبزًا...". ومن خلال هذه الألعاب، يجرّب القواعد الاجتماعية وآداب التواصل. شاركيه هذه العملية الإبداعية باتباع السيناريو الذي يضعه.') WHERE id = 'c878d5a6-c839-4863-9ea6-c1e45caf4ee6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«مفاهيم الزمن المجرّدة» في الكلام. أصبح طفلكِ يفهم الآن فترات زمنية أوسع مثل «عطلة نهاية الأسبوع» و«في العيد» و«في عيد الميلاد». عندما تتحدثين معه عن حدث مهم قريب (مثل نزهة)، استخدمي عبارات مثل «بعد ٣ أيام» لتعميق إدراكه للزمن.') WHERE id = '4dbdf376-fb0e-469f-bb2e-b3be32d8d1c8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«نسخ الحروف» ضمن المهارات الحركية الدقيقة. يحاول طفلكِ الآن نسخ بعض الحروف البسيطة (مثل A وO وT) كما يراها. وهذا يساعد على ترسيخ الرموز في الذاكرتين البصرية والحركية. اقترحي عليه أن «يكتب» الحروف في صينية من الرمل أو باستخدام ألوان الأصابع.') WHERE id = '83f43947-4f06-425b-801a-dd053a64d6b1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«ضبط النفس: تأجيل الرغبة». أصبح طفلكِ الآن يتقبّل أن عليه الانتظار مدة أطول قليلًا للحصول على مكافأة (مثل «الحلوى بعد الطعام»). وهذا دليل على تطور قوة الإرادة وضبط النفس (تأجيل الإشباع). احرصي على إبراز صبره والثناء عليه؛ فهذه المهارة من مفاتيح النجاح الأكاديمي مستقبلًا.') WHERE id = '51891c5d-a6e3-40d4-8ba5-38112ce2f223';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التضامن الجماعي» في السلوك الاجتماعي. عندما يبكي أحد أصدقاء طفلكِ، لم يعد يكتفي بالنظر إليه، بل يسأله «ماذا حدث؟» أو يأتي ليخبركِ. هذه هي المرحلة الفاعلة من التعاطف. ادعمي جانبه الحنون بقولكِ: «أنت صديق لطيف جدًا».') WHERE id = '9932ed27-e891-4fec-aac9-e64c5a418a49';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«أساسيات الجمع» في التطور المعرفي. أصبح طفلكِ الآن قادرًا على إدراك أن إضافة لعبة واحدة إلى لعبتين يجعل المجموع ٣، من دون عدّها (أو من خلال عدّها بسرعة). اطرحي عليه خلال الأنشطة اليومية مسائل حسابية صغيرة، مثل: «كان لديك تفاحتان، وأعطيتكِ تفاحة أخرى، فكم أصبح لديك الآن؟».') WHERE id = '5f9e5aa3-02e0-4bd3-85bf-ad954730aed0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «القفز على قدم واحدة (Hop-stop)». أصبح طفلكِ الآن قادرًا على القفز على قدم واحدة مرتين أو ٣ مرات متتالية. ويتطلب ذلك توازنًا عاليًا وقوة في عضلات الساقين. العبي معه في المنزل لعبة «الحجلة» للارتقاء بتناسقه الحركي إلى أعلى مستوى.') WHERE id = '5d319604-f8fa-4e75-83e3-e78cf306cb47';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«السرد الوصفي» في الكلام. يستطيع طفلكِ وصف صورة رسمها أو حدث شاهده بجمل متسلسلة: «كان هناك كلب هنا، ركض، ثم تسلّق الشجرة...». انتبهي إلى تسلسل أفكاره في أثناء حديثه؛ فهو مؤشر على كيفية تنظيم الأحداث منطقيًا في ذهنه.') WHERE id = '5e32473e-0836-4d23-8816-7e98014c394b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إنجاز كبير بعد ١٤٠٠ يوم! أكمل طفلكِ الآن شهره الـ٤٦. لقد أصبح «عالِمًا» صغيرًا واعيًا بذاته، يتعاطف مع مشاعر الآخرين ويستكشف العالم بمنطق. طوال هذه الأيام الـ١٤٠٠، كنتِ لطفلكِ الملاذ الأكثر أمانًا والمعلّمة الأفضل. أنتِ أم رائعة!') WHERE id = 'af7c9867-8fc8-42cc-b62a-1044c801bdef';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بكِ في الشهر الـ٤٧! أصبح طفلكِ الآن يفهم معنى «المسؤولية» بصورة أفضل. أعطيه «مهام» منزلية صغيرة، مثل سقي النباتات أو وضع المناديل على المائدة. يساعده ذلك على الشعور بأنه فرد مهم ونافع في الأسرة. احرصي على تقدير جهوده وشكره عليها.') WHERE id = '13b68bb4-0e80-4802-bd12-f626258d3f54';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الجري بخطوات متبادلة» ضمن المهارات الحركية. بات طفلكِ قادرًا في أثناء الجري على اجتياز الدرج أو العوائق بإيقاع منتظم، واضعًا قدمًا واحدة مع كل خطوة. يدل ذلك على مدى تطور قوة الجزء السفلي من جسمه وقدرته على التخطيط البصري الحركي.') WHERE id = '8fba68a9-4860-41c9-9d6a-0aabd4a4dc7d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الأصوات والحروف» في الكلام. أصبح طفلكِ قادرًا على تمييز الصوت الذي تبدأ به الكلمات، مثل: «تبدأ كلمة تفاحة بحرف التاء». العبي معه لعبة «البحث عن الأصوات»؛ واطلبي منه العثور في الغرفة على أشياء تبدأ بصوت محدد. يُعد ذلك من أهم الأسس لاكتساب مهارتي القراءة والكتابة مستقبلًا.') WHERE id = '4c5fdac9-9874-4896-80d4-6960b6675b1b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الإمساك الصحيح بالقلم (القبضة الثلاثية)» ضمن المهارات الحركية الدقيقة. أصبح طفلكِ يمسك القلم بثقة أكبر باستخدام الإبهام والسبابة والوسطى (القبضة «الثلاثية»). يتيح له ذلك رسم صور أكثر تفصيلًا ونسخ الحروف. أعطيه أقلامًا بسماكات مختلفة لتدريب عضلات أصابعه.') WHERE id = '01cf8b7d-9668-4ab1-a360-d6968cb99749';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بدأ طفلكِ يُبدي اهتمامًا بمفهوم "الساعة". وقد يسأل: "كم الساعة؟". اشرحي له الوقت من خلال الأحداث بدلًا من الدقائق: "عندما يصل العقرب الكبير إلى هنا، سنخرج للتنزه". فهذا يساعده على فهم أن الزمن مفهوم قابل للقياس.') WHERE id = '3a58737c-1dc5-47f3-86ee-31c959892712';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"التنسيق الحركي المتقاطع" في النشاط البدني. أصبح طفلكِ قادرًا على لمس ركبته اليسرى بيده اليمنى (والعكس) أثناء المشي في مكانه. تتطلب هذه الحركة عمل نصفي الدماغ معًا في الوقت نفسه، وتُسهّل عليه تعلّم القراءة والكتابة مستقبلًا.') WHERE id = '86960e2f-7035-4c14-a9a6-baeb23c3ea3d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"تفاصيل الماضي" في تطور الكلام. أصبح طفلكِ قادرًا على سرد حدث وقع قبل بضعة أيام بتسلسل: "عندما ذهبنا إلى بيت جدتي، رأينا قطة هناك، وكانت قد تسلقت الشجرة". ولتعزيز هذه "الذاكرة العرضية" لديه، اسأليه في نهاية اليوم: "ما أكثر شيء ممتع حدث اليوم؟".') WHERE id = '6caf0def-6055-4b83-9a80-442193cfb9e1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"قص الورق: الأشكال المعقدة" في المهارات الحركية الدقيقة. لم يعد طفلكِ يحاول بالمقص قص خط مستقيم فحسب، بل يحاول أيضًا قص خطوط متموجة أو دائرة كبيرة. وهذا يدل على تطور التناسق بين اليد والعين بدرجة عالية جدًا.') WHERE id = '64c3b0ce-8c21-4147-b606-f32ae65475bf';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"مفهوم اليمين واليسار". أصبح طفلكِ قادرًا على التمييز بين يده اليمنى واليسرى، وإن لم يكن ذلك بدقة تامة بعد. عززي إدراكه المكاني بقولكِ له: "أمسك الملعقة بيدك اليمنى" أو "ارتدِ جوربك في قدمك اليسرى". هذه المهارة مهمة كي لا يخلط مستقبلًا بين اتجاهات الحروف.') WHERE id = '51c70f08-e08e-4a17-97ca-6373b3c435eb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"القيادة ضمن المجموعة" في السلوك الاجتماعي. أثناء اللعب، أصبح طفلكِ يوزع الأدوار على الأطفال الآخرين قائلًا: "أنت انتقل إلى هنا، وأنت افعل هذا". وبهذا يختبر فهمه للتسلسل الاجتماعي ومهاراته التنظيمية. راقبي محاولاته القيادية وساعديه على أن يكون عادلًا.') WHERE id = 'ed221959-c928-4692-880d-29170d62352e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"ضبط النفس: فهم منطق القواعد". لم يعد طفلكِ يحاول الالتزام بالقواعد لمجرد أنكِ طلبتِ منه ذلك، بل لأنه يفهم منطقها. "أمسك بيدك عندما نسير في الطريق لأن هناك سيارات". واصلي توضيح أهمية القواعد للحفاظ على السلامة والنظام؛ فهذا أساس الانضباط الذاتي.') WHERE id = 'd91c45ef-c67b-4312-9a1e-572e86ed0a0e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"التقاسم العادل" في السلوك الاجتماعي. بدأ طفلكِ يهتم بتقسيم الألعاب أو الحلوى بالتساوي بين أصدقائه: "واحدة لك وواحدة لي". وهذا يجمع بين التعاطف الاجتماعي والمفاهيم الرياضية الأولية، مثل القسمة.') WHERE id = '2a9fd489-5479-4444-9ad0-d9ca9e6d37c8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"تصنيف الأشياء" في التطور المعرفي. أصبح طفلكِ يصنّف الأشياء وفقًا لنوعها ومكان استخدامها: "هذه للمطبخ، وهذه لغرفة النوم". وهذا يوضح كيف تُنظَّم المعلومات في دماغه بصورة منهجية وهرمية.') WHERE id = 'b49a3e45-1e44-429c-b3ab-7432f30a4a37';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق البدني: "إمساك الكرة ورميها (التكامل)". أصبح طفلكِ قادرًا على رمي الكرة نحو الهدف فور إمساكها. وهذا يعني قدرته على الانتقال بسلاسة بين الحركات المتتابعة. نظّمي معه في الحديقة لعبة "ارمِ والتقط" لتعزيز سرعة استجابته ورشاقته.') WHERE id = 'b2cee277-0949-412e-af09-df96b2fd9cfd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"بناء الجمل المركبة" في تطور الكلام. أصبح طفلكِ يؤلف جملًا طويلة ومنطقية باستخدام أدوات الربط مثل "إذا" و"لأن" و"لكن". استمعي إليه دون مقاطعته، وساعديه على توسيع فكرته بقولكِ: "إذًا، أنت تفكر بهذه الطريقة...". فهذا يعزز قدرته على التعبير عن نفسه وعلى استخدام حصيلته اللغوية بفاعلية.') WHERE id = 'eaf98320-82a4-46ba-81fe-43fd023e6b82';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'القوة العاطفية: "تهدئة النفس". قد لا يبكي طفلكِ فورًا عند تعرضه لسقوط بسيط أو إخفاق، بل قد يقول لنفسه: "لم يحدث شيء" ثم ينهض. وهذا مؤشر مهم على المرونة العاطفية. ادعمي شجاعته دائمًا بقولكِ: "أنت قوي جدًا!".') WHERE id = 'c0cb0b02-4a51-4012-b51b-53868aad0bf0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: "ثبات الكمية: العدد". إذا وضعتِ العدد نفسه من الحجارة متقاربًا في جهة، ومتباعدًا في الجهة الأخرى، فسيبدأ طفلكِ في إدراك أن عدد الحجارة متساوٍ في الجهتين. تمثل هذه المرحلة انتقالًا من الانخداع بالمظهر البصري إلى الاستنتاج المنطقي.') WHERE id = '55c3f5e4-d3a4-465e-b035-b83e41b450d4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: "القفز على قدم واحدة". أصبح طفلكِ قادرًا على القفز إلى الأمام عدة مرات على قدم واحدة. ويتطلب ذلك التوازن وقوة دفع كبيرة في الساق. إنه وقت رائع لتلعبي معه في المنزل لعبة "الحجلة".') WHERE id = 'ddfca79d-8eb7-4cbd-84fd-61e54d7153db';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور النطق: "الأصوات داخل الكلمات". أصبح طفلكِ قادرًا أيضًا على تمييز الأصوات في نهاية الكلمات (فمثلًا، يمكنه القول إن كلمة "alma" تنتهي بصوت ''a''). وهذه مرحلة متقدمة جدًا من الوعي الفونيمي. العبي معه لعبة "ابحث عن كلمة تبدأ بالحرف الأخير" (سلسلة الكلمات) لتنمية حصيلته اللغوية وانتباهه السمعي.') WHERE id = '3863c552-322d-4dc8-a917-02d61270f313';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: "الإخفاق والاستراتيجية". عندما لا ينجح طفلكِ في أداء مهمة ما، لا يبكي فورًا، بل يفكر: "هل أجرّب طريقة أخرى؟". وهذا هو أساس "عقلية النمو" (growth mindset). احرصي على مدحه لبحثه عن طريقة جديدة، لا على النتيجة فقط.') WHERE id = 'da0d4f8a-08c6-45ad-9022-933f9025eb01';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ يميّز الأشياء ليس بناءً على مظهرها فقط، بل وفقًا للمادة المصنوعة منها أيضًا: "هذا بلاستيك، وهذا حديد". أعطيه أشياء ذات ملمس مختلف واسأليه عن الفروق بينها. سيساعده ذلك على تحليل العالم من حوله بمزيد من التفصيل وتنظيم معلوماته عن العالم المادي.') WHERE id = 'ec9b72ac-4600-4d72-8d5e-3a0bc232d29c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية: "القفز الدقيق". أصبح طفلكِ قادرًا على القفز نحو هدف محدد (مثل القفز داخل دائرة مرسومة على الأرض). ويُظهر ذلك قدرته على التوازن وتقدير المسافات في المكان. ستكون لعبة "القفز من حجر إلى حجر" في الحديقة تمرينًا رائعًا له.') WHERE id = 'f6611b06-b8bc-42ff-84b4-2e17ea2e10d6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الخيال ورواية القصص» في الكلام. قد يروي لكِ طفلكِ حكايات قصيرة من نسج خياله، تمتزج فيها الحقيقة بالخيال. شجّعيه بأسئلة تنمّ عن الاهتمام مثل: «حقًا؟» أو «وماذا حدث بعد ذلك؟». فهذا يساعده مستقبلًا على التحدث بطلاقة وتعبير.') WHERE id = 'c414dc79-8944-48c3-a5d5-e50145e600bc';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إنجاز 1430 يومًا! أتمّ طفلكِ الآن 47 شهرًا. لقد أصبح «عالِمًا» صغيرًا يعي ذاته، ويتعاطف مع مشاعر الآخرين، ويستكشف العالم بمنطق. خلال هذه الأيام الـ1430، كنتِ لطفلكِ الملاذ الأكثر أمانًا والمعلّمة الأفضل. أنتِ أم رائعة!') WHERE id = '8f2e9299-bb7b-4d28-9fbc-c07c7ba2a262';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بدأ العد التنازلي للشهر الـ48 (عمر 4 سنوات)! أصبح طفلكِ الآن يطبّق تمامًا الفرق بين «أنا» و«نحن» في اللعب الاجتماعي. فإذا كان يوزّع المهام قائلًا مثلًا: «هيا نبني سفينة معًا، أمسك أنت بالشراع وسأتولى أنا الدفة»، فهذا يمثّل ذروة ذكاء التعاون لديه. أشيدي بروح الفريق هذه؛ فهي مهمة لحياته المدرسية مستقبلًا.') WHERE id = 'b940be7d-ee82-4c09-8760-e2ce9294193f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الانعطافات الدقيقة» في الحركة الجسدية. يستطيع طفلكِ الآن التوقف فجأة أثناء الركض بأقصى سرعة أو الانعطاف بحدة من دون أن يفقد توازنه. وهذا يدل على التنسيق الكامل بين الجهاز الدهليزي والتحكم العضلي. أنشئي له «مسار حواجز» صغيرًا في الحديقة.') WHERE id = 'ce453995-5119-4943-ace6-1439bc5d5820';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«تحليل الأصوات» في الكلام. بدأ طفلكِ الآن يميّز الأصوات في نهاية الكلمات، وليس في بدايتها فقط، مثل: «تنتهي كلمة ماما بصوت الألف». وهذا دليل على تطور الوعي الفونيمي لديه. نمّي حسّه اللغوي باللعب معه لعبة «اعثر على كلمة جديدة تبدأ بالصوت الأخير».') WHERE id = 'e258838d-b844-4e68-840e-2eb0ef520682';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«قص الورق: الأشكال التفصيلية» ضمن المهارات الحركية الدقيقة. يحاول طفلكِ الآن قص أشكال معقدة بالمقص باتباع حوافها، مثل نجمة أو صورة ظلية لحيوان صغير. وهذا يوضح مدى تطور التآزر بين العين واليد لديه. قدّمي له أوراقًا بألوان مختلفة.') WHERE id = '619d1623-d881-46f6-a718-4a537172efc7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور الكلام: "تصنيف الأضداد". أصبح طفلكِ قادرًا على التمييز تمامًا بين مفاهيم مثل "ساخن-بارد" و"مرتفع-منخفض" و"ثقيل-خفيف". العبي معه لعبة "اعثر على العكس": قولي أنتِ "كبير"، وليقل هو "صغير". يساعد ذلك على تنمية حصيلته اللغوية وقدرته على التفكير التجريدي والمقارنة.') WHERE id = '00735398-0d89-4428-a943-f4a27fc19021';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية الدقيقة: "نسخ الأشكال: المثلث وعلامة الزائد". أصبح طفلكِ قادرًا على رسم علامة زائد (+) من خلال تقاطع خطين مستقيمين، ويحاول رسم أشكال تشبه المثلث. هذه هي الأسس الأولى للكتابة. قدّمي له أقلام تلوين وأوراقًا فارغة لدعم هذه "الاكتشافات الهندسية".') WHERE id = '1b117df4-43a4-4780-a2e3-365c2acc3518';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"ضبط النفس: تأجيل الرغبة". أصبح طفلكِ يتقبل ضرورة الانتظار مدة أطول قليلًا للحصول على مكافأة، مثل "الحلوى بعد تناول الطعام". يدل ذلك على تطور قوة الإرادة وضبط النفس (تأجيل الإشباع). احرصي على الإشادة بصبره؛ فهو مفتاح النجاح الأكاديمي في المستقبل.') WHERE id = '93c7b1b4-9941-4328-bd03-c48ffc7f605f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في السلوك الاجتماعي: "التضامن مع المجموعة". عندما يبكي أحد أصدقاء طفلكِ، لم يعد يكتفي بالنظر إليه، بل يسأله "ماذا حدث؟" أو يأتي ليخبركِ. هذه هي المرحلة النشطة من التعاطف. ادعمي هذا الجانب الحنون لديه بقولكِ: "أنت صديق لطيف جدًا".') WHERE id = 'e9a7f349-2186-4929-ba3f-64f7d951af57';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: "أسس الجمع". أصبح طفلكِ قادرًا على إدراك أن إضافة لعبة واحدة إلى لعبتين يجعل مجموعها 3، من دون عدّها أو بعد عدّها بسرعة. اطرحي عليه خلال الأنشطة اليومية ألغازًا حسابية صغيرة مثل: "كان لديك 2 من التفاح، وأعطيتكِ أنا تفاحة واحدة، فكم أصبح لديك الآن؟".') WHERE id = '6d1eeaa2-0164-4cca-94b4-9c14e8d79d60';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التناسق الجسدي: "الحركة على الدرج". أصبح طفلكِ يصعد الدرج وينزله بثقة، ويمكنه أحيانًا الحفاظ على توازنه حتى عندما يحمل لعبة في يده. يدل ذلك على مستوى متقدم من التوازن الديناميكي. ابقي دائمًا بالقرب منه، لكن امنحيه الثقة والمساحة ليتحرك بحرية.') WHERE id = '28cfd5f7-ecbc-4133-9e9d-cc5c82140054';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يعد الطفل يميّز الأشياء من خلال مظهرها فحسب، بل أيضًا وفقًا للمادة المصنوعة منها: «هذا بلاستيك، أما هذا فحديد». أعطيه أشياء ذات ملمس متنوع واسأليه عن الفروق بينها. يساعده ذلك على تحليل العالم المحيط به بمزيد من التفصيل وتنظيم معلوماته عن العالم المادي.') WHERE id = '0ec14802-bab2-45c4-8cbf-788bdfa85e13';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«القفز الدقيق» في المهارات الحركية. أصبح الطفل قادرًا على القفز نحو هدف محدد، مثل داخل دائرة مرسومة على الأرض. يدل ذلك على قدرته على الحفاظ على التوازن وتقدير المسافات في المكان. وتُعدّ لعبة «القفز من حجر إلى آخر» في الحديقة تمرينًا رائعًا له.') WHERE id = '0ddedeb7-e832-48ca-923d-05838885cdc1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«تصنيف الأضداد» في تطور اللغة. أصبح الطفل يميّز تمامًا بين مفاهيم مثل «ساخن وبارد» و«مرتفع ومنخفض» و«ثقيل وخفيف». العبي معه لعبة «اعثر على العكس»: قولي أنتِ «كبير»، وليقل هو «صغير». ينمّي ذلك حصيلته اللغوية وقدرته على التفكير التجريدي والمقارنة.') WHERE id = '3810cfc8-49ab-40fa-b90d-2edf9dc84fae';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«نسخ الأشكال: المثلث وعلامة الجمع» ضمن المهارات الحركية الدقيقة. أصبح الطفل قادرًا على رسم علامة الجمع (+) بتقاطع خطين مستقيمين، ويحاول رسم أشكال تشبه المثلث. تمثّل هذه المهارات الأسس الأولى للكتابة. ادعمي هذه «الاكتشافات الهندسية» بإعطائه أقلام تلوين وأوراقًا فارغة.') WHERE id = 'dfeb7b05-cea8-4a6f-b41b-005f3d3c488e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«ضبط النفس: تأجيل الرغبة». أصبح الطفل يتقبّل ضرورة الانتظار مدة أطول قليلًا للحصول على مكافأة، مثل «الحلوى بعد تناول الطعام». يعكس ذلك تطور قوة الإرادة وضبط النفس (تأجيل الإشباع). احرصي على الإشادة بصبره؛ فهو مفتاح النجاح الأكاديمي مستقبلًا.') WHERE id = '988ae101-5f2f-4a86-a365-28a27e843965';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«التضامن الجماعي» في السلوك الاجتماعي. عندما يبكي أحد أصدقاء الطفل، لم يعد يكتفي بالنظر إليه، بل يسأله: «ماذا حدث؟» أو يأتي ليخبركِ. تمثّل هذه مرحلة التعاطف الفعّال. شجّعي هذا الجانب الحنون فيه بقولكِ: «أنت صديق عطوف جدًا».') WHERE id = 'ed4539aa-f1cf-4dd1-97f9-a5cf3f6b499d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"التحكم في الذات: الدبلوماسية العاطفية". عندما لا يحصل طفلكِ على ما يريده، قد يبدأ بدلًا من الصراخ في توضيح أسبابه لكِ: "لكنني كنت أريد هذا كثيرًا، لأن...". قدّري محاولته هذه للحوار. اعترفي بمشاعره وأكّدي له أنكِ تتفهمينها، لكن اشرحي له أيضًا بصبر سبب ثبات القواعد وعدم تغييرها.') WHERE id = 'd8f54a1a-d4b0-4c91-b361-1e6376bfa2db';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الالتزام بالقواعد" في السلوك الاجتماعي. أصبح طفلكِ يولي أهمية خاصة للعب وفق القواعد دون مخالفتها في ألعاب الطاولة، مثل الدومينو أو ألعاب الأرقام البسيطة. وهذه مرحلة مهمة من التكيف الاجتماعي. عندما يلتزم بالقواعد، شجّعيه بقولكِ: "لقد لعبت بنزاهة وصبر كبيرين".') WHERE id = '111e7db0-d36d-44a0-97d8-10b28cd566ca';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في التطور المعرفي: "ثبات الكمية: اختبار الحجم". إذا شكّلتِ المقدار نفسه من الصلصال مرةً على هيئة كرة ومرةً على هيئة "ثعبان" طويل، فسيبدأ طفلكِ في إدراك أن الكمية لم تتغير. تمثل هذه المرحلة انتقالًا من الانخداع بالمظهر البصري إلى الاستنتاج المنطقي. جرّبا هذه التجارب معًا.') WHERE id = '0655a03a-60b9-48e1-b285-1d3c83082836';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الحركي: "القفز على قدم واحدة". أصبح طفلكِ قادرًا على القفز إلى الأمام عدة مرات على قدم واحدة. يتطلب ذلك التوازن وقوة عضلية سريعة في الساق. إنه وقت رائع للعب "الحجلة" معه في المنزل؛ فهي تعزز أيضًا قدرته على تحديد الاتجاهات وفهم موقعه في المكان.') WHERE id = 'c5a0358e-6841-4ba2-8c21-cb976413e324';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في تطور اللغة: "دمج الخيال والمنطق". قد يروي لكِ طفلكِ قصصًا من ابتكاره، لكنها تتبع تسلسلًا منطقيًا. "كان هناك ذات يوم روبوت، فتوقف لأن بطاريته نفدت...". شجّعيه على متابعة قصصه بأسئلة مثل: "وماذا حدث بعد ذلك؟". سيساعده ذلك مستقبلًا على التحدث بطلاقة وتعبير واضح.') WHERE id = '5fe788e8-9a0a-4448-9455-65cf7a8679b1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المرونة العاطفية: "استراتيجية جديدة للتعامل مع الإخفاق". عندما لا ينجح طفلكِ في إتمام مهمة، مثل تركيب أحجية، لا يغضب فورًا، بل يبحث عن طرق جديدة قائلًا: "ربما أضع هذه القطعة هكذا؟". وهذا هو أساس "عقلية النمو" (growth mindset). احرصي على مدح جهده في إيجاد طريقة جديدة، لا النتيجة التي توصل إليها.') WHERE id = '19cb7d19-f480-4e1f-805a-267dba1df2a8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«أساسيات الجمع» في التطور المعرفي. أصبح طفلكِ قادرًا على إدراك أن وضع لعبة واحدة بجانب لعبتين يجعل المجموع 3، من دون عدّها أو من خلال عدّها بسرعة. اطرحي عليهِ في الأنشطة اليومية مسائل حسابية صغيرة مثل: «كان لديكَ تفاحتان، وأعطيتُكَ تفاحة أخرى، فكم أصبح لديكَ الآن؟».') WHERE id = '321e201a-5cd6-485a-a700-1c1f11885a2b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «الحركة على الدرج». أصبح طفلكِ يصعد الدرج وينزله بثقة، ويمكنه أحيانًا الحفاظ على توازنه حتى عندما يحمل لعبة في يده. وهذا يدل على مستوى متقدم من التوازن الديناميكي. ابقي دائمًا بالقرب منه، لكن امنحيه الثقة ليتحرك بحرية.') WHERE id = '26b9ae52-0022-4e15-934b-ad179ba90589';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الخيال وسرد القصص» في تطور الكلام. قد يروي لكِ طفلكِ حكايات قصيرة من نسج خياله، تمتزج فيها الحقيقة بالخيال. شجّعيه على متابعة قصصه بأسئلة تُظهر اهتمامكِ، مثل: «حقًا؟» أو «وماذا حدث بعد ذلك؟». فهذا يساعده مستقبلًا على التحدث بطلاقة وتعبير.') WHERE id = 'e96b1dc7-ba0c-47d3-b15a-cb6918e2bc9b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يتبقَّ سوى 30 يومًا حتى يبلغ طفلكِ 4 سنوات! إنه الآن في أكثر مراحل ما قبل المدرسة ثراءً بالتطور والتعلّم. لقد أصبح فردًا متكاملًا، إنسانًا صغيرًا له أذواقه ومخاوفه وأسئلته التي لا تنتهي. لقد قطعتِ هذه الرحلة بالعلم والحب. «Anacan» معكما دائمًا!') WHERE id = '34fd4a41-2c8b-49b5-b2b0-6911f5bb04ab';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ يصنّف الأشياء ليس وفق مظهرها الخارجي فحسب، بل وفق الفئة التي تنتمي إليها أيضًا: «هذه حيوانات بحرية، وتلك حيوانات الغابة». وهذا يدل على أن المعلومات في دماغه أصبحت منظّمة ضمن فئات علمية. العبي معه لعبة «مَن يعيش أين؟».') WHERE id = 'bacec645-5384-4fc1-94d1-94b2914a27a1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في المهارات الحركية: «الجري السريع والتوقف المتناسق». أصبح طفلكِ قادرًا على التوقف فورًا عند سماع أمركِ «توقف!» أثناء الجري بأقصى سرعته، من دون أن يسقط أو يتعثر إلى الأمام. وهذا يدل على بلوغ التحكم العضلي والاستجابة السمعية الحركية مستوى متقدمًا جدًا. كرّرا هذه اللعبة بانتظام في الحديقة.') WHERE id = 'ea737131-3977-4085-b4c4-94dd4ae125f1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«بناء القصص المعقّدة» في الكلام. أصبح طفلكِ الآن يبتكر حبكة في القصص الخيالية التي يؤلفها مستخدمًا أدوات ربط مثل «لأن»، و«لكن»، و«لذلك». أنصتي إلى قصصه باهتمام، وشجّعيه على إضافة تفاصيل جديدة بأسئلة مثل: «برأيك، ماذا فعل البطل بعد ذلك؟».') WHERE id = '24dad4d0-2c9d-4d1c-bb0a-41d9b402e0e7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يتبقَّ سوى 20 يومًا على بلوغ طفلكِ سن الرابعة! لقد تجاوز الآن عادات مرحلة الرضاعة تمامًا، وأصبح شخصًا صغيرًا ذا طابع مميز. كنتِ خلال هذه الأيام الـ1460 النور الأكبر في مسيرة نموه. إنجازاته ثمرة حبكِ. أنتِ رائعة!') WHERE id = 'd76fe554-fd7b-4db0-9296-a5ba3be690d0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«النقاش المهذب» في الكلام. لم يعد طفلكِ يكتفي بقول: «من فضلكِ، هل تسمحين؟» للحصول على ما يريده، بل يذكر سببًا أيضًا: «لأنني أحبه كثيرًا». ردّكِ المهذب يسهم في تشكيل أسلوبه في التواصل الاجتماعي. قدّري كل طلب مهذب منه بقولكِ: «يسعدني أن أجيبك لأنك طلبت ذلك بأسلوب جميل».') WHERE id = '0bfff590-18d1-438c-bef2-c5dac59fc7e3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«النسخ البصري للحروف والأرقام» ضمن المهارات الحركية الدقيقة. يحاول طفلكِ الآن رسم حروف اسمه أو أرقام مثل «1, 2, 3» على الورق. وهذا يجمع بين الحركة والذاكرة البصرية. أعطيه أقلام تلوين بألوان مختلفة، وعلّقي «كتاباته» في مكان ظاهر في المنزل.') WHERE id = '65fb665a-a079-4bde-be1e-8536275e5fd6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«ضبط النفس: الاستقلال العاطفي». عندما يواجه طفلكِ مشكلة صغيرة، مثل تفكك لعبته، لم يعد يهرع إليكِ فورًا، بل يحاول إصلاحها بنفسه أولًا. وهذا يعزز شعوره بأنه «قادر على فعل ذلك». راقبي محاولاته المستقلة هذه، ولا تتدخلي إلا عندما يحتاج إلى مساعدتكِ.') WHERE id = '5a2e55ce-3f97-41a9-965d-b857b33a020f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«شرح القواعد» في السلوك الاجتماعي. أصبح طفلكِ يشرح قواعد اللعبة للأطفال الأصغر سنًا أو لألعابه، قائلًا: «أنا أولًا، ثم أنت». وهذا مؤشر على الانضباط الذاتي والمهارات القيادية. ادعمي هذا الجانب «التعليمي» لديه.') WHERE id = '1e4b1da3-fa3d-4b83-9554-7fdd901b9dfb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«تقويم الزمن» في التطور المعرفي. أصبح طفلكِ يفهم عبارات مثل «بقيت 3 أيام» أو «سنذهب في عطلة نهاية الأسبوع». أعدّا «تقويمًا للعد التنازلي» مع اقتراب عيد ميلاده. يساعده وضع علامة على كل يوم يمضي على إدراك مرور الوقت بصورة ملموسة.') WHERE id = 'e9a169de-bc44-43dd-b6f0-9adaff7e3796';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التناسق الجسدي: «ركل الكرة نحو هدف». لم يعد طفلكِ يركل الكرة عشوائيًا، بل يحاول توجيهها نحو هدف محدد، مثل تمريرها بين حجرين. ويتطلب ذلك تقدير المسافة في المكان والتحكم الدقيق في عضلات الساق.') WHERE id = '1c5a132d-9357-46a5-b5fe-17d6baae9cac';

