UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'وقت الاستلقاء على البطن أمام المرآة'), description_ar = COALESCE(description_ar, 'وقت للاستلقاء على البطن باستخدام المرآة لجذب انتباه طفلكِ'), instructions_ar = COALESCE(instructions_ar, '1. ضعي طفلكِ على بطنه فوق سطح ناعم\n2. ضعي مرآة أمام طفلكِ\n3. تحدثي إليه وشجعيه على رفع رأسه والنظر إلى المرآة') WHERE id = 'c1e1e351-1af5-4816-8f2c-de374135c16b';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'وقت التدليك اللطيف'), description_ar = COALESCE(description_ar, 'تدليك طفلكِ لتعزيز الترابط ودعم نموه'), instructions_ar = COALESCE(instructions_ar, '1. استخدمي زيتًا آمنًا للأطفال\n2. دلّكي ذراعي طفلكِ وساقيه وبطنه برفق\n3. غنّي له أو تحدثي إليه أثناء التدليك') WHERE id = 'ea46fd4e-7a05-4463-bf0d-2b9e8add8866';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'مشاهدة الفقاعات'), description_ar = COALESCE(description_ar, 'مشاهدة الفقاعات لتنمية مهارة التتبع البصري'), instructions_ar = COALESCE(instructions_ar, '1. انفخي فقاعات بالقرب من طفلكِ\n2. أشيري إلى الفقاعات وصِفيها له\n3. دعي الفقاعات تنفجر برفق على بشرة طفلكِ') WHERE id = '449a2aa8-5640-4e79-b7fa-0c92027bb12c';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'استكشاف الملمس'), description_ar = COALESCE(description_ar, 'استكشاف أنواع مختلفة من الملمس'), instructions_ar = COALESCE(instructions_ar, '1. اجمعي أشياء ذات ملمس مختلف\n2. دعي طفلكِ يلمس كل غرض\n3. صِفي له الملمس: ناعم، خشن، أملس') WHERE id = 'e257be70-2380-44c1-91be-9e079d4879b7';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'اللعب بالحاويات'), description_ar = COALESCE(description_ar, 'وضع الأشياء داخل الحاويات وإخراجها منها'), instructions_ar = COALESCE(instructions_ar, '1. استخدمي حاوية آمنة وألعابًا طرية\n2. أري طفلكِ كيفية وضع الأشياء داخلها\n3. شجعي طفلكِ على إخراج الأشياء منها\n4. احتفلي بمشاركته بالتصفيق') WHERE id = '4d841e68-97b6-4186-be6e-26bef3df65df';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'دحرجة الكرة'), description_ar = COALESCE(description_ar, 'دحرجة الكرة ذهابًا وإيابًا'), instructions_ar = COALESCE(instructions_ar, '1. اجلسي في مواجهة طفلكِ\n2. دحرجي كرة طرية باتجاه طفلكِ\n3. شجعيه على دفعها نحوكِ\n4. شجعيه بحماس عندما يشارك') WHERE id = '073a2084-da2c-4ef3-8a93-22136a2c77a5';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'تتبّع الخشخيشة'), description_ar = COALESCE(description_ar, 'تتبّع الخشخيشة بصريًا وسمعيًا'), instructions_ar = COALESCE(instructions_ar, '1. هزّي الخشخيشة لجذب انتباه طفلكِ\n2. حرّكيها ببطء في اتجاهات مختلفة\n3. دعي طفلكِ يحاول الإمساك بها') WHERE id = 'ea96ae3c-ed32-4118-b146-ecbb3a3bb763';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'مكالمة هاتفية تخيّلية'), description_ar = COALESCE(description_ar, 'لعب تخيّلي باستخدام الهاتف'), instructions_ar = COALESCE(instructions_ar, '1. أعطي طفلكِ هاتفًا لعبة\n2. تظاهري بالاتصال بطفلكِ\n3. شجّعي طفلكِ على «التحدث»\n4. تناوبا على الكلام') WHERE id = 'e08ba272-48b6-4a5f-b44b-0ba7da5cb808';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'الغناء الهادئ'), description_ar = COALESCE(description_ar, 'غنّي لطفلكِ بصوت خافت'), instructions_ar = COALESCE(instructions_ar, 'احملي طفلكِ بالقرب منكِ وغنّي له تهويدات هادئة أو أغاني بسيطة. راقبي مدى استجابته لصوتكِ.') WHERE id = 'a3c29297-6e01-48c7-9b34-d7d9d3af361a';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'وقت الاستلقاء على البطن مع الألعاب'), description_ar = COALESCE(description_ar, 'ضعي ألعابًا ملوّنة أمام طفلكِ أثناء استلقائه على بطنه'), instructions_ar = COALESCE(instructions_ar, 'ضعي طفلكِ على بطنه. ضعي ألعابًا ملوّنة بعيدًا قليلًا عن متناول يديه لتشجيعه على مدّ يديه ورفع رأسه.') WHERE id = 'e0e77763-f782-46a8-bcfe-1cf276ba2cce';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'وقت رشّ الماء'), description_ar = COALESCE(description_ar, 'دعي طفلكِ يرشّ الماء بيديه'), instructions_ar = COALESCE(instructions_ar, 'املئي وعاءً غير عميق بالماء الدافئ. دعي طفلكِ يلمس الماء ويرشّه. راقبيه عن كثب دائمًا.') WHERE id = '5cea30c3-38d1-4326-b521-b5428eba62a1';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'الطفل الطائر'), description_ar = COALESCE(description_ar, 'ارفعي طفلكِ برفق في الهواء'), instructions_ar = COALESCE(instructions_ar, 'استلقي على ظهركِ، وأمسكي طفلكِ بإحكام ثم ارفعيه برفق كما لو كان يطير. هذا نشاط رائع لتقوية الرابطة بينكما.') WHERE id = 'eb368346-4c28-48f4-acc2-82c3747e66bf';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'وقت الاستلقاء على البطن أمام المرآة'), description_ar = COALESCE(description_ar, 'رؤية رضيعكِ لنفسه في المرآة تحفّز نموه'), instructions_ar = COALESCE(instructions_ar, 'ضعي رضيعكِ على بطنه فوق وسادة. ضعي مرآة أمامه. أريه انعكاسه في المرآة.') WHERE id = '20e1c63e-791f-43a8-bb33-84ebfe166368';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'فرقة المطبخ'), description_ar = COALESCE(description_ar, 'تنمية الإحساس بالإيقاع باستخدام القدور والمقالي'), instructions_ar = COALESCE(instructions_ar, 'ضعي ملعقة خشبية وقدورًا أمام رضيعكِ. أريه كيف يطرق عليها. اصنعا إيقاعًا معًا.') WHERE id = '5a6d5c7d-3489-4b3d-8210-fbeed43d3536';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'نفق الصندوق'), description_ar = COALESCE(description_ar, 'تنمية مهارات الحبو والاستكشاف'), instructions_ar = COALESCE(instructions_ar, 'افتحي جانبي صندوق كرتوني كبير. شجّعي رضيعكِ على الحبو عبره من أحد الجانبين. ناديه من الجانب الآخر.') WHERE id = '8266c528-ae95-47fa-b7f4-28400410ebc2';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'دمى الجوارب'), description_ar = COALESCE(description_ar, 'تنمية التواصل والإبداع'), instructions_ar = COALESCE(instructions_ar, 'اصنعي دمية من جورب قديم. "تحدّثي" مع رضيعكِ من خلالها. أصدري أصواتًا مختلفة.') WHERE id = 'fc6ee2c8-0599-4677-994a-dc1385d83024';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'جولة الملامس'), description_ar = COALESCE(description_ar, 'تنمية الحواس باستخدام ملامس مختلفة'), instructions_ar = COALESCE(instructions_ar, 'رتّبي مواد ذات ملامس مختلفة (بطانية، وشاح، ورق) على الأرض. دعي رضيعكِ يحبو فوقها.') WHERE id = '3b19cf38-0d12-4b49-81d4-69a60f7b3cc2';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'بطاقات عالية التباين'), description_ar = COALESCE(description_ar, 'بطاقات بأنماط سوداء وبيضاء لتنمية حاسة البصر'), instructions_ar = COALESCE(instructions_ar, '1. أمسكي البطاقة على بُعد 20-30cm من وجه رضيعكِ\n2. حرّكيها ببطء من اليسار إلى اليمين\n3. راقبي عيني رضيعكِ وهما تتبعان البطاقة') WHERE id = '16373dad-486f-490c-bc14-144cfd354f5f';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'سلة الكنوز'), description_ar = COALESCE(description_ar, 'املئي سلة بأغراض منزلية آمنة'), instructions_ar = COALESCE(instructions_ar, 'اجمعي 5-10 أغراض آمنة ذات ملمس وأشكال متنوعة. دعي طفلكِ يستكشفها بحرية، واذكري اسم كل غرض.') WHERE id = 'ebc79f1e-7d23-4c5a-b28e-dda90e096b3a';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'أغنية التصفيق'), description_ar = COALESCE(description_ar, 'غنّيا وصفّقا معًا'), instructions_ar = COALESCE(instructions_ar, 'غنّي أغاني تصفيق بسيطة. ساعدي طفلكِ على ضم يديه والتصفيق بهما. هذا نشاط رائع لتنمية الإحساس بالإيقاع والتناسق الحركي.') WHERE id = 'a4aa194b-9d64-4f72-8ba4-90ae6e12f0c5';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'لعبة إسقاط الملاعق'), description_ar = COALESCE(description_ar, 'أسقطي الملاعق في قدر'), instructions_ar = COALESCE(instructions_ar, 'أري طفلكِ كيفية إسقاط الملاعق الخشبية في قدر. دعيه يستمع إلى الصوت ويكرر ذلك.') WHERE id = 'b99f62da-0ba0-4a8c-a136-3eae65f486ee';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'نقل كرات القطن'), description_ar = COALESCE(description_ar, 'انقلي كرات القطن بين الأوعية'), instructions_ar = COALESCE(instructions_ar, 'أعطي طفلكِ وعاءين وكرات من القطن. أريه كيفية التقاطها ونقلها من وعاء إلى آخر. هذا نشاط رائع لتنمية المهارات الحركية الدقيقة.') WHERE id = 'bf6bdf5d-9977-460c-978a-4df325af6d86';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'تمزيق الورق'), description_ar = COALESCE(description_ar, 'مزّقي الورق إلى قطع'), instructions_ar = COALESCE(instructions_ar, 'أعطي طفلكِ ورقًا ناعمًا ليمزقه. يساعد الصوت والملمس على تنمية وعيه الحسي وتقوية يديه.') WHERE id = 'c80230e8-6d2c-459b-9557-6ff0795bbec7';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'نفق الأنبوب الكرتوني'), description_ar = COALESCE(description_ar, 'دحرجي كرة عبر أنابيب كرتونية'), instructions_ar = COALESCE(instructions_ar, 'أمسكي أنبوبًا كرتونيًا وأري طفلكِ كيفية دحرجة كرة صغيرة عبره. ثم طاردا الكرة معًا.') WHERE id = '977ee460-5cf3-4eaa-878a-9d316320f9a5';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'لعبة الغميضة بقطعة قماش'), description_ar = COALESCE(description_ar, 'لعبة الغميضة الكلاسيكية'), instructions_ar = COALESCE(instructions_ar, '1. غطّي وجهكِ بقطعة قماش
2. قولي: "أين أنا؟"
3. أزيلي القماش وقولي: "ها أنا ذا!"
4. غطّي وجه طفلكِ برفق وكرّري اللعبة') WHERE id = '58d3e4f3-7256-4eaa-901e-ce192a8aca44';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'لعبة معلّقة بالأبيض والأسود'), description_ar = COALESCE(description_ar, 'علّقي صورًا عالية التباين فوق طفلكِ'), instructions_ar = COALESCE(instructions_ar, 'قصّي أشكالًا بسيطة من الورق وعلّقيها على ارتفاع 20-30cm فوق طفلكِ. دعي طفلكِ يتتبّع حركتها بعينيه.') WHERE id = '8c2f484b-326a-4dac-b7a4-7eb528aff395';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'تكديس الأكواب'), description_ar = COALESCE(description_ar, 'بناء أبراج باستخدام الأكواب'), instructions_ar = COALESCE(instructions_ar, '1. أري طفلكِ كيفية تكديس الأكواب
2. دعي طفلكِ يهدمها
3. أعيدي بناءها وكرّري النشاط
4. اذكري أسماء الألوان أثناء تكديس الأكواب') WHERE id = '6145784f-e184-4ae7-8691-ff33671cc7d0';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'قراءة كتاب مصوّر'), description_ar = COALESCE(description_ar, 'قراءة تفاعلية باستخدام الكتب المصوّرة'), instructions_ar = COALESCE(instructions_ar, '1. اختاري كتبًا ذات صور زاهية
2. أشيري إلى الصور واذكري أسماءها
3. دعي طفلكِ يقلّب الصفحات
4. قلّدي أصوات الحيوانات') WHERE id = '68d82e2b-fe11-4b41-af57-aa141f8eb6cc';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'لعبة فرز الأشكال'), description_ar = COALESCE(description_ar, 'فرز الأشكال ووضعها في الفتحات المطابقة'), instructions_ar = COALESCE(instructions_ar, '1. أري طفلكِ كيفية إدخال الأشكال في الفتحات المطابقة
2. وجّهي يد طفلكِ في البداية
3. احتفلي بنجاحه
4. اذكري أسماء الأشكال أثناء اللعب') WHERE id = '60e5d3d1-5587-48f5-99df-4e806c62490a';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'حفلة رقص'), description_ar = COALESCE(description_ar, 'الرقص معًا على أنغام الموسيقى'), instructions_ar = COALESCE(instructions_ar, '1. شغّلي موسيقى مرحة
2. ارقصي وأنتِ تحملين طفلكِ بين ذراعيكِ
3. ضعي طفلكِ على الأرض وارقصا معًا
4. صفّقا ودورا حول نفسيكما') WHERE id = '52245d35-3235-4e80-b73d-af4fe323ed93';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'عصر الإسفنج'), description_ar = COALESCE(description_ar, 'اعصري قطع الإسفنج المبللة في أوعية'), instructions_ar = COALESCE(instructions_ar, 'بلّلي قطع الإسفنج وأري طفلكِ كيف يعصر الماء في وعاء. هذا النشاط رائع لتقوية اليدين.') WHERE id = 'df24840d-33ce-4c49-b093-3e0206c89ed5';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'نفخ الريش'), description_ar = COALESCE(description_ar, 'انفخي الريش وشاهديه يطفو في الهواء'), instructions_ar = COALESCE(instructions_ar, 'ضعي الريش على سطح مستوٍ. انفخي برفق ودعي طفلكِ يحاول الإمساك به أو نفخه أيضًا.') WHERE id = 'efd51de1-efff-48a2-a2e9-f6a4a3d7a2ee';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'اللعب بالرمل'), description_ar = COALESCE(description_ar, 'الحفر والسكب باستخدام الرمل'), instructions_ar = COALESCE(instructions_ar, 'املئي صينية بالرمل. وقدّمي لطفلكِ أكوابًا وملاعق. دعيه يحفر ويسكب ويتحسس ملمس الرمل.') WHERE id = '53ef4599-988b-4a29-8f82-c3c78d48283b';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'تشكيل عجينة اللعب'), description_ar = COALESCE(description_ar, 'اضغطي عجينة اللعب ولفّيها وشكّليها'), instructions_ar = COALESCE(instructions_ar, 'أعطي طفلكِ عجينة اللعب. وأريه كيفية ضغطها ولفّها وثقبها. استخدمي قوالب البسكويت لصنع أشكال مختلفة.') WHERE id = '9a13c43a-a835-47cf-99fe-bd97a0f1562c';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'برج المكعبات'), description_ar = COALESCE(description_ar, 'رصّي المكعبات لأعلى ارتفاع ممكن'), instructions_ar = COALESCE(instructions_ar, 'أري طفلكِ كيف يرصّ المكعبات. عُدّي كل مكعب. احتفلا عندما يسقط البرج! ثم أعيدا بناءه معًا.') WHERE id = '5c63d4c6-a28a-488e-84cb-86ad690cd854';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'سحب الأوشحة'), description_ar = COALESCE(description_ar, 'اسحبي الأوشحة من وعاء'), instructions_ar = COALESCE(instructions_ar, 'ضعي الأوشحة في صندوق به فتحة. دعي طفلكِ يسحبها واحدًا تلو الآخر. واذكري اسم كل لون.') WHERE id = '00ca6e21-d67f-4f0a-a874-ef5c64e2e91a';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'سكب الماء'), description_ar = COALESCE(description_ar, 'سكب الماء من كوب إلى آخر'), instructions_ar = COALESCE(instructions_ar, 'أعطي طفلكِ كوبين وبعض الماء. وضّحي له كيفية سكب الماء من كوب إلى آخر. هذا نشاط رائع لتنمية التناسق الحركي.') WHERE id = '94152e25-5d19-43e0-9c7f-26f0205d234e';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'لعبة الغميضة بالدمية'), description_ar = COALESCE(description_ar, 'إخفاء دمية تحت الأكواب والعثور عليها'), instructions_ar = COALESCE(instructions_ar, 'ضعي 2-3 أكواب مقلوبة. أخفي دمية صغيرة تحت أحدها، ثم اطلبي من طفلكِ العثور عليها.') WHERE id = '18e16dc8-b896-4c03-8b0c-c7052e294b98';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'فرز الألوان'), description_ar = COALESCE(description_ar, 'فرز الأشياء حسب اللون في حاويات'), instructions_ar = COALESCE(instructions_ar, 'استخدمي أشياء بألوان مختلفة، مثل المكعبات أو الكرات أو الأغطية. ضعي حاويات واطلبي من طفلكِ فرز الأشياء حسب اللون.') WHERE id = 'a9054a6e-ef97-45fa-aea0-e0e0cc640bc3';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'لعبة أجزاء الجسم'), description_ar = COALESCE(description_ar, 'الإشارة إلى أجزاء الجسم وتسميتها'), instructions_ar = COALESCE(instructions_ar, 'المسي أنفكِ وأذنيكِ وعينيكِ وسمّيها. اطلبي من طفلكِ تقليدكِ. غنّي معه أغنية الرأس والكتفين والركبتين.') WHERE id = '07108cc6-ef41-4d92-ad52-d3d9ab5b5c1a';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'اتبع القائد'), description_ar = COALESCE(description_ar, 'تقليد الحركات معًا'), instructions_ar = COALESCE(instructions_ar, 'قومي بحركات بسيطة، مثل القفز والتصفيق والدوران والدوس بالقدمين. اطلبي من طفلكِ تقليدكِ، ثم دعيه يقود اللعبة.') WHERE id = '61ed8f13-2ee8-4bf5-b395-427c971b2b93';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'وقت الأحجية'), description_ar = COALESCE(description_ar, 'أحاجي بسيطة للأشكال'), instructions_ar = COALESCE(instructions_ar, 'أعطي طفلكِ أحجية بسيطة مكوّنة من 3-5 قطع. ساعديه على مطابقة الأشكال، واحتفلي معه بوضع كل قطعة في مكانها.') WHERE id = '407aee71-093f-47d5-be98-f518ebc93883';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'مساعد الغسيل'), description_ar = COALESCE(description_ar, 'فرز الجوارب حسب اللون'), instructions_ar = COALESCE(instructions_ar, 'اخلطي جوارب بألوان مختلفة معًا. اطلبي من طفلكِ العثور على الأزواج المتطابقة حسب اللون.') WHERE id = 'c6f840ec-4a7f-4cab-a710-22e0769b14e1';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'لعبة الظلال'), description_ar = COALESCE(description_ar, 'تشكيل دمى الظل على الحائط'), instructions_ar = COALESCE(instructions_ar, 'في غرفة مظلمة، استخدمي مصباحًا يدويًا لتشكيل ظلال بيديكِ على الحائط. شكّلي حيوانات وأشياء مختلفة.') WHERE id = '236f386f-6b5f-4108-a856-812efa52e5d0';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'غسل الألعاب'), description_ar = COALESCE(description_ar, 'غسل الألعاب بالماء والصابون'), instructions_ar = COALESCE(instructions_ar, 'املئي حوضًا بالماء الدافئ والصابون. أعطي طفلكِ إسفنجة وألعابًا ليغسلها. اذكري اسم كل لعبة أثناء غسلها.') WHERE id = '3bde9afc-8036-426d-ae82-c76b546162fc';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'لعبة العدّ'), description_ar = COALESCE(description_ar, 'عدّ الأشياء معًا'), instructions_ar = COALESCE(instructions_ar, 'اجمعي أشياء صغيرة مثل المكعبات. عدّيها مع طفلكِ واحدًا تلو الآخر. شكّلي مجموعات من ٢ و٣ و٤ أشياء.') WHERE id = '97af70f2-c634-4bfa-bd72-86e31f80ae2a';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'أصوات الحيوانات'), description_ar = COALESCE(description_ar, 'تقليد أصوات الحيوانات معًا'), instructions_ar = COALESCE(instructions_ar, 'أشيري إلى صور الحيوانات في كتاب. قلّدي صوت كل حيوان. شجّعي طفلكِ على تقليدكِ.') WHERE id = 'ff72da83-28a7-4824-919d-7d40add23a69';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'جبل الوسائد'), description_ar = COALESCE(description_ar, 'تسلّق عوائق مصنوعة من الوسائد'), instructions_ar = COALESCE(instructions_ar, 'رتّبي الوسائد كمسار مليء بالعوائق. شجّعي طفلكِ على التسلّق فوقها والمرور بينها.') WHERE id = '7a752652-ca03-444b-9521-72269d1948b7';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'اللعب بالملصقات'), description_ar = COALESCE(description_ar, 'انزعي الملصقات وألصقيها على الورق'), instructions_ar = COALESCE(instructions_ar, 'أعطي طفلكِ ملصقات وورقًا. يساعد نزع الملصقات على تنمية المهارات الحركية الدقيقة. اصنعا صورة معًا.') WHERE id = 'ab3c62c3-5d7c-4ac6-ad8b-ac7d714a3ea7';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'نزهة في الطبيعة'), description_ar = COALESCE(description_ar, 'اجمعا أوراق الأشجار والحجارة'), instructions_ar = COALESCE(instructions_ar, 'اخرجا في نزهة قصيرة. اجمعا أوراق الأشجار والحجارة والزهور. تحدثي مع طفلكِ عن الألوان والأشكال والملامس.') WHERE id = '62e05487-3056-4592-b1ea-0b4cac9e8f41';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'حلقة الطبول'), description_ar = COALESCE(description_ar, 'اصنعا إيقاعات باستخدام القدور والملاعق'), instructions_ar = COALESCE(instructions_ar, 'اقلبي القدور لتصبح مثل الطبول. استخدمي الملاعق الخشبية كعصي للطبول. اصنعا إيقاعات معًا.') WHERE id = '55dd9c21-79eb-44fa-92b7-7a1329f2835d';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'حاوية الأرز الحسية'), description_ar = COALESCE(description_ar, 'استكشاف الأرز باليدين والأدوات'), instructions_ar = COALESCE(instructions_ar, 'املئي حاوية بالأرز. أضيفي أكوابًا وملاعق وألعابًا صغيرة. دعي طفلكِ يغرف الأرز ويسكبه ويبحث عن الألعاب.') WHERE id = '1edc1365-0580-41a0-86fb-6e413cd251cc';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'الأرجوحة بالبطانية'), description_ar = COALESCE(description_ar, 'أرجِحا رضيعكِ برفق داخل بطانية'), instructions_ar = COALESCE(instructions_ar, 'يمسك شخصان بالغان زوايا البطانية بينما يكون رضيعكِ بداخلها. أرجِحاه برفق من جانب إلى آخر مع الغناء.') WHERE id = '8055a758-49ff-45d1-880c-15da141896b2';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'الآلات الموسيقية'), description_ar = COALESCE(description_ar, 'صنع الموسيقى باستخدام آلات بسيطة'), instructions_ar = COALESCE(instructions_ar, '1. أعطي رضيعكِ آلات آمنة مثل الخشخيشات\n2. شغّلي الموسيقى وحرّكي الخشخيشات مع الإيقاع\n3. غنّيا الأغاني معًا\n4. دعي رضيعكِ يستكشف الأصوات') WHERE id = '23d036b7-20b9-4a05-a223-49a6d472d380';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'الزجاجة الحسية'), description_ar = COALESCE(description_ar, 'تجذب الزجاجة المملوءة بسائل ملوّن انتباه طفلكِ'), instructions_ar = COALESCE(instructions_ar, 'أضيفي ماءً ملوّنًا أو مواد لامعة إلى زجاجة بلاستيكية. أغلقي الغطاء بإحكام. أريها لطفلكِ ودعيه يدحرجها.') WHERE id = '75be8860-ac3f-4a9e-87c7-5122de70d0a6';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'إمساك اليد والقبض'), description_ar = COALESCE(description_ar, 'دعي طفلكِ يتدرّب على الإمساك بأصابعكِ'), instructions_ar = COALESCE(instructions_ar, 'قدّمي أصابعكِ لطفلكِ ليمسك بها. اسحبيها برفق لتشجيعه على تقوية قبضته.') WHERE id = 'f5161cf6-25f1-4eda-b672-91e0dc7075f4';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'استكشاف ملمس الأقمشة'), description_ar = COALESCE(description_ar, 'دعي طفلكِ يلمس أقمشة مختلفة'), instructions_ar = COALESCE(instructions_ar, 'اجمعي أقمشة ناعمة وخشنة وملساء وزغبية. دعي طفلكِ يلمس كلًّا منها ويتحسّسه بينما تذكرين اسم ملمسه.') WHERE id = 'd62cf27d-4570-4976-85c1-ea88d0004a93';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'هزّ الخشخيشة'), description_ar = COALESCE(description_ar, 'يهزّ طفلكِ الخشخيشة لإصدار أصوات'), instructions_ar = COALESCE(instructions_ar, 'أعطي طفلكِ خشخيشة ووضّحي له كيفية هزّها. أظهري فرحتكِ عندما يقلّدكِ. جرّبي إيقاعات مختلفة.') WHERE id = 'b0958c0b-1439-4e5e-8443-a1ae673d0845';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'الرسم بمكعبات الثلج'), description_ar = COALESCE(description_ar, 'الرسم على الورق باستخدام مكعبات ثلج ملوّنة'), instructions_ar = COALESCE(instructions_ar, 'جمّدي ماءً ممزوجًا بملوّن الطعام. دعي طفلكِ يمرّر الثلج على الورق لتكوين أشكال ملوّنة.') WHERE id = '2fb728ab-9f62-4c72-8288-051a6eb7e14e';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'الفرز باستخدام علبة البيض'), description_ar = COALESCE(description_ar, 'فرز أشياء صغيرة في تجاويف علبة البيض'), instructions_ar = COALESCE(instructions_ar, 'ضعي أشياء صغيرة وآمنة بالقرب من طفلكِ. أريه كيفية وضع شيء واحد في كل تجويف من علبة البيض. عدّي الأشياء أثناء ذلك.') WHERE id = '4b4383db-2e14-4720-b060-17d8ff1704ee';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'منزل من الورق المقوى'), description_ar = COALESCE(description_ar, 'اصنعي منزلًا للعب باستخدام صندوق كبير'), instructions_ar = COALESCE(instructions_ar, 'اقطعي نوافذ وبابًا في صندوق كبير. زيّناه معًا. دعي طفلكِ يلعب بداخله.') WHERE id = '25a4322e-633e-4a3e-9979-250fedcd62b2';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'الزحف عبر النفق'), description_ar = COALESCE(description_ar, 'الزحف عبر نفق مصنوع من البطانيات'), instructions_ar = COALESCE(instructions_ar, 'مدّي البطانيات فوق الكراسي لصنع نفق. شجّعي طفلكِ على الزحف عبره. ضعي الألعاب عند نهايته.') WHERE id = 'ae4fecd1-f9d4-4188-aac6-c77af614920c';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'عقد من المعكرونة'), description_ar = COALESCE(description_ar, 'نظْم قطع المعكرونة في خيط'), instructions_ar = COALESCE(instructions_ar, 'استخدمي قطع معكرونة أنبوبية كبيرة. أري طفلكِ كيفية إدخالها في خيط أو رباط حذاء. هذا نشاط رائع لتنمية المهارات الحركية الدقيقة.') WHERE id = '64c0f7f0-7997-4646-84a7-28213e200807';
UPDATE public.play_activities SET title_ar = COALESCE(title_ar, 'الرسم بالأصابع'), description_ar = COALESCE(description_ar, 'الرسم بالأصابع على الورق'), instructions_ar = COALESCE(instructions_ar, 'ضعي ألوانًا آمنة على الورق. دعي طفلكِ يستخدم أصابعه ويديه لابتكار لوحة فنية. تحدّثي معه عن الألوان.') WHERE id = '48b54a1e-5f01-444e-ac3a-7700916922cc';

