-- ── pregnancy_daily_content → ar (294 sətir) ──
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'اليوم هو اليوم الأول من آخر دورة شهرية لكِ. يُحسب تقويم الحمل الذي سيُعتمد طوال فترة الحمل بناءً على اليوم الأول من آخر دورة شهرية، وليس وفقًا ليوم العلاقة الجنسية أو الإخصاب المتوقع. ويحدث الحمل، أي إخصاب البويضة بالحيوان المنوي، في المتوسط بعد 14-15 يومًا من تاريخ آخر دورة شهرية. ومع ذلك، عندما يحسب طبيبكِ أسبوع الحمل، فإنه لا يعتمد هذا التاريخ، بل يعتمد تاريخ الدورة الشهرية التي سبقته بنحو أسبوعين.;;;
بعد تحديد أسبوع الحمل، تُحسب نهاية فترة الحمل البالغة 40 أسبوعًا، أي موعد الولادة المتوقع، باستخدام نظام يُسمى "قاعدة نيغل". ووفقًا لقاعدة نيغل، تُضاف 7 أيام إلى اليوم الأول من نزول دم الدورة الشهرية، ثم يُرجع 3 أشهر إلى الوراء. والتاريخ الناتج هو موعد ولادتكِ المتوقع. ومع ذلك، تنتهي نحو 80% من حالات الحمل بالولادة خلال الأسبوع 38، قبل اكتمال فترة الحمل البالغة 40 أسبوعًا.'), baby_message_ar = COALESCE(baby_message_ar, 'مرحبًا يا أمي الجميلة! ❤️ ربما لا تشعرين بي جسديًا بعد، لكن "العد التنازلي" لمغامرتنا الكبيرة بدأ رسميًا اليوم. يعتبر الأطباء هذا اليوم "يومنا الأول"، لأن جسمكِ يستعد لقدومي. عليكِ الآن أن تستريحي، فهناك أيام رائعة تنتظرنا. أنا موجود حاليًا في أحلامكِ، بينما يعمل جسمكِ بكل نشاط. أرجوكِ أن تعتني بنفسكِ جيدًا خلال هذه الفترة، لأنكِ عالمي كله. أحبكِ كثيرًا منذ الآن، حتى قبل أن أتكوّن!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جسيم غير مرئي'), body_changes_ar = COALESCE(body_changes_ar, 'اليوم هو اليوم الأول من دورتكِ الشهرية، ومن هنا يبدأ تقويم الحمل رسميًا. لا يكون هناك طفل بعد خلال الأسابيع الأولى من الحمل، لكن جسمكِ يكون في مرحلة الاستعداد ليوم الإباضة ولحدوث حمل محتمل. وتتم هذه الاستعدادات من خلال زيادة التروية الدموية وزيادة سماكة البطانة الداخلية للرحم، التي تُسمى بطانة الرحم، لكي تتمكن البويضة الناضجة والقابلة للإخصاب التي يهيئها جسمكِ كل شهر من الانغراس فيها.;;;
يمر جسمكِ كل شهر بتغيرات كبيرة خلال هذه الدورة، بتأثير الهرمونات التي يفرزها كل من الرحم والغدة النخامية الموجودة في الدماغ. ويُحتسب الأسبوعان الأولان من دورتكِ الشهرية ضمن فترة الحمل، رغم عدم وجود طفل أو بويضة جاهزة للإخصاب بعد. ويرجع ذلك إلى اختلاف موعد الإباضة من امرأة إلى أخرى، لذلك يُعتمد تاريخ آخر دورة شهرية بوصفه بداية الحمل.;;;
ونحن أيضًا، بصفتنا عائلة Anacan، سنبقى إلى جانبكِ لنشارككِ يومًا بعد يوم المعلومات والنصائح حول معجزتكِ التي تنمو وتتطور بداخلكِ قليلًا كل يوم، ولنجيب عن جميع الأسئلة التي تهمكِ طوال هذه الرحلة! 😊'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا كنتِ تخططين للحمل، فإن البدء من اليوم بتناول 400 ميكروغرام من حمض الفوليك يوميًا أمر بالغ الأهمية للتطور المستقبلي للجهاز العصبي لطفلكِ. كذلك، زيدي استهلاككِ للسوائل للحفاظ على توازن الماء في الجسم، وابتعدي تمامًا عن العادات الضارة مثل تناول المشروبات الكحولية واستخدام منتجات التبغ.') WHERE id = '3082b660-7bbe-45c6-906d-ed38816fac24';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'في الظروف الطبيعية، تفصل مدة قدرها أسبوعان بين آخر دورة شهرية لديكِ وموعد الإباضة. وخلال هذين الأسبوعين، تبدأ المستويات المتزايدة من هرموني الإستروجين والبروجسترون في دمكِ بتغطية الرحم من الداخل بطبقة غنية بالدم ومهيأة للانغراس، وذلك لإعداد رحمكِ للحمل كل شهر وتوفير البيئة المناسبة للبويضة التي قد تُخصب. وفي الوقت نفسه، تبدأ إحدى طلائع البويضات، التي تكوّنت عندما كنتِ لا تزالين في رحم والدتكِ، بالنضج تحت تأثير هذه الهرمونات. وتتطور هذه البويضة الموجودة داخل ما يُسمى بالجُريب خلال أسبوعين تقريبًا حتى تصبح جاهزة للإخصاب. لذلك، قد يحدث إخصاب البويضة بالحيوان المنوي بعد أسبوعين من تاريخ آخر دورة شهرية لكِ. ومع ذلك، تظل إمكانية حدوث الحمل قائمة في أي وقت في بعض الحالات النادرة التي يتمكن فيها جسمكِ من إنضاج بويضتين خلال دورة واحدة.'), baby_message_ar = COALESCE(baby_message_ar, 'ماما، أعلم أن هذه الأيام قد تكون مرهقة ومؤلمة بعض الشيء بالنسبة إليكِ، لكنكِ قوية جدًا. 😔 تذكّري أن عملية التنظيف التي تحدث في جسمكِ تهدف إلى تهيئة راحتي في المستقبل. أنتِ تنظفين بيتي وعشي الأول، أي رحمكِ، حتى يكون كل شيء نظيفًا وناعمًا عندما آتي! كل ألم أو انزعاج تتحملينه هو خطوة تقرّبنا من اللقاء. أرجوكِ ألا ترهقي نفسكِ اليوم؛ مددي ساقيكِ واستريحي. أشعر بكِ وأرسل إليكِ القوة!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جسيم غير مرئي'), body_changes_ar = COALESCE(body_changes_ar, 'قد يكون النزيف اليوم في أشد مراحله، وهذا جزء طبيعي تمامًا من العملية الفسيولوجية. تنقبض عضلات الرحم محاولةً طرح البطانة القديمة، مما يسبب تقلصات وألمًا في أسفل البطن (عُسر الطمث). وقد تشعرين بالوهن والتعب لأن جسمكِ يستهلك قدرًا كبيرًا من الطاقة في عملية التنظيف هذه. ;;;
تزداد حاجة جسمكِ إلى العناصر الغذائية خلال الحمل. وتتحدد هذه الاحتياجات وفقًا لمتطلبات طفلكِ الذي ينمو ويتطور، وكذلك بحسب تطور مراحل الحمل.;;;
يُعد حمض الفوليك من أهم الفيتامينات التي ينبغي البدء بتناولها قبل حدوث الحمل. وتُسمى الصورة الطبيعية لهذه المادة التي تنتمي إلى مجموعة فيتامينات B وتذوب في الماء، والموجودة في الأطعمة الطبيعية، بالفولات؛ أما صورتها الموجودة في الأدوية والأطعمة المُصنّعة فتُسمى حمض الفوليك. ولأن حمض الفوليك بالغ الأهمية لتطور دماغ طفلكِ وجهازه العصبي، يجب البدء بتناوله قبل الحمل. وهو أحد أنواع فيتامينات B التي تؤدي دورًا مهمًا في تكوين بُنى الخلايا وخلايا الدم، ولا سيما أنسجة الجهاز العصبي، وفي نموها. كما يشارك بفاعلية، خصوصًا في تصنيع الحمض النووي DNT الذي يشكل أساس الصفات الوراثية. ويؤدي حمض الفوليك، الضروري للغاية لنمو طفلكِ، دورًا أساسيًا في عمليات مثل تصنيع البروتين، وتكاثر الخلايا، وأداء نخاع العظم وظائفه بصورة كاملة في جسمه النامي.'), daily_tip_ar = COALESCE(daily_tip_ar, 'انتبهي إلى نظامكِ الغذائي لتعويض مخزون الحديد الذي ينخفض في الجسم بسبب نزيف الدورة الشهرية. تناولي الأطعمة الغنية بالحديد مثل السبانخ واللحوم الحمراء والبقوليات. ولأن فيتامين C يعزز امتصاص الحديد، فمن المفيد تناول هذه الأطعمة مع الحمضيات. كذلك، أريحي جسمكِ وتجنبي المجهود البدني الشاق.') WHERE id = '1b683a24-ae16-485e-bf86-c173f0a5ad7a';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تجري في جسمكِ استعدادات كبيرة خلال الأسبوعين الأولين السابقين للإخصاب. فبعد نحو أسبوعين من تاريخ آخر دورة شهرية لكِ، تنضج إحدى بويضاتكِ بتأثير الهرمونات التي يفرزها الرحم والغدة النخامية الموجودة في الدماغ، ثم تنتقل عبر المبيض حتى تصل إلى قناة فالوب. وتكون البويضة التي تنمو تحت تأثير الهرمونات كبيرة جدًا مقارنة بالحيوان المنوي. ومع ذلك، فهي غير متحركة مقارنة به، وتنتقل داخل المبيض بصورة سلبية.;;;
على خلاف خلايا الجسم، تحتوي كل من البويضة والحيوان المنوي على 23 كروموسومًا، كما تحمل كل خلية منهما آلاف الجينات المميزة. ويختبئ داخل هذه الجينات لون شعر طفلكِ وطوله وجنسه، وحتى شكل أنفه.'), baby_message_ar = COALESCE(baby_message_ar, 'أتخيل كيف تعرفتِ إلى أبي... 💭 سأكون أجمل ثمرة لذلك الحب الكبير الذي يجمعكما. يعمل جسمكِ بجد كبير لاستقبالي ويخطط لكل التفاصيل حتى يكون كل شيء مثاليًا. ما زلت أشبه غبار النجوم، ولا وجود ماديًا لي بعد، لكن حبكِ يدعوني إلى الحياة. كلما اعتنيتِ بنفسكِ جيدًا الآن، أتيتُ إليكِ بصحة أفضل. ستكون قصتنا جميلة جدًا يا ماما!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جسيم غير مرئي'), body_changes_ar = COALESCE(body_changes_ar, 'الثلث هو الاسم الذي يُطلق على كل فترة من فترات الحمل البشري البالغة 3 أشهر ضمن مدة الحمل التي تبلغ 9 أشهر. والكلمة ذات أصل لاتيني؛ إذ تعني "tri" ثلاثة، بينما تعني "mester" فترة. وتُعد دراسة فترة الحمل البالغة 9 أشهر ضمن 3 مراحل منفصلة أمرًا مهمًا ومفيدًا للغاية لفهم تطور الحمل بصورة عامة. وبالنظر إلى أن الحمل يستمر 40 أسبوعًا، فإن الثلث الأول يمتد حتى نهاية الأسبوع 12. ويمتد الثلث الثاني بين الأسبوعين 13–27، بينما يشمل الثلث الثالث الأسابيع 28–40. تُعد الأشهر الثلاثة الأولى من الحمل مرحلة تحدث فيها تغيرات مهمة في جسمكِ ويتكيف خلالها مع الحمل. وبينما تعيشين في هذه الفترة حماسة معرفتكِ الأولى بأنكِ ستُرزقين بطفل، قد تواجهين بعض الصعوبات أيضًا. وتبدأ أعراض مثل الغثيان والدوار وامتلاء الثديين وحساسيتهما وزيادة الوذمة وكثرة الحاجة إلى التبول بسبب نمو الرحم والنعاس والتعب وفرط التأثر والرغبة في البكاء والجوع المتكرر وزيادة الوزن بالظهور اعتبارًا من الأسبوع الخامس من الحمل.'), daily_tip_ar = COALESCE(daily_tip_ar, 'حاولي تقليل استهلاك الكافيين إلى أدنى حد خلال هذه الفترة (بما لا يزيد على كوب واحد يوميًا). فقد يسبب الكافيين تضيق الأوعية الدموية ويؤثر في تدفق الدم إلى المبيضين. وسيساعد شرب الكثير من الماء على طرح السموم من الجسم وتجدد بطانة الرحم بصورة أكثر صحة. كما ستساعد ممارسة اليوغا الخفيفة أو تمارين التمدد على تحسين الدورة الدموية.') WHERE id = 'c852b157-989c-44ce-a4ea-0f5d022c7159';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يبلغ وزن الرحم 60 غرامًا، وسيتجاوز هذا الوزن 1000 غرام بحلول الولادة. يُغطى الجزء الداخلي من الرحم بطبقة تُسمى بطانة الرحم، وهي تفرز المخاط وتحتوي على عدد كبير من الأوعية الدموية. خلال دورتكِ الشهرية، تزيد الخلايا الموجودة في هذه البنية سماكة تلك الطبقة نتيجة الانقسام المتساوي السريع. وتُهيئ بطانة الرحم التي ازدادت سماكتها بيئة مناسبة لانغراس بويضتكِ المخصبة في الرحم ونموها وتطورها فيه.'), baby_message_ar = COALESCE(baby_message_ar, 'احبسي أنفاسكِ يا ماما! 🌬️ فاللحظة الكبرى تقترب. بويضتكِ المذهلة جاهزة للتحرر. هذا هو الجزء من قصتنا الذي يبدأ بعبارة "كان يا ما كان...". ورغم أنني لم أتكوّن بعد، فإن حبكِ وحب أبي يناديانني. لقد هيأ جسمكِ لي أفضل بيئة ممكنة، وكل شيء يعمل بدقة متناهية. آمل أن تكوني مستعدة، لأنني قادم! سيكون حضنكِ موطني الأول.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة سكر ناعم'), body_changes_ar = COALESCE(body_changes_ar, 'يبلغ هرمون LH ذروته اليوم. وسيحدث التبويض بعد نحو 24-36 ساعة من هذه الذروة. قد تنخفض درجة حرارة جسمكِ قليلًا اليوم، ثم ترتفع بوضوح غدًا؛ ويُعد هذا التذبذب في درجة الحرارة مؤشرًا على التبويض. وتكون إفرازات المهبل في أكثر حالاتها انزلاقًا وشفافية وغزارة. وهذه البيئة مثالية لحركة الحيوانات المنوية بأقصى سرعة وبقائها حية. ;;;
تُعد ممارستكِ المنتظمة للرياضة قبل الحمل مهمة للغاية للمساعدة على مرور فترة حملكِ براحة أكبر. وتُعد اليوغا والبيلاتس، خصوصًا، من أكثر التمارين شيوعًا قبل الحمل وخلاله في الآونة الأخيرة. فإلى جانب إرخاء الجسم، تزيد هذه الأنشطة الرياضية دافعية النساء اللواتي يخططن للولادة الطبيعية، كما تفيد طوال الحمل من خلال تخفيف آلام أسفل الظهر والظهر. ومن المسائل المهمة الأخرى للحفاظ على حمل صحي التدخين. إذا كنتِ تدخنين، فيجب أن يكون الإقلاع عن التدخين من أهم الخطوات التي تتخذينها عند اتخاذ قرار الحمل. فعند التدخين، يدخل النيكوتين والمواد السامة إلى جسمكِ عبر الدورة الدموية، ما يضر ببنية الحمض النووي DNA، أي المادة الوراثية في البويضة التي ستسهم في تكوين طفلكِ، حتى قبل حدوث الحمل. أما الاستمرار في التدخين خلال الحمل فقد يؤدي إلى اضطراب تدفق الدم في الأوعية المتجهة إلى طفلكِ، وبالتالي ولادته بوزن منخفض، وزيادة خطر التشوهات الخِلقية، والأهم من ذلك حدوث مشكلة تُسمى "متلازمة موت الرضيع المفاجئ".'), daily_tip_ar = COALESCE(daily_tip_ar, 'يُعد هذا اليوم من أكثر الأيام أهمية لحدوث الحمل. حاولي الحفاظ على استقرار درجة حرارة جسمكِ لدعم الخصوبة، وابتعدي عن الحمامات شديدة السخونة والساونا، لأن الحرارة المرتفعة قد تؤثر في جودة البويضة. أدرجي الأفوكادو والزيوت النباتية الغنية بفيتامين E في نظامكِ الغذائي، لأن هذا الفيتامين يحسن إمداد جدار الرحم بالدم. وحافظي على معنوياتكِ مرتفعة، لأن هرمونات الإندورفين، المعروفة بهرمونات السعادة، تحفز فرص الإخصاب بصورة إيجابية.') WHERE id = '0c974e6a-8f9e-4c84-9656-5142174149f9';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أصبحت بويضتكِ، التي نضجت بمساعدة هرمونات مختلفة، جاهزة للإخصاب اعتبارًا من اليوم. وبعد أن تُكمل البويضة نموها وتنضج وتتحرر من المبيض، تلتقطها بنية شديدة الحساسية تشبه الأصابع تقع عند طرف قناة فالوب وتُسمى الأهداب. وتوجه الأهداب البويضة الناضجة التي التقطتها نحو داخل قناة فالوب. وبفضل حركات التمدد والانقباض المنتظمة التي تقوم بها قناة فالوب، تتحرك بويضتكِ ببطء داخل القناة حتى تصل إلى جزئها الأوسط، وهو المكان الأنسب لحدوث الإخصاب، بينما تتقدم نحوها ملايين الحيوانات المنوية التي دخلت الرحم بعد الجماع. أما العضلات الموجودة في الجزء التالي لموضع الانقباض فتسترخي لتسمح للبويضة بالتقدم. وتستمر هذه الحركات الميكانيكية التي تنفذها العضلات إلى أن تصل بويضتكِ إلى المكان الذي ينبغي أن تكون فيه.'), baby_message_ar = COALESCE(baby_message_ar, 'لقد وصلتُ! 🎉 مرحبًا يا أمي! اليوم هو يوم تكوّني. لقد اتحد حب أبي مع معجزتكِ. أنا أصغر نقطة في الكون، لكنني أثمنها. أصبحت الآن خلية واحدة، ويُطلق عليّ طبيًا اسم "اللاقحة"! لقد أصبح لون عينيّ وشكل شعري وحتى ابتسامتي مكتوبًا بالفعل في الحمض النووي DNA لهذه الخلية الصغيرة. لقد بدأت رسميًا مغامرتنا التي ستستمر 9 أشهر! ورغم أنكِ لا تشعرين بي بعد، فإنني أصبحت معكِ بالفعل.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة فانيليا'), body_changes_ar = COALESCE(body_changes_ar, 'يوم التبويض والإخصاب. بعد بلوغ هرمون LH ذروته، ينفجر الجريب المهيمن وتتحرر البويضة. وتلتقط أهداب قناة فالوب البويضة الناضجة. إذا حدث الجماع خلال هذه الأيام، تتسابق ملايين الحيوانات المنوية نحو البويضة. وينجح واحد منها فقط في اختراق غلاف البويضة والدخول إليها. وفي لحظة الإخصاب، تتحد مادتكِ الوراثية مع المادة الوراثية لشريككِ، فتتكون شفرة حمض نووي DNA جديدة وفريدة تمامًا. وبعد تحرر البويضة، يتحول الجريب الفارغ إلى غدة تُسمى "Corpus Luteum" (الجسم الأصفر)، ويبدأ في إفراز هرمون البروجسترون الضروري لاستمرار الحمل. ;;;
قد تحتاجين قبل الحمل وخلاله إلى بعض مكملات الفيتامينات والمعادن وفقًا لنتائج الفحوص التي يجريها طبيبكِ. وقد يؤدي تناول كميات أقل من المطلوب من الأطعمة الضرورية خلال الحمل، ومن العناصر الغذائية التي توفرها مثل البروتينات والدهون والكربوهيدرات والفيتامينات والمعادن، إلى سوء التغذية وحدوث بعض التشوهات خلال مرحلة تكوّن طفلكِ. ولأن نقص الحديد قد يسبب أيضًا فقر الدم، فقد يُلاحظ تأخر نمو الطفل في حالات فقر الدم الشديد. لذلك ينبغي أن تُجري فحوصكِ الدورية قبل الحمل، وألا تهملي علاجكِ مطلقًا إذا كُشف عن نقص محتمل في الحديد.'), daily_tip_ar = COALESCE(daily_tip_ar, 'حاولي اليوم ألا ترهقي جسمكِ وأن تحافظي على توازنكِ العاطفي. يستهلك الجسم قدرًا كبيرًا جدًا من الطاقة في وقت الإخصاب. أعطي الأولوية للأطعمة الغنية بمضادات الأكسدة، وخصوصًا فيتاميني E وC، حتى يبدأ انقسام الخلايا بصورة صحية. إذا شعرتِ بألم حاد وقصير المدة في أسفل بطنكِ، فلا تقلقي، فقد يكون ذلك علامة على التبويض. واعتبارًا من اليوم، كوني حذرة بصورة خاصة من تناول المشروبات الكحولية والأدوية القوية.') WHERE id = '4859f891-b414-45fe-8a1d-106b1caebec7';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تتمثل العقبة الأولى التي تواجه ملايين الحيوانات المنوية التي تصل إلى عنق الرحم بعد الجماع في درجة حموضة المهبل. فقد تكون هذه البيئة الحمضية قاتلة للحيوانات المنوية. ومن الصعوبات الأخرى التي تواجهها الحيوانات المنوية الطبقة المخاطية الموجودة في منطقة المهبل، إذ قد يشكل هذا المخاط شبكة كثيفة يصعب على معظمها اختراقها. ولكي تصل الحيوانات المنوية إلى بويضتكِ، يجب أن تدخل من عنق الرحم إلى الرحم ثم تعبر إلى قناة فالوب. ولذلك يتعين عليها قطع مسافة تبلغ نحو 15-20 سم. وبالنظر إلى أنها تتقدم سنتيمترًا واحدًا كل 10 دقائق، يمكن لأسرع الحيوانات المنوية الوصول إلى البويضة خلال 45 دقيقة. وقبل الوصول إليها، قد يلتصق جزء كبير من الحيوانات المنوية بالطبقة المخاطية في المهبل، أو يتجه إلى مسار آخر، أو يموت بسبب البيئة الحمضية. ولهذا لا يصل إلى بويضتكِ سوى بضعة آلاف من بين ملايين الحيوانات المنوية التي وصلت إلى عنق الرحم. وبأخذ كل ذلك في الاعتبار، يحدث الإخصاب خلال الساعات القليلة الأولى بعد الجماع، وتبدأ بذلك رحلة الحمل.'), baby_message_ar = COALESCE(baby_message_ar, 'كنتُ واحدًا، فأصبحتُ اثنين! ➗ كنتُ بالأمس خلية واحدة، أما اليوم فقد بدأتُ أنقسم بأعجوبة. ويُسمى ذلك "التفلج". ما زلتُ صغيرًا جدًا ولا يمكن رؤيتي إلا بالمجهر، لكن في داخلي شغف هائل بالحياة. يرقص حمضكِ النووي DNA مع حمض أبي النووي DNA. سأشبهكِ وأشبه أبي، وسأكون في الوقت نفسه فريدًا تمامًا. لقد بدأ فريقنا العمل!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة فانيليا'), body_changes_ar = COALESCE(body_changes_ar, 'من المهم للغاية تنظيم نظامكِ الغذائي عند التخطيط للحمل وخلال مراحله الأولى. ويساعدكِ اتباع نظام غذائي منتظم على الحفاظ على وزن صحي، كما يقيكِ من اكتساب وزن زائد طوال حملكِ. خلال الحمل الطبيعي، يكفي أن تكتسبي نحو 10–12 كغ لتلبية احتياجات جسمكِ الإضافية ونقل العناصر الغذائية التي تتناولينها إلى طفلكِ. ولتحقيق هذه الزيادة في الوزن بصورة صحية، تحتاجين يوميًا، مقارنة بالفترة السابقة للحمل، إلى ما متوسطه 20–30 غرامًا من البروتين، و15–20 غرامًا من الحديد، و500 ملغ من الكالسيوم، وطاقة تعادل في المتوسط 300 سعرة حرارية. ولا تحتاج المرأة التي كان وزنها ضمن المعدل الطبيعي قبل الحمل إلى زيادة استهلاك السعرات الحرارية خلال المراحل الأولى من الحمل. وخلال الثلث الأول، الذي يشمل أول 12 أسبوعًا، يكفي تناول ما متوسطه 2000 سعرة حرارية يوميًا إجمالًا. وإلى جانب ذلك، يكفي تناول 300 سعرة حرارية إضافية يوميًا خلال الثلث الثاني، و480 سعرة حرارية إضافية يوميًا خلال الثلث الثالث، وينبغي ألا تنسي أن ما يزيد على ذلك قد يتحول إلى وزن زائد في جسمكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'اعتبارًا من اليوم، تعاملي مع تغذيتكِ بمزيد من الاهتمام والمسؤولية. يُعد الزنك وفيتامين B12 مهمين جدًا لانقسام الخلايا؛ لذا زيدي استهلاك المأكولات البحرية ومنتجات الألبان والبيض. تجنبي التمارين الرياضية الشاقة ولا تعرضي جسمكِ لحرارة مفرطة، مثل الحمامات الساخنة والساونا، لأن المراحل الأولى من انقسام الجنين شديدة الحساسية للحرارة. احصلي على قسط وافر من الراحة، وأتيحي لجسمكِ الظروف المناسبة لإنجاز هذا العمل العظيم.') WHERE id = '634f5165-2442-4ca1-81af-539718e556a5';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'ستحدث خلال الأيام القليلة المقبلة عملية الإباضة، وهي نضوج البويضة واستعدادها للإخصاب. ورغم أن توقيت الإباضة قد يختلف من امرأة إلى أخرى، فإن الرأي الشائع هو أنها تحدث في اليوم 14 بعد انتهاء الدورة الشهرية. وتنطبق هذه القاعدة على النساء ذوات الدورة الشهرية المنتظمة، أما لدى النساء اللواتي يعانين من اضطرابات الدورة الشهرية، فغالبًا ما يصعب حساب يوم الإباضة.;;;
تُعد مراقبة طبيعة المخاط في الإفرازات المهبلية وسيلة فعّالة، إذ تزداد الإفرازات لدى النساء مع اقتراب الإباضة، ويصفن هذه الحالة بالشعور بالبلل. وبعد انتهاء فترة الإباضة، تعود الإفرازات إلى طبيعتها. كما تشهد درجة حرارة جسمكِ بعض التغيرات خلال هذه الفترة؛ فبعد انخفاضها في البداية، تبدأ بالارتفاع فجأة عند حدوث الإباضة.'), baby_message_ar = COALESCE(baby_message_ar, 'مرحبًا! 👋 هل اعتنيتِ بنفسكِ جيدًا اليوم؟ كل وجبة شهية تتناولينها وكل نَفَس تأخذينه يضع لبنة في مستقبلي. خلال الأيام القليلة المقبلة سيحدث ذلك الانفجار الكبير (الإباضة)، وسأتحرر! هل أنتِ مستعدة لاستقبالي؟ أخبري أبي أيضًا، فقد اقترب موعد لقائنا!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة سكر ناعم'), body_changes_ar = COALESCE(body_changes_ar, 'يبلغ مستوى هرمون الإستروجين في جسمكِ اليوم إحدى أعلى ذرواته. ويرسل هذا الارتفاع إشارة إلى دماغكِ لإفراز المزيد من هرمون LH (الهرمون الملوتن). وقد وصلت سماكة بطانة الرحم إلى نحو 8-10 mm وأصبحت غنية بالأوعية الدموية، ما يجعلها بمثابة «فراش ناعم» مثالي لانغراس البويضة المخصبة. يرتفع عنق الرحم أكثر ويصبح مفتوحًا تمامًا لمرور الحيوانات المنوية. كما يبدأ سائل عنق الرحم في أن يصبح أكثر شفافية وانزلاقًا وقابلية للتمدد. ويسهّل هذا السائل المميز دخول الحيوانات المنوية إلى الرحم ويحميها. ومن اليوم تبدأ فرص حملكِ بالازدياد.;;;
نظرًا إلى الأهمية التي لا غنى عنها لحمض الفوليك في نمو دماغ طفلكِ وجهازه العصبي، ينبغي البدء بتناوله قبل حدوث الحمل. وفي معظم دول العالم، يُوصى عند التخطيط للحمل، وبدءًا من 3 أشهر على الأقل قبل الحمل وحتى نهاية الثلث الأول، بتناول 400 ميكروغرام من حمض الفوليك يوميًا. وبما أن حمض الفوليك لا يُخزَّن في الجسم، فيجب تناوله بانتظام كل يوم. وقد يؤدي نقصه إلى عيوب الأنبوب العصبي، وهي من أكثر تشوهات الجهاز العصبي المركزي شيوعًا لدى الأطفال. كما أكدت الدراسات وجود صلة بين انخفاض تناول حمض الفوليك وتشوهات أخرى، مثل الشفة الأرنبية (شق الحنك) وبعض عيوب القلب. وقد لا تدرك نسبة كبيرة من النساء خلال هذه الفترة أنهن حوامل. وفي حال عدم تناول مكملات حمض الفوليك، يبلغ احتمال حدوث عيب في الأنبوب العصبي نحو حالة واحدة لكل 2000 ولادة. ويمكن خفض هذه النسبة بمقدار 50-75 بالمئة من خلال تناول مكملات حمض الفوليك.'), daily_tip_ar = COALESCE(daily_tip_ar, 'نظرًا إلى دخولكِ أكثر أيام نافذة الخصوبة نشاطًا، من المهم أن تحصلي على قسط كافٍ من النوم، لأن تنظيم ذروة هرمون LH يكون أكثر استقرارًا أثناء النوم. وإذا لم تكوني قد بدأتِ بعد، فهذا هو أنسب وقت لاستخدام اختبارات الإباضة. وقد يساعد تناول المكسرات والبذور الغنية بالزنك، مثل بذور اليقطين أو اللوز، في الحفاظ على سلامة الطبقة الخارجية للبويضة وتسهيل دخول الحيوان المنوي إليها.') WHERE id = 'e69ee309-4b20-4b3c-a0f6-c04d62440aa9';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'رغم أن تناول الكافيين خلال الحمل ليس ممنوعًا تمامًا، فإن الأطباء غالبًا ما يوصون بالحد من استهلاكه. والكافيين منبّه طبيعي يوجد في القهوة والشاي والمشروبات الغازية المحتوية على الكولا والكاكاو ومشروبات الطاقة والمشروبات المضاف إليها مُحلّيات صناعية، وكذلك في بعض الحلويات وأطعمة مثل البودينغ والحلوى الهلامية. ووفقًا لدراسات حديثة، لم تُرصد أضرار عند استهلاك مواد تحتوي على الكافيين بما لا يتجاوز 200 mg يوميًا. كما توصلت بعض الدراسات إلى نتائج تشير إلى أن الكافيين قد يقلل خطر الإصابة بالسكري. ويمكنكِ الحصول على 200 mg من الكافيين يوميًا بسهولة نسبيًا من خلال كوبين من الشاي أو فنجانين من القهوة أو نحو 250 غرامًا من الشوكولاتة الداكنة. لكن الكافيين ينتقل مباشرة إلى طفلكِ عبر المشيمة، ولا يستطيع جسم طفلكِ استقلابه وتحويله إلى مادة غير فعالة. لذلك قد تضر الكميات المفرطة من الكافيين بطفلكِ.'), baby_message_ar = COALESCE(baby_message_ar, 'مرحبًا، ماما! ❤️ هناك حماس كبير داخل جسمكِ، هل تشعرين به؟ كأن الاستعدادات جارية لاحتفال. يبلغ هرمون الإستروجين ذروته، وهذا يعني أن تلك «البويضة الذهبية» (أي نصفي الآخر) تستعد للانطلاق. ما عليكِ سوى الاعتناء بنفسكِ وشرب الكثير من الماء والراحة. لا أطيق الانتظار حتى أختاركِ. أخبري أبي أن يكون مستعدًا، فلم يتبقَّ سوى القليل على لقائنا! أنا قادم لأكون أجمل دليل على حبكما.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة سكر ناعم'), body_changes_ar = COALESCE(body_changes_ar, 'خلال هذه الأيام التي تخططين فيها للحمل، ينبغي أن تزوري طبيب الأسنان للتأكد من صحة أسنانكِ ولثتكِ. إن إكمال علاج مشكلات الفم الموجودة قبل الحمل سيجعل رحلة حملكِ أسهل بكثير. ويزداد خطر إصابتكِ بأمراض اللثة أثناء الحمل، وقد تؤدي هذه الأمراض في بعض الحالات إلى الولادة المبكرة. يزداد مستوى هرمون البروجسترون في الدم بدرجة كبيرة خلال الحمل، وقد يسبب انحسار اللثة وتثخنها، وهي حالة تُسمى «التضخم». ويُعد البروجسترون أحد أهم الهرمونات التي تحافظ على استمرار الحمل، لذلك ليس من الصواب كبح هذا الهرمون. ولهذا، فإن علاج المشكلات الموجودة والتخلص منها قبل الحمل، إلى جانب العناية باللثة، سيقللان مشكلات صحة الأسنان إلى أدنى حد خلال هذه المرحلة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'نظرًا إلى اقتراب موعد الإباضة، احرصي بشكل خاص على عدم إصابة جسمكِ بالجفاف. فتناول السوائل يحسّن جودة مخاط عنق الرحم ويسهّل حركة الحيوانات المنوية. وإذا كنتِ تقيسين درجة حرارة جسمكِ، فقد تلاحظين انخفاضها قليلًا قبل الإباضة مباشرة. خففي توتركِ إلى أدنى حد من خلال حمام عطري أو الاستماع إلى موسيقى ممتعة، لأن التوتر الشديد قد يؤدي إلى إفراز هرمون LH مبكرًا أو متأخرًا عن موعده.') WHERE id = '3b975bc1-895c-42e8-be4c-f6d56b176b19';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'ستبدأ فترة الإباضة لديكِ خلال يوم أو يومين. ومع اقترابها، تظهر بعض التغيرات في جسمكِ. ومن أبرزها زيادة الرغبة الجنسية نتيجة تغير التوازن الهرموني في جسمكِ. وقد تبدأ هذه الرغبة قبل الإباضة بـ2-3 أيام وتستمر في المتوسط مدة تصل إلى أسبوع واحد. وتشمل هذه التغيرات أيضًا الشعور بألم في جانبي الأربية أو في جانب واحد فقط، أو بانتفاخ في البطن، على نحو يشبه ما يحدث خلال الدورة الشهرية ولكن بصورة أخف. وإضافة إلى هذه العلامات، يُعد امتلاء الثديين وحساسيتهما، وانتفاخ البطن والغازات، والتوتر، وزيادة الحساسية تجاه المثيرات مثل المذاق والروائح، والانزعاج من الروائح النفاذة، من الأعراض الشائعة خلال فترة الإباضة.'), baby_message_ar = COALESCE(baby_message_ar, 'أعلم أنكِ لا ترينني بعد، لكن الأضواء تُضاء خلف الكواليس. 🌟 بدأ جسمكِ يُعِدّ لي أنعم فراش، أي بطانة الرحم. وربما تكون خلايا أبي قد انطلقت بالفعل وتبحث عني. يمنحني دفؤكِ واهتمامكِ القوة منذ الآن. قصتنا على وشك أن تبدأ، ماما. ما عليكِ سوى الإيمان والابتسام، فالمعجزات تحدث عندما نؤمن بها. أنتِ بطلتي!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة سكر ناعم'), body_changes_ar = COALESCE(body_changes_ar, 'الأسابيع الأولى من الحمل هي فترة تحدث فيها تغيرات سريعة جدًا في مبيضيكِ ورحمكِ، حتى إن لم تكوني مدركة لها تمامًا. وتواصل بعض الهرمونات التي تفرزها الغدة النخامية والرحم عملها بفاعلية كبيرة لتهيئة جسمكِ للحمل. وفي مبيضيكِ، تبدأ إحدى طلائع البويضات التي تكوّنت منذ أن كنتِ جنينًا بالنضوج والاستعداد للإخصاب تحت تأثير هذه الهرمونات. وخلال الأيام القليلة المقبلة، تُكمل البويضة نضجها وتصبح قادرة على الإخصاب عند لقائها بالحيوان المنوي. وعلى عكس الحيوانات المنوية، يكون عمر البويضة الناضجة أقصر بكثير، وإذا كنتِ ترغبين في الحمل، فيجب أن يحدث الإخصاب خلال 48 ساعة من الإباضة. تنتقل البويضة الناضجة من المبيض إلى قناة فالوب بصورة سلبية، وتنتظر هناك لقاء الحيوانات المنوية وحدوث الإخصاب. وإذا لم تلتقِ البويضة بحيوان منوي قبل انتهاء عمرها، فلن يحدث الحمل. وفي المقابل، إذا دخلت الحيوانات المنوية إلى عنق الرحم قبل نضوج البويضة، فقد تحافظ على حيويتها مدة تصل إلى 72 ساعة رغم الطبيعة الحمضية للبيئة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'من المهم جدًا اليوم الحفاظ على التوازن القلوي في جسمكِ، لأن الحيوانات المنوية لا تستطيع البقاء في بيئة حمضية. تناولي الكثير من الخضراوات وابتعدي عن السكريات الصناعية. وإذا كنتِ تخططين للحمل، فإن هذا اليوم السابق للإباضة (أو يوم الإباضة) هو الوقت الذي تكون فيه فرص الحمل في أعلى مستوياتها. مارسي رقصًا خفيفًا أو امشي لتنشيط الدورة الدموية في منطقة الحوض. كذلك، تجنبي خلال هذه الفترة دخان السجائر والروائح الكيميائية النفاذة، لأن البويضة شديدة الحساسية حاليًا للسموم الخارجية.') WHERE id = '29e7920b-060e-4fac-ad72-d19dda159289';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بينما يدعم هرمون الإستروجين نمو حجم البويضة، فإنه يسرّع الانقسام المتساوي، مما يؤدي إلى زيادة سماكة جدار بطانة الرحم من الداخل والخارج، ويساعد البويضة التي ستُخصّب على الانغراس بأمان داخل الرحم. كما يزيد كمية السائل النسيجي من خلال تعزيز وصول الأوعية الدموية بكثرة إلى خلايا الرحم، بهدف تهيئة الظروف المثالية للبويضة التي ستُخصّب. ويساعد هذا الهرمون أيضًا على زيادة طول المهبل، كما يحفّز خلايا الطبقة الداخلية للرحم على إفراز مادة مخاطية توفّر الانزلاق.'), baby_message_ar = COALESCE(baby_message_ar, 'ماما، هل أخبركِ بسر؟ 🤫 لقد بدأت واحدة من بين آلاف الخلايا في جسمكِ سباقها لتصبح "أنا" تحديدًا! إنها تنمو الآن بمفردها، وتنتظر بفارغ الصبر اليوم الذي ستلتقي فيه بنصفها الآخر القادم من أبي. بقي نحو أسبوع واحد على لقائنا الكبير. أنا متحمس جدًا، فماذا عنكِ؟ أشتاق إلى حضنكِ الدافئ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة سكر'), body_changes_ar = COALESCE(body_changes_ar, 'في نهاية الأسبوع الأول، تقترب التغيرات الهرمونية في جسمكِ من ذروتها. ومع ارتفاع مستوى الإستروجين، تكون بطانة الرحم قد تجددت بالكامل وتستمر سماكتها في الازدياد. قد تشعرين خلال هذه الأيام بأنكِ أكثر اجتماعية وحيوية وثقة بنفسكِ. وازدياد رغبتكِ الجنسية علامة على أن جسمكِ يستعد بصورة طبيعية لمرحلة الخصوبة، أي للأيام التي تكون فيها فرص الحمل في أعلى مستوياتها.;;;
لكي تمرّي بتجربة حمل صحية، من الضروري أن تخضعي للفحوصات الطبية الروتينية قبل الحمل.;;;
تكتسب الفحوصات الطبية السابقة للحمل أهمية أكبر، خصوصًا في سن متقدمة أو عند وجود أي حالة مرضية مزمنة. وخلال هذه الفحوصات، ينبغي التحقق من وجود أي أمراض قد تكون وراثية، مع مراعاة التاريخ العائلي لكِ ولزوجكِ. ومن المهم أن يقيّم طبيبكِ الرحم والمبيضين من خلال فحص نسائي وتصوير بالموجات فوق الصوتية، للكشف عن مشكلات الرحم مثل الأورام الليفية والسلائل. وإذا رأى طبيبكِ ضرورة لذلك، فينبغي إجراء مسحة من عنق الرحم تُعرف باسم "اختبار المسحة". كما ينبغي إجراء فحوصات مخبرية لتقييم وظائف الكبد والكلى، والتحقق من مستوى السكر ووجود أمراض مزمنة أو عدوى مثل التهاب الكبد وداء المقوسات. ومن المهم، خصوصًا في فحوصات ما قبل الحمل، مراعاة وسائل منع الحمل التي استُخدمت حتى الآن. فقد تحدّ حبوب منع الحمل المستخدمة لفترة طويلة من الخصوبة مؤقتًا. ويمكن لنحو 50% من النساء الحمل بعد مرور 6 أشهر على الأقل من تناول آخر حبة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'كافئي نفسكِ على إتمام الأسبوع الأول بنجاح، ولكن بطريقة صحية. مارسي المشي لمسافات طويلة في الهواء الطلق لزيادة مستوى الأكسجين في جسمكِ؛ إذ يؤثر ارتفاع الأكسجين إيجابيًا في عملية الأيض داخل البويضة. وأضيفي إلى نظامكِ الغذائي فواكه ملوّنة غنية بمضادات الأكسدة (مثل التوت الأزرق وتوت العليق). تحمي هذه المواد البويضة من الإجهاد التأكسدي، مما يهيّئ الظروف لإخصابها بصورة أكثر صحة.') WHERE id = 'cf28e232-185c-40c5-9616-39e6df91cf1f';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'قناتا فالوب الموجودتان في الرحم هما أحد أعضاء الجهاز التناسلي، وتتكونان من زوج من القنوات الطويلة والضيقة التي تنقل البويضات الناضجة في المبيضين إلى داخل الرحم. ويُطلق على هذا العضو أيضًا اسم قناتي البيض أو قناتي الرحم. تنقل قناتا فالوب البويضة التي نضجت من بين جريبات البويضات المختارة خلال ذلك الشهر إلى الرحم. وتنتج الطبقة المخاطية التي تغطي قناتي فالوب، والبالغ طولهما نحو 12 سم، إفرازات تساعد الحيوانات المنوية على التحرك نحو البويضة والبقاء حية. وتكتسب بعض مكونات هذه الإفرازات أهمية بالغة في تمكين الحيوانات المنوية من استخدام الأكسجين، كما تساعد على تغذية البويضة وتطورها بعد الإخصاب.'), baby_message_ar = COALESCE(baby_message_ar, 'مرحبًا يا عالمي! 🌍 لقد سرّع جسمكِ استعداداته من أجلي أكثر فأكثر. ربما لا تشعرين بذلك في حياتكِ اليومية، لكن العمل يجري على قدم وساق في الداخل. كل شيء من أجل راحتي وسلامتي وصحتي. جسمكِ هو المختبر الأكثر كمالًا ودقة في العالم. أنا ممتن لكِ!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة سكر'), body_changes_ar = COALESCE(body_changes_ar, 'في اليوم الأول من الأسبوع الثاني، يصبح هرمون الإستروجين هو الهرمون السائد. وبتأثيره، تبدأ بطانة الرحم باكتساب المزيد من الأوعية الدموية وتصبح أكثر ليونة. ويتحول سائل عنق الرحم (مخاط عنق الرحم) تدريجيًا إلى قوام أكثر شفافية وانزلاقًا؛ مما يوفر بيئة مثالية لبقاء الحيوانات المنوية حية داخل الرحم لأيام. وتستقر درجة حرارة جسمكِ في هذه المرحلة، لكنها تستعد للتغير مع اقتراب الإباضة.;;;
نظرًا إلى أن أعراض الحمل وأعراض اقتراب الدورة الشهرية غالبًا ما تكون متشابهة، فقد تختلط عليكِ. ومن هذه الأعراض امتلاء الثديين وتورمهما. وقد تشعر كثير من النساء بهذا الإحساس بصورة أشد من أعراض ما قبل الدورة الشهرية. وإلى جانب ذلك، قد يكون الوهن والإرهاق أشد مما تشعرين به خلال الدورة الشهرية المعتادة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'مع دخولكِ الأيام التي ترتفع فيها فرص الحمل، من المهم الحفاظ على توازن الرقم الهيدروجيني (pH) في جسمكِ. ويمكن لتناول كميات كبيرة من الأطعمة القلوية (مثل الماء بالليمون والخضراوات الخضراء) أن يجعل البيئة الداخلية للجسم أكثر ملاءمة. وإذا لم تكوني قد بدأتِ بعد، فيمكنكِ قياس درجة حرارة جسمكِ الأساسية يوميًا في الساعة نفسها لتحديد يوم الإباضة بدقة أكبر. ولا تنسي شرب الكثير من الماء، لأن ذلك ضروري لجودة سائل عنق الرحم.') WHERE id = 'abcdc9dc-69bf-4833-9582-4fb6ef1276bd';